def new_id(prefix: str) -> str:
    return f"{prefix}_{uuid.uuid4().hex}"


def compact_text(value: str, limit: int) -> str:
    return re.sub(r"\s+", " ", value or "").strip()[:limit]


_AGENT_SURFACE_CONTEXT_FIELDS = (
    "page_ref",
    "selection_ref",
    "task_ref",
    "event_ref",
    "artifact_ref",
    "person_ref",
    "document_ref",
    "action_ref",
    "sop_ref",
    "workflow_ref",
    "org_ref",
    "agent_ref",
    "system_ref",
    "trace_ref",
)


def normalise_agent_surface_context(
    value: Any,
    *,
    page_ref: str = "",
    task_ref: str = "",
    selected_text: str = "",
) -> dict[str, str]:
    raw = value.model_dump(mode="json") if hasattr(value, "model_dump") else dict(value or {})
    if page_ref:
        raw["page_ref"] = page_ref
    if task_ref:
        raw["task_ref"] = task_ref
    clean = {
        key: compact_text(str(raw.get(key) or ""), 1000)
        for key in _AGENT_SURFACE_CONTEXT_FIELDS
        if str(raw.get(key) or "").strip()
    }
    if selected_text and not clean.get("selection_ref"):
        clean["selection_ref"] = f"{clean.get('page_ref') or page_ref}#selection"[:1000]
    return clean


def truncate_markdown(value: str, limit: int) -> str:
    text = str(value or "")
    if len(text) <= limit:
        return text
    head = text[: max(1, limit - 3)]
    minimum = max(120, int(limit * 0.55))
    boundaries = [head.rfind("\n\n"), head.rfind("\n- "), head.rfind("\n")]
    cut = max((item for item in boundaries if item >= minimum), default=-1)
    if cut < 0:
        cut = head.rfind(" ")
    candidate = head[:cut if cut > 0 else len(head)].rstrip()
    if candidate.count("```") % 2:
        candidate = candidate[: candidate.rfind("```")].rstrip()
    if candidate.rfind("[") > candidate.rfind(")"):
        candidate = candidate[: candidate.rfind("[")].rstrip()
    return f"{candidate}\n\n…" if candidate else "…"


def public_grounding_status(answerability_status: str) -> str:
    """Map internal answerability vocabulary to the stable public contract."""

    return "no_evidence" if answerability_status == "insufficient" else answerability_status


