class AgentV2Service:
    SEMANTIC_ROUTE_CACHE_VERSION = "51"
    SEMANTIC_ROUTE_CACHE_TTL_SECONDS = 900
    STARTER_SUGGESTION_VERSION = "2"

    def __init__(
        self,
        settings: AgentV2Settings,
        *,
        identity_provider: Callable[[str], Principal] | None = None,
        domain_services: DomainServiceGateway | None = None,
        routine_target_executor: Callable[[dict[str, Any], WorkRoutineTriggerRequest, Principal], dict[str, Any]] | None = None,
        page_context_provider: Callable[[str, str], dict[str, Any]] | None = None,
        directory_provider: Callable[[], list[Principal]] | None = None,
        general_query_runtime: ProfileDrivenQueryRuntime | Any | None = None,
        source_intake_factory: Callable[[AgentV2Store], SourceIntakeService] | None = None,
        source_intake_authorizer: Callable[[Principal], IntakeAuthorization] | None = None,
        metadata_runtime_bindings: Any | None = None,
        reviewed_query_execution_authorizer: Callable[[Principal, dict[str, Any]], Any] | None = None,
        domain_tool_trust_provider: Callable[[], tuple] | None = None,
    ):
        self.settings = settings
        self.evaluation_state = EvaluationRuntimeState.from_settings(settings)
        self.store: AgentV2Store = build_store(settings)
        self.source_intake = source_intake_factory(self.store) if source_intake_factory else None
        if self.source_intake is not None and self.source_intake.store is not self.store:
            raise ValueError("SOURCE_INTAKE_SHARED_STORE_REQUIRED")
        self.source_intake_authorizer = source_intake_authorizer
        from .domain_intake import DomainIntakeService
        self.domain_intake = DomainIntakeService(self.source_intake, source_intake_authorizer,
            tool_trust_provider=domain_tool_trust_provider, identity_provider=identity_provider,
            current_token_provider=lambda token_id:self.store.get('tokens', token_id))
        self.metadata_runtime_bindings = metadata_runtime_bindings
        self.reviewed_query_execution_authorizer = reviewed_query_execution_authorizer
        self.answer_application = AnswerApplicationService(self.store)
        self.answer_delivery = GovernedAnswerDeliveryService(
            self.store,
            cursor_secret=settings.pat_hash_secret.encode("utf-8"),
            protected_result_loader=self._load_answer_protected_result,
        )
        self.bulk_migration_repository = AgentV2StoreBulkMigrationRepository(self.store)
        self.bulk_migration_orchestrator = BulkMigrationOrchestrator(
            self.bulk_migration_repository
        )
        self.bulk_migration_pi_runner: Callable[
            [str, dict[str, object]], dict[str, object]
        ] = self._unavailable_bulk_migration_pi_runner
        # Historical vertical-slice services are injected only by the
        # qualification harness.  The canonical service import closure must
        # not load their DEXA/ETCH implementation modules.
        self.north_star_etch_preview_service: Any | None = None
        self.evaluation_state_provisioning = self.evaluation_state.provision(self.store)
        self.repository = KnowledgeRepository(settings)
        self.registry = CapabilityRegistry(settings.agent_catalog_root / "capabilities-v2.yaml")
        self._semantic_route_contract_checksum = self._build_semantic_route_contract_checksum()
        self.model: ModelGateway = build_model_gateway(settings)
        self.model_residency = lmstudio_model_residency_state(settings)
        self._model_residency_checked_at = 0.0
        self.search = HybridSearchService(self.repository, self.store, self.model)
        self.policy = TaskPolicy(self.repository, self.store)
        self.quick_agent = QuickAgentRuntime(self.registry)
        self.entity_resolver = EntityResolver(directory_provider)
        self.pats = PatService(self.store, settings.pat_hash_secret, identity_provider=identity_provider)
        self.harnesses = HarnessRegistry(settings.agent_catalog_root / "harnesses-v2.yaml")
        self.evaluator = IndependentArtifactEvaluator(
            self.store,
            self.model,
            enabled=settings.independent_review,
        )
        self.claim_evaluator = IndependentClaimEvaluator(
            self.store,
            self.model,
            enabled=settings.claim_grounding_enabled,
        )
        self.domain_services = domain_services or DomainServiceGateway()
        self.general_query_runtime = general_query_runtime
        self._job_lock = threading.Lock()
        self.platform = HarnessPlatformRuntime(
            store=self.store,
            repository=self.repository,
            harnesses=self.harnesses,
            domain_services=self.domain_services,
        )
        self.routine_target_executor = routine_target_executor
        self.learning = WorkLearningService(
            store=self.store,
            repository=self.repository,
            search=self.search,
            harnesses=self.harnesses,
            page_context_provider=page_context_provider,
            model_profile=settings.model_name or "deterministic",
        )
        self.knowledge = LivingKnowledgeService(
            settings=self.settings,
            repository=self.repository,
            store=self.store,
            search=self.search,
            directory_provider=directory_provider,
        )
        self.learning.runtime_relation_notifier = self.knowledge.compile_graph
        self.platform.runtime_relation_notifier = self.knowledge.compile_graph
        self.harness_packages = HarnessPackageCompiler(
            settings=self.settings,
            capabilities=self.registry,
            harnesses=self.harnesses,
            ontology=self.knowledge.ontology_registry,
        )
        self.platform.harness_package_provider = self.current_harness_package
        self.capability_handlers = CapabilityHandlerRegistry()
        self._turn_request_lock = threading.Lock()
        self._active_turn_requests: dict[str, str] = {}
        self._cancelled_turn_requests: set[str] = set()
        handler_bindings = {
            "artifact_transform": self._handle_artifact_transform,
            "routine_plan": self._handle_routine_plan,
            "task_runtime": self._handle_task_runtime,
            "grounded_read": self._handle_grounded_read,
            "current_work": self._handle_current_work,
            "deep_job": self._handle_deep_job,
            "draft_artifact": self._handle_draft_artifact,
            "ontology_migration": self._handle_ontology_migration,
            "governed_query": self._handle_governed_query,
        }
        handler_phases = {
            "grounded_read": {"post_retrieval_grounding"},
        }
        self._grounded_output_contracts: dict[
            str,
            Callable[
                [CapabilityHandlerContext, CapabilityHandlerResult],
                CapabilityHandlerResult,
            ],
        ] = {
            "case_comparison.v1": self._compile_case_comparison_output,
        }
        for handler_id, handler in handler_bindings.items():
            self.capability_handlers.register(
                handler_id,
                handler,
                phases=handler_phases.get(handler_id),
            )
        missing_handlers = CapabilityRegistry.HANDLER_PLUGINS - self.capability_handlers.registered_ids()
        if missing_handlers:
            raise RuntimeError("missing capability handler plugins: " + ", ".join(sorted(missing_handlers)))
        declared_grounded_output_contracts = {
            str(contract_id)
            for definition in self.registry.all()
            for contract_id in (
                definition.handler_config.get("grounded_output_contracts") or {}
            ).values()
            if str(contract_id).strip()
        }
        unknown_grounded_output_contracts = (
            declared_grounded_output_contracts
            - set(self._grounded_output_contracts)
        )
        if unknown_grounded_output_contracts:
            raise RuntimeError(
                "unknown grounded output contracts: "
                + ", ".join(sorted(unknown_grounded_output_contracts))
            )

    @staticmethod
    def _contract_checksum(value: Any) -> str:
        return hashlib.sha256(
            json.dumps(
                value,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
                default=str,
            ).encode("utf-8")
        ).hexdigest()

    @staticmethod
    def _plan_input_contract(plan: dict[str, Any]) -> dict[str, Any]:
        """Return the reviewed inputs that a confirmation is allowed to use.

        The projection is deliberately independent of timestamps and runtime
        status.  It is shared by Action, Task, Skill and draft plans so adding
        a new capability does not require another confirmation branch.
        """

        return {
            "capability_id": str(plan.get("capability_id") or ""),
            "operation": str(plan.get("operation") or ""),
            "target_ref": str(plan.get("target_ref") or ""),
            "artifact_id": str(plan.get("artifact_id") or ""),
            "candidate_id": str(plan.get("candidate_id") or ""),
            "domain_operation": str(plan.get("domain_operation") or ""),
            "domain_ref": str(plan.get("domain_ref") or ""),
            "domain_payload": copy.deepcopy(
                plan.get("domain_payload")
                if isinstance(plan.get("domain_payload"), dict)
                else {}
            ),
            "risk": str(plan.get("risk") or ""),
            "work_run_id": str(plan.get("work_run_id") or ""),
        }

    def _ensure_plan_binding(self, plan_id: str) -> dict[str, Any]:
        """Persist one immutable confirmation binding for a draft plan."""

        plan = self.store.get("plans", plan_id)
        if not plan:
            raise HTTPException(status_code=404, detail="plan not found")
        revision = int(plan.get("revision") or 1)
        domain_payload = (
            dict(plan.get("domain_payload") or {})
            if isinstance(plan.get("domain_payload"), dict)
            else {}
        )
        if plan.get("domain_operation") and not domain_payload.get("idempotency_key"):
            domain_payload["idempotency_key"] = str(
                plan.get("idempotency_key") or f"plan:{plan_id}"
            )
            plan["domain_payload"] = domain_payload
            plan["idempotency_key"] = domain_payload["idempotency_key"]
        binding = (
            dict(plan.get("confirmation_binding") or {})
            if isinstance(plan.get("confirmation_binding"), dict)
            else {}
        )
        if not binding:
            input_fingerprint = self._contract_checksum(
                self._plan_input_contract(plan)
            )
            binding = {
                "principal_id": str(plan.get("employee_id") or ""),
                "plan_revision": revision,
                "input_fingerprint": input_fingerprint,
                "bound_at": now_iso(),
            }
            binding["plan_checksum"] = self._contract_checksum(
                {
                    "plan_id": plan_id,
                    "principal_id": binding["principal_id"],
                    "plan_revision": binding["plan_revision"],
                    "input_fingerprint": input_fingerprint,
                    "plan": self._plan_input_contract(plan),
                }
            )
            plan["confirmation_binding"] = binding
            plan["plan_checksum"] = binding["plan_checksum"]
            plan["input_fingerprint"] = input_fingerprint
            plan["revision"] = revision
            self.store.put("plans", plan_id, plan)
        expected_input = self._contract_checksum(self._plan_input_contract(plan))
        expected_checksum = self._contract_checksum(
            {
                "plan_id": plan_id,
                "principal_id": str(binding.get("principal_id") or ""),
                "plan_revision": int(binding.get("plan_revision") or 1),
                "input_fingerprint": expected_input,
                "plan": self._plan_input_contract(plan),
            }
        )
        if (
            expected_input != str(binding.get("input_fingerprint") or "")
            or expected_checksum != str(binding.get("plan_checksum") or "")
        ):
            raise HTTPException(
                status_code=409,
                detail={"code": "plan_binding_integrity_failed"},
            )
        return plan

    def _attach_plan_binding(self, response: AgentTurnResponse) -> AgentTurnResponse:
        if not response.plan_ref:
            return response
        plan = self._ensure_plan_binding(response.plan_ref)
        binding = dict(plan.get("confirmation_binding") or {})
        response.plan_revision = int(binding.get("plan_revision") or 1)
        response.plan_checksum = str(binding.get("plan_checksum") or "")
        response.input_fingerprint = str(binding.get("input_fingerprint") or "")
        return response

    def _semantic_result_checksum(self, response: AgentTurnResponse) -> str:
        intent = (
            response.work_intent.model_dump(mode="json")
            if response.work_intent is not None
            else {}
        )
        # A surface-parity checksum describes the stable semantic result, not
        # the answer model's choice between equivalent direct extracts from
        # the same displayed evidence set.  Claim-to-source/chunk bindings are
        # still validated and returned on every response; the checksum keeps
        # their typed support shape as a multiset and binds the result to the
        # exact public source set separately.  This makes Web, REST, MCP and
        # external-agent results comparable without treating prose ordering
        # or an equivalent source-row projection as a semantic mutation.
        claim_contracts = sorted(
            (
                {
                    "claim_kind": claim.claim_kind,
                    "source_scope": claim.source_scope,
                    "support_status": claim.support_status,
                    "required_for_answer": claim.required_for_answer,
                }
                for claim in response.grounded_claims
            ),
            key=lambda item: json.dumps(item, sort_keys=True, ensure_ascii=False),
        )
        payload = {
            "status": response.status,
            "capability_id": response.capability_id,
            "grounding_status": response.grounding_status,
            "operation": str(intent.get("operation") or ""),
            "user_effect": str(intent.get("user_effect") or ""),
            "work_view": str(intent.get("work_view") or ""),
            "topic_mode": str(intent.get("topic_mode") or ""),
            "used_source_refs": sorted(set(response.used_source_refs)),
            "claims": claim_contracts,
            "artifact_types": sorted(
                str(item.artifact_type) for item in response.artifact_refs
            ),
            "stop_reason": response.stop_reason,
        }
        return self._contract_checksum(payload)

    def register_turn_request(self, principal: Principal, request: AgentTurnRequest) -> str:
        request_id = str(request.request_id or new_id("turnreq"))[:120]
        request.request_id = request_id
        with self._turn_request_lock:
            owner = self._active_turn_requests.get(request_id)
            if owner and owner != principal.employee_id:
                raise HTTPException(status_code=409, detail="turn request id is already active")
            self._active_turn_requests[request_id] = principal.employee_id
        return request_id

    def cancel_turn_request(self, principal: Principal, request_id: str) -> dict[str, Any]:
        request_id = str(request_id or "").strip()
        with self._turn_request_lock:
            owner = self._active_turn_requests.get(request_id)
            if not owner:
                raise HTTPException(status_code=404, detail="active turn request not found")
            if owner != principal.employee_id and not principal.is_admin:
                raise HTTPException(status_code=403, detail="turn request belongs to another employee")
            self._cancelled_turn_requests.add(request_id)
        return {"request_id": request_id, "status": "cancelling"}

    def _turn_cancelled(self, request: AgentTurnRequest) -> bool:
        request_id = str(request.request_id or "")
        if not request_id:
            return False
        with self._turn_request_lock:
            return request_id in self._cancelled_turn_requests

    def _release_turn_request(self, request: AgentTurnRequest) -> None:
        request_id = str(request.request_id or "")
        if not request_id:
            return
        with self._turn_request_lock:
            self._active_turn_requests.pop(request_id, None)
            self._cancelled_turn_requests.discard(request_id)

    def inspect_model_residency(self) -> dict[str, Any]:
        self.model_residency = inspect_lmstudio_model_residency(self.settings)
        self._model_residency_checked_at = time.monotonic()
        return dict(self.model_residency)

    def ensure_model_residency(self) -> dict[str, Any]:
        """Compatibility alias; model lifecycle remains externally managed by LM Studio."""

        return self.inspect_model_residency()

    def _build_semantic_route_contract_checksum(self) -> str:
        """Fingerprint every local input that can change a cached semantic route.

        The route cache contains a validated SemanticPlan, its catalog-compiled
        ExecutionPlan, and (for grounded reads) the model's claim bindings.  A
        cache keyed only by schema name and catalog version can therefore reuse
        an answer created by older planner prompts or verification code while a
        dirty checkout is being evaluated.  Keep those old rows for audit, but
        make them unreachable from a changed meaning contract.
        """

        module_root = Path(__file__).resolve().parent
        paths = [
            Path(__file__).resolve(),
            module_root / "quick_agent.py",
            module_root / "semantic_kernel.py",
            module_root / "models.py",
            module_root / "capabilities.py",
            module_root / "repository.py",
            self.registry.catalog_path.resolve(),
            self.registry.catalog_path.with_name("draft-contracts-v2.yaml").resolve(),
        ]
        digest = hashlib.sha256()
        digest.update(self.SEMANTIC_ROUTE_CACHE_VERSION.encode("utf-8"))
        for path in paths:
            digest.update(str(path.name).encode("utf-8"))
            digest.update(b"\0")
            digest.update(path.read_bytes())
            digest.update(b"\0")
        return digest.hexdigest()

    def _semantic_route_cache_key(self, principal: Principal, route_input: dict[str, Any]) -> str:
        model_state = self.model.readiness()
        cache_route_input = copy.deepcopy(route_input)
        source_policy = (
            cache_route_input.get("source_policy_context")
            if isinstance(cache_route_input.get("source_policy_context"), dict)
            else {}
        )
        if source_policy:
            # A source-set id and its optimistic revision identify the owning
            # WorkSession, not the meaning of the source policy.  Keeping them
            # in the cross-surface route key forced an otherwise identical
            # request from Web, REST, MCP, or an external Agent to call the
            # planner again for every newly-created session.  The admissible
            # evidence policy itself remains fully bound to the key.
            cache_route_input["source_policy_context"] = {
                key: copy.deepcopy(value)
                for key, value in source_policy.items()
                if key not in {"source_set_ref", "revision"}
            }
        cache_hints = []
        for hint in cache_route_input.get("knowledge_hints") or []:
            if not isinstance(hint, dict):
                continue
            if str(hint.get("answer_scope") or "canonical") == "operational":
                cache_hints.append(
                    {
                        key: hint.get(key)
                        for key in ("ref", "title", "kind", "authority", "source", "answer_scope")
                    }
                )
            else:
                cache_hints.append(hint)
        cache_route_input["knowledge_hints"] = cache_hints
        payload = {
            "version": self.SEMANTIC_ROUTE_CACHE_VERSION,
            "semantic_contract_checksum": self._semantic_route_contract_checksum,
            "catalog_revision": self.registry.version,
            "planner_schema_revision": PLANNER_SCHEMA_REVISION,
            "employee_id": principal.employee_id,
            "team_ids": sorted(principal.teams),
            "roles": sorted(principal.roles),
            "is_admin": principal.is_admin,
            "model": {
                "provider": model_state.get("provider") or "",
                "name": model_state.get("model") or "",
            },
            "route_input": cache_route_input,
        }
        encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
        return "semantic_route_" + hashlib.sha256(encoded.encode("utf-8")).hexdigest()

    def _semantic_route(
        self,
        principal: Principal,
        route_input: dict[str, Any],
        *,
        read_cache: bool = True,
    ) -> dict[str, Any]:
        cache_key = self._semantic_route_cache_key(principal, route_input)
        cached = self.store.get("semantic_routes", cache_key) or {} if read_cache else {}
        try:
            cache_valid = (
                cached.get("cache_version") == self.SEMANTIC_ROUTE_CACHE_VERSION
                and cached.get("semantic_contract_checksum")
                == self._semantic_route_contract_checksum
                and parse_time(str(cached.get("expires_at") or "")) > datetime.now(timezone.utc)
                and isinstance(cached.get("route"), dict)
            )
        except (TypeError, ValueError):
            cache_valid = False
        if cache_valid:
            cached_route = copy.deepcopy(cached["route"])
            cached_intent = cached_route.get("work_intent") if isinstance(cached_route.get("work_intent"), dict) else {}
            if str(cached_intent.get("answer_source_scope") or "canonical") != "operational":
                cached_route["semantic_cache"] = {
                    "hit": True,
                    "cache_version": self.SEMANTIC_ROUTE_CACHE_VERSION,
                    "semantic_contract_checksum": self._semantic_route_contract_checksum,
                }
                return cached_route

        route = self.quick_agent.route(**route_input, model=self.model)
        semantic_plan = route.get("semantic_plan") if isinstance(route.get("semantic_plan"), dict) else {}
        semantic_plan_v4 = (
            route.get("semantic_plan_v4")
            if isinstance(route.get("semantic_plan_v4"), dict)
            else {}
        )
        execution_plan = (
            route.get("execution_plan")
            if isinstance(route.get("execution_plan"), dict)
            else {}
        )
        if not semantic_plan or not semantic_plan_v4 or not execution_plan:
            raise SemanticPlanningError(
                "planner_invalid",
                "Validated SemanticPlanV4 or its catalog-compiled ExecutionPlan is missing.",
            )
        plan_payload = json.dumps(
            semantic_plan_v4,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        semantic_plan_ref = "semantic_plan_" + hashlib.sha256(
            f"{principal.employee_id}:{self.registry.version}:{plan_payload}".encode("utf-8")
        ).hexdigest()[:32]
        self.store.put(
            "semantic_plans",
            semantic_plan_ref,
            {
                "semantic_plan_ref": semantic_plan_ref,
                "employee_id": principal.employee_id,
                "catalog_revision": self.registry.version,
                "planner_schema_revision": PLANNER_SCHEMA_REVISION,
                "schema_revision": str(
                    semantic_plan_v4.get("schema_revision") or PLANNER_SCHEMA_REVISION
                ),
                "plan": semantic_plan_v4,
                "compatibility_plan": semantic_plan,
                "execution_plan": execution_plan,
                "validation": route.get("plan_validation") or {},
                "created_at": now_iso(),
            },
        )
        route["semantic_plan_ref"] = semantic_plan_ref
        route["semantic_cache"] = {
            "hit": False,
            "cache_version": self.SEMANTIC_ROUTE_CACHE_VERSION,
            "semantic_contract_checksum": self._semantic_route_contract_checksum,
            "mode": "default" if read_cache else "refresh",
        }
        route_intent = route.get("work_intent") if isinstance(route.get("work_intent"), dict) else {}
        if (
            route.get("source") in {"llm_structured", "explicit", "offer_id"}
            and str(route_intent.get("answer_source_scope") or "canonical") != "operational"
        ):
            self.store.put(
                "semantic_routes",
                cache_key,
                {
                    "cache_key": cache_key,
                    "cache_version": self.SEMANTIC_ROUTE_CACHE_VERSION,
                    "semantic_contract_checksum": self._semantic_route_contract_checksum,
                    "employee_id": principal.employee_id,
                    "route": copy.deepcopy(route),
                    "created_at": now_iso(),
                    "expires_at": (
                        datetime.now(timezone.utc)
                        + timedelta(seconds=self.SEMANTIC_ROUTE_CACHE_TTL_SECONDS)
                    ).isoformat(),
                },
            )
        return route

    @staticmethod
    def _owns(principal: Principal, row: dict[str, Any]) -> bool:
        return str(row.get("employee_id") or "") == principal.employee_id or principal.is_admin

    def _require_owned(self, principal: Principal, row: dict[str, Any] | None, label: str) -> dict[str, Any]:
        if not row:
            raise HTTPException(status_code=404, detail=f"{label} not found")
        if not self._owns(principal, row):
            raise HTTPException(status_code=403, detail=f"{label} belongs to another employee")
        return row

    def _completion_label_lookup(self, principal: Principal) -> dict[str, str]:
        lookup: dict[str, str] = {}
        identity_fields = (
            "boi_id",
            "event_type",
            "action_key",
            "workflow_definition_key",
            "skill_key",
            "term",
        )
        for record in self.repository.authoritative_records(principal, include_drafts=True):
            title = str(record.title or record.record_id).strip()
            if not title:
                continue
            lookup[record.record_id] = title
            for field in identity_fields:
                value = str(record.metadata.get(field) or "").strip()
                if value:
                    lookup[value] = title
                    if field == "event_type":
                        lookup[f"event:{value}"] = title
                        lookup[f"boi:public:event-types:{value}"] = title
                    elif field == "action_key":
                        lookup[f"action:{value}"] = title
                    elif field == "workflow_definition_key":
                        lookup[f"workflow:{value}"] = title
                        lookup[f"boi:public:workflows:{value}"] = title
                    elif field == "skill_key":
                        lookup[f"skill:{value}"] = title
            if ":" in record.record_id:
                suffix = record.record_id.split(":", 1)[1]
                if suffix:
                    lookup.setdefault(suffix, title)
        return lookup

    def _delete_expired_work_sessions(self, principal: Principal) -> None:
        now = datetime.now(timezone.utc)
        for session in self.store.list("work_sessions", employee_id=principal.employee_id, limit=500):
            if session.get("pinned") or session.get("status") == "archived":
                continue
            try:
                expired = parse_time(str(session.get("expires_at") or "")) <= now
            except (TypeError, ValueError):
                expired = False
            if not expired:
                continue
            session_id = str(session.get("session_id") or "")
            self.store.delete("work_sessions", session_id)
            for message in self.store.list("session_messages", employee_id=principal.employee_id, limit=5000):
                if message.get("session_id") == session_id:
                    self.store.delete("session_messages", str(message.get("message_id") or ""))

    def create_work_session(
        self,
        principal: Principal,
        request: WorkSessionCreateRequest | None = None,
    ) -> dict[str, Any]:
        self._delete_expired_work_sessions(principal)
        request = request or WorkSessionCreateRequest()
        session_id = new_id("ws")
        created_at = now_iso()
        surface_context = normalise_agent_surface_context(
            request.surface_context,
            page_ref=request.page_ref,
        )
        session = {
            "session_id": session_id,
            "employee_id": principal.employee_id,
            "title": compact_text(request.title, 160) or "새 업무",
            "status": "active",
            "conversation_id": session_id,
            "conversation_summary": "",
            "active_artifact_id": "",
            "active_goal_plan_id": "",
            "source_set_id": self._source_set_id(session_id),
            "selected_task_id": "",
            "active_panel": "result",
            "page_ref": surface_context.get("page_ref", ""),
            "surface_context": surface_context,
            "helper_id": compact_text(request.helper_id, 120),
            "revision": 1,
            "pinned": False,
            "expires_at": (datetime.now(timezone.utc) + timedelta(days=30)).isoformat(),
            "created_at": created_at,
            "updated_at": created_at,
        }
        stored = self.store.put("work_sessions", session_id, session)
        self._ensure_source_set(principal, session_id)
        return stored

    def list_work_sessions(self, principal: Principal, *, limit: int = 20) -> dict[str, Any]:
        self._delete_expired_work_sessions(principal)
        items = self.store.list("work_sessions", employee_id=principal.employee_id, limit=max(1, min(limit, 100)))
        return {"count": len(items), "items": items}

    def starter_suggestions(
        self,
        principal: Principal,
        *,
        page_ref: str = "",
        limit: int = 8,
    ) -> list[StarterSuggestion]:
        """Build grounded entry points from work the principal can actually access."""

        suggestions: list[StarterSuggestion] = []
        used_categories: set[str] = set()
        area_counts: dict[str, int] = {}
        seen_suggestions: set[str] = set()

        class TemplateValues(dict[str, str]):
            def __missing__(self, key: str) -> str:
                return ""

        def add(definition: CapabilityDefinition, offer: Any, candidate: dict[str, Any]) -> None:
            selected_ref = str(candidate.get("record_id") or "").strip()
            selected_title = compact_text(str(candidate.get("title") or ""), 160)
            subject = (
                f"person:{principal.employee_id}"
                if offer.subject_binding == "principal_person"
                else selected_ref
            )
            refs = [selected_ref]
            if offer.include_anchor_source:
                refs.append(str(candidate.get("anchor_ref") or ""))
            refs = list(dict.fromkeys(ref for ref in refs if ref))[:4]
            if not subject or not refs:
                return
            if offer.only_when_category_empty and offer.category in used_categories:
                return
            if offer.only_when_area_empty and area_counts.get(offer.area):
                return
            values = TemplateValues(
                subject_title=selected_title,
                subject_ref=selected_ref,
                anchor_title=compact_text(str(candidate.get("anchor_title") or ""), 160),
                anchor_ref=str(candidate.get("anchor_ref") or ""),
                employee_id=principal.employee_id,
            )
            label = offer.label_template.format_map(values)
            prompt = offer.prompt_template.format_map(values)
            reason = offer.reason_template.format_map(values)
            if offer.use_entrypoint_copy:
                metadata = candidate.get("metadata") if isinstance(candidate.get("metadata"), dict) else {}
                prompts = metadata.get("agent_entrypoint_prompts") if isinstance(metadata, dict) else {}
                prompt_spec = prompts.get(offer.entrypoint_area) if isinstance(prompts, dict) else None
                if isinstance(prompt_spec, dict):
                    label = str(prompt_spec.get("label") or label)
                    prompt = str(prompt_spec.get("prompt") or prompt)
                    reason = str(prompt_spec.get("reason") or reason)
            user_effect = offer.user_effect or definition.default_user_effect
            operation = offer.semantic_operation or definition.default_operation
            work_view = offer.work_view or definition.default_work_view
            if user_effect is None or operation is None:
                return
            result_kind = offer.result_kind
            graph_query_kind = offer.graph_query_kind
            if graph_query_kind and result_kind in {"table", "timeline", "mermaid", "explorer"}:
                try:
                    graph_result = self.knowledge.query(
                        principal,
                        GraphQueryPlan(
                            focal_entities=[subject],
                            query_kind=graph_query_kind,  # type: ignore[arg-type]
                            direction="both",
                            depth=2,
                            limit=24,
                            presentation=result_kind,  # type: ignore[arg-type]
                        ),
                    )
                except Exception:
                    graph_result = {}
                if not (
                    graph_result.get("ok")
                    and graph_result.get("meaningful")
                    and graph_result.get("edges")
                ):
                    if not offer.fallback_to_answer:
                        return
                    result_kind = "answer"
                    graph_query_kind = ""
            digest = hashlib.sha256(f"{offer.offer_id}:{subject}:{prompt}".encode("utf-8")).hexdigest()[:16]
            if digest in seen_suggestions:
                return
            suggestions.append(
                StarterSuggestion(
                    suggestion_id=f"suggestion_{digest}",
                    category=offer.category,
                    label=compact_text(label, 160),
                    prompt=compact_text(prompt, 1200),
                    subject_ref=subject,
                    source_refs=refs,
                    reason=compact_text(reason, 240),
                    priority=offer.priority,
                    area=offer.area,
                    context_basis=offer.context_basis,
                    subject_title=selected_title or compact_text(label, 160),
                    result_kind=result_kind,  # type: ignore[arg-type]
                    graph_query_kind=graph_query_kind,  # type: ignore[arg-type]
                    capability_id=definition.capability_id,
                    user_effect=user_effect,  # type: ignore[arg-type]
                    operation=operation,
                    work_view=work_view,  # type: ignore[arg-type]
                )
            )
            seen_suggestions.add(digest)
            used_categories.add(offer.category)
            area_counts[offer.area] = area_counts.get(offer.area, 0) + 1

        records = [
            item
            for item in self.repository.authoritative_records(principal)
            if item.authority in {"reviewed", "published"} and item.visibility in {"public", "team"}
        ]
        records_by_id = {item.record_id: item for item in records}

        def directly_connected_records(seed_refs: list[str]) -> list[KnowledgeRecord]:
            seeds = list(dict.fromkeys(str(item).strip() for item in seed_refs if str(item).strip()))
            if not seeds:
                return []
            candidate_refs: list[str] = []
            for seed in seeds:
                record = records_by_id.get(seed)
                if not record:
                    continue
                for key in ("source_refs", "related", "related_terms", "linked_boi_ids", "backlinks"):
                    value = record.metadata.get(key)
                    values = value if isinstance(value, list) else [value] if value else []
                    for candidate in values:
                        ref = str(
                            candidate.get("ref") or candidate.get("boi_id") or ""
                            if isinstance(candidate, dict)
                            else candidate or ""
                        ).strip()
                        resolved = self._record_for_ref(principal, ref) if ref else None
                        if resolved:
                            candidate_refs.append(str(resolved.record_id))
            try:
                graph = self.store.ontology_neighbors(
                    seeds,
                    depth=1,
                    limit=24,
                    employee_id=principal.employee_id,
                    team_ids=principal.teams,
                    include_all=principal.is_admin,
                )
                for edge in graph.get("edges") or []:
                    source_id = str(edge.get("source_id") or "")
                    target_id = str(edge.get("target_id") or "")
                    if source_id in seeds and target_id not in seeds:
                        candidate_refs.append(target_id)
                    elif target_id in seeds and source_id not in seeds:
                        candidate_refs.append(source_id)
            except Exception:
                pass
            return [
                records_by_id[ref]
                for ref in dict.fromkeys(candidate_refs)
                if ref in records_by_id and ref not in seeds
            ]

        current_work = self._current_work_records(principal, limit=3)
        current = current_work[0] if current_work else None
        page_anchor = self.learning.contexts.page_anchor(principal, page_ref)
        page_record = (
            self._record_for_ref(principal, page_anchor.ref)
            if page_anchor and page_anchor.resolved
            else None
        )

        recent_artifact: dict[str, Any] | None = None
        for work_session in self.store.list("work_sessions", employee_id=principal.employee_id, limit=10):
            artifact_id = str(work_session.get("active_artifact_id") or "")
            artifact = self.store.get("artifacts", artifact_id) if artifact_id else None
            if artifact and self._owns(principal, artifact):
                recent_artifact = artifact
                break

        def record_candidate(
            record: KnowledgeRecord,
            *,
            anchor: KnowledgeRecord | None = None,
        ) -> dict[str, Any]:
            return {
                "record_id": record.record_id,
                "title": record.title,
                "kind": record.kind,
                "metadata": record.metadata,
                "anchor_ref": anchor.record_id if anchor else "",
                "anchor_title": anchor.title if anchor else "",
            }

        def entrypoint_record(area: str) -> KnowledgeRecord | None:
            return next(
                (
                    item
                    for item in records
                    if area in (item.metadata.get("agent_entrypoint_areas") or [])
                ),
                None,
            )

        connected_cache: dict[str, list[KnowledgeRecord]] = {}

        def candidates_for(offer: Any) -> list[dict[str, Any]]:
            if offer.current_work_condition == "present" and current is None:
                return []
            if offer.current_work_condition == "absent" and current is not None:
                return []
            selected: list[dict[str, Any]]
            if offer.selector == "current_work":
                selected = [record_candidate(current)] if current else []
            elif offer.selector == "page_anchor":
                selected = [record_candidate(page_record)] if page_record else []
            elif offer.selector == "recent_artifact":
                if not recent_artifact:
                    selected = []
                else:
                    artifact_type = str(recent_artifact.get("artifact_type") or "")
                    if offer.artifact_type_prefixes and not any(
                        artifact_type.startswith(prefix)
                        for prefix in offer.artifact_type_prefixes
                    ):
                        selected = []
                    else:
                        selected = [
                            {
                                "record_id": str(recent_artifact.get("artifact_id") or ""),
                                "title": str(recent_artifact.get("title") or "최근 작업 결과"),
                                "kind": artifact_type,
                                "metadata": {},
                                "anchor_ref": "",
                                "anchor_title": "",
                            }
                        ]
            elif offer.selector == "connected_record":
                relationship_anchor = page_record or entrypoint_record(offer.anchor_entrypoint_area)
                anchor_ref = relationship_anchor.record_id if relationship_anchor else ""
                if anchor_ref and anchor_ref not in connected_cache:
                    connected_cache[anchor_ref] = directly_connected_records([anchor_ref])
                selected = [
                    record_candidate(item, anchor=relationship_anchor)
                    for item in connected_cache.get(anchor_ref, [])
                    if not offer.record_kinds or item.kind in offer.record_kinds
                ]
            elif offer.selector == "canonical_entrypoint":
                record = entrypoint_record(offer.entrypoint_area)
                selected = [record_candidate(record)] if record else []
            elif offer.selector == "current_or_page":
                record = current or page_record
                selected = [record_candidate(record)] if record else []
            else:
                selected = []
            if offer.record_kinds:
                selected = [item for item in selected if item.get("kind") in offer.record_kinds]
            return selected

        offers = sorted(
            self.registry.starter_offers(),
            key=lambda pair: (pair[1].priority, pair[1].offer_id),
        )
        for definition, offer in offers:
            for candidate in candidates_for(offer):
                before = len(suggestions)
                add(definition, offer, candidate)
                if len(suggestions) > before and offer.only_when_category_empty:
                    break

        suggestions.sort(key=lambda item: (item.priority, item.label))
        for index, item in enumerate(suggestions):
            item.featured = index < 4
        return suggestions[: max(1, min(limit, 18))]

    def create_starter_suggestion_set(
        self,
        principal: Principal,
        request: StarterSuggestionSetRequest,
    ) -> dict[str, Any]:
        starters = self.starter_suggestions(principal, page_ref=request.page_ref, limit=18)
        source = [item.model_dump(mode="json") for item in starters]
        fingerprint_payload = {
            "version": self.STARTER_SUGGESTION_VERSION,
            "employee_id": principal.employee_id,
            "teams": principal.teams,
            "page_ref": request.page_ref,
            "work_session_id": request.work_session_id,
            "source_revision": self.repository.source_signature(),
            "starters": [(item["suggestion_id"], item["subject_ref"], item["priority"]) for item in source],
        }
        fingerprint = hashlib.sha256(json.dumps(fingerprint_payload, ensure_ascii=False, default=str, sort_keys=True).encode("utf-8")).hexdigest()
        set_id = f"starterset_{fingerprint[:24]}"
        existing = self.store.get("starter_suggestion_sets", set_id)
        if existing and existing.get("employee_id") == principal.employee_id:
            return existing
        created = {
            "set_id": set_id,
            "employee_id": principal.employee_id,
            "page_ref": request.page_ref,
            "work_session_id": request.work_session_id,
            "context_fingerprint": fingerprint,
            "state": "updating" if source else "ready",
            "items": source,
            "refined": False,
            "created_at": now_iso(),
            "updated_at": now_iso(),
        }
        stored = self.store.put("starter_suggestion_sets", set_id, created)
        if source:
            threading.Thread(
                target=self._refine_starter_suggestion_set,
                args=(set_id, principal, source),
                name=f"boi-starter-refine-{set_id[-8:]}",
                daemon=True,
            ).start()
        return stored

    def _refine_starter_suggestion_set(
        self,
        set_id: str,
        principal: Principal,
        source: list[dict[str, Any]],
    ) -> None:
        schema = {
            "type": "object",
            "properties": {
                "items": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "suggestion_id": {"type": "string"},
                        },
                        "required": ["suggestion_id"],
                        "additionalProperties": False,
                    },
                }
            },
            "required": ["items"],
            "additionalProperties": False,
        }
        try:
            generated = self.model.generate_structured(
                system=(
                    "You only rank grounded BoI Agent starter question IDs. "
                    "Never rewrite text or invent a source, subject, capability, or current task. "
                    "Prefer personal current work, then page context, recent work, team knowledge, and reviewed public entrypoints."
                ),
                prompt=json.dumps(
                    {
                        "identity": {"teams": principal.teams, "roles": principal.roles},
                        "instructions": "Return only suggestion_id values in best order. Keep at least one item per available area.",
                        "candidates": [
                            {key: item.get(key) for key in ("suggestion_id", "area", "label", "prompt", "reason", "subject_title", "context_basis")}
                            for item in source
                        ],
                    },
                    ensure_ascii=False,
                ),
                schema=schema,
            )
            allowed = {str(item.get("suggestion_id")): item for item in source}
            refined: list[dict[str, Any]] = []
            used: set[str] = set()
            for row in generated.get("items") or []:
                suggestion_id = str(row.get("suggestion_id") or "")
                original = allowed.get(suggestion_id)
                if not original or suggestion_id in used:
                    continue
                refined.append(copy.deepcopy(original))
                used.add(suggestion_id)
            refined.extend(item for item in source if str(item.get("suggestion_id")) not in used)
            for index, item in enumerate(refined):
                item["featured"] = index < 4
            current = self.store.get("starter_suggestion_sets", set_id) or {}
            if current.get("employee_id") != principal.employee_id:
                return
            self.store.put(
                "starter_suggestion_sets",
                set_id,
                {**current, "state": "ready", "items": refined, "refined": True, "updated_at": now_iso()},
            )
        except Exception:
            current = self.store.get("starter_suggestion_sets", set_id) or {}
            if current.get("employee_id") == principal.employee_id:
                self.store.put(
                    "starter_suggestion_sets",
                    set_id,
                    {**current, "state": "ready", "refined": False, "updated_at": now_iso()},
                )

    def get_starter_suggestion_set(self, principal: Principal, set_id: str) -> dict[str, Any]:
        item = self.store.get("starter_suggestion_sets", set_id)
        if not item or item.get("employee_id") != principal.employee_id:
            raise HTTPException(status_code=404, detail="starter suggestion set not found")
        return item

    def user_work_profile(self, principal: Principal) -> dict[str, Any]:
        """Build the small, replaceable read model used for contextual turns."""

        current_work = self._current_work_records(principal, limit=5)
        sessions = self.store.list("work_sessions", employee_id=principal.employee_id, limit=12)
        sessions = [item for item in sessions if str(item.get("status") or "active") == "active"][:6]
        recent_artifacts: list[dict[str, Any]] = []
        used_sources: list[str] = []
        for session in sessions:
            artifact_id = str(session.get("active_artifact_id") or "")
            artifact = self.store.get("artifacts", artifact_id) if artifact_id else None
            if artifact and self._owns(principal, artifact):
                recent_artifacts.append(
                    {
                        "artifact_id": artifact_id,
                        "title": compact_text(str(artifact.get("title") or ""), 160),
                        "artifact_type": str(artifact.get("artifact_type") or ""),
                        "status": str(artifact.get("status") or "draft"),
                        "updated_at": str(artifact.get("updated_at") or artifact.get("created_at") or ""),
                    }
                )
            source_set = self.store.get("source_sets", self._source_set_id(str(session.get("session_id") or "")))
            if source_set:
                used_sources.extend(str(ref) for ref in source_set.get("auto_selected") or [] if str(ref))
                used_sources.extend(str(ref) for ref in source_set.get("pinned") or [] if str(ref))
        profile = {
            "profile_id": f"work-profile:{principal.employee_id}",
            "employee_id": principal.employee_id,
            "teams": list(principal.teams),
            "current_work": [
                {
                    "ref": item.record_id,
                    "title": compact_text(item.title, 160),
                    "status": item.status,
                    "url": item.url,
                }
                for item in current_work
            ],
            "recent_sessions": [
                {
                    "session_id": str(item.get("session_id") or ""),
                    "title": compact_text(str(item.get("title") or ""), 120),
                    "active_artifact_id": str(item.get("active_artifact_id") or ""),
                    "updated_at": str(item.get("updated_at") or ""),
                }
                for item in sessions
            ],
            "recent_artifacts": recent_artifacts[:6],
            "recently_used_source_refs": list(dict.fromkeys(used_sources))[:16],
            "source_revision": self.repository.source_signature(),
            "updated_at": now_iso(),
        }
        return self.store.put("user_work_profiles", principal.employee_id, profile)

    def _apply_starter_suggestion(self, principal: Principal, request: AgentTurnRequest) -> None:
        suggestion_id = str(request.suggestion_id or "").strip()
        if not suggestion_id:
            return
        suggestion = None
        suggestion_set_id = str(request.suggestion_set_id or "").strip()
        if suggestion_set_id:
            stored_set = self.store.get("starter_suggestion_sets", suggestion_set_id) or {}
            if stored_set.get("employee_id") == principal.employee_id:
                stored_item = next(
                    (item for item in stored_set.get("items") or [] if item.get("suggestion_id") == suggestion_id),
                    None,
                )
                if stored_item:
                    try:
                        suggestion = StarterSuggestion.model_validate(stored_item)
                    except Exception:
                        suggestion = None
        if suggestion is None:
            suggestion = next(
                (
                    item
                    for item in self.starter_suggestions(principal, page_ref=request.page_ref, limit=18)
                    if item.suggestion_id == suggestion_id
                ),
                None,
            )
        if suggestion is None:
            request.input_delta["_starter_suggestion_status"] = "stale"
            return
        request.question = suggestion.prompt
        request.capability_id = suggestion.capability_id
        request.input_delta.update(
            {
                "_starter_suggestion_status": "resolved",
                "_starter_suggestion_id": suggestion.suggestion_id,
                "_starter_subject_ref": suggestion.subject_ref,
                "_starter_source_refs": list(suggestion.source_refs),
                "_starter_result_kind": suggestion.result_kind,
                "_starter_graph_query_kind": suggestion.graph_query_kind,
                "user_effect": suggestion.user_effect,
                "operation": suggestion.operation.value,
                "work_view": suggestion.work_view,
            }
        )

    def get_work_session(self, principal: Principal, session_id: str) -> dict[str, Any]:
        return self._require_owned(principal, self.store.get("work_sessions", session_id), "work session")

    @staticmethod
    def _source_set_id(session_id: str) -> str:
        return f"sources_{session_id}"

    def _ensure_source_set(self, principal: Principal, session_id: str) -> dict[str, Any]:
        self.get_work_session(principal, session_id)
        source_set_id = self._source_set_id(session_id)
        existing = self.store.get("source_sets", source_set_id)
        if existing:
            return self._require_owned(principal, existing, "source set")
        created = {
            "source_set_id": source_set_id,
            "work_session_id": session_id,
            "employee_id": principal.employee_id,
            "auto_selected": [],
            "related": [],
            "pinned": [],
            "excluded": [],
            "attached": [],
            "snapshot_revision": self.repository.source_signature(),
            "revision": 1,
            "created_at": now_iso(),
            "updated_at": now_iso(),
        }
        return self.store.put("source_sets", source_set_id, created)

    def _source_item(self, principal: Principal, ref: str, *, state: str) -> dict[str, Any]:
        clean = str(ref or "").strip()
        records = self.repository.authoritative_records(principal, include_drafts=True)
        records.extend(self.repository.history_records(principal, include_seed=True))
        record = next((item for item in records if item.record_id == clean), None)
        if record:
            return {
                "source_ref": record.record_id,
                "title": record.title,
                "kind": record.kind,
                "summary": compact_text(record.description or record.text, 240),
                "url": record.url,
                "authority": record.authority,
                "state": state,
            }
        if clean.startswith("artifact_"):
            artifact = self.store.get("artifacts", clean) or {}
            if artifact and self._owns(principal, artifact):
                return {
                    "source_ref": clean,
                    "title": str(artifact.get("title") or "private 지식 노트"),
                    "kind": "note",
                    "summary": compact_text(str((artifact.get("draft") or {}).get("body") or artifact.get("preview") or ""), 240),
                    "url": f"/agent?session={artifact.get('work_session_id') or ''}&artifact={clean}",
                    "authority": "provisional",
                    "state": state,
                }
        return {
            "source_ref": clean,
            "title": clean,
            "kind": "external",
            "summary": "연결된 외부 참고 자료",
            "url": clean if clean.startswith(("http://", "https://", "/")) else "",
            "authority": "unreviewed",
            "state": state,
        }

    def get_source_set(self, principal: Principal, session_id: str) -> dict[str, Any]:
        source_set = self._ensure_source_set(principal, session_id)
        groups = {
            "used": [self._source_item(principal, ref, state="used") for ref in source_set.get("auto_selected") or []],
            "related": [self._source_item(principal, ref, state="related") for ref in source_set.get("related") or []],
            "pinned": [self._source_item(principal, ref, state="pinned") for ref in source_set.get("pinned") or []],
            "attached": [self._source_item(principal, ref, state="attached") for ref in source_set.get("attached") or []],
        }
        return {**source_set, "groups": groups}

    def patch_source_set(
        self,
        principal: Principal,
        session_id: str,
        request: SourceSetPatchRequest,
    ) -> dict[str, Any]:
        source_set = self._ensure_source_set(principal, session_id)
        current_revision = int(source_set.get("revision") or 1)
        if request.expected_revision != current_revision:
            raise HTTPException(
                status_code=409,
                detail={"status": "revision_conflict", "current_revision": current_revision, "source_set": self.get_source_set(principal, session_id)},
            )
        pinned = list(dict.fromkeys(str(item) for item in source_set.get("pinned") or [] if str(item).strip()))
        excluded = list(dict.fromkeys(str(item) for item in source_set.get("excluded") or [] if str(item).strip()))
        previous_pinned = list(pinned)
        previous_excluded = list(excluded)
        for ref in request.pin_refs:
            if ref not in pinned:
                pinned.append(ref)
            if ref in excluded:
                excluded.remove(ref)
        for ref in request.unpin_refs:
            if ref in pinned:
                pinned.remove(ref)
        for ref in request.exclude_refs:
            if ref not in excluded:
                excluded.append(ref)
            if ref in pinned:
                pinned.remove(ref)
        for ref in request.include_refs:
            if ref in excluded:
                excluded.remove(ref)
        next_revision = current_revision + 1
        user_change = {
            "from_revision": current_revision,
            "to_revision": next_revision,
            "pinned_added": [ref for ref in pinned if ref not in set(previous_pinned)],
            "pinned_removed": [ref for ref in previous_pinned if ref not in set(pinned)],
            "excluded_added": [ref for ref in excluded if ref not in set(previous_excluded)],
            "excluded_removed": [ref for ref in previous_excluded if ref not in set(excluded)],
            "consumed_by_run_id": "",
            "created_at": now_iso(),
        }
        source_set.update(
            {
                "pinned": pinned[:100],
                "excluded": excluded[:100],
                "auto_selected": [
                    ref for ref in source_set.get("auto_selected") or [] if ref not in set(excluded)
                ],
                "related": [
                    ref for ref in source_set.get("related") or [] if ref not in set(excluded)
                ],
                "attached": (
                    list(dict.fromkeys(str(item) for item in request.attached_refs if str(item).strip()))[:100]
                    if request.attached_refs is not None
                    else source_set.get("attached") or []
                ),
                "revision": next_revision,
                "last_user_change": user_change,
                "updated_at": now_iso(),
            }
        )
        self.store.put("source_sets", str(source_set["source_set_id"]), source_set)
        return self.get_source_set(principal, session_id)

    def _source_policy_context(
        self,
        principal: Principal,
        source_set: dict[str, Any],
    ) -> dict[str, Any]:
        """Return bounded, ACL-filtered source policy state for semantic planning.

        Source pin/exclude is a typed user interaction.  It changes admissible
        evidence, not the active topic by itself.  The planner needs that state
        explicitly; inferring it from question wording or from missing chunks
        made ordinary follow-ups spend their repair call and stop.
        """

        def visible_refs(values: Any) -> list[str]:
            return list(
                dict.fromkeys(
                    ref
                    for raw in values or []
                    if (ref := str(raw or "").strip())
                    and self._record_for_ref(principal, ref) is not None
                )
            )[:100]

        raw_change = (
            source_set.get("last_user_change")
            if isinstance(source_set.get("last_user_change"), dict)
            else {}
        )
        pending_change = (
            {
                "from_revision": int(raw_change.get("from_revision") or 0),
                "to_revision": int(raw_change.get("to_revision") or 0),
                "pinned_added": visible_refs(raw_change.get("pinned_added")),
                "pinned_removed": visible_refs(raw_change.get("pinned_removed")),
                "excluded_added": visible_refs(raw_change.get("excluded_added")),
                "excluded_removed": visible_refs(raw_change.get("excluded_removed")),
            }
            if raw_change and not str(raw_change.get("consumed_by_run_id") or "")
            else {}
        )
        return {
            "source_set_ref": str(source_set.get("source_set_id") or ""),
            "revision": int(source_set.get("revision") or 1),
            "pinned_source_refs": visible_refs(source_set.get("pinned")),
            "excluded_source_refs": visible_refs(source_set.get("excluded")),
            "pending_user_change": pending_change,
        }

    def _update_auto_sources(
        self,
        principal: Principal,
        session_id: str,
        evidence: list[EvidenceRef],
        attached_refs: list[str],
        *,
        used_refs: list[str] | None = None,
    ) -> dict[str, Any]:
        source_set = self._ensure_source_set(principal, session_id)
        excluded = {str(item) for item in source_set.get("excluded") or []}
        available_refs = [item.evidence_id for item in evidence if item.evidence_id not in excluded]
        used = [ref for ref in (used_refs or available_refs) if ref in available_refs]
        auto_selected = list(dict.fromkeys(used))
        related = [ref for ref in available_refs if ref not in set(auto_selected)]
        attached = list(source_set.get("attached") or [])
        for ref in attached_refs:
            if ref and ref not in attached:
                attached.append(ref)
        source_set.update(
            {
                "auto_selected": auto_selected,
                "related": related,
                "attached": attached[:100],
                "snapshot_revision": self.repository.source_signature(),
                "revision": int(source_set.get("revision") or 1) + 1,
                "updated_at": now_iso(),
            }
        )
        self.store.put("source_sets", str(source_set["source_set_id"]), source_set)
        return source_set

    def patch_work_session(
        self,
        principal: Principal,
        session_id: str,
        request: WorkSessionPatchRequest,
    ) -> dict[str, Any]:
        session = self.get_work_session(principal, session_id)
        current_revision = int(session.get("revision") or 1)
        if request.expected_revision != current_revision:
            raise HTTPException(
                status_code=409,
                detail={"status": "revision_conflict", "current_revision": current_revision, "session": session},
            )
        values = request.model_dump(exclude_unset=True)
        values.pop("expected_revision", None)
        for key, value in values.items():
            session[key] = value
        session.update(
            {
                "revision": current_revision + 1,
                "updated_at": now_iso(),
                "expires_at": (
                    session.get("expires_at")
                    if session.get("pinned")
                    else (datetime.now(timezone.utc) + timedelta(days=30)).isoformat()
                ),
            }
        )
        return self.store.put("work_sessions", session_id, session)

    def continue_work_run(
        self,
        principal: Principal,
        work_run_id: str,
        request: WorkRunContinueRequest,
    ) -> dict[str, Any]:
        run, candidates = self.learning.continue_run(principal, work_run_id, request)
        messages = {
            "completed": "완료된 모습과 확인할 근거가 충족되어 업무를 완료했습니다.",
            "waiting_human": "추가 확인이나 담당자 입력이 필요합니다.",
            "waiting_signal": "연결된 시스템의 확인 결과를 기다리고 있습니다.",
            "in_progress": "새로운 근거를 반영해 업무를 이어갑니다.",
            "stopped": "진전 없는 반복을 막기 위해 멈췄습니다. 다른 근거나 담당자 확인이 필요합니다.",
            "blocked": "업무를 이어가기 전에 보완할 항목이 있습니다.",
        }
        message = messages.get(str(run.get("status") or ""), "업무 진행 상태를 갱신했습니다.")
        session_id = str(run.get("work_session_id") or "")
        if session_id:
            session = self.store.get("work_sessions", session_id)
            if session and self._owns(principal, session):
                agent_run = self.store.get("runs", str(run.get("agent_run_id") or "")) or {}
                capability_id = str(agent_run.get("capability_id") or "")
                self._append_session_message(
                    principal,
                    session_id,
                    role="user",
                    display_text=request.delta.summary,
                    run_id=str(run.get("agent_run_id") or ""),
                    capability_id=capability_id,
                    work_run_id=work_run_id,
                )
                loop_state = {
                    "iteration_count": (run.get("loop") or {}).get("iteration_count") or 0,
                    "decision": run.get("decision") or "",
                    "status": run.get("status") or "",
                    "revision": run.get("revision") or 1,
                }
                self._append_session_message(
                    principal,
                    session_id,
                    role="assistant",
                    display_text=message,
                    run_id=str(run.get("agent_run_id") or ""),
                    capability_id=capability_id,
                    work_run_id=work_run_id,
                    loop_state=loop_state,
                    knowledge_candidates=candidates,
                )
                session.update(
                    {
                        "active_work_run_id": work_run_id,
                        "revision": int(session.get("revision") or 1) + 1,
                        "updated_at": now_iso(),
                    }
                )
                self.store.put("work_sessions", session_id, session)
        return {
            "work_run": run,
            "message": message,
            "knowledge_candidates": [item.model_dump(mode="json") for item in candidates],
        }

    def session_timeline(self, principal: Principal, session_id: str, *, limit: int = 100) -> dict[str, Any]:
        self.get_work_session(principal, session_id)
        items = [
            item
            for item in self.store.list("session_messages", employee_id=principal.employee_id, limit=5000)
            if item.get("session_id") == session_id
        ]
        items.sort(key=lambda item: str(item.get("created_at") or ""))
        items = items[-max(1, min(limit, 300)) :]
        items = [
            {
                **item,
                "display_html": (
                    str(item.get("display_html") or "")
                    or render_agent_markdown(str(item.get("display_text") or ""))
                ),
            }
            if item.get("role") == "assistant"
            else item
            for item in items
        ]
        return {"count": len(items), "items": items}

    def work_session_bundle(self, principal: Principal, session_id: str) -> dict[str, Any]:
        session = self.get_work_session(principal, session_id)
        artifact = None
        if session.get("active_artifact_id"):
            try:
                artifact = self.get_artifact(principal, str(session["active_artifact_id"]))
            except HTTPException:
                artifact = None
        return {
            "session": session,
            "timeline": self.session_timeline(principal, session_id)["items"],
            "active_artifact": artifact,
            "source_set": self.get_source_set(principal, session_id),
        }

    def delete_work_session(self, principal: Principal, session_id: str) -> dict[str, Any]:
        self.get_work_session(principal, session_id)
        deleted_messages = 0
        deleted_artifacts = 0
        for message in self.store.list("session_messages", employee_id=principal.employee_id, limit=5000):
            if message.get("session_id") == session_id:
                deleted_messages += int(self.store.delete("session_messages", str(message.get("message_id") or "")))
        for artifact in self.store.list("artifacts", employee_id=principal.employee_id, limit=5000):
            if artifact.get("work_session_id") != session_id or artifact.get("status") not in {"draft", "provisional"}:
                continue
            artifact_id = str(artifact.get("artifact_id") or "")
            deleted_artifacts += int(self.store.delete("artifacts", artifact_id))
            for revision in self.store.list("artifact_revisions", employee_id=principal.employee_id, limit=5000):
                if revision.get("artifact_id") == artifact_id:
                    self.store.delete("artifact_revisions", str(revision.get("revision_id") or ""))
        self.store.delete("work_sessions", session_id)
        self.store.delete("source_sets", self._source_set_id(session_id))
        return {
            "session_id": session_id,
            "status": "deleted",
            "deleted_messages": deleted_messages,
            "deleted_draft_artifacts": deleted_artifacts,
        }

    def _append_session_message(
        self,
        principal: Principal,
        session_id: str,
        *,
        role: str,
        display_text: str,
        run_id: str = "",
        capability_id: str = "",
        evidence_refs: list[EvidenceRef] | None = None,
        artifact_refs: list[ArtifactRef] | None = None,
        next_actions: list[NextAction] | None = None,
        citations: list[CitationRef] | None = None,
        related_questions: list[RelatedQuestion] | None = None,
        goal_plan_ref: str = "",
        source_set_ref: str = "",
        work_run_id: str = "",
        job_ref: str = "",
        loop_state: dict[str, Any] | None = None,
        harness_results: list[HarnessResult] | None = None,
        knowledge_candidates: list[KnowledgeCandidateRef] | None = None,
        grounded_claims: list[GroundedClaim] | None = None,
        answerability: AnswerabilityReport | None = None,
        topic_state_ref: str = "",
        used_source_refs: list[str] | None = None,
    ) -> dict[str, Any]:
        message_id = new_id("msg")
        payload = {
            "message_id": message_id,
            "session_id": session_id,
            "employee_id": principal.employee_id,
            "role": role,
            "display_text": str(display_text or ""),
            "display_html": render_agent_markdown(str(display_text or "")) if role == "assistant" else "",
            "run_id": run_id,
            "capability_id": capability_id,
            "evidence_refs": [
                {
                    "evidence_id": item.evidence_id,
                    "kind": item.kind,
                    "title": item.title,
                    "summary": item.summary,
                    "url": item.url,
                    "source": item.source,
                    "score": item.score,
                }
                for item in (evidence_refs or [])
            ],
            "artifact_refs": [item.model_dump(mode="json") for item in (artifact_refs or [])],
            "next_actions": [item.model_dump(mode="json") for item in (next_actions or [])],
            "citations": [item.model_dump(mode="json") for item in (citations or [])],
            "related_questions": [item.model_dump(mode="json") for item in (related_questions or [])],
            "goal_plan_ref": goal_plan_ref,
            "source_set_ref": source_set_ref,
            "work_run_id": work_run_id,
            "job_ref": job_ref,
            "loop_state": loop_state or {},
            "harness_results": [item.model_dump(mode="json") for item in (harness_results or [])],
            "knowledge_candidates": [item.model_dump(mode="json") for item in (knowledge_candidates or [])],
            "grounded_claims": [item.model_dump(mode="json") for item in (grounded_claims or [])],
            "answerability": answerability.model_dump(mode="json") if answerability else {},
            "topic_state_ref": topic_state_ref,
            "used_source_refs": list(
                dict.fromkeys(str(item).strip() for item in (used_source_refs or []) if str(item).strip())
            ),
            "created_at": now_iso(),
        }
        return self.store.put("session_messages", message_id, payload)

    def _session_context(self, principal: Principal, session: dict[str, Any]) -> dict[str, Any]:
        timeline = self.session_timeline(principal, str(session["session_id"]), limit=500)["items"]
        summary = str(session.get("conversation_summary") or "")
        artifact_outline: dict[str, Any] = {}
        artifact_id = str(session.get("active_artifact_id") or "")
        if artifact_id:
            artifact = self.store.get("artifacts", artifact_id) or {}
            draft = artifact.get("draft") if isinstance(artifact.get("draft"), dict) else {}
            artifact_outline = {
                "artifact_id": artifact_id,
                "artifact_type": artifact.get("artifact_type") or "",
                "title": artifact.get("title") or "",
                "capability_id": artifact.get("capability_id") or "",
                "revision": artifact.get("revision") or 1,
                "tasks": [
                    {
                        "task_id": item.get("task_id") or "",
                        "name": str(item.get("name") or ""),
                        "purpose": str(item.get("purpose") or ""),
                        "exit_criteria": item.get("exit_criteria") or [],
                    }
                    for item in (draft.get("tasks") or [])
                    if isinstance(item, dict)
                ],
            }
        recent_source_refs = list(
            dict.fromkeys(
                [
                    *[
                        str(ref)
                        for item in timeline
                        for ref in item.get("used_source_refs") or []
                        if str(ref or "").strip()
                    ],
                    *([artifact_id] if artifact_id else []),
                ]
            )
        )
        return {
            "summary": summary,
            "surface_context": dict(session.get("surface_context") or {}),
            "recent_messages": [
                {
                    "role": item.get("role"),
                    "text": str(item.get("display_text") or ""),
                    # Only sources admitted by verified claims or a grounded domain
                    # artifact may cross the turn boundary. Citation presence alone is
                    # not proof that the source supported the answer.
                    "source_refs": list(
                        dict.fromkeys(
                            str(ref)
                            for ref in item.get("used_source_refs") or []
                            if str(ref).strip()
                        )
                    ),
                    "grounded_claims": [
                        claim
                        for claim in item.get("grounded_claims") or []
                        if isinstance(claim, dict) and claim.get("support_status") == "supported"
                    ],
                    "artifact_refs": [
                        str(artifact.get("artifact_id") or "")
                        for artifact in item.get("artifact_refs") or []
                        if isinstance(artifact, dict) and artifact.get("artifact_id")
                    ],
                }
                for item in timeline
            ],
            "recent_source_refs": recent_source_refs,
            "active_artifact": artifact_outline,
            "topic_state": session.get("topic_state") if isinstance(session.get("topic_state"), dict) else {},
        }

    def _active_session_task(self, principal: Principal, session: dict[str, Any]) -> dict[str, Any]:
        artifact_id = str(session.get("active_artifact_id") or "")
        task_id = str(session.get("selected_task_id") or "")
        if not artifact_id or not task_id:
            return {}
        artifact = self.store.get("artifacts", artifact_id) or {}
        if not artifact or not self._owns(principal, artifact):
            return {}
        draft = artifact.get("draft") if isinstance(artifact.get("draft"), dict) else {}
        tasks = [item for item in draft.get("tasks") or [] if isinstance(item, dict)]
        return next((item for item in tasks if item.get("task_id") == task_id), None) or {}

    @staticmethod
    def _task_package_record(item: dict[str, Any]) -> KnowledgeRecord:
        package_id = str(item.get("task_package_id") or "")
        task_ref = str(item.get("task_ref") or "")
        task_id = str(item.get("task_id") or "")
        goal = compact_text(str(item.get("goal") or task_ref or task_id or "현재 업무"), 240)
        state = str(item.get("current_state") or item.get("status") or "waiting_agent")
        evidence_refs = [
            str(ref)
            for ref in item.get("evidence_refs") or []
            if str(ref).strip()
        ]
        return KnowledgeRecord(
            record_id=package_id,
            kind="task",
            title=goal,
            description=f"TaskPackage 상태: {state}",
            text="\n".join(
                [
                    f"Task: {task_ref or task_id}",
                    f"목표: {goal}",
                    f"상태: {state}",
                    f"수행 방식: {item.get('task_mode') or 'copilot'}",
                    f"실행자 계약: {item.get('executor_binding') or 'hybrid'}",
                    *( ["필수 근거: " + ", ".join(evidence_refs)] if evidence_refs else [] ),
                ]
            ),
            url=f"/api/v2/agent-tasks/{package_id}",
            source="runtime",
            authority="runtime",
            status=state,
            visibility="private",
            owner=str(item.get("employee_id") or ""),
            timestamp=str(item.get("updated_at") or item.get("created_at") or ""),
            metadata={
                **item,
                "answer_scope": "operational",
                "evidence_provenance": "operational_verified",
                "source_refs": evidence_refs,
            },
        )

    @staticmethod
    def _task_run_record(item: dict[str, Any]) -> KnowledgeRecord:
        task_run_id = str(item.get("task_run_id") or "")
        task_ref = str(item.get("task_ref") or item.get("task_id") or "현재 업무")
        state = str(item.get("status") or "waiting_agent")
        return KnowledgeRecord(
            record_id=task_run_id,
            kind="task",
            title=compact_text(task_ref, 240),
            description=f"TaskRun 상태: {state}",
            text="\n".join(
                [
                    f"Task: {task_ref}",
                    f"상태: {state}",
                    f"WorkflowRun: {item.get('workflow_run_id') or '-'}",
                ]
            ),
            url=f"/api/v2/agent-tasks/{item.get('task_package_id')}" if item.get("task_package_id") else "",
            source="runtime",
            authority="runtime",
            status=state,
            visibility="private",
            owner=str(item.get("employee_id") or ""),
            timestamp=str(item.get("updated_at") or item.get("created_at") or ""),
            metadata={
                **item,
                "answer_scope": "operational",
                "evidence_provenance": "operational_verified",
            },
        )

    def _current_work_records(
        self,
        principal: Principal,
        *,
        employee_id: str = "",
        limit: int = 50,
    ) -> list[KnowledgeRecord]:
        target_employee_id = employee_id or principal.employee_id
        if target_employee_id != principal.employee_id and not principal.is_admin:
            return []
        records = (
            list(self.repository.current_work(principal, limit=limit))
            if target_employee_id == principal.employee_id
            else []
        )
        package_rows = self.store.list(
            "agent_task_packages",
            employee_id=target_employee_id,
            limit=1000,
        )
        package_ids: set[str] = set()
        task_run_ids: set[str] = set()
        for item in package_rows:
            if not self._owns(principal, item):
                continue
            state = str(item.get("current_state") or item.get("status") or "")
            package_id = str(item.get("task_package_id") or "")
            if state not in CURRENT_TASK_STATES or not package_id:
                continue
            package_ids.add(package_id)
            if item.get("task_run_id"):
                task_run_ids.add(str(item["task_run_id"]))
            records.append(self._task_package_record(item))
        for item in self.store.list(
            "task_runs",
            employee_id=target_employee_id,
            limit=1000,
        ):
            if not self._owns(principal, item):
                continue
            task_run_id = str(item.get("task_run_id") or "")
            if (
                str(item.get("status") or "") not in CURRENT_TASK_STATES
                or not task_run_id
                or task_run_id in task_run_ids
                or str(item.get("task_package_id") or "") in package_ids
            ):
                continue
            records.append(self._task_run_record(item))
        def timestamp_key(item: KnowledgeRecord) -> float:
            try:
                return parse_time(item.timestamp).timestamp()
            except (TypeError, ValueError):
                return 0.0

        def work_identity(item: KnowledgeRecord) -> str:
            if item.record_id.startswith("active_action:"):
                metadata = item.metadata if isinstance(item.metadata, dict) else {}
                action_key = str(metadata.get("action_key") or item.title or "")
                context_ref = str(
                    metadata.get("task_ref")
                    or metadata.get("event_id")
                    or metadata.get("workflow_run_id")
                    or ""
                )
                return f"active_action:{action_key}:{context_ref}"
            return item.record_id

        ordered = sorted(records, key=timestamp_key, reverse=True)
        deduped: list[KnowledgeRecord] = []
        seen_work: set[str] = set()
        for item in ordered:
            identity = work_identity(item)
            if not identity or identity in seen_work:
                continue
            seen_work.add(identity)
            deduped.append(item)
        return deduped[: max(1, limit)]

    def _record_for_ref(self, principal: Principal, ref: str) -> Any | None:
        runtime_record = self.search.runtime_record(ref, principal)
        if runtime_record is not None:
            return runtime_record
        # Canonical Wiki identities have their own typed namespace and are
        # already ACL-filtered by the repository. Probing every operational
        # collection before resolving each graph edge source adds multiple
        # Postgres round-trips per displayed claim and cannot produce a more
        # authoritative match for the same ``boi:`` identity.
        if ref.startswith(("boi:public:", "boi:team:", "boi:private:")):
            records = self.repository.authoritative_records(
                principal,
                include_drafts=True,
            )
            records.extend(
                self.repository.history_records(
                    principal,
                    include_seed=True,
                )
            )
            return next(
                (item for item in records if item.record_id == ref),
                None,
            )
        # TaskPackage and TaskRun identifiers are typed store identities, not
        # naming conventions. External agents, imported workflow engines, and
        # evaluation harnesses may use UUIDs or human-readable IDs. Resolve an
        # exact row first and enforce ownership before projecting it; prefixes
        # are never an authorization or evidence boundary.
        package = self.store.get("agent_task_packages", ref)
        if package is not None:
            if not self._owns(principal, package):
                return None
            return self._task_package_record(package)
        task_run_ref = ref.removeprefix("runtime-task:")
        task_run = self.store.get("task_runs", task_run_ref)
        if task_run is not None:
            if not self._owns(principal, task_run):
                return None
            return self._task_run_record(task_run)
        operational_collections = (
            ("workflow_runs", "workflow_run", "workflow_ref", "/api/v2/workflow-runs/{ref}"),
            ("event_occurrences", "event_occurrence", "event_type", "/api/v2/event-runtime/occurrences/{ref}"),
            ("action_runs", "action_run", "action_ref", "/actions"),
            ("external_work_results", "external_work_result", "external_work_result_id", "/api/v2/workflow-runs/{work_run_id}"),
            ("outcomes", "outcome", "boi_ref", "/api/v2/outcomes/{outcome_ref}"),
            ("evidence_ledger", "evidence_ledger", "title", "/api/v2/workflow-runs/{work_run_id}"),
            ("event_detector_decisions", "detector_decision", "decision", "/api/v2/event-runtime/definitions/{definition_id}/detector-decisions"),
        )
        for collection, kind, title_field, url_template in operational_collections:
            lookup_ref = ref.removeprefix("boi:runtime:outcome:") if collection == "outcomes" else ref
            row = self.store.get(collection, lookup_ref)
            if row is None:
                continue
            if not self._owns(principal, row):
                return None
            title = str(row.get(title_field) or lookup_ref)
            lifecycle_status = str(row.get("status") or row.get("verification") or "active")
            summary = str(
                row.get("summary")
                or (row.get("result") or {}).get("summary")
                or title
            )
            outcome_ref = str(row.get("boi_ref") or lookup_ref)
            url = url_template.format(
                ref=lookup_ref,
                work_run_id=str(row.get("work_run_id") or row.get("workflow_run_id") or ""),
                outcome_ref=outcome_ref,
                definition_id=str(row.get("definition_id") or ""),
            )
            return KnowledgeRecord(
                record_id=ref,
                kind=kind,
                title=title,
                description=summary,
                text=(
                    f"{title}\n상태: {lifecycle_status}\n"
                    f"검증된 runtime record: {lookup_ref}"
                ),
                url=url,
                source="operational_ledger",
                authority="runtime",
                # Evidence availability is active even when the represented
                # workflow/action lifecycle has reached `completed`.
                status="active",
                visibility="private",
                owner=str(row.get("employee_id") or ""),
                timestamp=str(
                    row.get("updated_at")
                    or row.get("created_at")
                    or row.get("occurred_at")
                    or ""
                ),
                metadata={
                    "answer_scope": "operational",
                    "evidence_provenance": str(
                        row.get("provenance") or "operational_verified"
                    ),
                    "lifecycle_status": lifecycle_status,
                    "source_revision": str(
                        row.get("revision")
                        or row.get("updated_at")
                        or row.get("created_at")
                        or lookup_ref
                    ),
                },
            )
        usage = self.store.get("usage_records", ref)
        if usage is not None:
            visibility = str(usage.get("visibility") or "private")
            owner = str(usage.get("employee_id") or "")
            allowed_employees = {
                str(item)
                for item in usage.get("allowed_employee_ids") or []
                if str(item)
            }
            allowed_teams = {
                str(item)
                for item in usage.get("allowed_team_ids") or []
                if str(item)
            }
            visible = bool(
                principal.is_admin
                or visibility == "public"
                or owner == principal.employee_id
                or principal.employee_id in allowed_employees
                or (
                    visibility in {"team", "directory"}
                    and bool(allowed_teams & set(principal.teams))
                )
            )
            if not visible:
                return None
            purpose = str(usage.get("purpose") or "업무 수행")
            lines = [
                f"사번 {owner}의 검증된 업무 사용 기록입니다.",
                f"목적: {purpose}",
            ]
            for label, value in (
                ("Task", usage.get("task_ref")),
                ("Agent", usage.get("agent_definition_ref")),
                ("Agent 배포", usage.get("agent_deployment_ref")),
                ("System", usage.get("system_ref")),
                ("WorkRun", usage.get("work_run_id")),
            ):
                if str(value or "").strip():
                    lines.append(f"{label}: {value}")
            result_refs = [
                str(item)
                for item in usage.get("result_refs") or []
                if str(item).strip()
            ]
            if result_refs:
                lines.append("결과: " + ", ".join(result_refs))
            return KnowledgeRecord(
                record_id=ref,
                kind="usage_record",
                title=f"{owner or '구성원'} Agent·System 사용 기록",
                description=purpose,
                text="\n".join(lines),
                url=(
                    f"/api/v2/work-runs/{usage.get('work_run_id')}"
                    if usage.get("work_run_id")
                    else "/knowledge-graph"
                ),
                source="operational_ledger",
                authority="runtime",
                status="active",
                visibility=visibility,
                owner=owner,
                timestamp=str(usage.get("occurred_at") or ""),
                metadata={
                    "answer_scope": "operational",
                    "evidence_provenance": str(
                        usage.get("provenance") or "operational_verified"
                    ),
                    "source_revision": str(usage.get("source_revision") or ""),
                    "work_run_id": str(usage.get("work_run_id") or ""),
                    "task_ref": str(usage.get("task_ref") or ""),
                    "source_refs": result_refs,
                    "outcome_present": bool(result_refs),
                },
            )
        if ref.startswith("directory:person:"):
            employee_id = ref.removeprefix("directory:person:").strip()
            identity = next(
                (
                    item
                    for item in self.knowledge.directory_principals(principal)
                    if item.employee_id == employee_id
                ),
                None,
            )
            if identity is None:
                return None
            official_roles = [
                str(item)
                for item in identity.roles
                if str(item).strip() and not is_access_control_role(item)
            ]
            statements = [
                f"사번 {identity.employee_id}의 공식 소속 팀은 {team_id}입니다."
                for team_id in identity.teams
                if str(team_id).strip()
            ]
            statements.extend(
                f"사번 {identity.employee_id}의 공식 업무 역할은 {role_id}입니다."
                for role_id in official_roles
            )
            if not statements:
                statements.append(
                    f"사번 {identity.employee_id}은(는) Directory에 등록된 구성원입니다."
                )
            return KnowledgeRecord(
                record_id=ref,
                kind="directory_person",
                title=f"{identity.display_name or identity.employee_id} 공식 조직 정보",
                description="HR·Directory에서 확인한 공식 소속과 업무 역할입니다.",
                text="\n".join(statements),
                url=(
                    "/knowledge-graph?"
                    + urlencode({"source_ref": f"person:{identity.employee_id}"})
                ),
                source="directory",
                authority="canonical",
                status="active",
                visibility="public",
                owner="",
                timestamp="",
                metadata={
                    "answer_scope": "canonical",
                    "authority_scope": "company",
                    "evidence_provenance": "canonical_declared",
                    "employee_id": identity.employee_id,
                    "team_ids": list(identity.teams),
                    "official_roles": official_roles,
                },
            )
        # Completion records use a typed, stable namespace. Querying their
        # Postgres collection for every canonical Wiki/document ref turns a
        # bounded evidence pass into one network round-trip per source. Keep
        # the lookup data-driven by the record identity instead of probing an
        # unrelated collection and then falling through.
        completion = (
            self.store.get("completion_records", ref)
            if ref.startswith("completion_")
            else None
        )
        if completion:
            if not self._owns(principal, completion):
                return None
            work_run_id = str(completion.get("work_run_id") or "")
            task_ref = str(completion.get("task_ref") or "")
            summary = str(completion.get("summary") or "Task 완료 판단을 검증했습니다.")
            evidence_refs = [
                str(item)
                for item in completion.get("evidence_refs") or []
                if str(item).strip()
            ]
            evidence_line = (
                "\n\n검증 근거: " + ", ".join(evidence_refs)
                if evidence_refs
                else ""
            )
            return KnowledgeRecord(
                record_id=ref,
                kind="completion_record",
                title=f"{task_ref or 'Task'} 완료 판단",
                description=summary,
                text=(
                    f"Task: {task_ref or '-'}\n"
                    f"완료 판단: {summary}"
                    f"{evidence_line}"
                ),
                url=f"/api/v2/completion-records/{ref}",
                source="runtime",
                authority="verified",
                status="completed",
                visibility="private",
                owner=str(completion.get("employee_id") or ""),
                timestamp=str(completion.get("created_at") or ""),
                metadata={
                    "answer_scope": "operational",
                    "task_ref": task_ref,
                    "work_run_id": work_run_id,
                    "source_refs": evidence_refs,
                    "evidence_ledger_ids": completion.get("evidence_ledger_ids") or [],
                },
            )
        if ref.startswith("graph-evidence:"):
            row = self.store.get("graph_relation_evidence", ref)
            if not row:
                return None
            if str(row.get("employee_id") or "") != principal.employee_id and not principal.is_admin:
                return None
            return KnowledgeRecord(
                record_id=ref,
                kind="relationship",
                title=str(row.get("title") or "검증된 업무 관계"),
                description=str(row.get("summary") or ""),
                text=str(row.get("text") or row.get("summary") or ""),
                url=str(row.get("url") or "/knowledge-graph"),
                source="ontology",
                authority="reviewed",
                status="reviewed",
                visibility="private",
                owner=str(row.get("employee_id") or ""),
                timestamp=str(row.get("created_at") or ""),
                metadata={
                    "answer_scope": "operational",
                    "query_plan": row.get("query_plan") or {},
                    "underlying_source_refs": row.get("underlying_source_refs") or [],
                    "provenance": row.get("provenance") or [],
                },
            )
        records = self.repository.authoritative_records(principal, include_drafts=True)
        records.extend(self.repository.history_records(principal, include_seed=True))
        record = next((item for item in records if item.record_id == ref), None)
        if record is None and ref.startswith("action:"):
            # Action plans use the stable Catalog identity ``action:{key}``,
            # while the canonical OKF source may use its document BoI id and
            # declare the key in metadata. Resolve that typed identity through
            # the ACL-filtered repository instead of depending on a matching
            # filename/BoI id. The alias remains the evidence identity and the
            # canonical source is retained for provenance and navigation.
            action_key = ref.removeprefix("action:").strip()
            status_rank = {
                "active": 6,
                "published": 5,
                "reviewed": 4,
                "approved": 3,
                "poc": 2,
                "draft": 1,
            }
            authority_rank = {
                "canonical": 5,
                "published": 4,
                "reviewed": 3,
                "runtime": 2,
                "provisional": 1,
            }
            visibility_rank = {"public": 3, "team": 2, "private": 1}
            candidates = [
                item
                for item in records
                if item.kind == "action"
                and str((item.metadata or {}).get("action_key") or "").strip()
                == action_key
            ]
            if candidates:
                canonical_record = max(
                    candidates,
                    key=lambda item: (
                        status_rank.get(str(item.status or "").lower(), 0),
                        authority_rank.get(str(item.authority or "").lower(), 0),
                        visibility_rank.get(str(item.visibility or "").lower(), 0),
                        str(item.timestamp or ""),
                        str(item.record_id or ""),
                    ),
                )
                canonical_ref = str(canonical_record.record_id)
                record = replace(
                    canonical_record,
                    record_id=ref,
                    metadata={
                        **dict(canonical_record.metadata or {}),
                        "canonical_source_ref": canonical_ref,
                        "source_refs": list(
                            dict.fromkeys(
                                [
                                    canonical_ref,
                                    *[
                                        str(item)
                                        for item in (canonical_record.metadata or {}).get(
                                            "source_refs", []
                                        )
                                        if str(item)
                                    ],
                                ]
                            )
                        ),
                    },
                )
        if record:
            return record
        if not ref.startswith("candidate_"):
            return None
        candidate = self.store.get("knowledge_candidates", ref)
        if not candidate or candidate.get("status") not in {
            "provisional",
            "reviewed",
            "promotion_requested",
        }:
            return None
        if candidate.get("employee_id") != principal.employee_id and not principal.is_admin:
            return None
        return KnowledgeRecord(
            record_id=ref,
            kind="knowledge_candidate",
            title=str(candidate.get("title") or "업무에서 남긴 내용"),
            description=str(candidate.get("summary") or ""),
            text=str(candidate.get("reusable_lesson") or candidate.get("summary") or ""),
            url=f"/api/v2/knowledge-candidates/{ref}",
            source="knowledge_candidate",
            authority="reviewed" if candidate.get("status") == "reviewed" else "provisional",
            status=str(candidate.get("status") or "provisional"),
            visibility="private",
            owner=str(candidate.get("employee_id") or ""),
            timestamp=str(candidate.get("updated_at") or candidate.get("created_at") or ""),
            metadata={
                "answer_scope": "validation",
                "evidence_provenance": "private_provisional",
                "source_refs": candidate.get("source_refs") or [],
                "source_task_ref": candidate.get("source_task_ref") or "",
                "target_asset_ref": candidate.get("target_asset_ref") or "",
                "source_validation": candidate.get("source_validation") or {},
                "outcome_present": bool(
                    (
                        candidate.get("source_validation")
                        if isinstance(candidate.get("source_validation"), dict)
                        else {}
                    ).get("verified_refs")
                ),
            },
        )

    @staticmethod
    def _selection_display_text(value: str) -> str:
        """Normalize rendered Markdown text for exact selection verification."""

        text = re.sub(r"!\[([^\]]*)\]\([^)]+\)", r"\1", str(value or ""))
        text = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", text)
        text = re.sub(r"<[^>]+>", " ", text)
        # Inline Markdown emphasis/code markers are not rendered characters.
        # Replacing them with spaces changes punctuation adjacency (for
        # example `` `term`, `` becomes ``term ,``) and breaks an otherwise
        # exact browser selection. Structural block markers still delimit
        # visible segments and therefore become spaces.
        text = re.sub(r"[`*_~]", "", text)
        text = re.sub(r"[#>|]", " ", text)
        return re.sub(r"\s+", " ", text).strip()

    def _verified_page_selection(
        self,
        principal: Principal,
        *,
        page_anchor: Any,
        selected_text: str,
        selection_ref: str,
    ) -> dict[str, Any]:
        """Bind a browser selection to one ACL-visible page source and chunk.

        The browser text is never trusted as business evidence on its own. It
        becomes planner/context input only when its rendered form occurs
        exactly in the server-side page record visible to the caller.
        """

        selected = self._selection_display_text(selected_text)
        if not selected:
            return {}
        if not page_anchor or not page_anchor.resolved:
            return {"status": "unverified", "reason": "page_anchor_unresolved"}
        record = self._record_for_ref(principal, str(page_anchor.ref or ""))
        if record is None:
            return {"status": "unverified", "reason": "page_source_not_visible"}

        visible_lines: list[tuple[int, int, int, str, str]] = []
        visible_document = ""
        heading = ""
        for line_number, raw_line in enumerate(
            (record.text or record.description or record.title).splitlines(),
            start=1,
        ):
            if raw_line.lstrip().startswith("#"):
                heading = raw_line.lstrip("# ").strip()
            normalized_line = self._selection_display_text(raw_line)
            if not normalized_line:
                continue
            if visible_document:
                visible_document += " "
            start = len(visible_document)
            visible_document += normalized_line
            visible_lines.append(
                (start, len(visible_document), line_number, raw_line, heading)
            )

        match_start = visible_document.find(selected)
        if match_start < 0:
            return {
                "status": "unverified",
                "reason": "selection_not_in_page_source",
                "source_ref": record.record_id,
            }
        match_end = match_start + len(selected)
        matched_lines = [
            item
            for item in visible_lines
            if item[0] < match_end and item[1] > match_start
        ]
        if not matched_lines:
            return {
                "status": "unverified",
                "reason": "selection_line_mapping_failed",
                "source_ref": record.record_id,
            }
        start_line = matched_lines[0][2]
        end_line = matched_lines[-1][2]
        selected_heading = next(
            (item[4] for item in reversed(matched_lines) if item[4]),
            "",
        )
        chunk_id = "chunk:selection:" + hashlib.sha256(
            (
                f"{record.record_id}:{selection_ref}:{start_line}:{end_line}:"
                f"{selected}"
            ).encode("utf-8")
        ).hexdigest()[:24]
        return {
            "status": "verified",
            "selection_ref": selection_ref,
            "source_ref": record.record_id,
            "source_kind": record.kind,
            "source_title": record.title,
            "selected_text": compact_text(selected_text, 4000),
            "selected_text_hash": hashlib.sha256(selected.encode("utf-8")).hexdigest(),
            "chunk": {
                "chunk_id": chunk_id,
                "record_id": record.record_id,
                "kind": record.kind,
                "title": record.title,
                "heading": selected_heading,
                "content": compact_text(selected_text, 4000),
                "start_line": start_line,
                "end_line": end_line,
                "metadata": {
                    "url": record.url,
                    "status": record.status,
                    "selection_ref": selection_ref,
                },
            },
        }

    @staticmethod
    def _selection_after_source_policy(
        binding: dict[str, Any],
        excluded_refs: set[str],
    ) -> dict[str, Any]:
        """Remove selected source content before planning when the user excluded it."""

        source_ref = str(binding.get("source_ref") or "").strip()
        if binding.get("status") != "verified" or source_ref not in excluded_refs:
            return binding
        return {
            "status": "excluded",
            "reason": "user_excluded",
            "selection_ref": str(binding.get("selection_ref") or ""),
            "source_ref": source_ref,
        }

    @staticmethod
    def _planner_conversation_after_source_policy(
        context: dict[str, Any],
        excluded_refs: set[str],
    ) -> dict[str, Any]:
        """Keep discourse identity while removing excluded evidence from planner state."""

        if not excluded_refs:
            return context
        filtered = copy.deepcopy(context)
        removed_evidence = False

        def keep_claim(claim: Any) -> bool:
            nonlocal removed_evidence
            if not isinstance(claim, dict):
                return False
            source_refs = {
                str(ref)
                for ref in claim.get("source_refs") or []
                if str(ref).strip()
            }
            if source_refs & excluded_refs:
                removed_evidence = True
                return False
            return True

        messages: list[dict[str, Any]] = []
        for raw_message in filtered.get("recent_messages") or []:
            if not isinstance(raw_message, dict):
                continue
            message = dict(raw_message)
            original_refs = [
                str(ref)
                for ref in message.get("source_refs") or []
                if str(ref).strip()
            ]
            message["source_refs"] = [
                ref for ref in original_refs if ref not in excluded_refs
            ]
            if len(message["source_refs"]) != len(original_refs):
                removed_evidence = True
            message["grounded_claims"] = [
                claim
                for claim in message.get("grounded_claims") or []
                if keep_claim(claim)
            ]
            messages.append(message)
        filtered["recent_messages"] = messages

        recent_refs = [
            str(ref)
            for ref in filtered.get("recent_source_refs") or []
            if str(ref).strip()
        ]
        filtered["recent_source_refs"] = [
            ref for ref in recent_refs if ref not in excluded_refs
        ]
        if len(filtered["recent_source_refs"]) != len(recent_refs):
            removed_evidence = True

        topic_state = (
            dict(filtered.get("topic_state") or {})
            if isinstance(filtered.get("topic_state"), dict)
            else {}
        )
        topic_refs = [
            str(ref)
            for ref in topic_state.get("used_source_refs") or []
            if str(ref).strip()
        ]
        topic_state["used_source_refs"] = [
            ref for ref in topic_refs if ref not in excluded_refs
        ]
        if len(topic_state["used_source_refs"]) != len(topic_refs):
            removed_evidence = True
        topic_state["claims"] = [
            claim
            for claim in topic_state.get("claims") or []
            if keep_claim(claim)
        ]
        filtered["topic_state"] = topic_state
        if removed_evidence:
            # A free-form summary cannot be safely split by source. The typed
            # topic identities remain available, but the planner must rebuild
            # assertions from the still-admitted evidence set.
            filtered["summary"] = ""
            filtered["source_policy"] = {"excluded_evidence_removed": True}
        return filtered

    def _source_set_planner_hints(
        self,
        principal: Principal,
        source_set: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Expose ACL-visible pinned sources as bounded planner metadata."""

        excluded = {
            str(ref)
            for ref in source_set.get("excluded") or []
            if str(ref).strip()
        }
        refs = list(
            dict.fromkeys(
                str(ref)
                for ref in [
                    *(source_set.get("pinned") or []),
                    *(source_set.get("attached") or []),
                ]
                if str(ref).strip() and str(ref) not in excluded
            )
        )
        hints: list[dict[str, Any]] = []
        for ref in refs:
            record = self._record_for_ref(principal, ref)
            if record is None:
                continue
            chunks = chunks_for_record(record)
            chunk = chunks[0] if chunks else {}
            hints.append(
                {
                    "ref": record.record_id,
                    "title": record.title,
                    "kind": record.kind,
                    "summary": compact_text(record.description or record.text, 800),
                    "authority": record.authority,
                    "source": record.source,
                    "answer_scope": self.repository.answer_scope(record),
                    "authority_scope": self.repository.authority_scope(record),
                    "chunk_id": str(chunk.get("chunk_id") or ""),
                    "chunk_text": compact_text(
                        str(chunk.get("content") or chunk.get("text") or record.description),
                        4000,
                    ),
                    "is_primary": True,
                    "from_source_set": "pinned",
                }
            )
        return hints

    @staticmethod
    def _bind_verified_selection_evidence(
        evidence: list[EvidenceRef],
        binding: dict[str, Any],
    ) -> list[EvidenceRef]:
        if binding.get("status") != "verified" or not isinstance(binding.get("chunk"), dict):
            return evidence
        source_ref = str(binding.get("source_ref") or "")
        return [
            item.model_copy(
                update={
                    "score": max(1.0, float(item.score or 0.0)),
                    "metadata": {
                        **dict(item.metadata or {}),
                        "best_chunk": copy.deepcopy(binding["chunk"]),
                        "selection_ref": str(binding.get("selection_ref") or ""),
                        "selection_verified": True,
                        "selected_text_hash": str(
                            binding.get("selected_text_hash") or ""
                        ),
                    },
                }
            )
            if item.evidence_id == source_ref
            else item
            for item in evidence
        ]

    def _verified_selection_chunk_for_claim(
        self,
        *,
        record: Any,
        evidence_item: EvidenceRef | None,
        citation: CitationRef,
    ) -> dict[str, Any]:
        """Revalidate one server-bound browser selection for claim grounding.

        Selection chunks are intentionally not part of the canonical search
        index. They may participate in grounding only when the server-created
        evidence metadata, citation identity, source identity, content digest,
        and current ACL-visible source all agree exactly.
        """

        if evidence_item is None:
            return {}
        metadata = dict(evidence_item.metadata or {})
        chunk = metadata.get("best_chunk")
        if (
            metadata.get("selection_verified") is not True
            or not str(metadata.get("selection_ref") or "").strip()
            or not isinstance(chunk, dict)
            or evidence_item.evidence_id != record.record_id
            or str(chunk.get("record_id") or "") != record.record_id
            or not citation.chunk_id.startswith("chunk:selection:")
            or str(chunk.get("chunk_id") or "") != citation.chunk_id
        ):
            return {}

        content = str(chunk.get("content") or chunk.get("text") or "")
        selected = self._selection_display_text(content)
        expected_hash = str(metadata.get("selected_text_hash") or "")
        if (
            not selected
            or not expected_hash
            or hashlib.sha256(selected.encode("utf-8")).hexdigest()
            != expected_hash
        ):
            return {}
        source_text = self._selection_display_text(
            record.text or record.description or record.title
        )
        if selected not in source_text:
            return {}
        return chunk

    def _query_specific_primary_hints(
        self,
        principal: Principal,
        hints: list[dict[str, Any]],
        query: str,
        *,
        selection_binding: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        """Re-select the exact chunk for sources explicitly anchored by the user.

        Search ranking may promote a selected page after computing the generic
        candidate chunk. The page remains a useful scope anchor, but its
        evidence excerpt must answer the current question rather than inherit
        that stale chunk. ACL is re-applied through ``_record_for_ref`` before
        any source text is exposed to the planner.
        """

        refreshed: list[dict[str, Any]] = []
        for raw_hint in hints:
            hint = dict(raw_hint)
            if not bool(hint.get("is_primary")):
                refreshed.append(hint)
                continue
            record = self._record_for_ref(principal, str(hint.get("ref") or ""))
            if record is None:
                refreshed.append(hint)
                continue
            chunk = (
                copy.deepcopy((selection_binding or {}).get("chunk"))
                if (selection_binding or {}).get("status") == "verified"
                and str((selection_binding or {}).get("source_ref") or "")
                == record.record_id
                else best_chunk_for_query(record, query)
            )
            if chunk:
                hint["chunk_id"] = str(chunk.get("chunk_id") or "")
                hint["chunk_text"] = str(
                    chunk.get("content")
                    or chunk.get("text")
                    or record.description
                    or record.text
                )
                hint["heading"] = str(chunk.get("heading") or "")
                hint["start_line"] = int(chunk.get("start_line") or 0)
                hint["end_line"] = int(
                    chunk.get("end_line") or chunk.get("start_line") or 0
                )
                hint["query_specific_chunk"] = True
                if (selection_binding or {}).get("status") == "verified":
                    hint["selection_ref"] = str(
                        (selection_binding or {}).get("selection_ref") or ""
                    )
                    hint["selection_verified"] = True
            refreshed.append(hint)
        return refreshed

    def _semantic_entity_kind_for_ref(self, principal: Principal, ref: str) -> str:
        """Return the ACL-verified semantic type of a trusted entity ref.

        This classifies an already resolved identity; it does not interpret
        user wording or select a capability. Keeping it outside the planner
        prevents a model type-label mistake from changing the meaning of a
        verified WorkSession result.
        """

        clean = str(ref or "").strip()
        if not clean:
            return ""
        record = self._record_for_ref(principal, clean)
        if record is not None:
            if clean.startswith("active_action:") and any(
                item.record_id == clean
                for item in self._current_work_records(principal)
            ):
                # The history adapter stores action log rows as reusable
                # cases, while the current-work projection exposes an open
                # action as an actionable Task. Preserve that operational
                # state distinction in the semantic identity contract.
                return "task"
            return str(record.kind or "").strip()
        artifact = self.store.get("artifacts", clean) if clean.startswith("artifact_") else None
        if artifact and self._owns(principal, artifact):
            artifact_type = str(self._artifact_contract_type(artifact) or "")
            return {
                "sop_draft": "sop",
                "workflow_draft": "workflow",
                "business_event_draft": "business_event",
                "action_draft": "action",
                "skill_draft": "skill",
            }.get(artifact_type, "artifact")
        try:
            graph = self.store.ontology_neighbors(
                [clean],
                depth=1,
                limit=24,
                employee_id=principal.employee_id,
                team_ids=principal.teams,
                include_all=(
                    principal.is_admin
                    or "ontology.people.analytics" in principal.roles
                ),
            )
        except Exception:
            graph = {"nodes": []}
        graph_node = next(
            (
                item
                for item in graph.get("nodes") or []
                if str(item.get("node_id") or "") == clean
            ),
            None,
        )
        if graph_node is not None:
            return str(graph_node.get("node_type") or "").strip()
        if clean.startswith("person:"):
            employee_id = clean.removeprefix("person:")
            if any(
                item.employee_id == employee_id
                and (
                    principal.is_admin
                    or item.employee_id == principal.employee_id
                    or bool(set(item.teams) & set(principal.teams))
                )
                for item in self.knowledge.directory_principals(principal)
            ):
                return "person"
        if clean.startswith("team:"):
            team_id = clean.removeprefix("team:")
            if principal.is_admin or team_id in principal.teams:
                return "team"
        return ""

    def _verified_surface_targets(
        self,
        principal: Principal,
        surface_context: dict[str, str],
    ) -> dict[str, dict[str, str]]:
        """Resolve explicit UI/API refs without interpreting request language."""

        prefix_candidates = {
            "person_ref": ("person:",),
            "org_ref": ("team:", "org-unit:"),
            "task_ref": ("task:",),
            "event_ref": ("event:",),
            "action_ref": ("action:",),
            "workflow_ref": ("workflow:",),
            "agent_ref": ("agent:", "agent-deployment:"),
            "system_ref": ("system:",),
            "trace_ref": ("usage:", "outcome:"),
        }
        metadata_aliases = {
            "event_ref": ("event_id", "event_type"),
            "action_ref": ("action_key",),
            "workflow_ref": ("workflow_definition_key", "workflow_key"),
            "document_ref": ("boi_id",),
        }
        records: list[Any] | None = None
        resolved: dict[str, dict[str, str]] = {}
        for field, raw_value in surface_context.items():
            if field in {"page_ref", "selection_ref"}:
                continue
            raw_ref = str(raw_value or "").strip()
            if not raw_ref:
                continue
            candidates: list[str] = []
            if ":" not in raw_ref:
                # A surface may expose a catalog key rather than its typed
                # ontology identity. Prefer the field's verified namespace so
                # the same Action/Event/Person identity flows through planning,
                # retrieval and execution. The raw value remains a fallback for
                # runtime ids whose canonical form is intentionally unprefixed.
                candidates.extend(
                    f"{prefix}{raw_ref}"
                    for prefix in prefix_candidates.get(field, ())
                )
            candidates.append(raw_ref)
            selected_ref = ""
            selected_kind = ""
            for candidate in dict.fromkeys(candidates):
                kind = self._semantic_entity_kind_for_ref(principal, candidate)
                if kind:
                    selected_ref, selected_kind = candidate, kind
                    break
            if not selected_ref and field in metadata_aliases:
                if records is None:
                    records = self.repository.authoritative_records(
                        principal,
                        include_drafts=True,
                    )
                    records.extend(
                        self.repository.history_records(
                            principal,
                            include_seed=False,
                        )
                    )
                matches = [
                    item
                    for item in records
                    if any(
                        str((item.metadata or {}).get(alias) or "").strip()
                        == raw_ref
                        for alias in metadata_aliases[field]
                    )
                ]
                if len(matches) == 1:
                    selected_ref = str(matches[0].record_id)
                    selected_kind = str(matches[0].kind or "")
            if selected_ref and selected_kind:
                resolved[field] = {
                    "ref": selected_ref,
                    "kind": selected_kind,
                    "raw_ref": raw_ref,
                }
        return resolved

    @staticmethod
    def _evidence_from_record(record: Any, *, score: float = 1.0) -> EvidenceRef:
        return EvidenceRef(
            evidence_id=record.record_id,
            kind=record.kind,
            title=record.title,
            summary=record.description or compact_text(record.text, 360),
            url=record.url,
            source=record.source,
            authority=record.authority,
            score=score,
            metadata={"status": record.status},
        )

    @staticmethod
    def _prioritize_evidence(
        evidence: list[EvidenceRef],
        priority_refs: set[str],
        *,
        limit: int | None = None,
    ) -> list[EvidenceRef]:
        ordered = [
            *[item for item in evidence if item.evidence_id in priority_refs],
            *[item for item in evidence if item.evidence_id not in priority_refs],
        ]
        return ordered[:limit] if limit is not None else ordered

    @staticmethod
    def _bound_context_evidence(
        evidence: list[EvidenceRef],
        handler_config: dict[str, Any],
        *,
        protected_refs: set[str] | None = None,
    ) -> tuple[list[EvidenceRef], list[str], int]:
        """Compile the Catalog's recall-to-context boundary.

        Retrieval may retain a wider ACL/policy-filtered candidate set for
        diagnostics and pageable results.  The WorkContext, citations, and
        answer call should only process the bounded set declared by the
        capability.  Explicit page/selection/topic/result bindings are kept
        ahead of ranked recall and are never silently discarded by the base
        limit.
        """

        raw_limit = handler_config.get("max_context_sources")
        if raw_limit in {None, ""}:
            return list(evidence), [], 0
        try:
            configured_limit = max(1, min(int(raw_limit), 50))
        except (TypeError, ValueError):
            return list(evidence), [], 0
        protected = {str(ref) for ref in (protected_refs or set()) if str(ref)}
        ordered = AgentV2Service._prioritize_evidence(evidence, protected)
        effective_limit = max(
            configured_limit,
            sum(1 for item in ordered if item.evidence_id in protected),
        )
        selected = ordered[:effective_limit]
        excluded = [
            item.evidence_id
            for item in ordered[effective_limit:]
            if item.evidence_id
        ]
        return selected, excluded, effective_limit

    @staticmethod
    def _merge_context_evidence(
        context: WorkContextPack,
        selected: list[EvidenceRef],
        *,
        limit: int | None = None,
    ) -> None:
        """Keep late-bound domain evidence inside the original context contract.

        Some deterministic domain readers, such as the ontology query service,
        resolve their exact provenance after the initial hybrid recall. Those
        sources still have to be part of the selected WorkContextPack before
        they can become citations or Evidence Ledger entries.
        """

        merged = list(
            {
                item.evidence_id: item
                for item in [*selected, *context.evidence_refs]
                if item.evidence_id
            }.values()
        )
        if limit is not None:
            merged = merged[:limit]
        context.evidence_refs = merged
        context.evidence_summary = {
            **context.evidence_summary,
            "available": [item.evidence_id for item in merged],
        }
        context.manifest["evidence_count"] = len(merged)
        if context.context_manifest is None:
            return
        context.context_manifest.selected_refs = [item.evidence_id for item in merged]
        context.context_manifest.provenance = {
            item.evidence_id: {
                "source": item.source,
                "authority": item.authority,
                "url": item.url,
            }
            for item in merged
        }

    def _apply_source_set(
        self,
        principal: Principal,
        session_id: str,
        evidence: list[EvidenceRef],
        *,
        page_ref: str,
        context_refs: list[str] | None = None,
    ) -> list[EvidenceRef]:
        source_set = self._ensure_source_set(principal, session_id)
        excluded = {str(item) for item in source_set.get("excluded") or []}
        selected = [item for item in evidence if item.evidence_id not in excluded]
        seen = {item.evidence_id for item in selected}

        records = self.repository.authoritative_records(principal, include_drafts=True)
        page_anchor = self.learning.contexts.page_anchor(principal, page_ref)
        page_record = next(
            (item for item in records if page_anchor and page_anchor.resolved and item.record_id == page_anchor.ref),
            None,
        )
        ordered_refs = [page_record.record_id] if page_record else []
        ordered_refs.extend(str(item) for item in (context_refs or []) if str(item).strip())
        ordered_refs.extend(str(item) for item in source_set.get("pinned") or [])
        ordered_refs = list(dict.fromkeys(ordered_refs))
        priority: list[EvidenceRef] = []
        for ref in ordered_refs:
            if not ref or ref in excluded:
                continue
            existing = next((item for item in selected if item.evidence_id == ref), None)
            if existing:
                selected.remove(existing)
                priority.append(existing)
                continue
            record = self._record_for_ref(principal, ref)
            if record:
                priority.append(self._evidence_from_record(record, score=1.0))
                seen.add(ref)
                continue
            artifact = self.store.get("artifacts", ref) if ref.startswith("artifact_") else None
            if artifact and self._owns(principal, artifact):
                body = str((artifact.get("draft") or {}).get("body") or artifact.get("preview") or "")
                priority.append(
                    EvidenceRef(
                        evidence_id=ref,
                        kind="note",
                        title=str(artifact.get("title") or "private 지식 노트"),
                        summary=body,
                        url=f"/agent?session={session_id}&artifact={ref}",
                        source="private_note",
                        authority="provisional",
                        score=1.0,
                    ),
                )
                seen.add(ref)
        return [*priority, *selected]

    def _continued_artifact_source_refs(
        self,
        principal: Principal,
        *,
        session: dict[str, Any],
        intent: WorkIntent,
        source_set: dict[str, Any],
        active_artifact: dict[str, Any] | None,
    ) -> list[str]:
        """Freeze a grounded result's sources when it becomes an artifact.

        A topic-continuing draft/transform is a projection of the verified
        result already shown to the user. Broad lexical retrieval may still
        help planning, but it must not silently become an input to the draft.
        Explicitly pinned/attached sources and the selected typed context stay
        eligible. ACL and source-set exclusions are applied before returning.
        """

        if intent.topic_mode != "continue" or intent.user_effect not in {
            "draft",
            "transform",
        }:
            return []
        topic_state = (
            session.get("topic_state")
            if isinstance(session.get("topic_state"), dict)
            else {}
        )
        supported_refs: set[str] = set()
        for claim in topic_state.get("claims") or []:
            if (
                not isinstance(claim, dict)
                or claim.get("support_status") != "supported"
                or not claim.get("supporting_chunk_ids")
            ):
                continue
            supported_refs.update(
                str(ref)
                for ref in claim.get("source_refs") or []
                if str(ref).strip()
            )
        prior_refs = [
            str(ref)
            for ref in topic_state.get("used_source_refs") or []
            if str(ref).strip() and str(ref) in supported_refs
        ]
        artifact_refs: list[str] = []
        if active_artifact and self._owns(principal, active_artifact):
            artifact_refs.extend(
                str(ref)
                for ref in active_artifact.get("source_refs") or []
                if str(ref).strip()
            )
            artifact_refs.extend(
                str(item.get("evidence_id") or "")
                for item in active_artifact.get("evidence_ledger") or []
                if isinstance(item, dict) and str(item.get("evidence_id") or "").strip()
            )
        inherited_refs = list(dict.fromkeys([*prior_refs, *artifact_refs]))
        if not inherited_refs:
            return []
        explicit_refs = [
            *intent.context_refs,
            intent.target_ref,
            *(source_set.get("pinned") or []),
            *(source_set.get("attached") or []),
        ]
        excluded = {str(ref) for ref in source_set.get("excluded") or [] if str(ref)}
        selected: list[str] = []
        for raw_ref in [*inherited_refs, *explicit_refs]:
            ref = str(raw_ref or "").strip()
            if not ref or ref in excluded or ref in selected:
                continue
            record = self._record_for_ref(principal, ref)
            artifact = self.store.get("artifacts", ref) if ref.startswith("artifact_") else None
            if record is None and not (artifact and self._owns(principal, artifact)):
                continue
            selected.append(ref)
        return selected

    def _citations_for_evidence(
        self,
        principal: Principal,
        session_id: str,
        query: str,
        evidence: list[EvidenceRef],
    ) -> list[CitationRef]:
        citations: list[CitationRef] = []
        cited_source_refs: set[str] = set()
        for item in evidence:
            if not item.evidence_id or item.evidence_id in cited_source_refs:
                continue
            record = self._record_for_ref(principal, item.evidence_id)
            if record:
                chunk = item.metadata.get("best_chunk") if isinstance(item.metadata.get("best_chunk"), dict) else {}
                if not chunk or str(chunk.get("record_id") or "") != record.record_id:
                    chunk = best_chunk_for_query(record, query)
                # A citation excerpt must preserve the selected chunk rather
                # than cutting off the exact row or statement that supports a
                # displayed claim. Search chunks are bounded independently.
                excerpt = compact_text(
                    str(chunk.get("content") or record.description or record.text),
                    1_600,
                )
                chunk_id = str(chunk.get("chunk_id") or "")
                heading = str(chunk.get("heading") or "")
                start_line = int(chunk.get("start_line") or 0)
                end_line = int(chunk.get("end_line") or start_line)
                target = record.url
                kind = record.kind
                title = record.title
            else:
                artifact = self.store.get("artifacts", item.evidence_id) if item.evidence_id.startswith("artifact_") else None
                if not artifact or not self._owns(principal, artifact):
                    continue
                body = str((artifact.get("draft") or {}).get("body") or artifact.get("preview") or "")
                excerpt = compact_text(body, 520)
                chunk_id = ""
                heading = ""
                start_line = 1
                end_line = max(1, len(body.splitlines()))
                target = f"/agent?session={session_id}&artifact={item.evidence_id}"
                kind = "note"
                title = str(artifact.get("title") or item.title)
            citation_id = new_id("cite")
            separator = "&" if "?" in target else "?"
            citation = CitationRef(
                citation_id=citation_id,
                source_ref=item.evidence_id,
                chunk_id=chunk_id,
                title=title,
                heading=heading,
                excerpt=excerpt,
                target_url=f"{target}{separator}citation={citation_id}" if target else "",
                start_line=start_line,
                end_line=end_line,
                kind=kind,
                resolved_source=ResolvedSourceRef(
                    source_ref=item.evidence_id,
                    title=title,
                    canonical_url=target,
                    source_kind=kind,
                    navigation_state="navigable" if target else "unresolved",
                ),
            )
            self.store.put(
                "citations",
                citation_id,
                {
                    **citation.model_dump(mode="json"),
                    "employee_id": principal.employee_id,
                    "work_session_id": session_id,
                    "created_at": now_iso(),
                },
            )
            citations.append(citation)
            cited_source_refs.add(item.evidence_id)
        return citations

    def _grounded_answer_hints(
        self,
        principal: Principal,
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
    ) -> list[dict[str, Any]]:
        """Bind final Catalog evidence to the exact chunks exposed to users."""

        citation_by_source = {
            str(item.source_ref): item
            for item in citations
            if item.source_ref and item.chunk_id and item.excerpt
        }
        hints: list[dict[str, Any]] = []
        for item in evidence:
            citation = citation_by_source.get(str(item.evidence_id))
            if citation is None:
                continue
            record = self._record_for_ref(principal, str(item.evidence_id))
            if record is None:
                continue
            metadata = dict(item.metadata or {})
            selected_chunk = (
                metadata.get("best_chunk")
                if isinstance(metadata.get("best_chunk"), dict)
                else {}
            )
            selection_verified = bool(
                metadata.get("selection_verified") is True
                and str(metadata.get("selection_ref") or "").strip()
                and citation.chunk_id.startswith("chunk:selection:")
                and str(selected_chunk.get("chunk_id") or "")
                == citation.chunk_id
            )
            hints.append(
                {
                    "ref": item.evidence_id,
                    "title": item.title or record.title,
                    "kind": item.kind or record.kind,
                    "summary": item.summary or record.description,
                    "authority": item.authority or record.authority,
                    "source": item.source or record.source,
                    "answer_scope": self.repository.answer_scope(record),
                    "authority_scope": self.repository.authority_scope(record),
                    "chunk_id": citation.chunk_id,
                    "chunk_text": citation.excerpt,
                    "is_primary": False,
                    "selection_verified": selection_verified,
                    "selection_ref": (
                        str(metadata.get("selection_ref") or "")
                        if selection_verified
                        else ""
                    ),
                }
            )
        return hints

    def get_citation(self, principal: Principal, citation_id: str) -> dict[str, Any]:
        citation = self._require_owned(principal, self.store.get("citations", citation_id), "citation")
        source_ref = str(citation.get("source_ref") or "")
        if source_ref.startswith("artifact_"):
            artifact = self.store.get("artifacts", source_ref)
            if not artifact or not self._owns(principal, artifact):
                raise HTTPException(status_code=403, detail="citation source is no longer accessible")
        elif not self._record_for_ref(principal, source_ref):
            raise HTTPException(status_code=403, detail="citation source is no longer accessible")
        return citation

    def _model_related_questions(
        self,
        principal: Principal,
        session: dict[str, Any],
        raw_questions: Any,
        citations: list[CitationRef],
    ) -> list[RelatedQuestion]:
        citation_order = list(citations)
        if not citation_order or not isinstance(raw_questions, list):
            return []
        session_id = str(session.get("session_id") or "")
        timeline = (
            self.session_timeline(principal, session_id, limit=6).get("items") or []
            if session_id and self.store.get("work_sessions", session_id)
            else []
        )
        recent = {
            str(item.get("display_text") or "").strip().lower()
            for item in timeline
        }
        has_work_context = bool(
            session.get("active_artifact_id")
            or session.get("active_work_run_id")
            or session.get("selected_task_id")
        )
        result: list[RelatedQuestion] = []
        for item in raw_questions[:3]:
            if not isinstance(item, dict):
                continue
            kind = str(item.get("kind") or "understand")
            if kind not in {"understand", "connect", "apply"} or (kind == "apply" and not has_work_context):
                continue
            label = compact_text(str(item.get("label") or ""), 160)
            question = compact_text(str(item.get("question") or ""), 1000)
            numbers = list(
                dict.fromkeys(
                    int(number)
                    for number in item.get("source_numbers") or []
                    if isinstance(number, int) and 1 <= number <= len(citation_order)
                )
            )
            if not label or not question or not numbers or question.lower() in recent:
                continue
            result.append(
                RelatedQuestion(
                    question_id=new_id("question"),
                    kind=kind,  # type: ignore[arg-type]
                    label=label,
                    question=question,
                    source_refs=list(dict.fromkeys(citation_order[number - 1].source_ref for number in numbers)),
                )
            )
        return result

    def _create_goal_plan(
        self,
        principal: Principal,
        session: dict[str, Any],
        question: str,
        definition: CapabilityDefinition,
        route: dict[str, Any],
        intent: WorkIntent,
        *,
        persist: bool = True,
    ) -> dict[str, Any]:
        operation_labels = {
            WorkOperation.understand: "업무 맥락과 근거 이해",
            WorkOperation.compare: "근거와 차이 비교",
            WorkOperation.create: "검토 가능한 초안 생성",
            WorkOperation.refine: "현재 결과 개선",
            WorkOperation.connect: "검증된 관계 연결",
            WorkOperation.validate: "완료 조건과 근거 검증",
            WorkOperation.test: "적용 전 시험",
            WorkOperation.run: "확인된 실행 수행",
            WorkOperation.observe: "실행 결과와 상태 확인",
            WorkOperation.complete: "완료 조건 충족 확인",
            WorkOperation.capture: "재사용할 결과 정리",
            WorkOperation.promote: "공유 검토 요청",
        }
        read_operations = {
            WorkOperation.understand,
            WorkOperation.compare,
            WorkOperation.validate,
            WorkOperation.test,
            WorkOperation.observe,
        }
        guarded_operations = {WorkOperation.run, WorkOperation.complete, WorkOperation.promote}
        pipeline = list(intent.operation_plan or [intent.operation])
        steps: list[GoalStep] = []
        custom_labels = definition.handler_config.get("operation_labels")
        custom_labels = custom_labels if isinstance(custom_labels, dict) else {}
        for index, operation in enumerate(pipeline):
            operation_class = (
                "deep"
                if definition.deep and operation in {WorkOperation.create, WorkOperation.compare}
                else "guarded"
                if operation in guarded_operations
                else "read"
                if operation in read_operations
                else "draft"
            )
            steps.append(
                GoalStep(
                    step_id=f"{operation.value}_{index + 1}",
                    capability_id=definition.capability_id,
                    label=compact_text(
                        str(custom_labels.get(operation.value) or operation_labels[operation]),
                        120,
                    ),
                    operation=operation_class,  # type: ignore[arg-type]
                    semantic_operation=operation,
                    depends_on=[steps[-1].step_id] if steps else [],
                )
            )
        route_class = "deep" if definition.deep else "workflow" if len(steps) > 2 or intent.operation != WorkOperation.understand else "quick"
        goal_plan_id = new_id("goal") if persist else ""
        plan = {
            "goal_plan_id": goal_plan_id,
            "employee_id": principal.employee_id,
            "work_session_id": session["session_id"],
            "interpreted_goal": intent.resolved_goal or question,
            "route_class": route_class,
            "confidence": intent.confidence,
            "route_source": route.get("source") or "auto",
            "assumptions": [],
            "asset_kind": intent.asset_kind.value,
            "operation_plan": [item.value for item in intent.operation_plan],
            "desired_outcome": intent.desired_outcome,
            "steps": [item.model_dump(mode="json") for item in steps],
            "status": "planned",
            "revision": 1,
            "created_at": now_iso(),
            "updated_at": now_iso(),
            "_transient_turn": not persist,
        }
        return self.store.put("goal_plans", goal_plan_id, plan) if persist else plan

    def _finish_goal_plan(
        self,
        goal_plan: dict[str, Any],
        *,
        evidence: list[EvidenceRef],
        artifacts: list[ArtifactRef],
        queued: bool,
        response_status: str,
        plan_ref: str,
        intent: WorkIntent,
        work_run: dict[str, Any],
    ) -> dict[str, Any]:
        harness_blocked = any(
            isinstance(item, dict) and item.get("status") == "blocked"
            for item in work_run.get("harness_results") or []
        )
        work_status = str(work_run.get("status") or "")
        candidate_ready = bool(work_run.get("knowledge_candidate_ids"))
        steps = []
        raw_steps = list(goal_plan.get("steps") or [])
        current_index = next(
            (
                index
                for index, item in enumerate(raw_steps)
                if str(item.get("semantic_operation") or "understand") == intent.operation.value
            ),
            len(raw_steps) - 1,
        )
        for index, item in enumerate(raw_steps):
            step = dict(item)
            semantic_operation = str(step.get("semantic_operation") or "understand")
            is_current = semantic_operation == intent.operation.value
            if work_status == "blocked" and is_current:
                step_status = "blocked"
            elif queued and step.get("operation") == "deep" and is_current:
                step_status = "queued"
            elif semantic_operation == WorkOperation.validate.value and harness_blocked:
                step_status = "blocked" if harness_blocked else "completed"
            elif semantic_operation == WorkOperation.capture.value:
                step_status = "completed" if candidate_ready else "pending"
            elif is_current:
                if response_status == "failed":
                    step_status = "failed"
                elif response_status == "needs_input":
                    step_status = "waiting_input"
                elif plan_ref and intent.operation in {
                    WorkOperation.test,
                    WorkOperation.run,
                    WorkOperation.complete,
                    WorkOperation.promote,
                }:
                    step_status = "waiting_confirmation"
                elif work_status == "waiting_review" and intent.operation in {WorkOperation.refine, WorkOperation.connect}:
                    step_status = "waiting_review"
                else:
                    step_status = "completed"
            elif index < current_index:
                step_status = "completed"
            else:
                step_status = "pending"
            step["status"] = step_status
            step["evidence_refs"] = [value.evidence_id for value in evidence]
            step["artifact_refs"] = [value.artifact_id for value in artifacts[:3]]
            steps.append(step)
        statuses = {str(item.get("status") or "pending") for item in steps}
        if "failed" in statuses:
            plan_status = "failed"
        elif "blocked" in statuses:
            plan_status = "blocked"
        elif "waiting_input" in statuses:
            plan_status = "waiting_input"
        elif "waiting_confirmation" in statuses:
            plan_status = "waiting_confirmation"
        elif "waiting_review" in statuses:
            plan_status = "waiting_review"
        elif "queued" in statuses:
            plan_status = "queued"
        elif "pending" in statuses or "running" in statuses:
            plan_status = "running"
        else:
            plan_status = "completed"
        goal_plan.update(
            {
                "steps": steps,
                "status": plan_status,
                "revision": int(goal_plan.get("revision") or 1) + 1,
                "updated_at": now_iso(),
            }
        )
        if goal_plan.get("_transient_turn"):
            return goal_plan
        return self.store.put("goal_plans", str(goal_plan["goal_plan_id"]), goal_plan)

    def get_goal_plan(self, principal: Principal, goal_plan_id: str) -> dict[str, Any]:
        return self._require_owned(principal, self.store.get("goal_plans", goal_plan_id), "goal plan")

    def _advance_goal_plan_after_domain_result(
        self,
        principal: Principal,
        *,
        work_run_id: str,
        domain_operation: str,
    ) -> dict[str, Any]:
        if not work_run_id:
            return {}
        run = self.learning.get_run(principal, work_run_id)
        goal_plan_id = str(run.get("goal_plan_id") or "")
        if not goal_plan_id:
            return {}
        goal_plan = self.get_goal_plan(principal, goal_plan_id)
        steps = []
        transitioned = False
        run_completed = str(run.get("status") or "") == "completed"
        for raw in goal_plan.get("steps") or []:
            step = dict(raw)
            step_status = str(step.get("status") or "")
            if (
                run_completed
                and step_status not in {"failed", "blocked", "cancelled", "stopped"}
            ) or step_status in {"waiting_confirmation", "waiting_review"}:
                step["status"] = "completed"
                step["domain_result"] = {
                    "operation": domain_operation,
                    "confirmed": True,
                }
                transitioned = True
            steps.append(step)
        if not transitioned:
            return goal_plan
        statuses = {str(item.get("status") or "pending") for item in steps}
        goal_plan.update(
            {
                "steps": steps,
                "status": "completed" if statuses <= {"completed"} else "running",
                "revision": int(goal_plan.get("revision") or 1) + 1,
                "updated_at": now_iso(),
            }
        )
        return self.store.put("goal_plans", goal_plan_id, goal_plan)

    def readiness(self, principal: Principal, *, probe_model: bool = False) -> dict[str, Any]:
        store_state = self.store.health()
        if self.settings.lmstudio_require_preloaded_models and (
            probe_model
            or not self._model_residency_checked_at
            or time.monotonic() - self._model_residency_checked_at >= 30.0
        ):
            self.inspect_model_residency()
        runtime_profile = inspect_model_runtime_profile(
            self.settings,
            residency_state=self.model_residency,
        )
        model_state = self.model.preflight() if probe_model else self.model.readiness()
        heartbeats = self.store.list("worker_heartbeats", limit=20)
        worker_ready = False
        latest_worker = ""
        latest_worker_row: dict[str, Any] = {}
        ready_worker_row: dict[str, Any] = {}
        for item in heartbeats:
            seen_at = str(item.get("last_seen_at") or "")
            if seen_at >= latest_worker:
                latest_worker = seen_at
                latest_worker_row = item
            try:
                age = datetime.now(timezone.utc) - parse_time(seen_at)
                metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
                if (
                    age.total_seconds() <= self.settings.worker_stale_seconds
                    and metadata.get("deepagents") is True
                    and metadata.get("model_adapter") is True
                ):
                    worker_ready = True
                    if seen_at >= str(ready_worker_row.get("last_seen_at") or ""):
                        ready_worker_row = item
            except (ValueError, TypeError):
                continue
        reported_worker = ready_worker_row or latest_worker_row
        reported_worker_metadata = (
            reported_worker.get("metadata")
            if isinstance(reported_worker.get("metadata"), dict)
            else {}
        )
        content_ready = self.repository.content_ready()
        # Readiness must stay bounded. Exact history counts can require parsing
        # multi-gigabyte JSONL ledgers and belong in explicit diagnostics, not a
        # health endpoint polled by the UI and orchestration scripts.
        search_stats = self.repository.stats(principal, include_history=False)
        index_manifest = self.store.get("manifests", "search") or {}
        knowledge_graph_manifest = self.store.get("manifests", "knowledge_graph") or {}
        knowledge_graph_state = self.knowledge.graph_snapshot_state(principal)
        knowledge_sources = self.knowledge.list_sources(principal).get("items") or []
        index_expected = bool(model_state.get("embeddings"))
        index_fresh = bool(
            index_manifest
            and int(index_manifest.get("record_count") or 0) > 0
            and int(index_manifest.get("chunk_count") or 0) > 0
            and index_manifest.get("index_schema_version") == SEARCH_INDEX_SCHEMA_VERSION
            and index_manifest.get("status") == "ready"
            and index_manifest.get("source_signature") == self.repository.source_signature()
            and int(store_state.get("search_documents") or index_manifest.get("record_count") or 0)
            == int(index_manifest.get("record_count") or 0)
            and int(store_state.get("search_chunks") or index_manifest.get("chunk_count") or 0)
            == int(index_manifest.get("chunk_count") or 0)
        )
        index_sync_state = (
            "ready"
            if index_fresh
            else "syncing"
            if str(index_manifest.get("sync_state") or index_manifest.get("status") or "") in {"syncing", "building"}
            else "degraded"
        )
        generation_residency_ready = (
            not self.settings.lmstudio_require_preloaded_models
            or self.model_residency.get("generation_ready") is True
        )
        embedding_residency_ready = (
            not self.settings.lmstudio_require_preloaded_models
            or self.model_residency.get("embedding_ready") is True
        )
        dependencies = {
            "content": content_ready,
            "postgres": bool(store_state.get("ready") and store_state.get("durable")),
            # A governed query runtime owns its own active Release/profile,
            # mapping, schema and Gateway readiness boundary.  Requiring the
            # unrelated Wiki content scanner here made an otherwise answerable
            # profile-driven question unavailable and encouraged unsafe
            # fallback paths.  Model readiness remains deliberately separate:
            # registered computations and deterministic cold planning need no
            # generation call.
            "governed_query_runtime": self.general_query_runtime is not None,
            "model": bool(model_state.get("generation"))
            and generation_residency_ready
            and (not probe_model or bool(model_state.get("ok"))),
            "embedding": bool(model_state.get("embeddings")) and embedding_residency_ready,
            "search_index": index_fresh,
            "knowledge_graph": bool(knowledge_graph_state.get("fresh")),
            "deep_worker": worker_ready,
            "pat": self.pats.available,
        }
        if self.evaluation_state.enabled:
            dependencies.update(self.evaluation_state.dependency_overrides)
        effective_index_fresh = bool(dependencies["search_index"])
        effective_worker_ready = bool(dependencies["deep_worker"])
        index_sync_state = (
            "ready"
            if effective_index_fresh
            else "syncing"
            if str(index_manifest.get("sync_state") or index_manifest.get("status") or "")
            in {"syncing", "building"}
            and "search_index" not in self.evaluation_state.dependency_overrides
            else "degraded"
        )
        capability_states: dict[str, str] = {}
        for definition in self.registry.all():
            state, _, _ = self.registry.state_for(
                definition,
                principal=principal,
                readiness=dependencies,
                task_mode=TaskMode.copilot,
                supplied_input={"query": "probe", "goal": "probe"},
            )
            capability_states[definition.capability_id] = state.value
        if self.evaluation_state.enabled:
            capability_states.update(self.evaluation_state.capability_overrides)
        platform_readiness = self.platform.readiness()
        harness_package = self.harness_packages.current()
        connectors = copy.deepcopy(self.evaluation_state.connectors)
        connectors_ready = all(
            str(connector.get("state") or "") == CapabilityState.ready.value
            for connector in connectors.values()
            if isinstance(connector, dict)
        )
        required_dependencies = ["content", "model"]
        if self.settings.require_postgres:
            required_dependencies.append("postgres")
        core_ready = all(dependencies[item] for item in required_dependencies)
        # A semantic/lexical fallback may keep individual read capabilities
        # usable, but an expected index that is absent or stale means the
        # platform is operating in a limited mode. Preserve that capability-
        # level fallback while refusing to publish a false global ``ready``.
        index_dependency_ready = not index_expected or bool(dependencies["search_index"])
        fully_ready = core_ready and index_dependency_ready and all(
            state == CapabilityState.ready.value
            for state in capability_states.values()
        ) and connectors_ready and bool(platform_readiness.get("ready")) and dependencies["knowledge_graph"] and (
            harness_package.get("readiness") == "ready"
        )
        readiness_state = "ready" if fully_ready else "degraded" if core_ready else "unavailable"
        return {
            "version": "2.0",
            "enabled": self.settings.enabled,
            "default": self.settings.default_enabled,
            "ready": fully_ready,
            "core_ready": core_ready,
            "fully_ready": fully_ready,
            "state": readiness_state,
            "dependencies": dependencies,
            "store": store_state,
            "model": model_state,
            "model_residency": dict(self.model_residency),
            "model_policy": {
                "route": self.settings.model_route,
                "provider": self.settings.model_provider,
                "model": self.settings.model_name,
                "context_window_tokens": runtime_profile.context_window_tokens,
                "max_output_tokens": runtime_profile.max_output_tokens,
                "profile_source": runtime_profile.source,
                "external_judge_mode": self.settings.gpt55_test_mode,
            },
            "worker": {
                "ready": effective_worker_ready,
                "worker_id": reported_worker.get("worker_id") or "",
                "latest_heartbeat": latest_worker,
                "runtime": {
                    key: reported_worker_metadata.get(key)
                    for key in (
                        "version",
                        "deepagents",
                        "model_adapter",
                        "openai_adapter",
                        "anthropic_adapter",
                    )
                    if key in reported_worker_metadata
                },
            },
            "quick_agent": {"ready": True, "engine": self.quick_agent.engine},
            "search": {
                **search_stats,
                "index": {
                    "expected": index_expected,
                    "fresh": effective_index_fresh,
                    "sync_state": index_sync_state,
                    "current_source_signature": self.repository.source_signature(),
                    "target_source_signature": str(index_manifest.get("target_source_signature") or ""),
                    "pending_changes": int(index_manifest.get("pending_changes") or 0),
                    "last_success_at": str(index_manifest.get("last_sync_success_at") or index_manifest.get("indexed_at") or ""),
                    "manifest": index_manifest,
                    "stored_documents": int(store_state.get("search_documents") or 0),
                },
            },
            "knowledge": {
                "source_count": len(knowledge_sources),
                "sources_ready": sum(1 for item in knowledge_sources if item.get("status") == "ready"),
                "graph": knowledge_graph_manifest,
                "graph_state": knowledge_graph_state,
                "open_health_findings": len(
                    self.store.list(
                        "knowledge_health_findings",
                        employee_id=principal.employee_id,
                        limit=1000,
                    )
                ),
            },
            "platform": platform_readiness,
            "connectors": connectors,
            "evaluation_fixture": self.evaluation_state.readiness_payload(),
            "harness_package": {
                "release": harness_package["release"],
                "checksum": harness_package["checksum"],
                "signature_status": harness_package["signature_status"],
                "readiness": harness_package["readiness"],
            },
            "capabilities": capability_states,
            "warnings": [
                message
                for condition, message in (
                    (not store_state.get("durable"), "Agent 상태가 memory mode이며 재시작 시 사라집니다."),
                    (not dependencies["model"], "초안과 심층 작업 모델이 준비되지 않았습니다."),
                    (not dependencies["embedding"], "semantic 검색이 비활성화되어 lexical/ontology 검색만 사용합니다."),
                    (
                        self.settings.lmstudio_require_preloaded_models
                        and not generation_residency_ready,
                        "로컬 LM Studio의 생성 모델이 수동 상주 상태가 아니어서 추론 호출을 차단했습니다.",
                    ),
                    (
                        not effective_index_fresh
                        and (
                            index_expected
                            or "search_index" in self.evaluation_state.dependency_overrides
                        ),
                        "검색 index가 없거나 지식 정본보다 오래되었습니다.",
                    ),
                    (
                        not knowledge_graph_state.get("fresh"),
                        "Knowledge Graph가 없거나 정본보다 오래되어 관계 capability가 degraded 상태입니다.",
                    ),
                    (not effective_worker_ready, "DeepAgents worker가 연결되지 않았습니다."),
                    (
                        not connectors_ready,
                        "일부 Source connector가 degraded 상태여서 해당 capability만 제한됩니다.",
                    ),
                    (
                        not platform_readiness.get("ready"),
                        "Event Runtime domain adapter가 준비되지 않아 해당 capability를 사용할 수 없습니다.",
                    ),
                    (self.store.durable and not self.pats.production_ready, "운영 PAT hash secret이 설정되지 않았습니다."),
                    (
                        harness_package["signature_status"] != "signed",
                        "HarnessPackage가 development integrity signature 상태입니다.",
                    ),
                )
                if condition
            ],
        }

    def _mcp_v2_status(self) -> dict[str, Any]:
        status_url = self.settings.mcp_health_url
        try:
            request = urllib.request.Request(status_url, headers={"accept": "application/json"})
            with urllib.request.urlopen(request, timeout=1.5) as response:  # noqa: S310 - configured service URL
                payload = json.loads(response.read().decode("utf-8"))
            ready = bool(
                payload.get("status") == "ok"
                and int((payload.get("capabilities") or {}).get("tools") or 0) == 14
                and str(payload.get("mcp_endpoint") or "").endswith("/mcp/v2")
            )
            return {"ready": ready, "status_url": status_url, "tools": (payload.get("capabilities") or {}).get("tools")}
        except Exception as exc:
            return {"ready": False, "status_url": status_url, "error": f"{type(exc).__name__}: {exc}"}

    @staticmethod
    def page_kind(page_ref: str) -> str:
        path = (page_ref or "/").split("?", 1)[0]
        if path in {"", "/"}:
            return "library"
        if path.endswith("/boi:public:boi-wiki-manual:guide:final-operator-guide"):
            return "library"
        if path.startswith("/docs/"):
            return "document"
        if path.startswith("/inbox"):
            return "inbox"
        if path.startswith("/sops") or path.startswith("/workflows"):
            return "sop"
        if path.startswith("/events") or path.startswith("/event-types"):
            return "event"
        if path.startswith("/actions"):
            return "action"
        if path.startswith("/agent"):
            return "agent"
        return "library"

    @staticmethod
    def context_fingerprint(principal: Principal, request: OfferRequest) -> str:
        value = json.dumps(
            {
                "employee_id": principal.employee_id,
                "page_ref": request.page_ref.split("#", 1)[0],
                "task_ref": request.task_ref,
                "selected_text": compact_text(request.selected_text, 500),
            },
            ensure_ascii=False,
            sort_keys=True,
        )
        return hashlib.sha256(value.encode("utf-8")).hexdigest()

    def _offer_candidates(self, page_kind: str) -> list[str]:
        candidates = [
            definition.capability_id
            for definition in self.registry.all()
            if page_kind in definition.offer_surfaces
        ]
        return candidates

    def create_offers(self, principal: Principal, request: OfferRequest) -> list[CapabilityOffer]:
        for existing in self.store.list("offers", employee_id=principal.employee_id, limit=500):
            try:
                expired = parse_time(str(existing.get("expires_at") or "")) <= datetime.now(timezone.utc)
            except (ValueError, TypeError):
                expired = True
            if expired and existing.get("offer_id"):
                self.store.delete("offers", str(existing["offer_id"]))
        readiness = self.readiness(principal)["dependencies"]
        fingerprint = self.context_fingerprint(principal, request)
        task_mode = self.policy.resolve_mode(principal, request.task_ref)
        supplied = {
            "query": request.selected_text,
            "goal": request.selected_text,
        }
        offers: list[CapabilityOffer] = []
        for capability_id in self._offer_candidates(self.page_kind(request.page_ref)):
            definition = self.registry.get(capability_id)
            state, missing, state_reason = self.registry.state_for(
                definition,
                principal=principal,
                readiness=readiness,
                task_mode=task_mode,
                supplied_input=supplied,
            )
            if state == CapabilityState.unavailable and not request.include_unavailable:
                continue
            offer = CapabilityOffer(
                offer_id=new_id("offer"),
                capability_id=capability_id,
                label=definition.title,
                reason=state_reason if state != CapabilityState.ready else definition.description,
                state=state,
                required_inputs=missing,
                context_fingerprint=fingerprint,
                preview=compact_text(request.selected_text, 180),
                expires_at=datetime.now(timezone.utc) + timedelta(seconds=self.settings.offer_ttl_seconds),
            )
            self.store.put(
                "offers",
                offer.offer_id,
                {
                    **offer.model_dump(mode="json"),
                    "employee_id": principal.employee_id,
                    "page_ref": request.page_ref,
                    "task_ref": request.task_ref,
                    "selected_text": request.selected_text,
                    "created_at": now_iso(),
                },
            )
            offers.append(offer)
        return offers

    def _load_offer(self, principal: Principal, offer_id: str) -> dict[str, Any]:
        offer = self.store.get("offers", offer_id)
        if not offer:
            raise HTTPException(status_code=404, detail="offer not found")
        if offer.get("employee_id") != principal.employee_id and not principal.is_admin:
            raise HTTPException(status_code=403, detail="offer belongs to another employee")
        try:
            if parse_time(str(offer.get("expires_at") or "")) <= datetime.now(timezone.utc):
                raise HTTPException(status_code=410, detail="offer expired; refresh recommendations")
        except ValueError as exc:
            raise HTTPException(status_code=410, detail="offer is invalid") from exc
        return offer

    def execute_offer(
        self,
        principal: Principal,
        offer_id: str,
        request: OfferExecuteRequest,
    ) -> AgentTurnResponse:
        offer = self._load_offer(principal, offer_id)
        fingerprint = self.context_fingerprint(
            principal,
            OfferRequest(
                page_ref=request.page_ref or str(offer.get("page_ref") or ""),
                task_ref=request.task_ref or str(offer.get("task_ref") or ""),
                selected_text=str(offer.get("selected_text") or ""),
            ),
        )
        if fingerprint != offer.get("context_fingerprint"):
            raise HTTPException(status_code=409, detail="page or Task context changed; refresh recommendations")
        capability_id = str(offer.get("capability_id") or "")
        if not capability_id:
            raise HTTPException(status_code=409, detail="offer capability is missing")
        definition = self.registry.get(capability_id)
        goal = str(request.input_delta.get("goal") or request.input_delta.get("query") or offer.get("selected_text") or "").strip()
        if not goal:
            goal = str(definition.handler_config.get("default_goal") or "").strip()
        if not goal:
            return self._needs_input_response(
                capability_id,
                ["goal"],
                "무엇을 확인하거나 만들지 적어주세요.",
            )
        return self.run_turn(
            principal,
            AgentTurnRequest(
                question=goal,
                page_ref=request.page_ref or str(offer.get("page_ref") or ""),
                task_ref=request.task_ref or str(offer.get("task_ref") or ""),
                offer_id=offer_id,
                input_delta=request.input_delta,
                capability_id=str(offer.get("capability_id") or ""),
            ),
        )

    def _needs_input_response(
        self,
        capability_id: str,
        fields: list[str],
        message: str,
        *,
        work_session_id: str = "",
    ) -> AgentTurnResponse:
        return AgentTurnResponse(
            run_id=new_id("run"),
            turn_id=new_id("turn"),
            conversation_id=work_session_id,
            work_session_id=work_session_id,
            status="needs_input",
            capability_id=capability_id,
            answer=AnswerBlock(summary=message, markdown=message),
            offers=[],
            error_code="needs_input:" + ",".join(fields),
        )

    def _verified_clarification_choices(
        self,
        principal: Principal,
        session: dict[str, Any],
    ) -> list[str]:
        """Return ACL-verified labels for the active referenceable subjects."""

        topic_state = (
            session.get("topic_state")
            if isinstance(session.get("topic_state"), dict)
            else {}
        )
        labels = (
            topic_state.get("entity_labels")
            if isinstance(topic_state.get("entity_labels"), dict)
            else {}
        )
        refs = list(
            dict.fromkeys(
                str(item)
                for key in ("subjects", "result_entities", "artifact_entities")
                for item in topic_state.get(key) or []
                if str(item).strip()
            )
        )
        choices: list[str] = []
        for ref in refs:
            label = str(labels.get(ref) or "").strip()
            if not label:
                record = self._record_for_ref(principal, ref)
                label = str(record.title if record is not None else "").strip()
            label = compact_text(label, 160)
            if label and label not in choices:
                choices.append(label)
            if len(choices) >= 3:
                break
        return choices

    def _verified_action_target_choices(
        self,
        principal: Principal,
        evidence: list[EvidenceRef],
        *,
        limit: int = 3,
    ) -> list[str]:
        """Return ACL-visible, enabled Action choices without selecting one."""

        if not self.domain_services.supports("action.invoke"):
            return []
        ranked: list[tuple[int, int, str]] = []
        risk_order = {"low": 0, "medium": 1, "high": 2}
        for position, item in enumerate(evidence):
            record = self._record_for_ref(principal, item.evidence_id)
            if record is None or record.kind != "action":
                continue
            metadata = record.metadata if isinstance(record.metadata, dict) else {}
            if metadata.get("enabled", True) is False:
                continue
            status = str(record.status or "").lower()
            if status not in {"active", "reviewed", "published", "approved", "poc"}:
                continue
            action_key = str(metadata.get("action_key") or "").strip()
            if not action_key:
                continue
            risk = str(metadata.get("risk_level") or "medium").lower()
            label = compact_text(str(record.title or action_key), 120)
            ranked.append(
                (
                    risk_order.get(risk, 3),
                    position,
                    f"{label} (`{action_key}`, 위험도 {risk})",
                )
            )
        return [
            label
            for _, _, label in sorted(ranked)[: max(0, min(int(limit), 3))]
        ]

    def _planning_failure_response(
        self,
        *,
        principal: Principal,
        session: dict[str, Any],
        request: AgentTurnRequest,
        run_id: str,
        turn_id: str,
        error: SemanticPlanningError,
    ) -> AgentTurnResponse:
        clarification = str(error.clarification_question or "").strip()
        status = "needs_input" if clarification else "failed"
        public_error_code = (
            "needs_input:reference_resolution"
            if clarification
            else error.code
        )
        if clarification:
            error_disposition = "human_interrupt"
        elif error.code in {"planner_unavailable", "planner_timeout"}:
            error_disposition = "transient_retry"
        elif error.code in {"planner_budget_exceeded", "REFERENCE_SEMANTICS_UNRESOLVED", "STRUCTURED_PLAN_CONSTRAINT_MISMATCH", "STRUCTURED_REFERENCE_TYPE_MISMATCH"}:
            error_disposition = "policy_stop"
        elif error.code in {
            "planner_invalid",
            "catalog_no_match",
            "catalog_ambiguous_match",
            "catalog_graph_recipe_missing",
        }:
            error_disposition = "semantic_repair"
        else:
            error_disposition = "unexpected_failure"
        message = clarification or (
            "로컬 의미 판단 모델을 사용할 수 없습니다. 잠시 후 다시 시도해주세요."
            if error.code == "planner_unavailable"
            else "요청의 의미와 실행 계약을 안전하게 확정하지 못했습니다. 다른 기능으로 바꾸어 실행하지 않았습니다."
        )
        if clarification and not re.search(r"(?m)^\s*[-*]\s+\S", message):
            choices = self._verified_clarification_choices(principal, session)
            if len(choices) >= 2:
                message = (
                    f"{message}\n\n선택 가능한 대상:\n"
                    + "\n".join(f"- {item}" for item in choices)
                )
        response = AgentTurnResponse(
            run_id=run_id,
            turn_id=turn_id,
            conversation_id=str(session["conversation_id"]),
            work_session_id=str(session["session_id"]),
            status=status,  # type: ignore[arg-type]
            capability_id="semantic.planner",
            answer=AnswerBlock(summary=message, markdown=message),
            error_code=public_error_code,
            grounding_status="no_evidence",
            answerability=AnswerabilityReport(status="insufficient"),
            stop_reason=error_disposition,
            context_usage={
                "planning_error": {
                    "code": error.code,
                    "message": compact_text(str(error), 1000),
                    "validation": (
                        error.report.model_dump(mode="json")
                        if error.report is not None
                        else {}
                    ),
                }
            },
        )
        self.store.put(
            "runs",
            run_id,
            {
                "run_id": run_id,
                "turn_id": turn_id,
                "employee_id": principal.employee_id,
                "work_session_id": session["session_id"],
                "capability_id": "semantic.planner",
                "status": status,
                "error_code": public_error_code,
                "planning_error_code": error.code,
                "error_disposition": error_disposition,
                "plan_validation": error.report.model_dump(mode="json") if error.report else {},
                "created_at": now_iso(),
            },
        )
        self._finish_work_session(principal, session, response, request.question)
        return response

    def _semantic_repair_stop_response(
        self,
        *,
        principal: Principal,
        session: dict[str, Any],
        request: AgentTurnRequest,
        run_id: str,
        turn_id: str,
        route: dict[str, Any],
    ) -> AgentTurnResponse:
        """Stop after the single planner repair without executing the plan.

        A repaired plan has consumed the complete two-call invalid-path
        allowance. Continuing into answer generation or mutation would either
        create a hidden third call or execute meaning the user never saw. The
        repaired contract is therefore retained for inspection and the user is
        asked to confirm/rephrase in a fresh turn.
        """

        plan = route.get("semantic_plan_v4") if isinstance(route.get("semantic_plan_v4"), dict) else {}
        resolved_goal = compact_text(str(plan.get("resolved_goal") or request.question), 1000)
        message = (
            "요청의 의미 계약을 한 번 수리했지만 이 턴에서는 더 실행하지 않았습니다. "
            f"제가 이해한 요청은 ‘{resolved_goal}’입니다. 맞다면 그대로 다시 요청하거나, "
            "대상·원하는 결과를 수정해 주세요."
        )
        response = AgentTurnResponse(
            run_id=run_id,
            turn_id=turn_id,
            conversation_id=str(session["conversation_id"]),
            work_session_id=str(session["session_id"]),
            status="needs_input",
            capability_id=str(route.get("capability_id") or "semantic.planner"),
            answer=AnswerBlock(summary="수리된 요청 의미를 확인해주세요.", markdown=message),
            error_code="planner_repair_limit",
            grounding_status="no_evidence",
            answerability=AnswerabilityReport(status="insufficient"),
            semantic_plan_ref=str(route.get("semantic_plan_ref") or ""),
            stop_reason="semantic_repair_limit",
            context_usage={
                "planner_repair": route.get("planner_repair") or {},
                "state_mutation": False,
            },
        )
        self.store.put(
            "runs",
            run_id,
            {
                "run_id": run_id,
                "turn_id": turn_id,
                "employee_id": principal.employee_id,
                "work_session_id": session["session_id"],
                "capability_id": response.capability_id,
                "status": response.status,
                "semantic_plan_ref": response.semantic_plan_ref,
                "stop_reason": response.stop_reason,
                "response": response.model_dump(mode="json"),
                "created_at": now_iso(),
            },
        )
        self._finish_work_session(principal, session, response, request.question)
        return response

    def _resolve_turn_session(self, principal: Principal, request: AgentTurnRequest) -> dict[str, Any]:
        surface_context = normalise_agent_surface_context(
            request.surface_context,
            page_ref=request.page_ref,
            task_ref=request.task_ref,
            selected_text=request.selected_text,
        )
        request.page_ref = surface_context.get("page_ref", request.page_ref)
        request.task_ref = surface_context.get("task_ref", request.task_ref)
        request.surface_context = request.surface_context.model_copy(update=surface_context)
        session_id = str(request.work_session_id or "")
        if not session_id and str(request.conversation_id or "").startswith("ws_"):
            session_id = str(request.conversation_id)
        if session_id:
            session = self.get_work_session(principal, session_id)
        else:
            session = self.create_work_session(
                principal,
                WorkSessionCreateRequest(
                    title=compact_text(request.question, 80),
                    page_ref=request.page_ref,
                    helper_id=request.helper_id or "",
                    surface_context=request.surface_context,
                ),
            )
        if (
            session.get("page_ref") != request.page_ref
            or dict(session.get("surface_context") or {}) != surface_context
        ):
            session.update(
                {
                    "page_ref": request.page_ref,
                    "surface_context": surface_context,
                    "revision": int(session.get("revision") or 1) + 1,
                    "updated_at": now_iso(),
                }
            )
            session = self.store.put("work_sessions", str(session["session_id"]), session)
        request.work_session_id = str(session["session_id"])
        request.conversation_id = str(session["conversation_id"])
        request.input_delta = {
            **request.input_delta,
            "_surface_context": surface_context,
            "_work_session_context": self._session_context(principal, session),
        }
        return session

    def _context(
        self,
        principal: Principal,
        definition: CapabilityDefinition,
        request: AgentTurnRequest,
        evidence: list[EvidenceRef],
        task_mode: TaskMode,
        *,
        session: dict[str, Any],
        source_set: dict[str, Any],
        resolved_goal: str = "",
        task_override: dict[str, Any] | None = None,
        subject_ref: str = "",
        subject_title: str = "",
        context_token_budget: int = 0,
        context_budget_resolution: dict[str, Any] | None = None,
    ) -> WorkContextPack:
        task = normalise_task_completion(
            task_override or self.policy.resolve_task(principal, request.task_ref),
            label_lookup=self._completion_label_lookup(principal),
        )
        context = self.learning.contexts.compile(
            principal=principal,
            definition=definition,
            goal=resolved_goal or request.question,
            page_ref=request.page_ref,
            task_ref=request.task_ref,
            task_mode=task_mode,
            task=task,
            evidence=evidence,
            session=session,
            source_set=source_set,
            external_ai_summary=request.external_ai_summary,
            external_refs=request.external_artifact_refs,
            subject_ref=subject_ref,
            subject_title=subject_title,
            model_profile=self.learning.model_profile,
            context_token_budget=context_token_budget,
        )
        surface_context = normalise_agent_surface_context(
            request.surface_context,
            page_ref=request.page_ref,
            task_ref=request.task_ref,
            selected_text=request.selected_text,
        )
        context.surface_context = surface_context
        raw_selection_binding = (
            request.input_delta.get("_selection_binding")
            if isinstance(request.input_delta.get("_selection_binding"), dict)
            else {}
        )
        selection_manifest = {
            "status": str(raw_selection_binding.get("status") or "none"),
            "reason": str(raw_selection_binding.get("reason") or ""),
            "selection_ref": str(
                raw_selection_binding.get("selection_ref") or ""
            ),
            "source_ref": str(raw_selection_binding.get("source_ref") or ""),
            "chunk_id": str(
                (raw_selection_binding.get("chunk") or {}).get("chunk_id")
                if isinstance(raw_selection_binding.get("chunk"), dict)
                else ""
            ),
            "selected_text_hash": str(
                raw_selection_binding.get("selected_text_hash") or ""
            ),
        }
        context.business_context["selection"] = selection_manifest
        if context.context_manifest is not None:
            context.context_manifest.surface_context = surface_context
            # A short server-verified page selection is a bounded evidence
            # chunk, not an unisolated raw document or data payload. Preserve
            # that distinction so the Context Harness can reject raw input
            # without blocking an exact user-selected Wiki citation.
            context.context_manifest.raw_content_in_prompt = False
            context.context_manifest.bounded_selection_in_prompt = (
                selection_manifest["status"] == "verified"
            )
            context.context_manifest.budget_resolution = dict(context_budget_resolution or {})
            stage_manifests = {
                name: copy.deepcopy(value)
                for name, value in {
                    "planner": request.input_delta.get("_planner_context_manifest"),
                    "retrieval": request.input_delta.get("_retrieval_policy_manifest"),
                    "answer": request.input_delta.get("_answer_context_manifest"),
                }.items()
                if isinstance(value, dict) and value
            }
            stage_manifests["selection"] = selection_manifest
            context.context_manifest.stage_manifests.update(stage_manifests)
        context.manifest.update(
            {
                "evidence_count": len(context.evidence_refs),
                "minio_enabled": bool(self.settings.minio_endpoint),
                "external_artifact_refs": list(request.external_artifact_refs),
                "source_set_ref": self._source_set_id(str(request.work_session_id or "")) if request.work_session_id else "",
                "conversation": request.input_delta.get("_work_session_context") or {},
                "helper_id": request.helper_id or "",
                "surface_context": surface_context,
                "selection_binding": selection_manifest,
                "raw_content_in_prompt": (
                    False
                ),
                "bounded_selection_in_prompt": (
                    selection_manifest["status"] == "verified"
                ),
                "context_stages": copy.deepcopy(
                    context.context_manifest.stage_manifests
                    if context.context_manifest is not None
                    else {}
                ),
            }
        )
        self.store.put("contexts", context.context_id, context.model_dump(mode="json"))
        return context

    def _grounded_answer_from_plan(
        self,
        principal: Principal,
        session: dict[str, Any],
        raw_answer: Any,
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
        *,
        primary_source_ref: str = "",
        include_report: bool = False,
        intent: WorkIntent | None = None,
        work_run_id: str = "",
    ) -> Any:
        """Bind claims structurally, then use the versioned fresh-context evaluator."""
        answer_intent = intent.answer_intent if intent is not None else "fact"
        if intent is None and isinstance(raw_answer, dict):
            answer_intent = str(raw_answer.get("answer_intent") or "fact")
        if answer_intent not in {"definition", "fact", "procedure", "comparison", "relationship", "work"}:
            answer_intent = "fact"
        insufficient = AnswerabilityReport(status="insufficient", answer_intent=answer_intent)
        def packed(
            answer: AnswerBlock | None,
            related: list[RelatedQuestion],
            claims: list[GroundedClaim],
            report: AnswerabilityReport,
        ) -> Any:
            return (answer, related, claims, report) if include_report else ((answer, related) if answer else None)

        if not isinstance(raw_answer, dict) or not evidence or not citations:
            insufficient.missing_evidence = ["질문을 직접 뒷받침하는 Wiki 근거를 찾지 못했습니다."]
            return packed(None, [], [], insufficient)
        citation_by_source = {item.source_ref: item for item in citations}
        evidence_by_source = {item.evidence_id: item for item in evidence}
        full_chunk_text: dict[tuple[str, str], str] = {}
        record_by_source: dict[str, Any] = {}
        for source_ref, citation in citation_by_source.items():
            record = self._record_for_ref(principal, source_ref)
            record_by_source[source_ref] = record
            if record is None:
                continue
            selection_chunk = self._verified_selection_chunk_for_claim(
                record=record,
                evidence_item=evidence_by_source.get(source_ref),
                citation=citation,
            )
            if selection_chunk:
                full_chunk_text[(source_ref, citation.chunk_id)] = str(
                    selection_chunk.get("content")
                    or selection_chunk.get("text")
                    or ""
                )
                continue
            for chunk in chunks_for_record(record):
                chunk_id = str(chunk.get("chunk_id") or "")
                if chunk_id == citation.chunk_id:
                    full_chunk_text[(source_ref, chunk_id)] = str(chunk.get("content") or "")
                    break
        number_by_ref = {
            item.source_ref: index
            for index, item in enumerate(citations, start=1)
            if item.source_ref in evidence_by_source
        }

        def refs_for(value: Any) -> list[str]:
            return list(
                dict.fromkeys(
                    str(item)
                    for item in value or []
                    if str(item) in citation_by_source and str(item) in evidence_by_source
                )
            )

        def clean(value: Any, limit: int) -> str:
            return compact_text(str(value or ""), limit).strip()

        def direct_extract_confidence(text: str, excerpts: list[str]) -> float:
            def normalized_statement(value: str) -> str:
                # Markdown emphasis and ordinary punctuation do not change a
                # quoted statement's meaning.  Normalize them along with
                # whitespace, while retaining every word and number so a
                # negation or broader-scope inference cannot become an exact
                # extract accidentally.
                without_markdown_emphasis = re.sub(r"[*_`~]+", "", value)
                return re.sub(
                    r"\s+",
                    " ",
                    re.sub(
                        r"[^\w가-힣]+",
                        " ",
                        without_markdown_emphasis,
                        flags=re.UNICODE,
                    ),
                ).strip().casefold()

            def direct_surface_variants(value: str) -> set[str]:
                """Return conservative formatting variants of one statement.

                Markdown tables often encode ``subject | definition`` while
                Korean prose renders the same direct extract as
                ``subject는 definition이다``.  Only topic particles and a
                positive terminal copula are normalized here; words, numbers,
                negation, scope, and ordering remain untouched.
                """

                base = normalized_statement(value)
                if not base:
                    return set()
                variants = {base}
                without_topic_particles = re.sub(
                    r"(?<=[0-9a-z가-힣])(?:은|는)(?=\s)",
                    "",
                    base,
                    flags=re.UNICODE,
                )
                variants.add(without_topic_particles)
                for candidate in list(variants):
                    if not candidate.endswith("아니다"):
                        without_copula = re.sub(
                            r"(?:입니다|이다)$",
                            "",
                            candidate,
                        ).strip()
                        if without_copula:
                            variants.add(without_copula)
                return {item for item in variants if item}

            def markdown_table_fact_variants(value: str) -> set[str]:
                """Project literal Markdown rows into conservative row facts.

                A table cell is a direct statement even when prose renders it
                as ``row subject + column header + cell value``.  This parser
                requires an actual header separator and preserves every cell
                word and its order; it does not infer absent values or compare
                unrelated rows.
                """

                def cells(line: str) -> list[str]:
                    stripped = line.strip()
                    if not stripped.startswith("|") or not stripped.endswith("|"):
                        return []
                    return [item.strip() for item in stripped[1:-1].split("|")]

                def separator(parts: list[str]) -> bool:
                    return bool(parts) and all(
                        re.fullmatch(r":?-{3,}:?", item.replace(" ", ""))
                        for item in parts
                    )

                lines = value.splitlines()
                facts: set[str] = set()
                index = 0
                while index + 1 < len(lines):
                    headers = cells(lines[index])
                    separators = cells(lines[index + 1])
                    if (
                        len(headers) < 2
                        or len(separators) != len(headers)
                        or not separator(separators)
                    ):
                        index += 1
                        continue
                    index += 2
                    while index < len(lines):
                        row = cells(lines[index])
                        if len(row) != len(headers) or not row[0]:
                            break
                        subject = row[0]
                        for header, cell_value in zip(headers[1:], row[1:]):
                            if not header or not cell_value:
                                continue
                            for particle in ("은", "는"):
                                facts.update(
                                    direct_surface_variants(
                                        f"{subject}의 {header}{particle} {cell_value}이다"
                                    )
                                )
                        index += 1
                    continue
                return facts

            def markdown_table_cell_facts(value: str) -> set[tuple[str, str, str]]:
                """Return literal ``(row, column, value)`` table cells.

                This representation permits a comparison renderer to
                transpose an existing source table without treating the
                formatting change as a new factual claim. Row names, column
                names, and cell values must still match exactly after the same
                punctuation/whitespace normalization used for direct extracts.
                """

                def cells(line: str) -> list[str]:
                    stripped = line.strip()
                    if not stripped.startswith("|") or not stripped.endswith("|"):
                        return []
                    return [item.strip() for item in stripped[1:-1].split("|")]

                def separator(parts: list[str]) -> bool:
                    return bool(parts) and all(
                        re.fullmatch(r":?-{3,}:?", item.replace(" ", ""))
                        for item in parts
                    )

                lines = value.splitlines()
                facts: set[tuple[str, str, str]] = set()
                index = 0
                while index + 1 < len(lines):
                    headers = cells(lines[index])
                    separators = cells(lines[index + 1])
                    if (
                        len(headers) < 2
                        or len(separators) != len(headers)
                        or not separator(separators)
                    ):
                        index += 1
                        continue
                    index += 2
                    while index < len(lines):
                        row = cells(lines[index])
                        if len(row) != len(headers) or not row[0]:
                            break
                        row_name = normalized_statement(row[0])
                        for header, cell_value in zip(headers[1:], row[1:]):
                            column_name = normalized_statement(header)
                            normalized_value = normalized_statement(cell_value)
                            if row_name and column_name and normalized_value:
                                facts.add((row_name, column_name, normalized_value))
                        index += 1
                return facts

            claim_table_cells = markdown_table_cell_facts(text)
            if claim_table_cells:
                source_table_cells = {
                    fact
                    for excerpt in excerpts
                    for fact in markdown_table_cell_facts(excerpt)
                }
                if source_table_cells and all(
                    fact in source_table_cells
                    or (fact[1], fact[0], fact[2]) in source_table_cells
                    for fact in claim_table_cells
                ):
                    return 1.0

            claim_variants = direct_surface_variants(text)
            excerpt_variants = [
                direct_surface_variants(excerpt)
                | markdown_table_fact_variants(excerpt)
                for excerpt in excerpts
                if excerpt.strip()
            ]
            if claim_variants and excerpt_variants and all(
                any(
                    claim in excerpt
                    for claim in claim_variants
                    for excerpt in variants
                )
                for variants in excerpt_variants
            ):
                return 1.0
            # A paraphrase may still be valid, but only a fresh-context
            # evaluator can establish that every bound chunk entails it.
            return 0.5

        raw_claims = list(raw_answer.get("claims") or [])
        if not raw_claims and not include_report:
            raw_claims = [
                {
                    "claim_id": "claim-summary",
                    "text": raw_answer.get("summary") or "",
                    "claim_kind": answer_intent,
                    "source_refs": raw_answer.get("summary_source_refs") or [],
                    "supporting_chunk_ids": [item.chunk_id or f"source:{item.source_ref}" for item in citations],
                }
            ]
        grounded_claims: list[GroundedClaim] = []
        support_bindings_by_claim: dict[str, list[dict[str, str]]] = {}
        for index, raw_claim in enumerate(raw_claims, start=1):
            if not isinstance(raw_claim, dict):
                continue
            text = str(raw_claim.get("text") or "").strip()
            source_refs = refs_for(raw_claim.get("source_refs"))
            chunk_ids = list(dict.fromkeys(str(item) for item in raw_claim.get("supporting_chunk_ids") or [] if str(item)))
            claim_kind = str(raw_claim.get("claim_kind") or answer_intent)
            raw_claim_scope = str(raw_claim.get("source_scope") or "canonical")
            expected_scope = intent.answer_source_scope if intent is not None else raw_claim_scope
            claim_scope = raw_claim_scope
            if claim_scope not in {"canonical", "operational", "validation"}:
                claim_scope = "canonical"
            if claim_kind not in {"definition", "fact", "procedure", "comparison", "relationship", "work"}:
                claim_kind = answer_intent
            excerpt_bindings: list[dict[str, str]] = []
            for ref in source_refs:
                citation = citation_by_source[ref]
                chunk_matches = citation.chunk_id in chunk_ids or (
                    not include_report and f"source:{citation.source_ref}" in chunk_ids
                )
                if not chunk_matches:
                    continue
                excerpt_bindings.append(
                    {
                        "source_ref": ref,
                        "chunk_id": citation.chunk_id,
                        "text": full_chunk_text.get((ref, citation.chunk_id), citation.excerpt),
                    }
                )
            # A model may list several candidate sources while binding only
            # one source's exact chunk. Public provenance must contain only
            # those source/chunk pairs that were actually bound; an unbound
            # source is neither supporting evidence nor a reason to discard a
            # separately valid direct extract.
            source_refs = list(
                dict.fromkeys(binding["source_ref"] for binding in excerpt_bindings)
            )
            chunk_ids = list(
                dict.fromkeys(binding["chunk_id"] for binding in excerpt_bindings)
            )
            excerpts = [binding["text"] for binding in excerpt_bindings]
            source_records = [record_by_source.get(ref) for ref in source_refs]
            scope_matches = bool(source_records) and claim_scope == expected_scope and all(
                record is not None and self.repository.answer_scope(record) == expected_scope
                for record in source_records
            ) and all(
                record is not None
                and self.repository.authority_scope_satisfies(
                    record,
                    intent.evidence_requirements.authority_scope if intent is not None else "any",
                )
                for record in source_records
            )
            reviewed_runtime_projection = bool(
                claim_scope == "operational"
                and source_records
                and all(
                    record is not None
                    and record.source == "runtime"
                    and record.authority == "reviewed"
                    for record in source_records
                )
            )
            if reviewed_runtime_projection and len(excerpts) == 1:
                # Runtime records are deterministic read models. Render the
                # exact bound projection rather than a generated paraphrase.
                text = excerpts[0].strip()
            supported = bool(
                text
                and source_refs
                and len(excerpt_bindings) == len(source_refs)
                and scope_matches
            )
            support_confidence = direct_extract_confidence(text, excerpts) if supported else 0.0
            claim_id = str(raw_claim.get("claim_id") or f"claim-{index}")[:80]
            grounded_claims.append(
                GroundedClaim(
                    claim_id=claim_id,
                    text=text,
                    claim_kind=claim_kind,  # type: ignore[arg-type]
                    source_scope=claim_scope,  # type: ignore[arg-type]
                    source_refs=source_refs,
                    supporting_chunk_ids=chunk_ids,
                    support_status="supported" if supported else "unsupported",
                    confidence=support_confidence,
                    required_for_answer=bool(raw_claim.get("required_for_answer", False)),
                )
            )
            support_bindings_by_claim[claim_id] = excerpt_bindings

        evaluator_policy = self.harnesses.definition("claim.grounding").evaluator_policy
        standard_read = bool(
            intent is not None
            and intent.user_effect == "read"
            and intent.loop_contract.kind.value == "turn"
            and intent.operation not in {
                WorkOperation.validate,
                WorkOperation.test,
                WorkOperation.run,
                WorkOperation.complete,
                WorkOperation.promote,
            }
        )
        if standard_read:
            # Standard reads have no independent LLM judge by design. A source
            # binding proves provenance, not entailment, so only a directly
            # extracted contiguous statement can be deterministically marked
            # supported. Paraphrases and absence/negation inferences stay
            # visible as unresolved claims instead of consuming another call.
            grounded_claims = [
                item.model_copy(update={"support_status": "unsupported"})
                if item.support_status == "supported" and item.confidence < 1.0
                else item
                for item in grounded_claims
            ]
            grounded_claims.extend(
                self._direct_source_projections(
                    principal,
                    grounded_claims,
                    citation_by_source,
                    expected_source_scope=(
                        intent.answer_source_scope if intent is not None else ""
                    ),
                )
            )
            grounded_claims = self._normalise_comparison_claim_bindings(
                grounded_claims,
                full_chunk_text,
            )
            # Optional generated detail that cannot be directly established
            # is omitted. Only an unsupported claim that is material to the
            # requested answer belongs in the explicit "확인하지 못한 내용"
            # section; supported optional facts remain visible.
            grounded_claims = [
                item
                for item in grounded_claims
                if item.support_status == "supported" or item.required_for_answer
            ]
        if not standard_read:
            grounded_claims, _evaluation = self.claim_evaluator.evaluate(
                principal,
                claims=grounded_claims,
                supporting_bindings=support_bindings_by_claim,
                policy=evaluator_policy,
                user_effect=intent.user_effect if intent else "read",
                operation=intent.operation.value if intent else "understand",
                work_run_id=work_run_id,
                model=self.model,
            )

        # Planner-provided unresolved claims and the deterministic gap
        # projection can describe the same requested fact.  Keep one semantic
        # claim instead of showing the same gap twice.  A supported binding
        # wins over an unsupported duplicate; among unsupported duplicates,
        # prefer the claim with fewer non-supporting source references.
        claim_priority = {
            "supported": 3,
            "conflicting": 2,
            "partial": 1,
            "unsupported": 0,
        }
        claim_order: list[str] = []
        claim_by_text: dict[str, GroundedClaim] = {}
        for item in grounded_claims:
            key = " ".join(item.text.split()).casefold()
            if not key:
                continue
            current = claim_by_text.get(key)
            if current is None:
                claim_order.append(key)
                claim_by_text[key] = item
                continue
            item_rank = claim_priority.get(item.support_status, -1)
            current_rank = claim_priority.get(current.support_status, -1)
            replace = item_rank > current_rank
            if item_rank == current_rank and item.support_status in {"partial", "unsupported"}:
                replace = (len(item.source_refs), len(item.supporting_chunk_ids)) < (
                    len(current.source_refs),
                    len(current.supporting_chunk_ids),
                )
            if replace:
                claim_by_text[key] = item.model_copy(
                    update={
                        "required_for_answer": bool(
                            item.required_for_answer or current.required_for_answer
                        )
                    }
                )
            elif item.required_for_answer and not current.required_for_answer:
                claim_by_text[key] = current.model_copy(
                    update={"required_for_answer": True}
                )
        grounded_claims = [claim_by_text[key] for key in claim_order]

        supported_claims = list(
            {
                item.text: item
                for item in grounded_claims
                if item.support_status == "supported"
            }.values()
        )
        conflicting_claims = [item for item in grounded_claims if item.support_status == "conflicting"]
        unsupported_claims = [item for item in grounded_claims if item.support_status in {"partial", "unsupported"}]
        report = AnswerabilityReport(
            status=(
                "conflicting"
                if conflicting_claims
                else "partial"
                if supported_claims and unsupported_claims
                else "grounded"
                if supported_claims
                else "insufficient"
            ),
            answer_intent=answer_intent,  # type: ignore[arg-type]
            supported_claim_count=len(supported_claims),
            unsupported_claim_count=len(unsupported_claims),
            conflicting_claim_count=len(conflicting_claims),
            missing_evidence=[item.text for item in unsupported_claims],
            conflicts=[item.text for item in conflicting_claims],
        )
        if not supported_claims:
            return packed(None, [], grounded_claims, report)

        used_refs = {ref for claim in supported_claims for ref in claim.source_refs}

        lines: list[str] = []
        rendered_comparison_claim_ids: set[str] = set()
        if answer_intent == "comparison":
            comparison_lines, rendered_comparison_claim_ids = (
                self._comparison_table_lines(
                    supported_claims,
                    full_chunk_text,
                    citation_by_source,
                    number_by_ref,
                )
            )
            lines.extend(comparison_lines)
        remaining_supported_claims = [
            claim
            for claim in supported_claims
            if claim.claim_id not in rendered_comparison_claim_ids
        ]
        if lines and remaining_supported_claims:
            lines.append("")
        for index, claim in enumerate(remaining_supported_claims):
            markers = " ".join(
                f"[{number_by_ref[ref]}](/api/v2/citations/{citation_by_source[ref].citation_id})"
                for ref in claim.source_refs
            )
            if index == 0 and not lines:
                lines.append(f"{claim.text} {markers}")
            else:
                lines.append(f"- {claim.text} {markers}")
        if unsupported_claims:
            lines.extend(["", "### 확인하지 못한 내용"])
            lines.extend(
                f"- {claim.text} — 직접 뒷받침하는 내부 근거를 확인하지 못했습니다."
                for claim in unsupported_claims
            )
        if conflicting_claims:
            lines.extend(["", "### 상충하는 내용"])
            lines.extend(
                f"- {claim.text} — 내부 근거가 서로 일치하지 않아 확정하지 않았습니다."
                for claim in conflicting_claims
            )
        lines.extend(["", "### 사용한 지식"])
        ordered_used_refs = [item.evidence_id for item in evidence if item.evidence_id in used_refs]
        for ref in ordered_used_refs:
            item = evidence_by_source[ref]
            citation = citation_by_source[ref]
            link = f"[{item.title}]({item.url})" if item.url else item.title
            lines.append(f"- {link} [근거](/api/v2/citations/{citation.citation_id})")

        citation_order = [citation_by_source[ref] for ref in ordered_used_refs]
        related_number_by_ref = {
            item.source_ref: index for index, item in enumerate(citation_order, start=1)
        }
        raw_related = []
        for item in (raw_answer.get("related_questions") or [])[:3]:
            if not isinstance(item, dict):
                continue
            source_numbers = [
                related_number_by_ref[ref]
                for ref in refs_for(item.get("source_refs"))
                if ref in related_number_by_ref
            ]
            raw_related.append({**item, "source_numbers": source_numbers})
        related = self._model_related_questions(principal, session, raw_related, citation_order)
        summary = supported_claims[0].text
        return packed(AnswerBlock(summary=summary, markdown="\n".join(lines)), related, grounded_claims, report)

    @staticmethod
    def _normalised_table_token(value: Any) -> str:
        without_emphasis = re.sub(r"[*_`~]+", "", str(value or ""))
        return re.sub(
            r"\s+",
            " ",
            re.sub(
                r"[^\w가-힣]+",
                " ",
                without_emphasis,
                flags=re.UNICODE,
            ),
        ).strip().casefold()

    @classmethod
    def _markdown_table_blocks(cls, value: Any) -> list[dict[str, Any]]:
        """Parse complete Markdown tables while retaining exact source rows."""

        def cells(line: str) -> list[str]:
            stripped = line.strip()
            if not stripped.startswith("|") or not stripped.endswith("|"):
                return []
            return [item.strip() for item in stripped[1:-1].split("|")]

        def separator(parts: list[str]) -> bool:
            return bool(parts) and all(
                re.fullmatch(r":?-{3,}:?", item.replace(" ", ""))
                for item in parts
            )

        lines = str(value or "").replace("\r\n", "\n").splitlines()
        blocks: list[dict[str, Any]] = []
        index = 0
        while index + 1 < len(lines):
            headers = cells(lines[index])
            separators = cells(lines[index + 1])
            if (
                len(headers) < 2
                or len(separators) != len(headers)
                or not separator(separators)
            ):
                index += 1
                continue
            rows: list[dict[str, Any]] = []
            index += 2
            while index < len(lines):
                row_cells = cells(lines[index])
                if len(row_cells) != len(headers) or not row_cells[0]:
                    break
                rows.append({"raw": lines[index].strip(), "cells": row_cells})
                index += 1
            if rows:
                blocks.append({"headers": headers, "rows": rows})
        return blocks

    @classmethod
    def _markdown_table_facts(
        cls,
        block: dict[str, Any],
    ) -> set[tuple[str, str, str]]:
        headers = [str(item) for item in block.get("headers") or []]
        facts: set[tuple[str, str, str]] = set()
        for row in block.get("rows") or []:
            row_cells = [str(item) for item in row.get("cells") or []]
            if len(row_cells) != len(headers) or not row_cells:
                continue
            row_name = cls._normalised_table_token(row_cells[0])
            for header, value in zip(headers[1:], row_cells[1:]):
                column_name = cls._normalised_table_token(header)
                normalised_value = cls._normalised_table_token(value)
                if row_name and column_name and normalised_value:
                    facts.add((row_name, column_name, normalised_value))
        return facts

    @classmethod
    def _normalise_comparison_claim_bindings(
        cls,
        claims: list[GroundedClaim],
        full_chunk_text: dict[tuple[str, str], str],
    ) -> list[GroundedClaim]:
        """Expose exact source rows for a verified transposed comparison.

        A deterministic table transpose is semantically valid, but a public
        claim must still be a direct substring of the cited chunk. Replace a
        fully verified generated table with the exact source rows that it
        compared. The renderer can arrange those rows as a table while every
        claim remains independently auditable by REST, MCP, and evaluators.
        """

        normalised: list[GroundedClaim] = []
        for claim in claims:
            claim_blocks = cls._markdown_table_blocks(claim.text)
            if (
                claim.support_status != "supported"
                or claim.claim_kind != "comparison"
                or claim.confidence < 1.0
                or not claim_blocks
            ):
                normalised.append(claim)
                continue
            claim_facts = {
                fact
                for block in claim_blocks
                for fact in cls._markdown_table_facts(block)
            }
            if not claim_facts:
                normalised.append(claim)
                continue
            replacements: list[GroundedClaim] = []
            seen_rows: set[tuple[str, str, str]] = set()
            for source_ref in claim.source_refs:
                for chunk_id in claim.supporting_chunk_ids:
                    source_text = full_chunk_text.get((source_ref, chunk_id), "")
                    for source_block in cls._markdown_table_blocks(source_text):
                        source_facts = cls._markdown_table_facts(source_block)
                        if not source_facts or not all(
                            fact in source_facts
                            or (fact[1], fact[0], fact[2]) in source_facts
                            for fact in claim_facts
                        ):
                            continue
                        headers = [str(item) for item in source_block.get("headers") or []]
                        for row in source_block.get("rows") or []:
                            row_block = {"headers": headers, "rows": [row]}
                            row_facts = cls._markdown_table_facts(row_block)
                            if not row_facts or not all(
                                fact in claim_facts
                                or (fact[1], fact[0], fact[2]) in claim_facts
                                for fact in row_facts
                            ):
                                continue
                            raw_row = str(row.get("raw") or "").strip()
                            identity = (source_ref, chunk_id, raw_row)
                            if not raw_row or identity in seen_rows:
                                continue
                            seen_rows.add(identity)
                            replacements.append(
                                GroundedClaim(
                                    claim_id=(
                                        f"{claim.claim_id}-source-row-"
                                        f"{len(replacements) + 1}"
                                    )[:80],
                                    text=raw_row,
                                    claim_kind="comparison",
                                    source_scope=claim.source_scope,
                                    source_refs=[source_ref],
                                    supporting_chunk_ids=[chunk_id],
                                    support_status="supported",
                                    confidence=1.0,
                                    required_for_answer=claim.required_for_answer,
                                )
                            )
            normalised.extend(replacements or [claim])
        return normalised

    @classmethod
    def _comparison_table_lines(
        cls,
        claims: list[GroundedClaim],
        full_chunk_text: dict[tuple[str, str], str],
        citation_by_source: dict[str, CitationRef],
        number_by_ref: dict[str, int],
    ) -> tuple[list[str], set[str]]:
        """Render exact source-row claims with one citation cell per row."""

        grouped: dict[tuple[str, str], list[GroundedClaim]] = {}
        for claim in claims:
            if (
                claim.claim_kind != "comparison"
                or "\n" in claim.text
                or not claim.text.strip().startswith("|")
                or not claim.text.strip().endswith("|")
                or len(claim.source_refs) != 1
                or len(claim.supporting_chunk_ids) != 1
            ):
                continue
            key = (claim.source_refs[0], claim.supporting_chunk_ids[0])
            grouped.setdefault(key, []).append(claim)

        lines: list[str] = []
        rendered: set[str] = set()
        for (source_ref, chunk_id), grouped_claims in grouped.items():
            citation = citation_by_source.get(source_ref)
            source_text = full_chunk_text.get((source_ref, chunk_id), "")
            if citation is None or source_ref not in number_by_ref or not source_text:
                continue
            claim_by_row = {
                claim.text.strip(): claim
                for claim in grouped_claims
            }
            selected_block: dict[str, Any] | None = None
            selected_rows: list[dict[str, Any]] = []
            for block in cls._markdown_table_blocks(source_text):
                matched_rows = [
                    row
                    for row in block.get("rows") or []
                    if str(row.get("raw") or "").strip() in claim_by_row
                ]
                if len(matched_rows) > len(selected_rows):
                    selected_block = block
                    selected_rows = matched_rows
            if selected_block is None or not selected_rows:
                continue
            if lines:
                lines.append("")
            headers = [str(item) for item in selected_block.get("headers") or []]
            lines.append("| " + " | ".join([*headers, "근거"]) + " |")
            lines.append("|" + "|".join("---" for _ in [*headers, "근거"]) + "|")
            marker = (
                f"[{number_by_ref[source_ref]}]"
                f"(/api/v2/citations/{citation.citation_id})"
            )
            for row in selected_rows:
                raw_row = str(row.get("raw") or "").strip()
                claim = claim_by_row[raw_row]
                row_cells = [str(item) for item in row.get("cells") or []]
                lines.append("| " + " | ".join([*row_cells, marker]) + " |")
                rendered.add(claim.claim_id)
        return lines, rendered

    @staticmethod
    def _atomic_source_statements(chunk_text: str) -> list[str]:
        """Return exact prose, list, and table rows from one source chunk."""

        statements: list[str] = []
        in_fence = False
        for raw_line in str(chunk_text or "").replace("\r\n", "\n").splitlines():
            line = raw_line.strip()
            if line.startswith("```") or line.startswith("~~~"):
                in_fence = not in_fence
                continue
            if in_fence or not line or line == "---" or line.startswith("#"):
                continue
            if re.fullmatch(r"\|?(?:\s*:?-{3,}:?\s*\|)+", line):
                continue
            statement = re.sub(r"^(?:>|[-*+]|\d+[.)])\s+", "", line).strip()
            if len(statement) < 4:
                continue
            statement = statement[:1200].rstrip()
            if statement and statement not in statements:
                statements.append(statement)
        return statements

    def _direct_source_projections(
        self,
        principal: Principal,
        claims: list[GroundedClaim],
        citation_by_source: dict[str, CitationRef],
        *,
        expected_source_scope: str,
    ) -> list[GroundedClaim]:
        """Recover useful exact facts from model-selected, bound chunks.

        A normal read cannot spend another model call to judge a paraphrase.
        When a generated claim already selected an exact source/chunk pair but
        its wording is not a direct extract, retain that unresolved claim and
        additionally expose only highly overlapping source lines verbatim.
        This never upgrades the paraphrase itself and never selects a new
        source, so provenance and partial-grounding semantics remain intact.
        """

        projected: list[GroundedClaim] = []
        seen: set[tuple[str, str, str]] = set()
        for claim in claims:
            if (
                claim.support_status == "supported"
                or not claim.source_refs
                or (
                    bool(expected_source_scope)
                    and claim.source_scope != expected_source_scope
                )
            ):
                continue
            claim_tokens = meaningful_query_tokens(claim.text)
            if not claim_tokens:
                continue
            claim_has_negation = bool(
                re.search(r"(?:\b(?:no|not|never)\b|않|아니|없)", claim.text, re.IGNORECASE)
            )
            for source_ref in claim.source_refs:
                citation = citation_by_source.get(source_ref)
                if (
                    citation is None
                    or not citation.chunk_id
                    or citation.chunk_id not in set(claim.supporting_chunk_ids)
                ):
                    continue
                record = self._record_for_ref(principal, source_ref)
                if record is None:
                    continue
                chunk_text = next(
                    (
                        str(item.get("content") or "")
                        for item in chunks_for_record(record)
                        if str(item.get("chunk_id") or "") == citation.chunk_id
                    ),
                    "",
                )
                ranked: list[tuple[int, float, float, int, str]] = []
                for position, statement in enumerate(
                    self._atomic_source_statements(chunk_text)
                ):
                    statement_tokens = meaningful_query_tokens(statement)
                    overlap = claim_tokens & statement_tokens
                    if not overlap or not statement_tokens:
                        continue
                    minimum_overlap = 1 if len(claim_tokens) <= 3 else 2
                    statement_coverage = len(overlap) / len(statement_tokens)
                    claim_coverage = len(overlap) / len(claim_tokens)
                    statement_has_negation = bool(
                        re.search(
                            r"(?:\b(?:no|not|never)\b|않|아니|없)",
                            statement,
                            re.IGNORECASE,
                        )
                    )
                    if (
                        len(overlap) < minimum_overlap
                        or statement_coverage < 0.35
                        or statement_has_negation != claim_has_negation
                    ):
                        continue
                    ranked.append(
                        (
                            len(overlap),
                            statement_coverage,
                            claim_coverage,
                            -position,
                            statement,
                        )
                    )
                statement_limit = 3 if len(claim_tokens) >= 8 else 1
                for _, _, _, _, statement in sorted(ranked, reverse=True)[
                    :statement_limit
                ]:
                    identity = (source_ref, citation.chunk_id, statement)
                    if identity in seen:
                        continue
                    seen.add(identity)
                    projected.append(
                        GroundedClaim(
                            claim_id=f"{claim.claim_id}-source-{len(projected) + 1}",
                            text=statement,
                            claim_kind=claim.claim_kind,
                            source_scope=claim.source_scope,
                            source_refs=[source_ref],
                            supporting_chunk_ids=[citation.chunk_id],
                            support_status="supported",
                            confidence=1.0,
                            required_for_answer=claim.required_for_answer,
                        )
                    )
        return projected

    @staticmethod
    def _specific_followup_excluded_prior_refs(
        session: dict[str, Any],
        intent: WorkIntent,
    ) -> set[str]:
        if not (
            intent.user_effect == "read"
            and
            intent.topic_mode == "continue"
            and intent.followup_reference_resolution == "specific"
            and len(intent.selected_prior_topic_entities) == 1
        ):
            return set()
        topic_state = (
            session.get("topic_state")
            if isinstance(session.get("topic_state"), dict)
            else {}
        )
        selected = str(intent.selected_prior_topic_entities[0])
        focal_refs = [
            str(item)
            for item in topic_state.get("subjects") or []
            if str(item)
        ]
        if selected in focal_refs:
            # Selecting the verified dialogue subject is not a drill-down into
            # one result row. Its result/source entities are the evidence that
            # established that subject and must remain available to a
            # same-subject follow-up. Only sibling focal subjects are outside
            # the explicit selection.
            return set(focal_refs) - {selected}
        ordered_prior_refs = list(
            dict.fromkeys(
                str(item)
                for field in ("subjects", "result_entities", "artifact_entities")
                for item in topic_state.get(field) or []
                if str(item)
            )
        )
        if selected not in ordered_prior_refs:
            return set()
        return set(ordered_prior_refs) - {selected}

    @staticmethod
    def _specific_followup_result_ref(
        session: dict[str, Any],
        intent: WorkIntent,
    ) -> str:
        """Return the exact prior result selected by verified discourse state.

        A specific continuation can either keep discussing a focal subject or
        drill into one row from the prior result set.  Only the latter is a
        source freeze: widening retrieval after an ordinal/result selection can
        silently answer from a different, higher-scoring record.  The choice is
        derived from typed topic state, never from reparsing question keywords.
        """

        if not (
            intent.user_effect == "read"
            and intent.topic_mode == "continue"
            and intent.followup_reference_resolution == "specific"
            and len(intent.selected_prior_topic_entities) == 1
        ):
            return ""
        topic_state = (
            session.get("topic_state")
            if isinstance(session.get("topic_state"), dict)
            else {}
        )
        selected = str(intent.selected_prior_topic_entities[0]).strip()
        if not selected:
            return ""
        focal_refs = {
            str(item).strip()
            for item in topic_state.get("subjects") or []
            if str(item).strip()
        }
        result_refs = {
            str(item).strip()
            for item in topic_state.get("result_entities") or []
            if str(item).strip()
        }
        if selected not in result_refs:
            return ""
        if selected in focal_refs and str(
            topic_state.get("ordinal_reference_scope") or ""
        ) != "results":
            # Legacy topic state may duplicate a focal entity in the result
            # collection.  Without an explicit result-scoped selection, retain
            # the subject's broader verified evidence.
            return ""
        return selected

    @staticmethod
    def _without_excluded_grounded_sources(
        raw_answer: Any,
        excluded_refs: set[str],
    ) -> Any:
        if not isinstance(raw_answer, dict) or not excluded_refs:
            return raw_answer
        filtered = copy.deepcopy(raw_answer)

        def item_refs(item: dict[str, Any]) -> set[str]:
            return {str(ref) for ref in item.get("source_refs") or [] if str(ref)}

        summary_refs = {
            str(ref) for ref in filtered.get("summary_source_refs") or [] if str(ref)
        }
        if summary_refs & excluded_refs:
            filtered["summary"] = ""
            filtered["summary_source_refs"] = []
        filtered["claims"] = [
            item
            for item in filtered.get("claims") or []
            if isinstance(item, dict) and not (item_refs(item) & excluded_refs)
        ]
        outcomes = []
        for outcome in filtered.get("outcomes") or []:
            if not isinstance(outcome, dict):
                continue
            items = [
                item
                for item in outcome.get("items") or []
                if isinstance(item, dict) and not (item_refs(item) & excluded_refs)
            ]
            if items:
                outcomes.append({**outcome, "items": items})
        filtered["outcomes"] = outcomes
        filtered["related_questions"] = [
            item
            for item in filtered.get("related_questions") or []
            if isinstance(item, dict) and not (item_refs(item) & excluded_refs)
        ]
        return filtered

    @staticmethod
    def _grounded_evidence_table(
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
    ) -> tuple[AnswerBlock, list[RelatedQuestion]] | None:
        """Compile an explicitly requested table from verified citation rows."""

        evidence_by_ref = {item.evidence_id: item for item in evidence}
        rows: list[str] = []
        used_citations: list[CitationRef] = []

        def cell(value: Any, limit: int) -> str:
            return compact_text(str(value or ""), limit).replace("|", "\\|").replace("\n", " ")

        for citation in citations:
            item = evidence_by_ref.get(citation.source_ref)
            if item is None:
                continue
            summary = cell(citation.excerpt or item.summary, 220)
            if not summary:
                continue
            number = len(used_citations) + 1
            title = cell(item.title, 100)
            if item.url:
                title = f"[{title}]({item.url})"
            rows.append(
                f"| {title} | {cell(item.kind, 40)} | {summary} "
                f"[{number}](/api/v2/citations/{citation.citation_id}) |"
            )
            used_citations.append(citation)
        if not rows:
            return None
        markers = " ".join(
            f"[{index}](/api/v2/citations/{item.citation_id})"
            for index, item in enumerate(used_citations, start=1)
        )
        markdown = "\n".join(
            [
                f"요청과 직접 관련된 확인 자료 {len(rows)}개를 구분했습니다. {markers}",
                "",
                "| 확인 자료 | 종류 | 확인할 내용 |",
                "|---|---|---|",
                *rows,
            ]
        )
        return (
            AnswerBlock(
                summary=f"요청과 직접 관련된 확인 자료 {len(rows)}개를 구분했습니다.",
                markdown=markdown,
            ),
            [],
        )

    @staticmethod
    def _diagram_label(value: Any, limit: int) -> str:
        text = compact_text(str(value or ""), limit)
        text = re.sub(
            r"\([^)]*\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b[^)]*\)",
            "",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(r"[\[\]{}<>`\\]", " ", text)
        return re.sub(r"\s+", " ", text).replace('"', "'").strip()

    @staticmethod
    def _diagram_label_is_user_facing(value: str) -> bool:
        """Reject schema-shaped labels while allowing ordinary names such as API or BoI."""
        return not re.search(r"(?i)\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b", value)

    @staticmethod
    def _diagram_asset_kind(value: Any, citations: list[CitationRef], numbers: list[int]) -> str:
        clean = str(value or "").strip()
        supported = {item.value for item in WorkAssetKind}
        if clean in supported:
            return clean
        source_kinds = [citations[number - 1].kind for number in numbers if 1 <= number <= len(citations)]
        mappings = {
            "sop": "sop",
            "workflow": "workflow",
            "task": "task",
            "event": "business_event",
            "business_event": "business_event",
            "action": "action",
            "skill": "skill",
            "runtime": "runtime",
            "case": "evidence",
            "evidence": "evidence",
        }
        return next((mappings[item] for item in source_kinds if item in mappings), "knowledge")

    @staticmethod
    def _evidence_asset_kind(kind: str) -> str:
        return {
            "sop": "sop",
            "workflow": "workflow",
            "task": "task",
            "event": "business_event",
            "business_event": "business_event",
            "action": "action",
            "skill": "skill",
            "runtime": "runtime",
            "case": "evidence",
            "evidence": "evidence",
        }.get(str(kind or "").strip(), "knowledge")

    def _normalise_mermaid_graph(
        self,
        raw_graph: dict[str, Any],
        citations: list[CitationRef],
        *,
        focal_refs: list[str] | None = None,
        allowed_asset_kinds: set[str] | None = None,
    ) -> dict[str, Any]:
        if not citations:
            raise RuntimeError("흐름 그림을 뒷받침할 인용 근거가 없습니다.")
        constraint_errors: list[str] = []
        for item in (raw_graph.get("nodes") or [])[:14]:
            if not isinstance(item, dict):
                continue
            raw_label = self._diagram_label(item.get("label"), 80)
            raw_asset_kind = str(item.get("asset_kind") or "").strip()
            if raw_label and not self._diagram_label_is_user_facing(raw_label):
                constraint_errors.append(f"스키마형 노드 라벨 '{raw_label}'")
            if allowed_asset_kinds and raw_asset_kind and raw_asset_kind not in allowed_asset_kinds:
                constraint_errors.append(f"허용되지 않은 노드 자산 종류 '{raw_asset_kind}'")
        for item in (raw_graph.get("edges") or [])[:20]:
            if not isinstance(item, dict):
                continue
            raw_label = self._diagram_label(item.get("label"), 48)
            if raw_label and not self._diagram_label_is_user_facing(raw_label):
                constraint_errors.append(f"스키마형 연결 라벨 '{raw_label}'")
        if constraint_errors:
            raise RuntimeError("; ".join(dict.fromkeys(constraint_errors))[:900])
        nodes: list[dict[str, Any]] = []
        model_ids: dict[str, str] = {}
        for item in (raw_graph.get("nodes") or [])[:14]:
            if not isinstance(item, dict):
                continue
            original_id = str(item.get("node_id") or "").strip()
            label = self._diagram_label(item.get("label"), 80)
            numbers = list(
                dict.fromkeys(
                    int(number)
                    for number in item.get("source_numbers") or []
                    if isinstance(number, int) and 1 <= number <= len(citations)
                )
            )
            if not original_id or original_id in model_ids or not label or not numbers:
                continue
            if not self._diagram_label_is_user_facing(label):
                raise RuntimeError("일반 사용자가 이해하기 어려운 스키마 필드명이 노드에 포함되었습니다.")
            asset_kind = self._diagram_asset_kind(item.get("asset_kind"), citations, numbers)
            if allowed_asset_kinds and asset_kind not in allowed_asset_kinds:
                raise RuntimeError(f"요청 범위에 없는 자산 종류가 포함되었습니다: {asset_kind}")
            node_id = f"N{len(nodes) + 1}"
            model_ids[original_id] = node_id
            source_refs = list(dict.fromkeys(citations[number - 1].source_ref for number in numbers))
            nodes.append(
                {
                    "node_id": node_id,
                    "label": label,
                    "kind": self._diagram_label(item.get("kind") or "업무", 32),
                    "asset_kind": asset_kind,
                    "source_refs": source_refs,
                }
            )
        if len(nodes) < 2:
            raise RuntimeError("근거가 확인된 흐름 단계가 2개 이상 필요합니다.")

        edges: list[dict[str, Any]] = []
        seen_edges: set[tuple[str, str, str]] = set()
        for item in (raw_graph.get("edges") or [])[:20]:
            if not isinstance(item, dict):
                continue
            source_id = model_ids.get(str(item.get("from") or "").strip(), "")
            target_id = model_ids.get(str(item.get("to") or "").strip(), "")
            label = self._diagram_label(item.get("label") or "이어짐", 48)
            numbers = list(
                dict.fromkeys(
                    int(number)
                    for number in item.get("source_numbers") or []
                    if isinstance(number, int) and 1 <= number <= len(citations)
                )
            )
            signature = (source_id, target_id, label)
            if not source_id or not target_id or source_id == target_id or not numbers or signature in seen_edges:
                continue
            if not self._diagram_label_is_user_facing(label):
                raise RuntimeError("일반 사용자가 이해하기 어려운 스키마 필드명이 연결 설명에 포함되었습니다.")
            seen_edges.add(signature)
            edges.append(
                {
                    "from": source_id,
                    "to": target_id,
                    "label": label,
                    "source_refs": list(dict.fromkeys(citations[number - 1].source_ref for number in numbers)),
                    "supporting_quotes": [
                        {
                            "source_ref": citations[source_number - 1].source_ref,
                            "chunk_id": citations[source_number - 1].chunk_id,
                            "quote": compact_text(str(raw_quote.get("quote") or ""), 320),
                        }
                        for raw_quote in item.get("supporting_quotes") or []
                        if isinstance(raw_quote, dict)
                        and isinstance(raw_quote.get("source_number"), int)
                        and (source_number := int(raw_quote["source_number"])) in numbers
                        and 1 <= source_number <= len(citations)
                        and str(raw_quote.get("quote") or "").strip()
                    ],
                }
            )
        if not edges:
            raise RuntimeError("근거가 확인된 단계 사이의 연결 관계가 필요합니다.")

        adjacency: dict[str, set[str]] = {item["node_id"]: set() for item in nodes}
        for item in edges:
            adjacency[item["from"]].add(item["to"])
            adjacency[item["to"]].add(item["from"])
        available_sources = {item.source_ref for item in citations}
        expected_focal = set(focal_refs or []).intersection(available_sources)
        starting_nodes = [
            item["node_id"]
            for item in nodes
            if expected_focal.intersection(item.get("source_refs") or [])
        ]
        if expected_focal and not starting_nodes:
            raise RuntimeError("현재 질문의 대상이 흐름 그림에 포함되지 않았습니다.")
        start = starting_nodes[0] if starting_nodes else nodes[0]["node_id"]
        visited: set[str] = set()
        pending = [start]
        while pending:
            node_id = pending.pop()
            if node_id in visited:
                continue
            visited.add(node_id)
            pending.extend(adjacency.get(node_id, set()) - visited)
        if len(visited) != len(nodes):
            raise RuntimeError("질문의 대상과 직접 이어지지 않는 별도 흐름이 포함되었습니다.")

        title = self._diagram_label(raw_graph.get("title") or "업무 흐름", 120) or "업무 흐름"
        source_refs = list(
            dict.fromkeys(
                ref
                for item in [*nodes, *edges]
                for ref in item.get("source_refs") or []
                if ref
            )
        )
        graph = {
            "title": title,
            "presentation": "mermaid",
            "compiler": "deterministic_graph_compiler",
            "nodes": nodes,
            "edges": edges,
            "source_refs": source_refs,
        }
        graph["mermaid"] = self._render_mermaid_source(graph)
        return graph

    @staticmethod
    def _render_mermaid_source(graph: dict[str, Any]) -> str:
        nodes = [item for item in graph.get("nodes") or [] if isinstance(item, dict)]
        edges = [item for item in graph.get("edges") or [] if isinstance(item, dict)]
        outgoing_counts: dict[str, int] = {}
        for item in edges:
            source_id = str(item.get("from") or "")
            outgoing_counts[source_id] = outgoing_counts.get(source_id, 0) + 1
        direction = "LR" if max(outgoing_counts.values(), default=0) >= 3 else "TD"
        lines = [f"flowchart {direction}"]
        for item in nodes:
            lines.append(f'  {item["node_id"]}["{item["label"]}"]')
        for item in edges:
            lines.append(f'  {item["from"]} -->|"{item["label"]}"| {item["to"]}')
        return "\n".join(lines)

    @staticmethod
    def _relation_support_units(value: str) -> list[str]:
        """Split one cited excerpt into conservative relation-sized units.

        A whole paragraph can mention several entities in unrelated clauses.
        Keeping commas and sentence boundaries atomic prevents co-occurrence
        elsewhere in the paragraph from being treated as a direct edge.
        """

        text = str(value or "").replace("\r\n", "\n")
        pieces = re.split(
            r"(?:\n+|(?<=[.!?。！？])\s+|\s*[,;；]\s*)",
            text,
        )
        units: list[str] = []
        for raw in pieces:
            clean = re.sub(r"^(?:#+|>|[-*+]\s+|\d+[.)]\s+)", "", raw.strip())
            clean = compact_text(clean, 800)
            if len(clean) >= 4 and clean not in units:
                units.append(clean)
        return units

    @staticmethod
    def _relation_surface(value: str) -> str:
        return re.sub(
            r"\s+",
            " ",
            re.sub(r"[^0-9a-z가-힣]+", " ", str(value or "").casefold()),
        ).strip()

    @staticmethod
    def _relation_token_matches(expected: str, observed: str) -> bool:
        """Compare relation words without treating inflection as new evidence.

        The graph label and the cited Korean clause can use a short stem and
        an inflected form (for example ``구체화`` and ``구체화된``).  English
        catalog nouns can likewise appear in singular or plural form.  This
        matcher only recognises those surface variations; it does not add a
        synonym or infer a relation that is absent from the quote.
        """

        left = str(expected or "").casefold().strip()
        right = str(observed or "").casefold().strip()
        if not left or not right:
            return False
        if left == right:
            return True
        if left.isascii() and right.isascii():
            return left.rstrip("s") == right.rstrip("s")
        shorter, longer = sorted((left, right), key=len)
        return len(shorter) >= 3 and longer.startswith(shorter)

    @classmethod
    def _relation_token_overlap_count(
        cls,
        expected: set[str],
        observed: set[str],
    ) -> int:
        return sum(
            1
            for expected_token in expected
            if any(
                cls._relation_token_matches(expected_token, observed_token)
                for observed_token in observed
            )
        )

    def _relation_identity_matches(
        self,
        node: dict[str, Any],
        *,
        quote: str,
        citation: CitationRef,
    ) -> bool:
        label = str(node.get("label") or "").strip()
        asset_kind = str(node.get("asset_kind") or "").strip()
        context_surface = self._relation_surface(
            " ".join([citation.title, citation.heading, quote])
        )
        aliases: set[str] = set()
        label_surface = self._relation_surface(label)
        if label_surface:
            aliases.add(label_surface)
        aliases.update(
            self._relation_surface(item)
            for item in meaningful_query_tokens(label)
            if len(self._relation_surface(item)) >= 2
        )
        if asset_kind and asset_kind not in {"knowledge", "evidence", "runtime"}:
            aliases.add(self._relation_surface(asset_kind))
            try:
                entity_type = self.knowledge.ontology_registry.entity_type(asset_kind)
            except KeyError:
                entity_type = None
            if entity_type is not None:
                aliases.add(self._relation_surface(entity_type.label))
                aliases.add(self._relation_surface(entity_type.entity_type_id))
        aliases = {
            item
            for item in aliases
            if item and item not in {"업무", "관계", "단계", "내용", "결과", "지식"}
        }
        return bool(aliases) and any(alias in context_surface for alias in aliases)

    def _validate_mermaid_graph_support(
        self,
        graph: dict[str, Any],
        citations: list[CitationRef],
    ) -> dict[str, Any]:
        """Require every displayed edge to bind to one exact cited clause."""

        citation_by_source = {
            item.source_ref: item
            for item in citations
            if item.source_ref and item.chunk_id and item.excerpt.strip()
        }
        nodes = {
            str(item.get("node_id") or ""): item
            for item in graph.get("nodes") or []
            if isinstance(item, dict)
        }
        supported_refs: list[str] = []
        supported_edges: list[dict[str, Any]] = []
        omitted_edges: list[dict[str, str]] = []
        for edge in graph.get("edges") or []:
            if not isinstance(edge, dict):
                continue
            source_node = nodes.get(str(edge.get("from") or ""))
            target_node = nodes.get(str(edge.get("to") or ""))
            if source_node is None or target_node is None:
                omitted_edges.append(
                    {
                        "from": str(edge.get("from") or ""),
                        "to": str(edge.get("to") or ""),
                        "from_label": str(
                            (source_node or {}).get("label")
                            or edge.get("from")
                            or ""
                        ),
                        "to_label": str(
                            (target_node or {}).get("label")
                            or edge.get("to")
                            or ""
                        ),
                        "label": str(edge.get("label") or ""),
                        "reason": "invalid_endpoint",
                    }
                )
                continue
            relation_tokens = {
                item
                for item in meaningful_query_tokens(str(edge.get("label") or ""))
                if item not in {"업무", "관계", "근거", "단계", "관련", "이어짐"}
            }
            minimum_relation_overlap = max(1, (len(relation_tokens) + 1) // 2)
            bindings: list[dict[str, str]] = []
            rejection_reasons: list[str] = []
            for raw_binding in edge.get("supporting_quotes") or []:
                if not isinstance(raw_binding, dict):
                    rejection_reasons.append("quote_shape")
                    continue
                source_ref = str(raw_binding.get("source_ref") or "")
                quote = compact_text(str(raw_binding.get("quote") or ""), 320)
                citation = citation_by_source.get(source_ref)
                if citation is None or not quote:
                    rejection_reasons.append("citation_or_quote_missing")
                    continue
                quote_surface = self._relation_surface(quote)
                excerpt_surface = self._relation_surface(citation.excerpt)
                if not quote_surface or quote_surface not in excerpt_surface:
                    rejection_reasons.append(
                        "quote_not_in_citation["
                        f"{source_ref}:{compact_text(quote, 80)} != "
                        f"{compact_text(citation.excerpt, 120)}]"
                    )
                    continue
                support_candidates: list[tuple[str, str]] = []
                for unit in self._relation_support_units(citation.excerpt):
                    unit_surface = self._relation_surface(unit)
                    if not unit_surface:
                        continue
                    if quote_surface in unit_surface:
                        # The model already selected a clause-sized subspan;
                        # retain the shortest exact quote it supplied.
                        support_candidates.append((quote, unit))
                    elif unit_surface in quote_surface:
                        # A model can copy two adjacent clauses even though one
                        # clause is sufficient. Narrow only within that exact
                        # quoted span and validate the narrowed unit below.
                        support_candidates.append((unit, unit))
                if not support_candidates:
                    rejection_reasons.append("quote_spans_multiple_clauses")
                    continue
                identity_candidates = [
                    (binding_text, support_unit)
                    for binding_text, support_unit in support_candidates
                    if self._relation_identity_matches(
                        source_node,
                        quote=binding_text,
                        citation=citation,
                    )
                    and self._relation_identity_matches(
                        target_node,
                        quote=binding_text,
                        citation=citation,
                    )
                ]
                if not identity_candidates:
                    # Even if both names occur somewhere in the model's broad
                    # quote, they must coexist in one exact sentence or clause.
                    rejection_reasons.append("quote_spans_multiple_clauses")
                    continue
                supported_candidates = [
                    (binding_text, support_unit)
                    for binding_text, support_unit in identity_candidates
                    if not relation_tokens
                    or self._relation_token_overlap_count(
                        relation_tokens,
                        meaningful_query_tokens(binding_text),
                    )
                    >= minimum_relation_overlap
                ]
                if not supported_candidates:
                    # Do not approve the model's unsupported relationship
                    # wording. Both endpoint identities are nevertheless in
                    # one exact cited clause, so retain only that deterministic
                    # co-occurrence relation with a visibly neutral label.
                    binding_text, _support_unit = min(
                        identity_candidates,
                        key=lambda item: (len(item[0]), item[0]),
                    )
                    edge["requested_label"] = str(edge.get("label") or "")
                    edge["label"] = "같은 원문 절에 함께 명시됨"
                    edge["support_kind"] = "clause_co_occurrence"
                else:
                    binding_text, _support_unit = min(
                        supported_candidates,
                        key=lambda item: (len(item[0]), item[0]),
                    )
                bindings.append(
                    {
                        "subject_ref": str(
                            edge.get("subject_ref")
                            or source_node.get("entity_ref")
                            or source_node.get("ref")
                            or source_node.get("node_id")
                            or edge.get("from")
                            or ""
                        ),
                        "predicate": str(
                            edge.get("predicate")
                            or edge.get("label")
                            or "related_to"
                        ),
                        "object_ref": str(
                            edge.get("object_ref")
                            or target_node.get("entity_ref")
                            or target_node.get("ref")
                            or target_node.get("node_id")
                            or edge.get("to")
                            or ""
                        ),
                        "source_ref": source_ref,
                        "chunk_id": citation.chunk_id,
                        "provenance": str(
                            edge.get("provenance")
                            or "deterministic_extracted"
                        ),
                        "text": compact_text(binding_text, 320),
                    }
                )
            if not bindings:
                omitted_edges.append(
                    {
                        "from": str(edge.get("from") or ""),
                        "to": str(edge.get("to") or ""),
                        "from_label": str(source_node.get("label") or edge.get("from") or ""),
                        "to_label": str(target_node.get("label") or edge.get("to") or ""),
                        "label": str(edge.get("label") or ""),
                        "reason": (
                            ",".join(dict.fromkeys(rejection_reasons))
                            or "supporting_quote_missing"
                        ),
                    }
                )
                continue
            edge["supporting_claims"] = bindings
            edge["source_refs"] = list(
                dict.fromkeys(item["source_ref"] for item in bindings)
            )
            supported_refs.extend(edge["source_refs"])
            supported_edges.append(edge)
        if not supported_edges:
            first_omitted = omitted_edges[0] if omitted_edges else {}
            raise RuntimeError(
                "표시할 관계가 인용 원문의 단일 문장·절과 직접 연결되지 않았습니다: "
                f"{first_omitted.get('from', '')}->{first_omitted.get('to', '')}"
                f"({first_omitted.get('label', '')}), "
                f"{first_omitted.get('reason', 'supporting_quote_missing')}"
            )

        adjacency: dict[str, set[str]] = {}
        for edge in supported_edges:
            source_id = str(edge.get("from") or "")
            target_id = str(edge.get("to") or "")
            adjacency.setdefault(source_id, set()).add(target_id)
            adjacency.setdefault(target_id, set()).add(source_id)
        components: list[set[str]] = []
        pending_nodes = set(adjacency)
        while pending_nodes:
            start = min(pending_nodes)
            component: set[str] = set()
            pending = [start]
            while pending:
                node_id = pending.pop()
                if node_id in component:
                    continue
                component.add(node_id)
                pending.extend(adjacency.get(node_id, set()) - component)
            components.append(component)
            pending_nodes -= component
        original_nodes = [
            item for item in graph.get("nodes") or [] if isinstance(item, dict)
        ]
        original_root = str(original_nodes[0].get("node_id") or "") if original_nodes else ""
        selected_component = max(
            components,
            key=lambda component: (
                original_root in component,
                sum(
                    1
                    for edge in supported_edges
                    if str(edge.get("from") or "") in component
                    and str(edge.get("to") or "") in component
                ),
                len(component),
                sorted(component),
            ),
        )
        disconnected_edges = [
            edge
            for edge in supported_edges
            if str(edge.get("from") or "") not in selected_component
            or str(edge.get("to") or "") not in selected_component
        ]
        omitted_edges.extend(
            {
                "from": str(edge.get("from") or ""),
                "to": str(edge.get("to") or ""),
                "from_label": str(
                    (nodes.get(str(edge.get("from") or "")) or {}).get("label")
                    or edge.get("from")
                    or ""
                ),
                "to_label": str(
                    (nodes.get(str(edge.get("to") or "")) or {}).get("label")
                    or edge.get("to")
                    or ""
                ),
                "label": str(edge.get("label") or ""),
                "reason": "disconnected_after_validation",
            }
            for edge in disconnected_edges
        )
        graph["nodes"] = [
            item
            for item in original_nodes
            if str(item.get("node_id") or "") in selected_component
        ]
        graph["edges"] = [
            edge
            for edge in supported_edges
            if str(edge.get("from") or "") in selected_component
            and str(edge.get("to") or "") in selected_component
        ]
        supported_refs = [
            source_ref
            for edge in graph["edges"]
            for source_ref in edge.get("source_refs") or []
            if source_ref
        ]
        graph["source_refs"] = list(dict.fromkeys(supported_refs))
        if not graph["source_refs"]:
            raise RuntimeError("흐름 그림의 직접 관계 근거가 없습니다.")
        # Keep model-grounded Mermaid artifacts compatible with the
        # deterministic Ontology graph projection.  Existing top-level graph
        # fields remain available to the Mermaid renderer and relation claim
        # projector, while every displayed node/edge also exposes the same
        # typed provenance payload consumed by A2UI, REST, and MCP clients.
        for node in graph["nodes"]:
            node["payload"] = {
                **(
                    node.get("payload")
                    if isinstance(node.get("payload"), dict)
                    else {}
                ),
                "title": str(node.get("label") or ""),
                "source_refs": list(
                    dict.fromkeys(
                        str(item)
                        for item in node.get("source_refs") or []
                        if str(item)
                    )
                ),
                "provenance": "deterministic_extracted",
            }
        for edge in graph["edges"]:
            edge["payload"] = {
                **(
                    edge.get("payload")
                    if isinstance(edge.get("payload"), dict)
                    else {}
                ),
                "user_label": str(edge.get("label") or ""),
                "source_refs": list(
                    dict.fromkeys(
                        str(item)
                        for item in edge.get("source_refs") or []
                        if str(item)
                    )
                ),
                "provenance": "deterministic_extracted",
            }
        graph["validation_status"] = "partial" if omitted_edges else "grounded"
        graph["omitted_edges"] = omitted_edges
        graph["mermaid"] = self._render_mermaid_source(graph)
        return graph

    @staticmethod
    def _continued_topic_presentation_sources(
        request: AgentTurnRequest,
        intent: WorkIntent,
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
    ) -> tuple[list[EvidenceRef], list[CitationRef]]:
        """Keep a presentation-only follow-up on the claims the user saw.

        Retrieval may discover additional related material, but "show the same
        relationship as Mermaid" is a representation change, not permission
        to replace the source set. Exact source+chunk bindings come from the
        verified topic state and remain subject to the already-applied ACL and
        source-set filters because this method only selects current evidence.
        """

        if not (
            intent.topic_mode == "continue"
            and intent.followup_semantic_change == "same_subject_question"
        ):
            return evidence, citations
        conversation = request.input_delta.get("_work_session_context")
        topic_state = (
            conversation.get("topic_state")
            if isinstance(conversation, dict)
            and isinstance(conversation.get("topic_state"), dict)
            else {}
        )
        trusted_chunks: dict[str, set[str]] = {}
        for claim in topic_state.get("claims") or []:
            if (
                not isinstance(claim, dict)
                or claim.get("support_status") != "supported"
            ):
                continue
            chunk_ids = {
                str(item)
                for item in claim.get("supporting_chunk_ids") or []
                if str(item).strip()
            }
            if not chunk_ids:
                continue
            for source_ref in claim.get("source_refs") or []:
                source_key = str(source_ref).strip()
                if source_key:
                    trusted_chunks.setdefault(source_key, set()).update(chunk_ids)
        if not trusted_chunks:
            return evidence, citations
        ordered_refs = list(
            dict.fromkeys(
                [
                    *[
                        str(item)
                        for item in topic_state.get("used_source_refs") or []
                        if str(item) in trusted_chunks
                    ],
                    *trusted_chunks,
                ]
            )
        )
        evidence_by_ref = {item.evidence_id: item for item in evidence}
        citations_by_ref: dict[str, list[CitationRef]] = {}
        for citation in citations:
            citations_by_ref.setdefault(citation.source_ref, []).append(citation)
        selected_evidence: list[EvidenceRef] = []
        selected_citations: list[CitationRef] = []
        for source_ref in ordered_refs:
            evidence_item = evidence_by_ref.get(source_ref)
            citation = next(
                (
                    item
                    for item in citations_by_ref.get(source_ref, [])
                    if item.chunk_id in trusted_chunks[source_ref]
                ),
                None,
            )
            if evidence_item is None or citation is None:
                continue
            selected_evidence.append(evidence_item)
            selected_citations.append(citation)
        if not selected_evidence or not selected_citations:
            return evidence, citations
        return selected_evidence, selected_citations

    def _select_mermaid_presentation_sources(
        self,
        *,
        capability_id: str,
        intent: WorkIntent,
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
    ) -> tuple[list[EvidenceRef], list[CitationRef]]:
        """Apply one catalog-owned source policy to graph and fallback output."""

        citation_by_source = {
            item.source_ref: item
            for item in citations
            if item.source_ref and item.chunk_id and item.excerpt.strip()
        }
        focal_refs = list(dict.fromkeys([*intent.context_refs, intent.target_ref]))
        if focal_refs and all(ref.startswith("topic:") for ref in focal_refs):
            focal_refs = [item.evidence_id for item in evidence]
        candidates = [
            item for item in evidence if item.evidence_id in citation_by_source
        ]
        top_score = max(
            (float(item.score or 0.0) for item in candidates),
            default=0.0,
        )
        try:
            presentation_source_limit = max(
                2,
                min(
                    12,
                    int(
                        self.registry.get(capability_id).handler_config.get(
                            "max_presentation_sources"
                        )
                        or 6
                    ),
                ),
            )
        except (KeyError, TypeError, ValueError):
            presentation_source_limit = 6
        selected_evidence = sorted(
            (
                item
                for item in candidates
                if not top_score
                or float(item.score or 0.0) >= top_score * 0.20
                or item.evidence_id in focal_refs
            ),
            key=lambda item: (
                item.evidence_id not in focal_refs,
                -float(item.score or 0.0),
                item.evidence_id,
            ),
        )[:presentation_source_limit]
        return (
            selected_evidence,
            [citation_by_source[item.evidence_id] for item in selected_evidence],
        )

    def _mermaid_artifact(
        self,
        principal: Principal,
        *,
        request: AgentTurnRequest,
        session: dict[str, Any],
        intent: WorkIntent,
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
        work_run_id: str,
        capability_id: str,
    ) -> tuple[AnswerBlock, ArtifactRef, list[RelatedQuestion]]:
        grounded, diagram_citations = self._select_mermaid_presentation_sources(
            capability_id=capability_id,
            intent=intent,
            evidence=evidence,
            citations=citations,
        )
        if not diagram_citations:
            raise RuntimeError("흐름 그림을 만들 확인 가능한 Wiki 근거가 없습니다.")

        # A valid Ontology graph is rendered before this fallback is reached.
        # If catalog evidence policy removes every graph edge, do not ask a
        # second model to invent a replacement shape. Project the exact,
        # already ACL/policy-checked citation bindings as a provenance graph.
        # This makes the fallback useful without asserting a domain sequence
        # or relationship that the source text does not declare.
        source_refs = list(
            dict.fromkeys(
                citation.source_ref
                for citation in diagram_citations
                if citation.source_ref and citation.chunk_id and citation.excerpt.strip()
            )
        )
        if not source_refs:
            raise RuntimeError("흐름 그림에 연결할 정확한 인용 위치가 없습니다.")
        evidence_by_ref = {item.evidence_id: item for item in grounded}
        topic_label = self._diagram_label(
            intent.topic_subject
            or (grounded[0].title if grounded else "")
            or intent.resolved_goal
            or request.question,
            80,
        ) or "확인할 업무 관계"
        title = self._diagram_label(f"{topic_label} 근거 관계", 120) or "확인된 근거 관계"
        topic_ref = "topic:request:" + self._contract_checksum(
            {
                "goal": intent.resolved_goal,
                "subject_refs": list(intent.context_refs),
                "target_ref": intent.target_ref,
            }
        )[:24]
        root_payload = {
            "title": topic_label,
            "entity_ref": topic_ref,
            "source_refs": source_refs,
            "provenance": "deterministic_extracted",
        }
        nodes: list[dict[str, Any]] = [
            {
                "node_id": "N1",
                "label": topic_label,
                "kind": "확인 요청",
                "asset_kind": intent.asset_kind.value,
                "entity_ref": topic_ref,
                "source_refs": source_refs,
                "payload": root_payload,
            }
        ]
        edges: list[dict[str, Any]] = []
        for index, citation in enumerate(diagram_citations, start=2):
            if citation.source_ref not in source_refs:
                continue
            evidence_item = evidence_by_ref.get(citation.source_ref)
            source_label = self._diagram_label(
                (evidence_item.title if evidence_item else "") or citation.title,
                80,
            ) or f"확인 근거 {index - 1}"
            source_ref = citation.source_ref
            source_payload = {
                "title": source_label,
                "entity_ref": source_ref,
                "source_refs": [source_ref],
                "provenance": "deterministic_extracted",
            }
            nodes.append(
                {
                    "node_id": f"N{index}",
                    "label": source_label,
                    "kind": citation.kind or "근거",
                    "asset_kind": self._evidence_asset_kind(
                        evidence_item.kind if evidence_item else citation.kind
                    ),
                    "entity_ref": source_ref,
                    "source_refs": [source_ref],
                    "payload": source_payload,
                }
            )
            edge_payload = {
                "user_label": "직접 근거",
                "subject_ref": topic_ref,
                "predicate": "supported_by",
                "object_ref": source_ref,
                "source_refs": [source_ref],
                "provenance": "deterministic_extracted",
            }
            edges.append(
                {
                    "from": "N1",
                    "to": f"N{index}",
                    "label": "직접 근거",
                    "subject_ref": topic_ref,
                    "predicate": "supported_by",
                    "object_ref": source_ref,
                    "provenance": "deterministic_extracted",
                    "source_refs": [source_ref],
                    "supporting_claims": [
                        {
                            "subject_ref": topic_ref,
                            "predicate": "supported_by",
                            "object_ref": source_ref,
                            "source_ref": source_ref,
                            "chunk_id": citation.chunk_id,
                            "provenance": "deterministic_extracted",
                            "text": compact_text(citation.excerpt, 320),
                        }
                    ],
                    "payload": edge_payload,
                }
            )
        if not edges:
            raise RuntimeError("흐름 그림의 직접 관계 근거가 없습니다.")
        graph = {
            "title": title,
            "presentation": "mermaid",
            "compiler": "deterministic_graph_compiler",
            "nodes": nodes,
            "edges": edges,
            "source_refs": source_refs,
            "validation_status": "grounded",
            "omitted_edges": [],
            "generation_mode": "deterministic_provenance",
        }
        graph["mermaid"] = self._render_mermaid_source(graph)

        artifact_id = new_id("artifact")
        title = graph["title"]
        actions = []
        payload = {
            "artifact_id": artifact_id,
            "employee_id": principal.employee_id,
            "capability_id": capability_id,
            "artifact_type": "mermaid_diagram",
            "status": "provisional",
            "title": title,
            "draft": graph,
            "work_session_id": str(session["session_id"]),
            "work_run_id": work_run_id,
            "revision": 1,
            "metadata": {
                "compiler": "deterministic_graph_compiler",
                "generation_mode": graph["generation_mode"],
            },
            "evidence_ledger": [
                {
                    "evidence_id": item.evidence_id,
                    "title": item.title,
                    "url": item.url,
                }
                for item in grounded
            ],
            "created_at": now_iso(),
            "updated_at": now_iso(),
            "generation_attempts": 0,
            "actions": [item.model_dump(mode="json") for item in actions],
        }
        self.store.put("artifacts", artifact_id, payload)
        artifact = ArtifactRef(
            artifact_id=artifact_id,
            artifact_type="mermaid_diagram",
            title=title,
            status="provisional",
            url=f"/agent?session={session['session_id']}&artifact={artifact_id}",
            preview="흐름 그림",
            metadata={
                "capability_id": capability_id,
                "revision": 1,
                "node_count": len(graph["nodes"]),
                "edge_count": len(graph["edges"]),
                "source_refs": graph["source_refs"],
                "compiler": "deterministic_graph_compiler",
                "generation_mode": graph["generation_mode"],
            },
            actions=actions,
        )
        omitted_claims = [
            self._mermaid_omitted_edge_claim_text(item)
            for item in graph.get("omitted_edges") or []
            if isinstance(item, dict)
        ]
        answer = AnswerBlock(
            summary=f"'{title}' 흐름 그림을 만들었습니다.",
            markdown=(
                f"### {title}\n\n검토된 Wiki 근거 {len(graph['source_refs'])}개를 바탕으로 실제 흐름 그림을 만들었습니다. "
                "결과 영역에서 질문과 직접 연결된 관계와 원문 근거를 확인할 수 있습니다. "
                + (
                    f"직접 근거가 한 원문 절에 모이지 않은 관계 {len(omitted_claims)}개는 "
                    "그림에서 제외했습니다. "
                    if omitted_claims
                    else ""
                )
                + " ".join(
                    f"[{index}](/api/v2/citations/{citation.citation_id})"
                    for index, citation in enumerate(
                        [
                            citation
                            for citation in diagram_citations
                            if citation.source_ref in set(graph["source_refs"])
                        ],
                        start=1,
                    )
                )
                + self._mermaid_unsupported_section(graph)
            ),
        )
        return answer, artifact, []

    @staticmethod
    def _mermaid_omitted_edge_claim_text(edge: dict[str, Any]) -> str:
        """Describe one rejected edge without turning it into a displayed fact."""

        source_label = compact_text(
            str(edge.get("from_label") or edge.get("from") or "출발 대상"),
            100,
        )
        target_label = compact_text(
            str(edge.get("to_label") or edge.get("to") or "도착 대상"),
            100,
        )
        relation_label = compact_text(str(edge.get("label") or "관계"), 100)
        return (
            f"{source_label} → {target_label} ({relation_label}) 관계는 "
            "단일 원문 절의 직접 근거를 확인하지 못했습니다."
        )

    @classmethod
    def _mermaid_unsupported_section(cls, graph: dict[str, Any]) -> str:
        claims = [
            cls._mermaid_omitted_edge_claim_text(item)
            for item in graph.get("omitted_edges") or []
            if isinstance(item, dict)
        ]
        if not claims:
            return ""
        return "\n\n### 확인하지 못한 내용\n" + "\n".join(
            f"- {item}" for item in claims
        )

    @staticmethod
    def _grounded_claims_for_mermaid_graph(
        graph: dict[str, Any],
        citations: list[CitationRef],
        *,
        source_scope: str,
    ) -> list[GroundedClaim]:
        """Project validated diagram relations into the response grounding contract."""

        citation_by_source = {
            item.source_ref: item
            for item in citations
            if item.source_ref and item.chunk_id
        }
        claims: list[GroundedClaim] = []
        seen_bindings: set[tuple[str, str, str]] = set()
        for index, edge in enumerate(graph.get("edges") or [], start=1):
            if not isinstance(edge, dict):
                continue
            for binding_index, binding in enumerate(
                edge.get("supporting_claims") or [],
                start=1,
            ):
                if not isinstance(binding, dict):
                    continue
                source_ref = str(binding.get("source_ref") or "")
                citation = citation_by_source.get(source_ref)
                chunk_id = str(binding.get("chunk_id") or "")
                subject_ref = str(
                    binding.get("subject_ref") or edge.get("subject_ref") or ""
                )
                predicate = str(
                    binding.get("predicate") or edge.get("predicate") or ""
                )
                object_ref = str(
                    binding.get("object_ref") or edge.get("object_ref") or ""
                )
                provenance = str(
                    binding.get("provenance")
                    or edge.get("provenance")
                    or (edge.get("payload") or {}).get("provenance")
                    or ""
                )
                text = str(binding.get("text") or "").strip()
                signature = (source_ref, chunk_id, text)
                if (
                    citation is None
                    or chunk_id != citation.chunk_id
                    or not text
                    or not subject_ref
                    or not predicate
                    or not object_ref
                    or provenance
                    not in {
                        "declared",
                        "extracted",
                        "canonical_declared",
                        "operational_verified",
                        "deterministic_extracted",
                        "human_verified",
                        "inferred",
                        "ambiguous",
                        "private_provisional",
                    }
                    or signature in seen_bindings
                ):
                    continue
                seen_bindings.add(signature)
                claims.append(
                    GroundedClaim(
                        claim_id=f"diagram-relation-{index}-{binding_index}",
                        text=text,
                        claim_kind="relationship",
                        source_scope=(
                            source_scope
                            if source_scope in {"canonical", "operational", "validation"}
                            else "canonical"
                        ),
                        source_refs=[source_ref],
                        supporting_chunk_ids=[chunk_id],
                        evidence_bindings=[
                            ClaimEvidenceBinding(
                                subject_ref=subject_ref,
                                predicate=predicate,
                                object_ref=object_ref,
                                source_ref=source_ref,
                                chunk_id=chunk_id,
                                provenance=provenance,
                            )
                        ],
                        support_status="supported",
                        confidence=1.0,
                        required_for_answer=True,
                    )
                )
        for index, omitted in enumerate(graph.get("omitted_edges") or [], start=1):
            if not isinstance(omitted, dict):
                continue
            claims.append(
                GroundedClaim(
                    claim_id=f"diagram-relation-unsupported-{index}",
                    text=AgentV2Service._mermaid_omitted_edge_claim_text(omitted),
                    claim_kind="relationship",
                    source_scope=(
                        source_scope
                        if source_scope in {"canonical", "operational", "validation"}
                        else "canonical"
                    ),
                    source_refs=[],
                    supporting_chunk_ids=[],
                    support_status="unsupported",
                    confidence=1.0,
                    required_for_answer=True,
                )
            )
        return claims

    def _split_mermaid_artifact_into_tasks(
        self,
        principal: Principal,
        *,
        definition: CapabilityDefinition,
        source_artifact: dict[str, Any],
        session: dict[str, Any],
        work_run_id: str,
        page_ref: str,
    ) -> tuple[AnswerBlock, ArtifactRef]:
        config = definition.handler_config or {}
        domain_operation = str(config.get("domain_operation") or "").strip()
        accepted_types = {
            str(item) for item in config.get("accepted_artifact_types") or [] if str(item).strip()
        }
        if not domain_operation or not self.domain_services.supports(domain_operation):
            raise RuntimeError("Task 후보 변환 서비스가 준비되지 않았습니다.")
        if accepted_types and str(source_artifact.get("artifact_type") or "") not in accepted_types:
            raise RuntimeError("선택한 결과물은 이 변환 계약에서 지원하지 않습니다.")
        source_draft = source_artifact.get("draft") if isinstance(source_artifact.get("draft"), dict) else {}
        mermaid_source = str(source_draft.get("mermaid") or "").strip()
        if (
            not mermaid_source
            and source_artifact.get("artifact_type") == "ontology_graph"
            and source_draft.get("presentation") == "mermaid"
        ):
            mermaid_source = self._mermaid_source_from_ontology_draft(source_draft)
        if not mermaid_source:
            raise RuntimeError("Task로 나눌 흐름 그림 원문이 없습니다.")
        source_title = str(source_artifact.get("title") or "업무 흐름").strip()
        title_suffix = str(config.get("title_suffix") or "Task 후보").strip()
        result = self.domain_services.execute(
            domain_operation,
            principal,
            {
                "title": f"{source_title} {title_suffix}",
                "mermaid_source": mermaid_source,
                "current_url": page_ref,
                "note": str(config.get("note") or ""),
                "source_artifact_id": str(source_artifact.get("artifact_id") or ""),
                "work_session_id": str(session.get("session_id") or ""),
            },
        )
        domain_draft = result.get("draft") if isinstance(result.get("draft"), dict) else {}
        raw_tasks = [item for item in domain_draft.get("workflow_tasks") or [] if isinstance(item, dict)]
        if not raw_tasks:
            raise RuntimeError("흐름에서 확인 가능한 Task 후보를 찾지 못했습니다.")
        tasks = [
            self._normalise_sop_task(
                {
                    **item,
                    "purpose": str(item.get("purpose") or ""),
                    "required_evidence": item.get("required_evidence") or [],
                    "outputs": item.get("outputs") or [],
                },
                index,
                principal=principal,
            )
            for index, item in enumerate(raw_tasks[:20])
        ]
        artifact_id = new_id("artifact")
        title = str(domain_draft.get("title") or f"{source_title} {title_suffix}")
        draft = {
            "title": title,
            "goal": "기존 흐름을 실행 가능한 Task 후보로 나눈 나만의 초안",
            "tasks": tasks,
            "workflow_edges": domain_draft.get("workflow_edges") or [],
            "candidate_links": domain_draft.get("candidate_links") or {},
            "mermaid": self._mermaid_from_tasks(tasks),
            "source_artifact_id": str(source_artifact.get("artifact_id") or ""),
            "source_mermaid": mermaid_source,
            "domain_ref": str(result.get("domain_ref") or domain_draft.get("draft_id") or ""),
        }
        evidence_ledger = [
            item
            for item in source_artifact.get("evidence_ledger") or []
            if isinstance(item, dict)
        ]
        source_refs = list(
            dict.fromkeys(
                [
                    *(
                        str(item)
                        for item in source_artifact.get("source_refs") or []
                        if str(item).strip()
                    ),
                    *(
                        str(item)
                        for item in source_draft.get("source_refs") or []
                        if str(item).strip()
                    ),
                    *(
                        str(item.get("evidence_id") or "")
                        for item in evidence_ledger
                        if str(item.get("evidence_id") or "").strip()
                    ),
                ]
            )
        )
        draft["source_refs"] = source_refs
        draft["bindings"] = copy.deepcopy(source_draft.get("bindings") or {})
        source_tasks = [
            item
            for item in source_draft.get("tasks") or []
            if isinstance(item, dict)
        ]
        source_task_ids = {
            str(item.get("task_id") or item.get("name") or "")
            for item in source_tasks
            if str(item.get("task_id") or item.get("name") or "").strip()
        }
        task_ids = {
            str(item.get("task_id") or item.get("name") or "")
            for item in tasks
            if str(item.get("task_id") or item.get("name") or "").strip()
        }
        editable_diff = {
            "base_artifact_id": str(source_artifact.get("artifact_id") or ""),
            "base_revision": int(source_artifact.get("revision") or 1),
            "changed_fields": ["tasks", "workflow_edges", "candidate_links"],
            "added_task_refs": sorted(task_ids - source_task_ids),
            "removed_task_refs": sorted(source_task_ids - task_ids),
            "before_task_count": len(source_tasks),
            "after_task_count": len(tasks),
        }
        payload = {
            "artifact_id": artifact_id,
            "employee_id": principal.employee_id,
            "capability_id": definition.capability_id,
            "artifact_type": str(config.get("output_artifact_type") or "workflow_draft"),
            "status": "draft",
            "title": title,
            "draft": draft,
            "work_session_id": str(session.get("session_id") or ""),
            "work_run_id": work_run_id,
            "revision": 1,
            "source_refs": source_refs,
            "evidence_ledger": evidence_ledger,
            "domain": result,
            "editable_diff": editable_diff,
            "diff": editable_diff,
            "preview_only": True,
            "production_changed": False,
            "created_at": now_iso(),
            "updated_at": now_iso(),
        }
        self.store.put("artifacts", artifact_id, payload)
        artifact = ArtifactRef(
            artifact_id=artifact_id,
            artifact_type=str(config.get("output_artifact_type") or "workflow_draft"),
            title=title,
            status="draft",
            url=f"/agent?session={session['session_id']}&artifact={artifact_id}",
            preview=f"Task 후보 {len(tasks)}개",
            metadata={
                "capability_id": definition.capability_id,
                "revision": 1,
                "task_count": len(tasks),
                "source_artifact_id": str(source_artifact.get("artifact_id") or ""),
                "domain_ref": draft["domain_ref"],
                "source_refs": source_refs,
                "presentation": "artifact",
                "editable_diff": editable_diff,
                "preview_only": True,
                "production_changed": False,
            },
            actions=[],
        )
        answer = AnswerBlock(
            summary=f"'{source_title}'을 Task 후보 {len(tasks)}개로 나눴습니다.",
            markdown=(
                f"### {title}\n\n기존 흐름과 근거를 유지한 나만 보는 Task 변경 미리보기입니다. "
                "새 SOP 초안을 만들지 않았고 원본 SOP 초안도 아직 바꾸거나 게시하지 않았습니다. "
                "결과 영역에서 추가·변경된 Task 이름과 완료 항목을 비교하세요."
            ),
        )
        return answer, artifact

    @staticmethod
    def _mermaid_source_from_ontology_draft(draft: dict[str, Any]) -> str:
        def clean(value: Any, limit: int = 80) -> str:
            return re.sub(r'["\n\r|<>]', " ", str(value or "")).strip()[:limit]

        nodes = [item for item in draft.get("nodes") or [] if isinstance(item, dict)][:14]
        node_ids = {
            str(item.get("node_id") or ""): f"N{index}"
            for index, item in enumerate(nodes, start=1)
            if str(item.get("node_id") or "")
        }
        lines = ["flowchart LR"]
        for item in nodes:
            node_id = str(item.get("node_id") or "")
            payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
            title = payload.get("title") or payload.get("label") or node_id
            if node_id in node_ids:
                lines.append(f'  {node_ids[node_id]}["{clean(title)}"]')
        for edge in [item for item in draft.get("edges") or [] if isinstance(item, dict)][:20]:
            source = node_ids.get(str(edge.get("source_id") or ""))
            target = node_ids.get(str(edge.get("target_id") or ""))
            if not source or not target:
                continue
            payload = edge.get("payload") if isinstance(edge.get("payload"), dict) else {}
            relation_label = (
                edge.get("user_label")
                or payload.get("user_label")
                or edge.get("relation")
                or "관련"
            )
            lines.append(f"  {source} -->|{clean(relation_label)}| {target}")
        return "\n".join(lines) if len(lines) > 1 else ""

    def _work_routine_plan(
        self,
        principal: Principal,
        definition: CapabilityDefinition,
        *,
        request: AgentTurnRequest,
        session: dict[str, Any],
        intent: WorkIntent,
        evidence: list[EvidenceRef],
        work_run_id: str,
    ) -> tuple[AnswerBlock, ArtifactRef, str]:
        if not self.model.readiness().get("generation"):
            raise RuntimeError("자동 확인 계획을 만들 모델이 준비되지 않았습니다.")
        source_refs = list(dict.fromkeys([*intent.context_refs, *[item.evidence_id for item in evidence]]))
        source_payload = [
            {
                "source_ref": item.evidence_id,
                "title": item.title,
                "kind": item.kind,
                "summary": item.summary,
            }
            for item in evidence
        ]
        system = (
            "You design one safe recurring workplace check in Korean. Interpret the request semantically and return "
            "a preview only. Choose event when a known business state or event should trigger the check, schedule for "
            "calendar-based timing, and interval only for elapsed-time polling. Do not invent an event reference. Use a "
            "calendar object for schedule requests: minutes and hours are required integer arrays; days_of_month, "
            "months, and weekdays use empty arrays to mean every value. Use weekday 0 for Sunday through 6 for "
            "Saturday. Leave cron empty because the server compiles it. State a clear stopping condition in ordinary "
            "workplace language. Use max_runs only when the user explicitly gave a finite run count and always provide "
            "that positive count; otherwise use cancelled. Use event_resolved only with an event trigger. The routine "
            "will not be created until the user confirms the plan."
        )
        prompt = (
            f"Resolved request: {intent.resolved_goal or request.question}\n"
            f"Current page: {request.page_ref or '-'}\n"
            f"Trusted context refs: {json.dumps(intent.context_refs, ensure_ascii=False)}\n"
            f"Available sources: {json.dumps(source_payload, ensure_ascii=False)}\n"
            "Create one minimal automatic-check preview."
        )
        validation_error = ""
        draft: dict[str, Any] = {}
        for attempt in range(2):
            repair_prompt = prompt
            if validation_error:
                repair_prompt += f"\nThe prior preview failed validation: {validation_error}. Regenerate it."
            draft = self.model.generate_structured(
                system=system,
                prompt=repair_prompt,
                schema=self._draft_schema(definition),
            )
            try:
                self._validate_draft(definition, draft)
                trigger = str(draft.get("trigger") or "")
                if trigger == "schedule":
                    draft["cron"] = self._compile_calendar_cron(draft.get("calendar"))
                    if not croniter.is_valid(str(draft["cron"])):
                        raise RuntimeError("일정에 유효한 반복 시간이 필요합니다.")
                if trigger == "event" and not str(draft.get("event_ref") or "").strip():
                    raise RuntimeError("상태 변화로 확인하려면 연결할 업무 이벤트가 필요합니다.")
                self._normalise_routine_stop(draft)
                break
            except (RuntimeError, TypeError, ValueError) as exc:
                validation_error = str(exc)
                if attempt == 1:
                    raise RuntimeError(validation_error) from exc

        trigger = str(draft.get("trigger") or "interval")
        routine_request = WorkRoutineCreateRequest(
            title=compact_text(str(draft.get("title") or "자동 확인"), 160),
            goal=compact_text(str(draft.get("goal") or intent.resolved_goal or request.question), 12000),
            capability_id=str(definition.handler_config.get("target_capability") or ""),
            page_ref=request.page_ref,
            task_ref=request.task_ref,
            trigger=trigger,  # type: ignore[arg-type]
            interval_seconds=max(60, int(draft.get("interval_seconds") or 300)),
            cron=str(draft.get("cron") or "").strip(),
            timezone=compact_text(str(draft.get("timezone") or "Asia/Seoul"), 80),
            event_ref=compact_text(str(draft.get("event_ref") or ""), 1000),
            routine_stop=str(draft.get("routine_stop") or "cancelled"),  # type: ignore[arg-type]
            max_runs=max(0, int(draft.get("max_runs") or 0)),
            input={
                "source_refs": source_refs,
                "completion_condition": compact_text(str(draft.get("completion_condition") or ""), 2000),
                "schedule_description": compact_text(str(draft.get("schedule_description") or ""), 500),
                "target_ref": compact_text(str(draft.get("target_ref") or intent.target_ref or ""), 1000),
            },
            origin="user",
            surface_visibility="normal",
        )
        draft.update(
            {
                "title": routine_request.title,
                "goal": routine_request.goal,
                "source_refs": source_refs,
                "confirmation_required": True,
            }
        )
        artifact_id = new_id("artifact")
        plan_id = new_id("plan")
        now = now_iso()
        configured_next_actions = self._configured_next_actions(
            definition,
            artifact_id=artifact_id,
            plan_id=plan_id,
            work_session_id=str(session["session_id"]),
        )
        self.store.put(
            "artifacts",
            artifact_id,
            {
                "artifact_id": artifact_id,
                "employee_id": principal.employee_id,
                "capability_id": definition.capability_id,
                "artifact_type": "work_routine_draft",
                "status": "draft",
                "title": routine_request.title,
                "draft": draft,
                "work_session_id": str(session["session_id"]),
                "work_run_id": work_run_id,
                "revision": 1,
                "evidence_ledger": [
                    {"evidence_id": item.evidence_id, "title": item.title, "url": item.url}
                    for item in evidence
                ],
                "next_actions": configured_next_actions,
                "created_at": now,
                "updated_at": now,
            },
        )
        self.store.put(
            "plans",
            plan_id,
            {
                "plan_id": plan_id,
                "employee_id": principal.employee_id,
                "capability_id": definition.capability_id,
                "artifact_id": artifact_id,
                "status": "draft",
                "risk": "medium",
                "domain_operation": "work_routine.create",
                "domain_payload": routine_request.model_dump(mode="json"),
                "domain_validation": {"valid": True, "errors": [], "warnings": []},
                "production_changed": False,
                "work_run_id": work_run_id,
                "created_at": now,
            },
        )
        artifact = ArtifactRef(
            artifact_id=artifact_id,
            artifact_type="work_routine_draft",
            title=routine_request.title,
            status="draft",
            url=f"/agent?session={session['session_id']}&artifact={artifact_id}",
            preview=str(draft.get("schedule_description") or "자동 확인 계획"),
            metadata={
                "plan_id": plan_id,
                "capability_id": definition.capability_id,
                "revision": 1,
                "next_actions": configured_next_actions,
            },
        )
        answer = AnswerBlock(
            summary=f"'{routine_request.title}' 자동 확인 계획을 준비했습니다.",
            markdown="\n".join(
                [
                    f"### {routine_request.title}",
                    f"- 목적: {routine_request.goal}",
                    f"- 다시 확인: {draft.get('schedule_description')}",
                    f"- 끝내는 기준: {draft.get('completion_condition')}",
                    "",
                    "아직 자동 확인을 만들지 않았습니다. 계획을 확인한 뒤 활성화할 수 있습니다.",
                ]
            ),
        )
        return answer, artifact, plan_id

    @staticmethod
    def _compile_calendar_cron(value: Any) -> str:
        if not isinstance(value, dict):
            raise RuntimeError("일정의 시각과 반복 주기가 필요합니다.")

        def field(name: str, minimum: int, maximum: int, *, required: bool = False) -> str:
            raw = value.get(name)
            if not isinstance(raw, list):
                raise RuntimeError("일정 값은 시·분·요일 단위로 정리되어야 합니다.")
            numbers = sorted(
                {
                    int(item)
                    for item in raw
                    if isinstance(item, int) and not isinstance(item, bool) and minimum <= item <= maximum
                }
            )
            if required and not numbers:
                raise RuntimeError("일정에 확인할 시각이 필요합니다.")
            return ",".join(str(item) for item in numbers) if numbers else "*"

        return " ".join(
            [
                field("minutes", 0, 59, required=True),
                field("hours", 0, 23, required=True),
                field("days_of_month", 1, 31),
                field("months", 1, 12),
                field("weekdays", 0, 6),
            ]
        )

    @staticmethod
    def _normalise_routine_stop(draft: dict[str, Any]) -> None:
        stop = str(draft.get("routine_stop") or "cancelled")
        trigger = str(draft.get("trigger") or "")
        try:
            max_runs = int(draft.get("max_runs") or 0)
        except (TypeError, ValueError):
            max_runs = 0
        if (stop == "max_runs" and max_runs < 1) or (stop == "event_resolved" and trigger != "event"):
            draft["routine_stop"] = "cancelled"
            draft["max_runs"] = 0

    @staticmethod
    def _inbox_answer(items: list[EvidenceRef]) -> AnswerBlock:
        if not items:
            message = "현재 처리할 Inbox 업무가 없습니다. 과거 seed 이력은 현재 업무에 포함하지 않았습니다."
            return AnswerBlock(summary=message, markdown=message)
        lines = [f"현재 처리할 업무가 {len(items)}건 있습니다.", ""]
        for item in items:
            lines.append(f"- [{item.title}]({item.url}): {item.summary or item.metadata.get('status', '확인 필요')}")
        return AnswerBlock(summary=lines[0], markdown="\n".join(lines))

    def _graph_plan_for_intent(self, principal: Principal, intent: WorkIntent) -> GraphQueryPlan | None:
        draft = intent.graph_query_draft
        if not draft or not draft.enabled:
            return None
        # `topic:` refs identify verified conversation state. Sending them to
        # the entity resolver performs a broad semantic search for a value
        # that can never be an Ontology node and may consume the entire turn
        # budget. Keep any real mixed focal refs, but let a topic-only request
        # fall through to the claim-grounded presentation path.
        focal_mentions = [
            item
            for item in draft.focal_mentions
            if str(item).strip() and not str(item).startswith("topic:")
        ]
        target_fallback = str(intent.target_ref or "").strip()
        if (
            draft.focal_mentions
            and not focal_mentions
            and (not target_fallback or target_fallback.startswith("topic:"))
        ):
            return None
        target_mentions = [
            str(item).strip()
            for item in draft.target_mentions
            if str(item).strip()
        ]
        resolution_inputs = [*focal_mentions, *target_mentions]
        if target_fallback and not target_fallback.startswith("topic:"):
            resolution_inputs.append(target_fallback)
        # Catalog compilation normally supplies typed ontology refs. The
        # resolver can ACL-check those without scanning every Wiki/history
        # record, so only materialize the repository when at least one input
        # is still a human-language mention. This keeps the generic resolver
        # for unresolved inputs while making typed graph reads scale with the
        # requested neighborhood.
        records = []
        if any(not item.startswith(ENTITY_PREFIXES) for item in resolution_inputs):
            records = self.repository.authoritative_records(
                principal,
                include_drafts=True,
            )
            records.extend(
                self.repository.history_records(principal, include_seed=False)
            )
        focal_entities = self.entity_resolver.resolve_many(
            focal_mentions,
            principal=principal,
            records=records,
        )
        if (
            not focal_entities
            and target_fallback
            and not target_fallback.startswith("topic:")
        ):
            focal_entities.append(target_fallback)
        if not focal_entities:
            return None
        focal_entities = [
            self.knowledge.resolve_node_reference(principal, item)
            for item in focal_entities
        ]

        target_entities = self.entity_resolver.resolve_many(
            target_mentions,
            principal=principal,
            records=records,
        )
        target_entities = [
            self.knowledge.resolve_node_reference(principal, item)
            for item in target_entities
        ]
        return GraphQueryPlan(
            focal_entities=list(dict.fromkeys(focal_entities))[:20],
            target_entities=list(dict.fromkeys(target_entities))[:20],
            query_kind=draft.query_kind,
            node_kinds=draft.node_kinds,
            relation_kinds=draft.relation_kinds,
            direction=draft.direction,
            depth=draft.depth,
            limit=80,
            time_from=draft.time_from,
            time_to=draft.time_to,
            as_of=str(intent.evidence_requirements.as_of or ""),
            presentation=draft.presentation,
        )

    def _graph_results_for_intent(
        self,
        principal: Principal,
        *,
        intent: WorkIntent,
        plan: GraphQueryPlan,
    ) -> dict[str, Any]:
        """Run the primary graph recipe and Catalog-compiled projections.

        The primary recipe keeps work-view semantics bounded (notably the
        distinction between active assignment and declared responsibility).
        ProjectionRecipe bindings add only the typed evidence families named
        by Catalog, so execution evidence cannot silently widen a work query
        into every ACL-readable neighbor relation.
        """

        projection_only = bool(intent.ontology_projection_bindings) and all(
            binding.primary_graph_mode == "projection_only"
            for binding in intent.ontology_projection_bindings
        )
        # A bounded work-view recipe remains authoritative when the user asks
        # for current assignment or official responsibility.  With no work
        # view, a Catalog projection marked projection_only replaces the
        # generic graph recipe so traversal-only neighbors cannot become
        # displayed evidence merely because they are ACL-readable.
        skip_primary = projection_only and intent.work_view == "none"
        if skip_primary:
            read_model_state = self.knowledge.graph_snapshot_state(principal)
            primary = {
                "ok": False,
                "meaningful": False,
                "status": "empty",
                "presentation": (
                    plan.presentation if plan.presentation != "auto" else "table"
                ),
                "nodes": [],
                "edges": [],
                "query_plan": plan.model_dump(mode="json"),
                "read_model_state": read_model_state,
                "degraded": (
                    []
                    if read_model_state.get("status") == "ready"
                    else [f"knowledge_graph_{read_model_state.get('status') or 'unavailable'}"]
                ),
            }
        else:
            primary = self.knowledge.query(principal, plan)
        projection_results: list[tuple[Any, dict[str, Any]]] = []
        projection_statuses: list[dict[str, Any]] = []
        for binding in intent.ontology_projection_bindings:
            try:
                projected = self.knowledge.project(
                    principal,
                    projection_id=binding.projection_id,
                    subject_ref=binding.subject_ref,
                    as_of=plan.as_of,
                    limit=plan.limit,
                    section_ids=set(binding.section_ids),
                )
            except HTTPException as exc:
                # A missing or ACL-hidden subject deliberately has the same
                # observable outcome.  Do not disclose the projection or a
                # hidden path through an Agent response.  Invalid Catalog
                # wiring remains a system error rather than a silent fallback.
                if exc.status_code in {403, 404}:
                    projection_statuses.append(
                        {
                            **binding.model_dump(mode="json"),
                            "status": "unavailable",
                            "meaningful": False,
                            "node_count": 0,
                            "edge_count": 0,
                        }
                    )
                    continue
                raise
            projected_node_lookup = {
                str(item.get("node_id") or ""): item
                for item in projected.get("nodes") or []
                if isinstance(item, dict) and str(item.get("node_id") or "")
            }
            selected_section_ids = set(binding.section_ids)
            selected_sections = [
                section
                for section_id, section in (projected.get("sections") or {}).items()
                if isinstance(section, dict)
                and (not selected_section_ids or section_id in selected_section_ids)
            ]
            projected_edges_by_id: dict[str, dict[str, Any]] = {}
            for section in selected_sections:
                for edge in section.get("edges") or []:
                    if not isinstance(edge, dict):
                        continue
                    edge_id = str(edge.get("edge_id") or "")
                    if edge_id:
                        projected_edges_by_id.setdefault(edge_id, edge)
            projected_edges = list(projected_edges_by_id.values())
            projected_node_ids = {
                binding.subject_ref,
                *[
                    str(value)
                    for edge in projected_edges
                    for value in (edge.get("source_id"), edge.get("target_id"))
                    if str(value or "")
                ],
            }
            projected_nodes = [
                projected_node_lookup[node_id]
                for node_id in projected_node_ids
                if node_id in projected_node_lookup
            ]
            materialized_projection = {
                **projected,
                "nodes": projected_nodes,
                "edges": projected_edges,
            }
            projection_results.append((binding, materialized_projection))
            projection_edge_count = len(projected_edges)
            projection_meaningful = projection_edge_count > 0
            projection_statuses.append(
                {
                    **binding.model_dump(mode="json"),
                    "status": "ready" if projection_meaningful else "empty",
                    "meaningful": projection_meaningful,
                    "node_count": len(projected_nodes),
                    "edge_count": projection_edge_count,
                }
            )
        if not projection_results:
            return {
                **primary,
                "projection_statuses": projection_statuses,
            }

        merged = copy.deepcopy(primary)
        nodes_by_id = {
            str(item.get("node_id") or ""): item
            for item in primary.get("nodes") or []
            if isinstance(item, dict) and str(item.get("node_id") or "")
        }
        edges_by_key: dict[tuple[str, str, str, str, tuple[str, ...]], dict[str, Any]] = {}

        def add_edge(item: dict[str, Any]) -> None:
            payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
            edge_key = (
                str(item.get("source_id") or ""),
                str(item.get("relation") or ""),
                str(item.get("target_id") or ""),
                str(payload.get("provenance") or payload.get("evidence_provenance") or ""),
                tuple(sorted(str(ref) for ref in payload.get("source_refs") or [] if str(ref))),
            )
            if all(edge_key[:3]):
                edges_by_key.setdefault(edge_key, item)

        for edge in primary.get("edges") or []:
            if isinstance(edge, dict):
                add_edge(edge)
        applied_bindings: list[dict[str, Any]] = []
        for binding, projected in projection_results:
            for node in projected.get("nodes") or []:
                if isinstance(node, dict) and str(node.get("node_id") or ""):
                    nodes_by_id.setdefault(str(node["node_id"]), node)
            for edge in projected.get("edges") or []:
                if isinstance(edge, dict):
                    add_edge(edge)
            applied_bindings.append(binding.model_dump(mode="json"))

        merged["nodes"] = list(nodes_by_id.values())
        merged["edges"] = list(edges_by_key.values())
        merged["ok"] = bool(merged["nodes"] and merged["edges"])
        merged["meaningful"] = bool(merged["edges"])
        merged["status"] = "connected" if merged["meaningful"] else str(
            primary.get("status") or "empty"
        )
        merged["projection_bindings"] = applied_bindings
        merged["projection_statuses"] = projection_statuses
        merged["query_plan"] = {
            **(
                primary.get("query_plan")
                if isinstance(primary.get("query_plan"), dict)
                else plan.model_dump(mode="json")
            ),
            "projection_bindings": applied_bindings,
        }
        return merged

    def _graph_result_artifact(
        self,
        principal: Principal,
        *,
        session: dict[str, Any],
        intent: WorkIntent,
        current_work: list[EvidenceRef],
        citations: list[CitationRef],
        work_run_id: str,
        capability_id: str,
        excluded_source_refs: set[str] | None = None,
    ) -> tuple[
        AnswerBlock,
        ArtifactRef,
        list[EvidenceRef],
        list[dict[str, Any]],
        list[str],
    ] | None:
        excluded_source_refs = {
            str(ref)
            for ref in excluded_source_refs or set()
            if str(ref).strip()
        }
        plan = self._graph_plan_for_intent(principal, intent)
        if not plan:
            return None
        result = self._graph_results_for_intent(
            principal,
            intent=intent,
            plan=plan,
        )
        read_model_state = (
            result.get("read_model_state")
            if isinstance(result.get("read_model_state"), dict)
            else {}
        )
        if (
            intent.evidence_requirements.require_freshness
            and not read_model_state.get("fresh")
        ):
            return None
        nodes = [item for item in result.get("nodes") or [] if isinstance(item, dict)]
        edges = [item for item in result.get("edges") or [] if isinstance(item, dict)]
        relation_limit = plan.limit
        relation_limit_value = self.registry.get(capability_id).handler_config.get(
            "max_relation_items"
        )
        if relation_limit_value is not None:
            try:
                relation_limit = max(1, min(int(relation_limit_value), plan.limit))
            except (TypeError, ValueError):
                relation_limit = plan.limit
            depth_by_ref = {
                str(key): int(value)
                for key, value in (result.get("depth_by_ref") or {}).items()
                if str(key) and isinstance(value, int)
            }
            focal_entities = set(plan.focal_entities)

            def edge_relevance(item: dict[str, Any]) -> tuple[int, int, int, str]:
                source_ref = str(item.get("source_id") or "")
                target_ref = str(item.get("target_id") or "")
                direct = 0 if focal_entities.intersection({source_ref, target_ref}) else 1
                depth = min(
                    depth_by_ref.get(source_ref, plan.depth + 1),
                    depth_by_ref.get(target_ref, plan.depth + 1),
                )
                return (
                    direct,
                    depth,
                    -int(
                        item.get("display_priority")
                        or (item.get("payload") or {}).get("display_priority")
                        or 0
                    ),
                    str(item.get("edge_id") or ""),
                )

            relation_buckets: dict[str, list[dict[str, Any]]] = {}
            for edge in edges:
                relation_buckets.setdefault(
                    str(edge.get("relation") or "related"), []
                ).append(edge)
            ranked_edges = sorted(
                (
                    rank,
                    -int(
                        edge.get("display_priority")
                        or (edge.get("payload") or {}).get("display_priority")
                        or 0
                    ),
                    relation,
                    str(edge.get("edge_id") or ""),
                    edge,
                )
                for relation, bucket in relation_buckets.items()
                for rank, edge in enumerate(
                    sorted(bucket, key=edge_relevance)
                )
            )
            # Keep the full ranked stream until ACL/evidence policy has been
            # applied below. Otherwise an ineligible early edge consumes the
            # display budget and hides a later, source-backed relation of the
            # same family.
            edges = [item[-1] for item in ranked_edges]
        if not nodes or not result.get("ok") or not result.get("meaningful"):
            return None
        if str(result.get("presentation") or "") in {"mermaid", "table"}:
            nodes, edges = self._bounded_mermaid_graph(
                plan,
                nodes,
                edges,
                preserve_focal_set=intent.topic_structure == "multiple_focal",
            )
            if not edges:
                return None
        node_lookup = {str(item.get("node_id") or ""): item for item in nodes}
        relation_lines: list[str] = []
        relation_lines_by_family: dict[str, list[str]] = {}
        underlying_source_refs: list[str] = []
        grounded_edges: list[dict[str, Any]] = []
        relation_claims: list[dict[str, Any]] = []
        provenance: list[str] = []
        allowed_graph_scopes = {
            str(item)
            for item in intent.evidence_requirements.scopes
            if str(item)
        } or {str(intent.answer_source_scope or "canonical")}
        allowed_graph_authorities = set(intent.evidence_authorities)
        allowed_graph_statuses = set(intent.evidence_statuses)
        for edge in edges:
            source_id = str(edge.get("source_id") or "")
            target_id = str(edge.get("target_id") or "")
            source = node_lookup.get(source_id) or {}
            target = node_lookup.get(target_id) or {}
            source_payload = source.get("payload") if isinstance(source.get("payload"), dict) else {}
            target_payload = target.get("payload") if isinstance(target.get("payload"), dict) else {}
            source_title = str(source_payload.get("title") or source_id)
            target_title = str(target_payload.get("title") or target_id)
            payload = edge.get("payload") if isinstance(edge.get("payload"), dict) else {}
            edge_provenance = str(payload.get("provenance") or "")
            edge_source_refs = [
                str(item)
                for item in payload.get("source_refs") or []
                if str(item).strip()
            ]
            metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
            if metadata.get("source_ref"):
                edge_source_refs.append(str(metadata["source_ref"]))
            edge_source_refs = list(dict.fromkeys(edge_source_refs))
            # The read model intentionally retains explicit draft relations so
            # impact previews and ontology review can inspect them.  A normal
            # Agent answer must still enforce the compiled evidence contract
            # before any relation becomes a displayed claim or citation.
            # Requiring every resolvable endpoint/source record to pass keeps
            # a draft declaration from borrowing the authority of its reviewed
            # target. Unknown synthetic endpoint ids are not citation sources;
            # at least one eligible backing record remains mandatory below.
            eligible_edge_source_refs: list[str] = []
            graph_policy_blocked = False
            for source_ref in edge_source_refs:
                # SourceSet policy is part of the common evidence boundary,
                # including deterministic ontology projections.  An excluded
                # backing source is removed rather than allowed to re-enter
                # through a prior artifact/read-model edge.  The relation may
                # remain only when another independently eligible source binds
                # the same typed edge.
                if source_ref in excluded_source_refs:
                    continue
                record = self._record_for_ref(principal, source_ref)
                if record is None:
                    continue
                if (
                    self.repository.answer_scope(record)
                    not in allowed_graph_scopes
                    or self.search._policy_exclusion_reason(
                        record,
                        allowed_authorities=allowed_graph_authorities,
                        allowed_statuses=allowed_graph_statuses,
                        require_freshness=bool(
                            intent.evidence_requirements.require_freshness
                        ),
                        require_outcome=False,
                        required_authority_scope=str(
                            intent.evidence_requirements.authority_scope or "any"
                        ),
                        as_of=str(intent.evidence_requirements.as_of or ""),
                    )
                ):
                    graph_policy_blocked = True
                    break
                eligible_edge_source_refs.append(source_ref)
            if graph_policy_blocked or not eligible_edge_source_refs:
                continue
            edge_source_refs = list(dict.fromkeys(eligible_edge_source_refs))
            if intent.work_view == "current":
                current_work_refs = {
                    item.evidence_id
                    for item in current_work
                    if item.evidence_id
                }
                # A current-work projection may only use active operational
                # assignment evidence. Historical CompletionRecords can still
                # appear in lineage and experience views, but must never be
                # relabelled as the person's current assignment.
                if not current_work_refs.intersection(edge_source_refs):
                    continue
            if edge_provenance in {"inferred", "ambiguous"} or not edge_source_refs:
                continue
            relation_label = str(
                edge.get("user_label")
                or payload.get("user_label")
                or edge.get("relation")
                or "관련"
            )
            relation_text = f"{source_title} — {relation_label} → {target_title}"
            relation_lines.append(f"- {relation_text}")
            relation_family = str(
                edge.get("relation_family")
                or payload.get("relation_family")
                or "other"
            )
            relation_lines_by_family.setdefault(relation_family, []).append(
                f"- {relation_text}"
            )
            relation_claims.append(
                {
                    "text": relation_text,
                    "subject_ref": source_id,
                    "predicate": str(edge.get("relation") or ""),
                    "object_ref": target_id,
                    "source_refs": edge_source_refs,
                    "provenance": edge_provenance,
                    "relation_family": relation_family,
                }
            )
            underlying_source_refs.extend(edge_source_refs)
            provenance.append(edge_provenance)
            # The artifact edge and its public claim must expose the same
            # post-policy source identities. A source discovered through the
            # typed metadata binding is valid, but leaving only the pre-filter
            # endpoint refs in ``payload.source_refs`` makes REST/MCP
            # verification disagree with the claim contract.
            grounded_edge = copy.deepcopy(edge)
            grounded_edge["payload"] = {
                **payload,
                "source_refs": list(edge_source_refs),
            }
            grounded_edges.append(grounded_edge)
            if len(grounded_edges) >= relation_limit:
                break

        if not grounded_edges:
            return None
        edges = grounded_edges
        visible_node_ids = {
            str(value)
            for edge in edges
            for value in (edge.get("source_id"), edge.get("target_id"))
            if str(value or "")
        }
        nodes = [item for item in nodes if str(item.get("node_id") or "") in visible_node_ids]
        underlying_source_refs = list(dict.fromkeys(underlying_source_refs))

        missing_evidence: list[str] = []
        for projection_status in result.get("projection_statuses") or []:
            if (
                projection_status.get("required_for_answer")
                and not projection_status.get("meaningful")
            ):
                missing_evidence.append(
                    str(projection_status.get("empty_message") or "요청한 관계 근거를 확인할 수 없습니다.")
                )

        lines: list[str] = []
        if intent.work_view in {"current", "combined"}:
            lines.extend(["### 실제 배정 업무 · operational evidence"])
            current_relation_lines = relation_lines_by_family.get("current_work", [])
            lines.extend(current_relation_lines)
            lines.extend(
                f"- [{item.title}]({item.url}){f': {item.summary}' if item.summary else ''}"
                for item in current_work
            )
            if not current_relation_lines and not current_work:
                message = "현재 배정을 뒷받침하는 active operational evidence를 확인할 수 없습니다."
                lines.append(f"- {message}")
                missing_evidence.append(message)

        if intent.work_view in {"responsibility", "combined"}:
            if lines:
                lines.append("")
            lines.extend(["### 공식 소속·보고 관계 · canonical evidence"])
            organization_lines = relation_lines_by_family.get("organization", [])
            lines.extend(organization_lines or ["- 공식 소속·보고 관계를 확인할 수 없습니다."])
            lines.extend(["", "### 공식 역할·책임 · canonical evidence"])
            responsibility_lines = relation_lines_by_family.get(
                "official_responsibility",
                [],
            )
            if responsibility_lines:
                lines.extend(responsibility_lines)
            else:
                message = "공식 역할·책임 관계를 확인할 수 없습니다. 공식 소속을 책임으로 해석하지 않았습니다."
                lines.append(f"- {message}")
                missing_evidence.append(message)

        if "execution_evidence" in set(intent.evidence_requirements.modes):
            if lines:
                lines.append("")
            lines.extend(["### Agent·System 업무 사용 · operational evidence"])
            usage_lines = relation_lines_by_family.get("usage", [])
            lines.extend(usage_lines or ["- 검증된 Agent·System 업무 사용 기록을 확인할 수 없습니다."])
            lines.extend(["", "### 검증 수행·결과 · operational/human evidence"])
            outcome_lines = [
                *relation_lines_by_family.get("experience", []),
                *relation_lines_by_family.get("result", []),
                *relation_lines_by_family.get("approval", []),
            ]
            lines.extend(outcome_lines or ["- 검증된 업무 결과나 Outcome 기록을 확인할 수 없습니다."])

        displayed_families = {
            "current_work",
            "organization",
            "official_responsibility",
            "usage",
            "experience",
            "result",
            "approval",
        }
        supporting_lines = [
            line
            for family, family_lines in relation_lines_by_family.items()
            if family not in displayed_families
            for line in family_lines
        ]
        if supporting_lines:
            if lines:
                lines.append("")
            lines.extend(["### 연결 맥락", *supporting_lines])

        missing_evidence = list(dict.fromkeys(item for item in missing_evidence if item))
        summary = f"확인 가능한 업무 관계 {len(edges)}건을 근거 유형별로 구분했습니다."
        if missing_evidence:
            summary += f" 요청 영역 {len(missing_evidence)}개는 확인 가능한 근거가 부족합니다."
        artifact_id = new_id("artifact")
        graph_evidence_id = "graph-evidence:" + hashlib.sha256(
            json.dumps(
                {
                    "employee_id": principal.employee_id,
                    "plan": plan.model_dump(mode="json"),
                    "edges": [str(item.get("edge_id") or "") for item in edges],
                    "source_refs": underlying_source_refs,
                },
                ensure_ascii=False,
                sort_keys=True,
            ).encode("utf-8")
        ).hexdigest()[:24]
        graph_evidence_text = "\n".join(
            [
                "검증된 Ontology 관계 조회 결과",
                f"질의 종류: {plan.query_kind}",
                *relation_lines,
            ]
        )
        self.store.put(
            "graph_relation_evidence",
            graph_evidence_id,
            {
                "evidence_id": graph_evidence_id,
                "employee_id": principal.employee_id,
                "title": "검증된 업무 관계",
                "summary": summary,
                "text": graph_evidence_text,
                "url": f"/knowledge-graph?focus={plan.focal_entities[0]}",
                "query_plan": plan.model_dump(mode="json"),
                "underlying_source_refs": underlying_source_refs,
                "provenance": list(dict.fromkeys(provenance)),
                "artifact_id": artifact_id,
                "created_at": now_iso(),
            },
        )
        graph_evidence_record = self._record_for_ref(principal, graph_evidence_id)
        if graph_evidence_record is None:
            return None
        underlying_evidence = [
            self._evidence_from_record(record, score=1.0)
            for source_ref in underlying_source_refs
            if (record := self._record_for_ref(principal, source_ref)) is not None
        ]
        graph_evidence = [
            self._evidence_from_record(graph_evidence_record, score=1.0),
            *underlying_evidence,
        ]
        title = "업무 역할과 연결 관계" if intent.work_view in {"responsibility", "combined"} else "지식 연결 관계"
        presentation = str(result.get("presentation") or "list")
        artifact_type = "mermaid_diagram" if presentation == "mermaid" else "ontology_graph"
        draft_payload = {
            "query_plan": result.get("query_plan") or plan.model_dump(mode="json"),
            "presentation": presentation,
            "compiler": "deterministic_graph_compiler",
            "generation_mode": "deterministic_ontology_projection",
            "nodes": nodes,
            "edges": edges,
            "source_refs": underlying_source_refs,
            "underlying_source_refs": underlying_source_refs,
            "graph_evidence_ref": graph_evidence_id,
            "provenance": list(dict.fromkeys(provenance)),
            "read_model_state": read_model_state,
            "projection_statuses": result.get("projection_statuses") or [],
            "missing_evidence": missing_evidence,
        }
        if artifact_type == "mermaid_diagram":
            draft_payload["mermaid"] = self._mermaid_source_from_ontology_draft(draft_payload)
        stored = {
            "artifact_id": artifact_id,
            "employee_id": principal.employee_id,
            "capability_id": capability_id,
            "artifact_type": artifact_type,
            "status": "provisional",
            "title": title,
            "draft": draft_payload,
            "work_session_id": str(session["session_id"]),
            "work_run_id": work_run_id,
            "revision": 1,
            "metadata": {
                "compiler": "deterministic_graph_compiler",
                "generation_mode": "deterministic_ontology_projection",
            },
            "created_at": now_iso(),
            "updated_at": now_iso(),
        }
        self.store.put("artifacts", artifact_id, stored)
        artifact = ArtifactRef(
            artifact_id=artifact_id,
            artifact_type=artifact_type,
            title=title,
            status="provisional",
            url=f"/agent?session={session['session_id']}&artifact={artifact_id}",
            preview=summary,
            metadata={
                "capability_id": capability_id,
                "revision": 1,
                "presentation": stored["draft"]["presentation"],
                "compiler": "deterministic_graph_compiler",
                "generation_mode": "deterministic_ontology_projection",
                "node_count": len(nodes),
                "edge_count": len(edges),
                "focal_entities": list(plan.focal_entities),
                "source_refs": underlying_source_refs,
                "underlying_source_refs": underlying_source_refs,
                "graph_evidence_ref": graph_evidence_id,
                "provenance": list(dict.fromkeys(provenance)),
                "read_model_state": read_model_state,
            },
        )
        answer_lines = [summary, "", *lines]
        return (
            AnswerBlock(summary=summary, markdown="\n".join(answer_lines)),
            artifact,
            graph_evidence,
            relation_claims,
            missing_evidence,
        )

    def _grounded_claims_table_artifact(
        self,
        principal: Principal,
        *,
        session: dict[str, Any],
        claims: list[GroundedClaim],
        work_run_id: str,
        capability_id: str,
    ) -> ArtifactRef | None:
        """Compile verified claims into the shared table artifact contract."""

        supported = [item for item in claims if item.support_status == "supported"]
        if not supported:
            return None
        nodes: list[dict[str, Any]] = []
        edges: list[dict[str, Any]] = []
        seen_sources: set[str] = set()
        source_refs: list[str] = []
        for claim in supported:
            claim_node_id = f"claim:{claim.claim_id}"
            nodes.append(
                {
                    "node_id": claim_node_id,
                    "node_kind": "grounded_claim",
                    "payload": {
                        "title": claim.text,
                        "claim_kind": claim.claim_kind,
                        "confidence": claim.confidence,
                    },
                }
            )
            for source_ref in claim.source_refs:
                if not source_ref:
                    continue
                source_refs.append(source_ref)
                source_node_id = f"source:{source_ref}"
                if source_node_id not in seen_sources:
                    seen_sources.add(source_node_id)
                    record = self._record_for_ref(principal, source_ref)
                    evidence = self._evidence_from_record(record, score=1.0) if record else None
                    nodes.append(
                        {
                            "node_id": source_node_id,
                            "node_kind": "source",
                            "payload": {
                                "title": evidence.title if evidence else source_ref,
                                "source_ref": source_ref,
                                "url": evidence.url if evidence else "",
                            },
                        }
                    )
                edges.append(
                    {
                        "source_id": claim_node_id,
                        "target_id": source_node_id,
                        "relation": "supported_by",
                        "payload": {
                            "provenance": "verified",
                            "source_refs": [source_ref],
                            "supporting_chunk_ids": list(claim.supporting_chunk_ids),
                        },
                    }
                )
        if not edges:
            return None

        artifact_id = new_id("artifact")
        source_refs = list(dict.fromkeys(source_refs))
        stored = {
            "artifact_id": artifact_id,
            "employee_id": principal.employee_id,
            "capability_id": capability_id,
            "artifact_type": "ontology_graph",
            "status": "provisional",
            "title": "검증된 답변 근거 표",
            "draft": {
                "presentation": "table",
                "nodes": nodes,
                "edges": edges,
                "source_refs": source_refs,
            },
            "work_session_id": str(session["session_id"]),
            "work_run_id": work_run_id,
            "revision": 1,
            "created_at": now_iso(),
            "updated_at": now_iso(),
        }
        self.store.put("artifacts", artifact_id, stored)
        return ArtifactRef(
            artifact_id=artifact_id,
            artifact_type="ontology_graph",
            title=str(stored["title"]),
            status="provisional",
            url=f"/agent?session={session['session_id']}&artifact={artifact_id}",
            preview=f"검증된 claim {len(supported)}건과 직접 근거를 표로 정리했습니다.",
            metadata={
                "capability_id": capability_id,
                "revision": 1,
                "presentation": "table",
                "node_count": len(nodes),
                "edge_count": len(edges),
                "source_refs": source_refs,
            },
        )

    @staticmethod
    def _bounded_mermaid_graph(
        plan: GraphQueryPlan,
        nodes: list[dict[str, Any]],
        edges: list[dict[str, Any]],
        *,
        preserve_focal_set: bool = False,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        """Keep Mermaid artifacts small, connected, and grounded around the focal entity."""

        node_lookup = {
            str(item.get("node_id") or ""): item
            for item in nodes
            if str(item.get("node_id") or "")
        }

        def source_refs(edge: dict[str, Any]) -> list[str]:
            payload = edge.get("payload") if isinstance(edge.get("payload"), dict) else {}
            refs = [str(item) for item in payload.get("source_refs") or [] if str(item)]
            metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
            if metadata.get("source_ref"):
                refs.append(str(metadata["source_ref"]))
            return list(dict.fromkeys(refs))

        grounded_edges = [
            edge
            for edge in edges
            if str(edge.get("source_id") or "") in node_lookup
            and str(edge.get("target_id") or "") in node_lookup
            and source_refs(edge)
        ]
        seeds = [item for item in plan.focal_entities if item in node_lookup]
        seeds = seeds[:4] if preserve_focal_set else seeds[:1]
        if not seeds:
            seeds = list(node_lookup)[:1]

        # The A2UI Mermaid contract allows fourteen nodes and twenty edges.
        # Use that bounded budget here so a structured multi-focal result can
        # retain at least one short branch per requested component before the
        # Catalog's stricter displayed-claim limit is applied below.
        node_limit = 14
        edge_limit = 20
        selected_ids = set(seeds[:node_limit])
        selected_edges: list[dict[str, Any]] = []
        seed_set = set(seeds[:node_limit])
        parent = {seed: seed for seed in seed_set}

        def find(seed: str) -> str:
            while parent[seed] != seed:
                parent[seed] = parent[parent[seed]]
                seed = parent[seed]
            return seed

        def union(left: str, right: str) -> None:
            left_root = find(left)
            right_root = find(right)
            if left_root != right_root:
                parent[right_root] = left_root

        if preserve_focal_set:
            for edge in grounded_edges:
                source_id = str(edge.get("source_id") or "")
                target_id = str(edge.get("target_id") or "")
                if source_id in seed_set and target_id in seed_set:
                    union(source_id, target_id)
                    if len(selected_edges) < edge_limit:
                        selected_edges.append(edge)
        component_map: dict[str, dict[str, int]] = {}
        for seed in seeds[:node_limit]:
            component_map.setdefault(find(seed), {})[seed] = 0
        components = [
            {"depths": depths, "predicates": set()}
            for depths in component_map.values()
        ]
        global_predicates = {
            str(edge.get("relation") or "")
            for edge in selected_edges
            if str(edge.get("relation") or "")
        }
        for component in components:
            component_depths = component["depths"]
            component_predicates = component["predicates"]
            for edge in grounded_edges:
                if (
                    str(edge.get("source_id") or "") in component_depths
                    and str(edge.get("target_id") or "") in component_depths
                ):
                    component_predicates.add(str(edge.get("relation") or ""))

        while components and len(selected_ids) < node_limit and len(selected_edges) < edge_limit:
            progressed = False
            for component in components:
                if len(selected_ids) >= node_limit or len(selected_edges) >= edge_limit:
                    break
                component_depths = component["depths"]
                component_predicates = component["predicates"]
                candidates: list[
                    tuple[int, int, int, int, dict[str, Any], str, str]
                ] = []
                for edge_index, edge in enumerate(grounded_edges):
                    source_id = str(edge.get("source_id") or "")
                    target_id = str(edge.get("target_id") or "")
                    source_inside = source_id in component_depths
                    target_inside = target_id in component_depths
                    if source_inside == target_inside:
                        continue
                    neighbor = target_id if source_inside else source_id
                    if neighbor in selected_ids:
                        continue
                    inside = source_id if source_inside else target_id
                    predicate = str(edge.get("relation") or "")
                    candidates.append(
                        (
                            int(predicate in global_predicates),
                            int(predicate in component_predicates),
                            component_depths[inside],
                            edge_index,
                            edge,
                            neighbor,
                            predicate,
                        )
                    )
                if candidates:
                    (
                        _predicate_seen_globally,
                        _predicate_seen,
                        inside_depth,
                        _edge_index,
                        edge,
                        neighbor,
                        predicate,
                    ) = min(
                        candidates,
                        key=lambda item: (item[0], item[1], item[2], item[3]),
                    )
                    selected_ids.add(neighbor)
                    component_depths[neighbor] = inside_depth + 1
                    component_predicates.add(predicate)
                    global_predicates.add(predicate)
                    selected_edges.append(edge)
                    progressed = True
            if not progressed:
                break

        selected_edge_ids = {str(item.get("edge_id") or id(item)) for item in selected_edges}
        for edge in grounded_edges:
            if len(selected_edges) >= edge_limit:
                break
            edge_key = str(edge.get("edge_id") or id(edge))
            if edge_key in selected_edge_ids:
                continue
            if {
                str(edge.get("source_id") or ""),
                str(edge.get("target_id") or ""),
            } <= selected_ids:
                selected_edges.append(edge)
                selected_edge_ids.add(edge_key)

        incident_refs: dict[str, list[str]] = {}
        for edge in selected_edges:
            refs = source_refs(edge)
            for node_id in (str(edge.get("source_id") or ""), str(edge.get("target_id") or "")):
                incident_refs.setdefault(node_id, []).extend(refs)
        selected_nodes = []
        for item in nodes:
            node_id = str(item.get("node_id") or "")
            if node_id not in selected_ids:
                continue
            node = dict(item)
            payload = dict(node.get("payload") or {})
            refs = [str(value) for value in payload.get("source_refs") or [] if str(value)]
            if payload.get("source_ref"):
                refs.append(str(payload["source_ref"]))
            refs.extend(incident_refs.get(node_id, []))
            payload["source_refs"] = list(dict.fromkeys(refs))
            if not payload["source_refs"]:
                continue
            node["payload"] = payload
            selected_nodes.append(node)
        grounded_node_ids = {str(item.get("node_id") or "") for item in selected_nodes}
        selected_edges = [
            item
            for item in selected_edges
            if str(item.get("source_id") or "") in grounded_node_ids
            and str(item.get("target_id") or "") in grounded_node_ids
        ]
        return selected_nodes[:node_limit], selected_edges[:edge_limit]

    def _draft_prompt(
        self,
        definition: CapabilityDefinition,
        request: AgentTurnRequest,
        evidence: list[EvidenceRef],
    ) -> tuple[str, str, dict[str, Any]]:
        schema = self._draft_schema(definition)
        resolved_goal = str(request.input_delta.get("_resolved_goal") or request.question)
        evidence_payload = [
            {
                "evidence_id": item.evidence_id,
                "title": item.title,
                "summary": item.summary,
                "kind": item.kind,
            }
            for item in evidence
        ]
        raw_session_context = request.input_delta.get("_work_session_context")
        session_context = raw_session_context if isinstance(raw_session_context, dict) else {}
        active_artifact = session_context.get("active_artifact")
        active_artifact_outline = active_artifact if isinstance(active_artifact, dict) else {}
        draft_context = {
            "summary": str(session_context.get("summary") or ""),
            "recent_messages": [
                dict(item)
                for item in (session_context.get("recent_messages") or [])
                if isinstance(item, dict)
            ],
            "active_artifact": active_artifact_outline,
        }
        system = (
            "You are the BoI Wiki draft engine. Create a private draft only. "
            "Do not claim that anything was published, executed, approved, or saved to production. "
            "Use only supplied evidence, name missing information explicitly, and write user-facing Korean. "
            "For SOP tasks, write completion labels as plain workplace Korean that a general employee can check. "
            "Never put raw BoI IDs, Event Type IDs, Action keys, JSON paths, or workflow IDs in a user-facing label. "
            "Put technical references only in completion_design bindings or evidence refs. "
            "Manual and Copilot completion requires human confirmation. Autopilot requires real system bindings; "
            "when no binding is known, leave it unresolved instead of claiming automatic verification."
            " For Skill drafts, declare invocation_mode as guide_only, agent_tool, or sandbox_run. "
            "guide_only never executes; agent_tool binds only to registered available_actions; sandbox_run carries only a reviewed "
            "server-side runtime_binding and can run only after confirmation in an isolated runtime."
            " For an SOP, derive the Task sequence from the requested goal, evidence, and completion contract. The server "
            "builds Mermaid and structured completion bindings from the Task sequence, exit criteria, and evidence."
        )
        prompt = (
            f"Capability: {definition.capability_id}\nGoal: {resolved_goal}\n"
            f"Page: {request.page_ref or '-'}\n"
            f"External AI summary (untrusted supporting context): {request.external_ai_summary or '-'}\n"
            f"External artifact references: {json.dumps(request.external_artifact_refs, ensure_ascii=False)}\n"
            f"Work session context: {json.dumps(draft_context, ensure_ascii=False)}\n"
            f"Helper instructions: {str(request.input_delta.get('_helper_instructions') or '') or '-'}\n"
            f"Verified helper Skills: {json.dumps(request.input_delta.get('_helper_skills') or [], ensure_ascii=False)}\n"
            f"Evidence:\n{json.dumps(evidence_payload, ensure_ascii=False)}"
        )
        return system, prompt, schema

    def _draft_contract(self, definition: CapabilityDefinition):
        contract_id = str(definition.handler_config.get("draft_contract") or "")
        if not contract_id:
            raise RuntimeError("draft contract is missing from the capability catalog")
        try:
            return self.registry.draft_contract(contract_id)
        except KeyError as exc:
            raise RuntimeError(f"unknown draft contract: {contract_id}") from exc

    def _draft_schema(self, definition: CapabilityDefinition) -> dict[str, Any]:
        return copy.deepcopy(self._draft_contract(definition).schema_)

    @staticmethod
    def _validate_sop_tasks(draft: dict[str, Any]) -> None:
        tasks = draft.get("tasks") or []
        if not tasks or any(not isinstance(task, dict) for task in tasks):
            raise RuntimeError("SOP draft requires one or more structured tasks")
        for index, task in enumerate(tasks):
            missing_task_fields = [
                field
                for field in ("name", "purpose", "execution_mode", "exit_criteria", "required_evidence")
                if task.get(field) in (None, "", [], {})
            ]
            if missing_task_fields:
                raise RuntimeError(
                    f"SOP task {index + 1} is missing: " + ", ".join(missing_task_fields)
                )
            if str(task.get("execution_mode") or "").lower() not in {"manual", "copilot", "autopilot"}:
                raise RuntimeError(f"SOP task {index + 1} has an invalid execution_mode")
            step_kind = str(task.get("step_kind") or "")
            if step_kind and step_kind not in {
                "EventWait",
                "Decision",
                "ManualTask",
                "AgentTask",
                "ActionInvoke",
                "HumanApproval",
            }:
                raise RuntimeError(f"SOP task {index + 1} has an invalid step_kind")
            executor_binding = str(task.get("executor_binding") or "")
            if executor_binding and executor_binding not in {
                "human",
                "action",
                "agent_claim",
                "external_manual",
                "hybrid",
            }:
                raise RuntimeError(f"SOP task {index + 1} has an invalid executor_binding")

    @staticmethod
    def _validate_preview_only(draft: dict[str, Any]) -> None:
        if draft.get("preview_only") is not True:
            raise RuntimeError("Action draft must remain preview_only")

    @staticmethod
    def _validate_skill_tests(draft: dict[str, Any]) -> None:
        tests = [item for item in draft.get("tests") or [] if isinstance(item, dict)]
        if not tests or any(
            not isinstance(item.get("sample_input"), dict)
            or not isinstance(item.get("expected_contains"), list)
            or not item.get("expected_contains")
            for item in tests
        ):
            raise RuntimeError("Skill draft requires a runnable sample_input and expected_contains test")

    @staticmethod
    def _validate_provisional_status(draft: dict[str, Any]) -> None:
        if draft.get("status") != "provisional":
            raise RuntimeError("knowledge draft must remain provisional")

    def _validate_draft(self, definition: CapabilityDefinition, draft: dict[str, Any]) -> None:
        schema = self._draft_schema(definition)
        missing = [
            key
            for key in schema.get("required") or []
            if key not in draft or draft.get(key) in (None, "", [])
        ]
        if missing:
            raise RuntimeError("draft is missing required fields: " + ", ".join(missing))
        validators = {
            "sop_tasks": self._validate_sop_tasks,
            "preview_only": self._validate_preview_only,
            "skill_tests": self._validate_skill_tests,
            "provisional_status": self._validate_provisional_status,
        }
        for plugin_id in self._draft_contract(definition).validator_plugins:
            validator = validators.get(str(plugin_id))
            if validator is None:
                raise RuntimeError(f"unknown draft validator plugin: {plugin_id}")
            validator(draft)

    def _normalise_draft(
        self,
        definition: CapabilityDefinition,
        draft: dict[str, Any],
        *,
        principal: Principal,
        source_refs: list[str] | None = None,
    ) -> dict[str, Any]:
        normalizers = {
            "sop_tasks": lambda value: self._normalise_sop_draft(
                value,
                principal=principal,
                source_refs=source_refs,
            ),
            "skill_contract": self._normalise_skill_draft,
        }
        normalised = copy.deepcopy(draft)
        for plugin_id in self._draft_contract(definition).normalizer_plugins:
            normalizer = normalizers.get(str(plugin_id))
            if normalizer is None:
                raise RuntimeError(f"unknown draft normalizer plugin: {plugin_id}")
            normalised = normalizer(normalised)
        return normalised

    @staticmethod
    def _normalise_skill_draft(draft: dict[str, Any]) -> dict[str, Any]:
        normalised = copy.deepcopy(draft)
        invocation_mode = str(normalised.get("invocation_mode") or "guide_only").strip().lower()
        if invocation_mode not in {"guide_only", "agent_tool", "sandbox_run"}:
            invocation_mode = "guide_only"
        normalised["invocation_mode"] = invocation_mode
        binding = (
            copy.deepcopy(normalised.get("runtime_binding"))
            if isinstance(normalised.get("runtime_binding"), dict)
            else {}
        )
        if invocation_mode == "agent_tool" and not binding.get("action_ref"):
            actions = [str(item) for item in normalised.get("available_actions") or [] if str(item).strip()]
            if len(actions) == 1:
                binding["action_ref"] = actions[0]
        binding.setdefault("language", "none")
        normalised["runtime_binding"] = binding
        normalised["browser_execution_allowed"] = False
        normalised["execution_boundary"] = {
            "guide_only": "manual_handoff",
            "agent_tool": "action_gateway",
            "sandbox_run": "isolated_runtime",
        }[invocation_mode]
        return normalised

    def _normalise_sop_task(
        self,
        task: dict[str, Any],
        index: int,
        *,
        principal: Principal | None = None,
    ) -> dict[str, Any]:
        normalised = dict(task)
        normalised["task_id"] = str(task.get("task_id") or new_id("task"))
        task_name = str(task.get("name") or f"Task {index + 1}").strip()
        normalised["name"] = re.sub(r"^\d+[.)]\s*", "", task_name) or f"Task {index + 1}"
        normalised["purpose"] = str(task.get("purpose") or task.get("goal") or "").strip()
        mode = str(task.get("execution_mode") or task.get("mode") or "copilot").lower()
        normalised["execution_mode"] = mode if mode in {"manual", "copilot", "autopilot"} else "copilot"
        normalised["task_mode"] = normalised["execution_mode"]
        for field in (
            "exit_criteria",
            "required_evidence",
            "outputs",
            "action_refs",
            "event_refs",
            "skill_refs",
            "verification",
            "fallback",
        ):
            value = task.get(field) or []
            if isinstance(value, str):
                value = [item.strip() for item in re.split(r"[\n,]", value) if item.strip()]
            normalised[field] = [str(item) for item in value if str(item).strip()]
        normalised["tat"] = str(task.get("tat") or task.get("target_tat") or "")
        label_lookup = self._completion_label_lookup(principal) if principal is not None else {}
        normalised = normalise_task_completion(normalised, label_lookup=label_lookup)
        normalised["completion_design"] = TaskCompletionDesign.model_validate(
            normalised.get("completion_design")
        ).model_dump(mode="json", exclude_none=True)
        allowed_step_kinds = {
            "EventWait",
            "Decision",
            "ManualTask",
            "AgentTask",
            "ActionInvoke",
            "HumanApproval",
        }
        requested_step_kind = str(task.get("step_kind") or "")
        normalised["step_kind"] = (
            requested_step_kind
            if requested_step_kind in allowed_step_kinds
            else "ManualTask"
            if normalised["task_mode"] == "manual"
            else "AgentTask"
        )
        default_executor = {
            "manual": "human",
            "copilot": "hybrid",
            "autopilot": "action" if normalised["action_refs"] else "agent_claim",
        }[normalised["task_mode"]]
        requested_executor = str(task.get("executor_binding") or "")
        allowed_executors = {"human", "action", "agent_claim", "external_manual", "hybrid"}
        normalised["executor_binding"] = (
            requested_executor if requested_executor in allowed_executors else default_executor
        )
        if normalised["step_kind"] in {"ManualTask", "HumanApproval"}:
            normalised["executor_binding"] = "human"
        elif normalised["step_kind"] == "ActionInvoke":
            normalised["executor_binding"] = "action"
        completion_checks = [
            item
            for item in normalised["completion_design"].get("checks") or []
            if isinstance(item, dict)
        ]
        system_complete = bool(completion_checks) and all(
            item.get("confirmation") == "system"
            and isinstance(item.get("binding"), dict)
            and item["binding"].get("kind") not in {None, "", "none"}
            and item["binding"].get("ref")
            for item in completion_checks
        )
        normalised["executor_readiness"] = (
            "unavailable"
            if normalised["task_mode"] == "autopilot" and not system_complete
            else "ready"
        )
        if normalised["step_kind"] == "EventWait" and not normalised["event_refs"]:
            normalised["executor_readiness"] = "unavailable"
        if normalised["step_kind"] == "ActionInvoke" and not normalised["action_refs"]:
            normalised["executor_readiness"] = "unavailable"
        if normalised["step_kind"] == "HumanApproval":
            normalised["approval_policy"] = (
                task.get("approval_policy")
                if isinstance(task.get("approval_policy"), dict)
                else {"required": True, "approver_source": "authenticated_principal"}
            )
        return normalised

    @staticmethod
    def _mermaid_from_tasks(tasks: list[dict[str, Any]]) -> str:
        lines = ["flowchart TD"]
        if not tasks:
            lines.append('  empty["Task를 추가하세요"]')
            return "\n".join(lines)
        for index, task in enumerate(tasks):
            node_id = f"T{index + 1}"
            name = str(task.get("name") or f"Task {index + 1}").replace('"', "'").replace("\n", " ")[:80]
            mode = str(task.get("task_mode") or task.get("execution_mode") or "copilot").capitalize()
            step_kind = str(task.get("step_kind") or "AgentTask")
            executor = str(task.get("executor_binding") or "hybrid")
            lines.append(
                f'  {node_id}["{index + 1}. {name}<br/>{step_kind} · {mode} · {executor}"]'
            )
            if index:
                lines.append(f"  T{index} --> {node_id}")
        return "\n".join(lines)

    def _sop_catalog_bindings(
        self,
        *,
        principal: Principal,
        source_refs: list[str],
        tasks: list[dict[str, Any]],
        declared: dict[str, Any],
    ) -> dict[str, list[str]]:
        """Compile SOP bindings from typed, ACL-visible catalog relations."""

        records = self.repository.authoritative_records(principal, include_drafts=False)
        known_by_kind = {
            kind: {
                str(record.record_id).removeprefix(f"{kind}:")
                for record in records
                if record.kind == kind
            }
            for kind in ("event", "action", "skill")
        }
        selected_refs = {str(item) for item in source_refs if str(item).strip()}
        ontology_bindings: dict[str, list[str]] = {
            "events": [],
            "actions": [],
            "skills": [],
        }
        if selected_refs:
            graph = self.store.ontology_neighbors(
                sorted(selected_refs),
                depth=1,
                limit=max(24, min(120, len(selected_refs) * 24)),
                employee_id=principal.employee_id,
                team_ids=list(principal.teams),
                include_all=principal.is_admin,
                relation_kinds=["links_to", "uses_event", "uses_action", "uses_skill"],
            )
            binding_for_kind = {
                "event": "events",
                "action": "actions",
                "skill": "skills",
            }
            for node in graph.get("nodes") or []:
                if not isinstance(node, dict):
                    continue
                node_kind = str(node.get("node_type") or "")
                binding = binding_for_kind.get(node_kind)
                node_id = str(node.get("node_id") or "").strip()
                if not binding or not node_id:
                    continue
                ontology_bindings[binding].append(
                    node_id.removeprefix(f"{node_kind}:")
                )
        related_workflows: list[dict[str, Any]] = []
        for record in records:
            if record.kind != "workflow":
                continue
            metadata = record.metadata if isinstance(record.metadata, dict) else {}
            linked_sops = {
                str(item)
                for item in [
                    metadata.get("primary_sop_ref"),
                    *(metadata.get("sop_refs") or []),
                ]
                if str(item).strip()
            }
            if record.record_id in selected_refs or linked_sops.intersection(selected_refs):
                related_workflows.append(metadata)

        raw = {
            "events": [
                *(declared.get("events") if isinstance(declared.get("events"), list) else []),
                *ontology_bindings["events"],
                *[
                    str(ref)
                    for task in tasks
                    for ref in task.get("event_refs") or []
                ],
                *[
                    str(ref)
                    for workflow in related_workflows
                    for ref in [
                        *(workflow.get("entry_events") or []),
                        *(workflow.get("emitted_events") or []),
                        *[
                            item.get("event_type")
                            for item in workflow.get("event_contracts") or []
                            if isinstance(item, dict)
                        ],
                    ]
                ],
            ],
            "actions": [
                *(declared.get("actions") if isinstance(declared.get("actions"), list) else []),
                *ontology_bindings["actions"],
                *[
                    str(ref)
                    for task in tasks
                    for ref in task.get("action_refs") or []
                ],
                *[
                    str(ref)
                    for workflow in related_workflows
                    for ref in workflow.get("action_refs") or []
                ],
            ],
            "skills": [
                *(declared.get("skills") if isinstance(declared.get("skills"), list) else []),
                *ontology_bindings["skills"],
                *[
                    str(ref)
                    for task in tasks
                    for ref in task.get("skill_refs") or []
                ],
                *[
                    str(ref)
                    for workflow in related_workflows
                    for ref in [
                        *(workflow.get("event_skill_refs") or []),
                        *(workflow.get("action_skill_refs") or []),
                    ]
                ],
            ],
        }
        kind_for_binding = {"events": "event", "actions": "action", "skills": "skill"}
        return {
            binding: list(
                dict.fromkeys(
                    ref
                    for raw_ref in candidates
                    if (ref := str(raw_ref or "").strip())
                    in known_by_kind[kind_for_binding[binding]]
                )
            )
            for binding, candidates in raw.items()
        }

    def _normalise_sop_draft(
        self,
        draft: dict[str, Any],
        *,
        principal: Principal | None = None,
        source_refs: list[str] | None = None,
    ) -> dict[str, Any]:
        normalised = dict(draft)
        tasks = [
            self._normalise_sop_task(item, index, principal=principal)
            for index, item in enumerate(draft.get("tasks") or [])
            if isinstance(item, dict)
        ]
        normalised["tasks"] = tasks
        normalised["mermaid"] = self._mermaid_from_tasks(tasks)
        normalised.setdefault("gaps", [])
        selected_source_refs = list(
            dict.fromkeys(
                str(item)
                for item in [*(source_refs or []), *(draft.get("source_refs") or [])]
                if str(item).strip()
            )
        )

        def values(field: str) -> list[str]:
            raw = normalised.get(field)
            if isinstance(raw, str):
                raw = [raw]
            if isinstance(raw, list):
                explicit = [str(item).strip() for item in raw if str(item).strip()]
                if explicit:
                    return list(dict.fromkeys(explicit))
            return []

        task_required_evidence = list(
            dict.fromkeys(
                str(item)
                for task in tasks
                for item in task.get("required_evidence") or []
                if str(item).strip()
            )
        )
        task_outputs = list(
            dict.fromkeys(
                str(item)
                for task in tasks
                for item in task.get("outputs") or []
                if str(item).strip()
            )
        )
        completion_conditions = list(
            dict.fromkeys(
                str(item)
                for task in tasks
                for item in task.get("exit_criteria") or []
                if str(item).strip()
            )
        )
        normalised["inputs"] = values("inputs") or task_required_evidence or selected_source_refs
        normalised["outputs"] = values("outputs") or task_outputs or [
            f"{task.get('name') or 'Task'} 완료 결과" for task in tasks
        ]
        normalised["completion_conditions"] = values("completion_conditions") or completion_conditions
        normalised["required_evidence"] = (
            values("required_evidence") or task_required_evidence or selected_source_refs
        )
        normalised["risks"] = values("risks") or [
            "근거가 누락되거나 상충하면 실행하지 않고 사람 검토로 전환한다."
        ]
        normalised["source_refs"] = selected_source_refs
        if principal is not None:
            declared_bindings = (
                normalised.get("bindings")
                if isinstance(normalised.get("bindings"), dict)
                else {}
            )
            normalised["bindings"] = self._sop_catalog_bindings(
                principal=principal,
                source_refs=selected_source_refs,
                tasks=tasks,
                declared=declared_bindings,
            )
        else:
            normalised.setdefault("bindings", {"events": [], "actions": [], "skills": []})
        return normalised

    def _draft(
        self,
        principal: Principal,
        definition: CapabilityDefinition,
        request: AgentTurnRequest,
        evidence: list[EvidenceRef],
        *,
        work_run_id: str = "",
        prefilled_draft: dict[str, Any] | None = None,
    ) -> tuple[AnswerBlock, ArtifactRef, str]:
        system, prompt, schema = self._draft_prompt(definition, request, evidence)
        validation_error = ""
        draft: dict[str, Any] = copy.deepcopy(prefilled_draft or {})
        if draft:
            self._validate_draft(definition, draft)
        else:
            for attempt in range(2):
                repair_prompt = prompt
                if validation_error:
                    repair_prompt += (
                        "\nThe previous draft was rejected by deterministic validation: "
                        f"{validation_error}. Regenerate the entire object and satisfy every required field."
                    )
                draft = self.model.generate_structured(system=system, prompt=repair_prompt, schema=schema)
                try:
                    self._validate_draft(definition, draft)
                    break
                except RuntimeError as exc:
                    validation_error = str(exc)
                    if attempt == 1:
                        raise
        source_refs = list(
            dict.fromkeys(item.evidence_id for item in evidence if item.evidence_id)
        )
        draft = self._normalise_draft(
            definition,
            draft,
            principal=principal,
            source_refs=source_refs,
        )
        title = str(draft.get("title") or definition.title).strip()
        title = re.sub(r"^\[(?:비공개\s*초안|private\s*draft)\]\s*", "", title, flags=re.IGNORECASE)
        title = re.sub(r"^(?:비공개\s*(?:SOP\s*)?초안|private\s*draft)\s*[:：-]\s*", "", title, flags=re.IGNORECASE)
        title = title or definition.title
        draft["title"] = title
        # A private preview already passed its schema, evidence and domain
        # validators above. A second model review made the user wait for a
        # result that still required human confirmation, so semantic review is
        # performed only by an explicit validate/test operation.
        independent_review = {
            "status": "not_requested",
            "summary": "개인 초안입니다. 게시 또는 실행 전에 검토를 요청할 수 있습니다.",
        }
        artifact_id = new_id("artifact")
        plan_id = new_id("plan")
        domain_operation = str(definition.handler_config.get("domain_operation") or "")
        domain_result: dict[str, Any] = {}
        if domain_operation and self.domain_services.supports(domain_operation):
            domain_result = self.domain_services.execute(
                domain_operation,
                principal,
                {
                    "artifact_id": artifact_id,
                    "plan_id": plan_id,
                    "capability_id": definition.capability_id,
                    "goal": request.question,
                    "page_ref": request.page_ref,
                    "task_ref": request.task_ref,
                    "work_session_id": request.work_session_id or "",
                    "draft": copy.deepcopy(draft),
                    "evidence_refs": [item.model_dump(mode="json") for item in evidence],
                },
            )
        artifact_type = str(definition.output_schema.get("type") or "draft")
        artifact_status = str(definition.handler_config.get("artifact_status") or "draft")
        configured_next_actions = self._configured_next_actions(
            definition,
            artifact_id=artifact_id,
            plan_id=plan_id,
            work_session_id=request.work_session_id or "",
        )
        task_refs = {
            str(item.get("task_id") or item.get("name") or "")
            for item in draft.get("tasks") or []
            if isinstance(item, dict)
            and str(item.get("task_id") or item.get("name") or "").strip()
        }
        editable_diff = {
            "base_artifact_id": "",
            "base_revision": 0,
            "changed_fields": sorted(str(key) for key in draft),
            "added_task_refs": sorted(task_refs),
            "removed_task_refs": [],
            "before_task_count": 0,
            "after_task_count": len(task_refs),
        }
        payload = {
            "artifact_id": artifact_id,
            "employee_id": principal.employee_id,
            "capability_id": definition.capability_id,
            "artifact_type": artifact_type,
            "status": artifact_status,
            "title": title,
            "draft": draft,
            "work_session_id": request.work_session_id or "",
            "revision": 1,
            "source_refs": source_refs,
            "evidence_ledger": [
                {"evidence_id": item.evidence_id, "title": item.title, "url": item.url}
                for item in evidence
            ],
            "domain": domain_result,
            "independent_review": independent_review,
            "next_actions": configured_next_actions,
            "editable_diff": editable_diff,
            "diff": editable_diff,
            "created_at": now_iso(),
            "updated_at": now_iso(),
            "generation_attempts": 2 if validation_error else 1,
            "preview_only": True,
            "production_changed": False,
        }
        self.store.put("artifacts", artifact_id, payload)
        self.store.put(
            "plans",
            plan_id,
            {
                "plan_id": plan_id,
                "employee_id": principal.employee_id,
                "capability_id": definition.capability_id,
                "artifact_id": artifact_id,
                "status": "draft",
                "risk": definition.risk.value,
                "domain_operation": str(domain_result.get("confirm_operation") or ""),
                "domain_ref": str(domain_result.get("domain_ref") or ""),
                "domain_kind": str(domain_result.get("domain_kind") or ""),
                "domain_validation": domain_result.get("validation") or {},
                "evaluation_ref": str(independent_review.get("evaluation_id") or ""),
                "review_status": str(independent_review.get("status") or "unavailable"),
                "production_changed": False,
                "work_run_id": work_run_id,
                "created_at": now_iso(),
            },
        )
        preview = json.dumps(draft, ensure_ascii=False, indent=2)[:1800]
        artifact = ArtifactRef(
            artifact_id=artifact_id,
            artifact_type=artifact_type,
            title=title,
            status=artifact_status,  # type: ignore[arg-type]
            url=(
                f"/agent?session={request.work_session_id}&artifact={artifact_id}"
                if request.work_session_id
                else f"/agent?artifact={artifact_id}"
            ),
            preview=preview,
            metadata={
                "plan_id": plan_id,
                "capability_id": definition.capability_id,
                "mermaid": str(draft.get("mermaid") or ""),
                "revision": 1,
                "task_count": len(draft.get("tasks") or []) if isinstance(draft.get("tasks"), list) else 0,
                "domain_ref": str(domain_result.get("domain_ref") or ""),
                "domain_kind": str(domain_result.get("domain_kind") or ""),
                "domain_status": str(domain_result.get("status") or ""),
                "evaluation_ref": str(independent_review.get("evaluation_id") or ""),
                "review_status": str(independent_review.get("status") or "unavailable"),
                "next_actions": configured_next_actions,
                "source_refs": source_refs,
                "presentation": "artifact",
                "editable_diff": editable_diff,
                "preview_only": True,
                "production_changed": False,
            },
        )
        task_summary = ""
        if isinstance(draft.get("tasks"), list):
            task_summary = f"\n\nTask {len(draft.get('tasks') or [])}개와 각 Task의 종료 기준·필수 근거를 결과 영역에 정리했습니다."
        review_summary = ""
        if independent_review.get("status") == "needs_revision":
            review_summary = "\n\n별도 검토에서 보완할 점이 확인되었습니다. 결과 영역의 검토 내용을 반영한 뒤 게시를 요청하세요."
        answer = AnswerBlock(
            summary=f"'{title}' 개인 초안을 만들었습니다. 아직 게시하거나 실행하지 않았습니다.",
            markdown=(
                f"### {title}\n\n개인 초안입니다. 근거와 누락 항목을 확인한 뒤 다음 단계를 선택하세요."
                f"{task_summary}"
                f"{review_summary}"
                + (
                    f"\n\n기존 {domain_result.get('domain_label') or '업무'} 초안 `{domain_result.get('domain_ref')}`과 연결했습니다."
                    if domain_result.get("domain_ref")
                    else ""
                )
            ),
        )
        return answer, artifact, plan_id

    @staticmethod
    def _configured_next_actions(
        definition: CapabilityDefinition,
        *,
        artifact_id: str,
        plan_id: str,
        work_session_id: str,
    ) -> list[dict[str, Any]]:
        """Bind catalog-declared commands without inferring them from capability IDs."""

        configured: list[dict[str, Any]] = []
        for raw in definition.handler_config.get("next_actions") or []:
            if not isinstance(raw, dict):
                continue
            payload = {
                key: value
                for key, value in raw.items()
                if key not in {"bind_artifact", "bind_plan", "href_template"}
            }
            if raw.get("bind_artifact"):
                payload["artifact_id"] = artifact_id
            if raw.get("bind_plan"):
                payload["plan_id"] = plan_id
            href_template = str(raw.get("href_template") or "")
            if href_template:
                payload["href"] = (
                    href_template.replace("{artifact_id}", artifact_id)
                    .replace("{plan_id}", plan_id)
                    .replace("{work_session_id}", work_session_id)
                )
            try:
                configured.append(NextAction.model_validate(payload).model_dump(mode="json"))
            except ValueError:
                continue
        return configured[:3]

    def _queue_deep_job(
        self,
        principal: Principal,
        definition: CapabilityDefinition,
        request: AgentTurnRequest,
        context: WorkContextPack,
        *,
        work_session_id: str,
        work_run_id: str,
    ) -> str:
        job_id = new_id("job")
        checkpoint_id = f"checkpoint_{hashlib.sha256(f'{job_id}:queued'.encode('utf-8')).hexdigest()[:32]}"
        queued_at = now_iso()
        pilot_mode = bool(request.input_delta.get("pilot_mode", True))
        requested_tools = int(request.input_delta.get("max_tool_calls") or 5)
        max_tool_calls = max(1, min(requested_tools, 5 if pilot_mode else 12))
        requested_budget = int(request.input_delta.get("token_budget") or self.settings.deep_token_budget)
        token_budget = max(4000, min(requested_budget, self.settings.deep_token_budget))
        deep_context_budget = resolve_context_budget(
            self.settings,
            requested_tokens=self.settings.deep_max_input_tokens,
            residency_state=self.model_residency,
        ).effective_tokens
        requested_subagents = int(request.input_delta.get("max_subagents") if request.input_delta.get("max_subagents") is not None else 2)
        subagent_budget_limit = deep_subagent_budget_limit(
            token_budget,
            deep_context_budget,
            hard_limit=2 if pilot_mode else 4,
            min_window_tokens=self.settings.deep_min_window_tokens,
        )
        max_subagents = max(0, min(requested_subagents, 2 if pilot_mode else 4, subagent_budget_limit))
        execution_windows = max_subagents + 2
        max_input_tokens = min(
            deep_context_budget,
            max(1_000, token_budget // execution_windows),
        )
        require_subagent = bool(request.input_delta.get("require_subagent", False))
        if require_subagent and max_subagents < 1:
            minimum_window = min(deep_context_budget, self.settings.deep_min_window_tokens)
            raise HTTPException(
                status_code=422,
                detail=(
                    "격리 검증을 요청하려면 token_budget을 최소 "
                    f"{minimum_window * 3}로 늘리고 max_subagents를 1 이상으로 설정해주세요."
                ),
            )
        requested_parallelism = int(request.input_delta.get("max_parallelism") or 2)
        max_parallelism = max(1, min(requested_parallelism, max(1, max_subagents), 2 if pilot_mode else 4))
        self.store.put(
            "jobs",
            job_id,
            {
                "job_id": job_id,
                "employee_id": principal.employee_id,
                "principal_roles": list(principal.roles),
                "principal_teams": list(principal.teams),
                "capability_id": definition.capability_id,
                "goal": str(request.input_delta.get("_resolved_goal") or request.question),
                "context_id": context.context_id,
                "work_session_id": work_session_id,
                "work_run_id": work_run_id,
                "status": "queued",
                "revision": 1,
                "attempt": 0,
                "max_attempts": 2,
                "pilot_mode": pilot_mode,
                "max_tool_calls": max_tool_calls,
                "requested_max_subagents": requested_subagents,
                "subagent_budget_limit": subagent_budget_limit,
                "max_subagents": max_subagents,
                "max_parallelism": max_parallelism,
                "subagent_policy": (
                    "enabled"
                    if max_subagents
                    else "disabled_by_token_budget"
                    if requested_subagents
                    else "disabled_by_request"
                ),
                "require_subagent": require_subagent,
                "token_budget": token_budget,
                "provider_context_capacity": deep_context_budget,
                "max_input_tokens": max_input_tokens,
                "independent_review_required": True,
                "timeout_seconds": max(30, min(int(request.input_delta.get("timeout_seconds") or 900), 3600)),
                "expires_at": (datetime.now(timezone.utc) + timedelta(seconds=max(30, min(int(request.input_delta.get("timeout_seconds") or 900), 3600)))).isoformat(),
                "checkpoint": {
                    "checkpoint_id": checkpoint_id,
                    "stage": "queued",
                    "progress": 0,
                    "pending_interrupt": "",
                    "harness_revision": self.harnesses.version,
                    "catalog_revision": self.registry.version,
                    "planner_schema_revision": "semantic-plan/v4",
                    "created_at": queued_at,
                },
                "progress_deltas": [
                    {
                        "delta_id": f"delta_{hashlib.sha256(f'{job_id}:queued'.encode('utf-8')).hexdigest()[:32]}",
                        "kind": "state_transition",
                        "state": "queued",
                        "summary": "심층 작업을 대기열에 등록했습니다.",
                        "checkpoint_id": checkpoint_id,
                        "created_at": queued_at,
                    }
                ],
                "child_job_ids": [],
                "orphan_workers": 0,
                "created_at": queued_at,
            },
        )
        self.store.put(
            "checkpoints",
            checkpoint_id,
            {
                "job_id": job_id,
                "work_run_id": work_run_id,
                "checkpoint_id": checkpoint_id,
                "stage": "queued",
                "progress": 0,
                "pending_interrupt": "",
                "harness_revision": self.harnesses.version,
                "catalog_revision": self.registry.version,
                "planner_schema_revision": "semantic-plan/v4",
                "created_at": queued_at,
            },
        )
        return job_id

    def _next_actions(
        self,
        *,
        work_session_id: str,
        artifacts: list[ArtifactRef],
        evidence: list[EvidenceRef],
        plan_ref: str = "",
    ) -> list[NextAction]:
        actions: list[NextAction] = []
        if plan_ref:
            actions.append(
                NextAction(
                    action_id="confirm_plan",
                    label="실행 계획 확인",
                    action_kind="confirm_plan",
                    plan_id=plan_ref,
                )
            )
        for artifact in artifacts:
            for configured in artifact.metadata.get("next_actions") or []:
                if not isinstance(configured, dict):
                    continue
                payload = dict(configured)
                payload.setdefault("artifact_id", artifact.artifact_id)
                if plan_ref:
                    payload.setdefault("plan_id", plan_ref)
                try:
                    actions.append(NextAction.model_validate(payload))
                except ValueError:
                    continue
            for artifact_action in artifact.actions:
                actions.append(
                    NextAction(
                        action_id=artifact_action.action_id,
                        label=artifact_action.label,
                        action_kind=artifact_action.action_kind,
                        state=artifact_action.state,
                        artifact_id=artifact.artifact_id,
                    )
                )
        if evidence:
            actions.append(
                NextAction(
                    action_id="show_sources",
                    label="사용한 지식",
                    action_kind="show_sources",
                )
            )
        unique_actions: list[NextAction] = []
        seen_actions: set[tuple[str, str, str, str]] = set()
        for action in actions:
            key = (
                action.action_kind,
                action.plan_id,
                action.artifact_id,
                action.task_id,
            )
            if key in seen_actions:
                continue
            seen_actions.add(key)
            unique_actions.append(action)
        return unique_actions[:3]

    def _active_session_work_run(self, principal: Principal, session: dict[str, Any]) -> dict[str, Any] | None:
        work_run_id = str(session.get("active_work_run_id") or "")
        if not work_run_id:
            return None
        work_run = self.store.get("work_runs", work_run_id)
        if not work_run or not self._owns(principal, work_run):
            return None
        if str(work_run.get("status") or "") in {"completed", "failed", "cancelled", "stopped"}:
            return None
        return work_run

    def _active_work_run_for_planner(self, work_run: dict[str, Any] | None) -> dict[str, Any]:
        if not work_run:
            return {}
        intent = work_run.get("intent") if isinstance(work_run.get("intent"), dict) else {}
        context = self.store.get("contexts", str(work_run.get("context_id") or "")) or {}
        completion = context.get("completion_design") if isinstance(context.get("completion_design"), dict) else {}
        last_delta = (work_run.get("loop") or {}).get("deltas") or []
        return {
            "work_run_id": str(work_run.get("work_run_id") or ""),
            "status": str(work_run.get("status") or ""),
            "decision": str(work_run.get("decision") or ""),
            "task_mode": str(work_run.get("task_mode") or ""),
            "goal": compact_text(str(intent.get("goal") or ""), 500),
            "asset_kind": str(intent.get("asset_kind") or ""),
            "operation": str(intent.get("operation") or ""),
            "stop_reason": str(work_run.get("stop_reason") or ""),
            "task_ref": str(context.get("task_ref") or ""),
            "completion_items": [
                str(item.get("label") or "")
                for item in completion.get("checks") or []
                if isinstance(item, dict) and item.get("label")
            ],
            "required_evidence": [
                str(item.get("label") or "")
                for item in completion.get("evidence") or []
                if isinstance(item, dict) and item.get("label") and item.get("required", True)
            ],
            "last_progress": compact_text(str((last_delta[-1] if last_delta else {}).get("summary") or ""), 500),
        }

    @staticmethod
    def _semantic_continuation_applies(
        route: dict[str, Any],
        intent: WorkIntent,
    ) -> bool:
        continuation = (
            (route.get("semantic_plan") or {}).get("continuation")
            if isinstance(route.get("semantic_plan"), dict)
            else {}
        ) or {}
        if route.get("source") != "llm_structured" or not bool(
            continuation.get("continue_active_run")
        ):
            return False
        # A private artifact transition must run its compiled capability.  It
        # is not evidence or human confirmation for a pre-existing WorkRun.
        # Real execute/complete continuations remain eligible.
        return not (
            intent.user_effect in {"draft", "transform"}
            and intent.requested_transition in {"draft", "transform"}
        )

    def _continue_active_work_from_turn(
        self,
        *,
        principal: Principal,
        request: AgentTurnRequest,
        session: dict[str, Any],
        active_work_run: dict[str, Any],
        route: dict[str, Any],
        run_id: str,
        turn_id: str,
    ) -> AgentTurnResponse:
        semantic_plan = SemanticPlan.model_validate(route.get("semantic_plan") or {})
        continuation = semantic_plan.continuation
        if not continuation.continue_active_run or continuation.delta_kind == "none":
            raise SemanticPlanningError(
                "planner_invalid",
                "The validated SemanticPlan does not contain a WorkRun continuation delta.",
            )
        delta_kind = continuation.delta_kind
        external_refs = [str(item).strip() for item in request.external_artifact_refs if str(item).strip()]
        delta_ref = external_refs[0] if external_refs else ""
        user_confirmation = continuation.user_confirmation
        work_record = continuation.work_record.model_dump(mode="json", exclude_defaults=True)
        continued, candidates = self.learning.continue_run(
            principal,
            str(active_work_run["work_run_id"]),
            WorkRunContinueRequest(
                expected_revision=int(active_work_run.get("revision") or 1),
                idempotency_key=str(request.input_delta.get("idempotency_key") or ""),
                confirmation="confirm" if user_confirmation else None,
                delta=LoopDelta(
                    kind=delta_kind,  # type: ignore[arg-type]
                    summary=compact_text(request.question, 2000),
                    ref=delta_ref,
                    metadata={
                        "semantic_continuation": True,
                        "external_ai_summary_present": bool(request.external_ai_summary.strip()),
                        "external_artifact_ref_count": len(external_refs),
                        **({"work_record": work_record} if work_record else {}),
                    },
                ),
            ),
        )
        context_row = self.store.get("contexts", str(continued.get("context_id") or "")) or {}
        agent_run = self.store.get("runs", str(continued.get("agent_run_id") or "")) or {}
        semantic_plan_row = self.store.get(
            "semantic_plans",
            str(continued.get("semantic_plan_ref") or ""),
        ) or {}
        semantic_plan = (
            semantic_plan_row.get("plan")
            if isinstance(semantic_plan_row.get("plan"), dict)
            else {}
        )
        capability_id = str(
            agent_run.get("capability_id")
            or context_row.get("capability_id")
            or semantic_plan.get("capability_id")
            or ""
        )
        view = self.learning.view_run(principal, str(continued["work_run_id"]))
        evidence = [
            EvidenceRef(
                evidence_id=str(item.get("evidence_id") or item.get("ledger_id") or ""),
                kind=str(item.get("kind") or "evidence"),
                title=str(item.get("title") or "확인 근거"),
                summary=str(item.get("summary") or ""),
                source=str(item.get("source") or "work_run"),
                authority=str(item.get("authority") or "runtime"),
            )
            for item in (view.get("evidence_ledger") or [])[-8:]
            if item.get("evidence_id") or item.get("ledger_id")
        ]
        artifacts: list[ArtifactRef] = []
        for artifact_id in list(continued.get("artifact_refs") or [])[:3]:
            row = self.store.get("artifacts", str(artifact_id)) or {}
            if not row or not self._owns(principal, row):
                continue
            artifact_status = str(row.get("status") or "draft")
            if artifact_status not in {"draft", "provisional", "reviewed"}:
                artifact_status = "draft"
            artifacts.append(
                ArtifactRef(
                    artifact_id=str(row.get("artifact_id") or artifact_id),
                    artifact_type=str(row.get("artifact_type") or row.get("capability_id") or "draft"),
                    title=str(row.get("title") or "작업 결과"),
                    status=artifact_status,  # type: ignore[arg-type]
                    url=f"/agent?session={session['session_id']}&artifact={artifact_id}",
                    metadata={
                        "capability_id": str(row.get("capability_id") or ""),
                        "revision": int(row.get("revision") or 1),
                    },
                )
            )
        status_value = str(continued.get("status") or "in_progress")
        messages = {
            "completed": "완료된 모습과 확인할 자료가 충족되어 업무를 완료했습니다.",
            "waiting_human": "담당자가 확인하거나 보완할 내용이 남아 있습니다.",
            "waiting_signal": "연결된 시스템의 확인 결과를 기다리고 있습니다.",
            "in_progress": "새로운 내용을 반영해 같은 업무를 이어갑니다.",
            "blocked": "업무를 이어가기 전에 보완할 항목이 있습니다.",
            "queued": "같은 업무에서 필요한 확인을 계속 진행하고 있습니다.",
        }
        message = messages.get(status_value, "업무 진행 상태를 갱신했습니다.")
        response_status = (
            "completed"
            if status_value == "completed"
            else "queued"
            if status_value in {"queued", "in_progress", "waiting_signal"}
            else "needs_input"
        )
        loop_state = {
            "iteration_count": int((continued.get("loop") or {}).get("iteration_count") or 0),
            "decision": str(continued.get("decision") or ""),
            "status": status_value,
            "revision": int(continued.get("revision") or 1),
        }
        page_anchor = self.learning.contexts.page_anchor(principal, request.page_ref)
        response = AgentTurnResponse(
            run_id=run_id,
            turn_id=turn_id,
            conversation_id=str(session.get("conversation_id") or session["session_id"]),
            work_session_id=str(session["session_id"]),
            status=response_status,  # type: ignore[arg-type]
            capability_id=capability_id,
            answer=AnswerBlock(summary=message, markdown=message),
            evidence_refs=evidence,
            artifact_refs=artifacts,
            next_actions=self._next_actions(
                work_session_id=str(session["session_id"]),
                artifacts=artifacts,
                evidence=evidence,
            ),
            context_ref=str(continued.get("context_id") or ""),
            goal_plan_ref=str(continued.get("goal_plan_id") or ""),
            source_set_ref=self._source_set_id(str(session["session_id"])),
            grounding_status="grounded" if evidence else "no_evidence",
            progress=[{"status": status_value, "label": message}],
            work_run_id=str(continued["work_run_id"]),
            work_intent=WorkIntent.model_validate(route.get("work_intent") or continued.get("intent") or {}),
            semantic_plan_ref=str(route.get("semantic_plan_ref") or ""),
            stop_reason=str(continued.get("stop_reason") or ""),
            loop_state=loop_state,
            harness_results=[HarnessResult.model_validate(item) for item in continued.get("harness_results") or []],
            knowledge_candidates=candidates,
            context_usage={
                "semantic_continuation": True,
                "planner_source": str(route.get("source") or ""),
                "page_anchor": page_anchor.model_dump(mode="json") if page_anchor else None,
            },
        )
        self.store.put(
            "runs",
            run_id,
            {
                "run_id": run_id,
                "turn_id": turn_id,
                "employee_id": principal.employee_id,
                "work_session_id": session["session_id"],
                "work_run_id": continued["work_run_id"],
                "capability_id": capability_id,
                "status": response.status,
                "semantic_continuation": True,
                "created_at": now_iso(),
            },
        )
        self._finish_work_session(principal, session, response, request.question)
        return response

    @staticmethod
    def _grounded_focal_topic_entities(
        intent: WorkIntent | None,
        claims: list[GroundedClaim],
        evidence: list[EvidenceRef],
        used_source_refs: set[str],
    ) -> tuple[list[str], dict[str, str]]:
        """Resolve an initially ambiguous semantic subject from displayed evidence.

        A planner may correctly keep a subject mention ambiguous when several
        ACL-visible documents share the same domain token. After answer
        grounding, however, one displayed source can uniquely establish that
        subject. Promote only that source into the ordered focal-topic list;
        supporting sources remain result evidence and therefore cannot become
        the target of an ordinal follow-up such as "the second one".
        """

        if intent is None:
            return [], {}
        declared = list(
            dict.fromkeys(
                str(item)
                for item in intent.referenceable_topic_entities
                if str(item).strip()
            )
        )
        supported_source_refs = list(
            dict.fromkeys(
                str(source_ref)
                for claim in claims
                if claim.support_status == "supported"
                for source_ref in claim.source_refs
                if str(source_ref).strip() and str(source_ref) in used_source_refs
            )
        )
        evidence_titles = {
            str(item.evidence_id): str(item.title or "")
            for item in evidence
            if str(item.evidence_id).strip()
        }
        claim_text_by_source: dict[str, list[str]] = {}
        for claim in claims:
            if claim.support_status != "supported":
                continue
            for source_ref in claim.source_refs:
                if source_ref in used_source_refs:
                    claim_text_by_source.setdefault(source_ref, []).append(claim.text)

        ordered: list[str] = []
        promoted_labels: dict[str, str] = {}
        for topic_entity in intent.topic_entities:
            candidate = str(topic_entity or "").strip()
            if not candidate:
                continue
            if candidate in declared:
                if candidate not in ordered:
                    ordered.append(candidate)
                continue
            ranked = sorted(
                (
                    (
                        QuickAgentRuntime._identity_score(
                            candidate,
                            evidence_titles.get(source_ref, ""),
                        ),
                        QuickAgentRuntime._identity_score(
                            candidate,
                            " ".join(claim_text_by_source.get(source_ref, [])),
                        ),
                        source_ref,
                    )
                    for source_ref in supported_source_refs
                    if source_ref not in ordered
                ),
                key=lambda item: (-item[0], -item[1], item[2]),
            )
            if not ranked or max(ranked[0][0], ranked[0][1]) <= 0:
                continue
            best_key = ranked[0][:2]
            if sum(item[:2] == best_key for item in ranked) != 1:
                continue
            selected_ref = ranked[0][2]
            ordered.append(selected_ref)
            promoted_labels[selected_ref] = candidate
        ordered.extend(item for item in declared if item not in ordered)
        if (
            not ordered
            and intent.topic_structure == "single_focal"
            and any(str(item or "").strip() for item in intent.topic_entities)
            and len(supported_source_refs) == 1
        ):
            selected_ref = supported_source_refs[0]
            ordered.append(selected_ref)
            promoted_labels[selected_ref] = (
                str(intent.topic_subject or "").strip()
                or evidence_titles.get(selected_ref, "")
            )
        return ordered, promoted_labels

    def _finish_work_session(
        self,
        principal: Principal,
        session: dict[str, Any],
        response: AgentTurnResponse,
        question: str,
    ) -> None:
        session_id = str(session["session_id"])
        self._append_session_message(
            principal,
            session_id,
            role="user",
            display_text=question,
            run_id=response.run_id,
            capability_id=response.capability_id,
        )
        self._append_session_message(
            principal,
            session_id,
            role="assistant",
            display_text=response.answer.markdown,
            run_id=response.run_id,
            capability_id=response.capability_id,
            evidence_refs=response.evidence_refs,
            artifact_refs=response.artifact_refs,
            next_actions=response.next_actions,
            citations=response.citations,
            related_questions=response.related_questions,
            goal_plan_ref=response.goal_plan_ref,
            source_set_ref=response.source_set_ref,
            work_run_id=response.work_run_id,
            job_ref=response.job_ref,
            loop_state=response.loop_state,
            harness_results=response.harness_results,
            knowledge_candidates=response.knowledge_candidates,
            grounded_claims=response.grounded_claims,
            answerability=response.answerability,
            topic_state_ref=response.topic_state_ref,
            used_source_refs=response.used_source_refs,
        )
        if response.artifact_refs:
            session["active_artifact_id"] = response.artifact_refs[0].artifact_id
            session["title"] = compact_text(response.artifact_refs[0].title, 120) or session.get("title") or "새 업무"
        elif session.get("title") in {"", "새 업무"}:
            session["title"] = compact_text(question, 80) or "새 업무"
        prior_topic = session.get("topic_state") if isinstance(session.get("topic_state"), dict) else {}
        definition: CapabilityDefinition | None = None
        try:
            definition = self.registry.get(response.capability_id)
            topic_identity_sources = set(definition.topic_identity_sources)
        except KeyError:
            # Internal failure responses are not executable catalog
            # capabilities and must not establish a referenceable topic.
            topic_identity_sources = set()
        semantic_plan_row = (
            self.store.get("semantic_plans", response.semantic_plan_ref)
            if response.semantic_plan_ref
            else {}
        ) or {}
        semantic_plan_payload = (
            semantic_plan_row.get("plan")
            if isinstance(semantic_plan_row.get("plan"), dict)
            else {}
        )
        semantic_plan_validation = (
            semantic_plan_row.get("validation")
            if isinstance(semantic_plan_row.get("validation"), dict)
            else {}
        )
        validated_topic_refs = {
            str(item.get("entity_ref") or "")
            for item in semantic_plan_payload.get("subjects") or []
            if isinstance(item, dict) and str(item.get("entity_ref") or "")
        }
        if str(semantic_plan_payload.get("target_ref") or ""):
            validated_topic_refs.add(str(semantic_plan_payload["target_ref"]))
        validated_unresolved_topic_labels = list(
            dict.fromkeys(
                str(item.get("mention") or "").strip()
                for item in semantic_plan_payload.get("subjects") or []
                if isinstance(item, dict)
                and not str(item.get("entity_ref") or "").strip()
                and str(item.get("resolution") or "")
                in {"unresolved", "ambiguous", "missing"}
                and str(item.get("mention") or "").strip()
            )
        )
        response_topic_refs = {
            str(item)
            for item in (
                response.work_intent.referenceable_topic_entities
                if response.work_intent
                else []
            )
            if str(item)
        }
        has_validated_resolved_entities = bool(
            semantic_plan_row
            and semantic_plan_row.get("employee_id") == principal.employee_id
            and semantic_plan_validation.get("valid") is True
            and response_topic_refs
            and response_topic_refs.issubset(validated_topic_refs)
        )
        visible_used_source_refs = set(response.used_source_refs)
        has_topic_identity = any(
            (
                source == "grounded_claims"
                and bool(response.used_source_refs)
                and any(
                    item.support_status == "supported"
                    and any(ref in visible_used_source_refs for ref in item.source_refs)
                    for item in response.grounded_claims
                )
            )
            or (
                source == "resolved_entities"
                and has_validated_resolved_entities
                and bool(
                    response.work_intent
                    and response.work_intent.referenceable_topic_entities
                )
            )
            or (source == "artifact" and bool(response.artifact_refs))
            for source in topic_identity_sources
        )
        starts_new_topic = bool(
            response.work_intent
            and response.work_intent.topic_mode == "new"
            and str(prior_topic.get("topic_state_ref") or "")
        )
        if starts_new_topic:
            invalidated_topic = {
                **copy.deepcopy(prior_topic),
                "correction_status": "invalidated",
                "invalidated_by_run_id": response.run_id,
                "invalidation_reason": "semantic_new_topic",
                "invalidated_at": now_iso(),
            }
            prior_invalidations = [
                item
                for item in session.get("topic_invalidations") or []
                if isinstance(item, dict)
            ]
            invalidation_key = (
                str(invalidated_topic.get("topic_state_ref") or ""),
                str(invalidated_topic.get("invalidated_by_run_id") or ""),
            )
            if invalidation_key not in {
                (
                    str(item.get("topic_state_ref") or ""),
                    str(item.get("invalidated_by_run_id") or ""),
                )
                for item in prior_invalidations
            }:
                prior_invalidations.append(invalidated_topic)
            session["topic_invalidations"] = prior_invalidations[-20:]
            if not response.artifact_refs:
                # A semantic correction/new topic disconnects the previous
                # artifact from the active discourse without deleting it.  It
                # remains reachable through the invalidated topic record and
                # artifact history, but cannot leak into the corrected turn or
                # a later pronoun resolution.
                session["active_artifact_id"] = ""
                session["selected_task_id"] = ""
                session["active_panel"] = "result"
        if response.answerability.status == "conflicting" and prior_topic:
            topic_state = {
                **prior_topic,
                "topic_state_ref": response.topic_state_ref,
                "correction_status": "invalidated",
                "invalidated_by_run_id": response.run_id,
            }
            corrections = [
                *[item for item in session.get("topic_corrections") or [] if isinstance(item, dict)],
                {
                    "topic_state_ref": str(prior_topic.get("topic_state_ref") or ""),
                    "invalidated_by_run_id": response.run_id,
                    "reason": "conflicting_internal_evidence",
                    "created_at": now_iso(),
                },
            ][-20:]
            session["topic_corrections"] = corrections
        elif not has_topic_identity:
            # Only evidence types declared by the capability contract may
            # establish a referenceable topic for the next turn.
            # A verified semantic new-topic/correction action still
            # invalidates the prior topic even when no evidence exists for the
            # replacement. Keeping the old topic active would make the next
            # pronoun silently refer to information the user just corrected.
            topic_state = {} if starts_new_topic else prior_topic
        else:
            graph_entities = [
                str(entity_ref)
                for artifact in response.artifact_refs
                if artifact.artifact_type in {"ontology_graph", "mermaid_diagram"}
                for entity_ref in artifact.metadata.get("focal_entities") or []
                if str(entity_ref)
            ]
            grounded_result_entities = list(
                dict.fromkeys(
                    str(source_ref)
                    for claim in response.grounded_claims
                    if claim.support_status == "supported" and "grounded_claims" in topic_identity_sources
                    for source_ref in claim.source_refs
                    if str(source_ref)
                )
            )
            resolved_candidates, grounded_focal_labels = (
                self._grounded_focal_topic_entities(
                    response.work_intent,
                    response.grounded_claims,
                    response.evidence_refs,
                    visible_used_source_refs,
                )
            )
            explicit_new_unresolved_topic = bool(
                starts_new_topic
                and semantic_plan_row
                and semantic_plan_row.get("employee_id") == principal.employee_id
                and semantic_plan_validation.get("valid") is True
                and not validated_topic_refs
                and validated_unresolved_topic_labels
            )
            if explicit_new_unresolved_topic:
                # A verified semantic correction may name a concept that has no
                # domain entity yet.  Its supporting Wiki document is evidence,
                # not the replacement topic identity.  Keep the concept as a
                # dialogue focal and the source rows as ordered results so a
                # later pronoun cannot silently reactivate the invalidated topic.
                resolved_candidates = []
                grounded_focal_labels = {}
            resolved_topic_entities = list(
                dict.fromkeys(
                    item
                    for item in resolved_candidates
                    if (
                        "resolved_entities" in topic_identity_sources
                        and has_validated_resolved_entities
                    )
                    or (
                        "grounded_claims" in topic_identity_sources
                        and item in grounded_result_entities
                    )
                )
            )
            primary_subject_count = (
                int(definition.topic_primary_subject_count or 0)
                if definition is not None
                else 0
            )
            if (
                primary_subject_count
                and response.work_intent is not None
                and response.work_intent.target_ref
                and resolved_topic_entities
                and resolved_topic_entities[0] == response.work_intent.target_ref
                and len(resolved_topic_entities) > primary_subject_count
            ):
                resolved_result_entities = resolved_topic_entities[
                    primary_subject_count:
                ]
                resolved_topic_entities = resolved_topic_entities[
                    :primary_subject_count
                ]
                if not grounded_result_entities:
                    # A validated semantic case candidate may establish the
                    # only available result identity when the response has no
                    # grounded result rows yet. Once displayed supported
                    # results exist, however, their claim/citation order is the
                    # sole ordinal contract. A planner-resolved context entity
                    # must not become an unseen "first result".
                    grounded_result_entities = list(
                        dict.fromkeys(resolved_result_entities)
                    )
            topic_label = (
                validated_unresolved_topic_labels[0]
                if explicit_new_unresolved_topic
                else response.work_intent.topic_subject
                if response.work_intent and response.work_intent.topic_subject
                else response.work_intent.resolved_goal
                if response.work_intent
                else question
            )
            if (
                not resolved_topic_entities
                and grounded_result_entities
                and "grounded_claims" in topic_identity_sources
                and response.topic_state_ref
            ):
                # A grounded answer can establish a dialogue-level focal subject
                # even when no single domain entity represents the whole concept.
                # The source documents remain ordered result identities rather
                # than being promoted to focal subjects.
                resolved_topic_entities = [response.topic_state_ref]
            artifact_entities = list(
                dict.fromkeys(
                    [
                        *graph_entities,
                        *(
                            [str(session.get("active_artifact_id"))]
                            if "artifact" in topic_identity_sources and session.get("active_artifact_id")
                            else []
                        ),
                    ]
                )
            )
            entity_labels = {
                **{
                    citation.source_ref: citation.title
                    for citation in response.citations
                    if citation.source_ref and citation.title
                },
                **{
                    evidence.evidence_id: evidence.title
                    for evidence in response.evidence_refs
                    if evidence.evidence_id and evidence.title
                },
                **{
                    artifact.artifact_id: artifact.title
                    for artifact in response.artifact_refs
                    if artifact.artifact_id and artifact.title
                },
                **grounded_focal_labels,
            }
            for subject_ref in resolved_topic_entities:
                entity_labels.setdefault(subject_ref, topic_label)
            topic_state = {
                "topic_state_ref": response.topic_state_ref,
                "subject": topic_label,
                "subjects": resolved_topic_entities,
                "result_entities": [
                    item for item in grounded_result_entities if item not in resolved_topic_entities
                ],
                "artifact_entities": artifact_entities,
                "topic_primary_subject_count": primary_subject_count,
                "ordinal_reference_scope": (
                    definition.followup_ordinal_scope
                    if definition is not None
                    else "auto"
                ),
                "origin_capability_id": response.capability_id,
                "entity_labels": entity_labels,
                "topic_structure": (
                    "multiple_focal" if len(resolved_topic_entities) > 1 else "single_focal"
                ),
                "entities": list(dict.fromkeys(
                    [
                        *resolved_topic_entities,
                        *grounded_result_entities,
                        *artifact_entities,
                    ]
                )),
                "operation": response.work_intent.operation.value if response.work_intent else "understand",
                "work_view": response.work_intent.work_view if response.work_intent else "none",
                "evidence_requirements": (
                    response.work_intent.evidence_requirements.model_dump(mode="json")
                    if response.work_intent
                    else {}
                ),
                "answer_intent": response.work_intent.answer_intent if response.work_intent else "fact",
                "answer_source_scope": response.work_intent.answer_source_scope if response.work_intent else "canonical",
                "claims": [item.model_dump(mode="json") for item in response.grounded_claims if item.support_status == "supported"],
                "used_source_refs": list(response.used_source_refs),
                "active_artifact_id": str(session.get("active_artifact_id") or ""),
                "correction_status": "active",
            }
        next_active_work_run_id = str(response.work_run_id or "")
        if not next_active_work_run_id and not starts_new_topic:
            # A planner/catalog failure or clarification has no new WorkRun.
            # Preserve the prior verified result so the user can correct the
            # request and still refer to "this result". A validated new topic
            # intentionally invalidates that binding.
            next_active_work_run_id = str(
                session.get("active_work_run_id") or ""
            )
        session.update(
            {
                "last_run_id": response.run_id,
                "last_capability_id": response.capability_id,
                "active_work_run_id": next_active_work_run_id,
                "active_goal_plan_id": response.goal_plan_ref,
                "source_set_id": response.source_set_ref,
                "topic_state": topic_state,
                "revision": int(session.get("revision") or 1) + 1,
                "updated_at": now_iso(),
                "expires_at": (
                    session.get("expires_at")
                    if session.get("pinned")
                    else (datetime.now(timezone.utc) + timedelta(days=30)).isoformat()
                ),
            }
        )
        if response.job_ref:
            session["active_job_id"] = response.job_ref
        context = self._session_context(principal, session)
        session["conversation_summary"] = context["summary"]
        self.store.put("work_sessions", session_id, session)
        if response.status == "completed":
            source_set = self.store.get("source_sets", self._source_set_id(session_id)) or {}
            last_user_change = (
                dict(source_set.get("last_user_change") or {})
                if isinstance(source_set.get("last_user_change"), dict)
                else {}
            )
            if last_user_change and not str(
                last_user_change.get("consumed_by_run_id") or ""
            ):
                last_user_change["consumed_by_run_id"] = response.run_id
                last_user_change["consumed_at"] = now_iso()
                source_set["last_user_change"] = last_user_change
                self.store.put(
                    "source_sets",
                    str(source_set["source_set_id"]),
                    source_set,
                )

    @staticmethod
    def _emit_turn_progress(
        sink: Callable[[str, dict[str, Any]], None] | None,
        stage: str,
        message: str,
        **payload: Any,
    ) -> None:
        if sink is None:
            return
        try:
            sink("progress", {"stage": stage, "message": message, **payload})
        except Exception:
            return

    def _handle_artifact_transform(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        source = execution.active_artifact
        if execution.intent.target_ref:
            selected = self.store.get("artifacts", execution.intent.target_ref)
            if selected and self._owns(execution.principal, selected):
                source = selected
        try:
            if not source:
                raise RuntimeError("변환할 결과물을 선택하지 않았습니다.")
            answer, artifact = self._split_mermaid_artifact_into_tasks(
                execution.principal,
                definition=execution.definition,
                source_artifact=source,
                session=execution.session,
                work_run_id=str(execution.work_run["work_run_id"]),
                page_ref=execution.request.page_ref,
            )
            (
                answer,
                provenance_claims,
                provenance_refs,
                provenance_citations,
                provenance_report,
            ) = self._artifact_provenance(execution, artifact, answer)
            return CapabilityHandlerResult(
                answer=answer,
                artifacts=[artifact],
                grounded_claims=provenance_claims,
                used_source_refs=provenance_refs,
                citations=provenance_citations,
                answerability=provenance_report,
                claim_grounded_response=bool(provenance_claims),
            )
        except RuntimeError:
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="흐름을 Task로 나누지 못했습니다.",
                    markdown=(
                        "현재 흐름에서 확인 가능한 Task 후보를 만들지 못했습니다. "
                        "Task로 나눌 흐름 그림을 다시 선택하거나 필요한 단계를 조금 더 설명해주세요."
                    ),
                ),
            )

    def _artifact_provenance(
        self,
        execution: CapabilityHandlerContext,
        artifact: ArtifactRef,
        answer: AnswerBlock,
    ) -> tuple[
        AnswerBlock,
        list[GroundedClaim],
        list[str],
        list[CitationRef],
        AnswerabilityReport | None,
    ]:
        source_refs = list(
            dict.fromkeys(
                str(ref)
                for ref in artifact.metadata.get("source_refs") or []
                if str(ref).strip()
            )
        )
        artifact_row = self.store.get("artifacts", artifact.artifact_id)
        referenced_in_draft: set[str] = set()

        def collect_explicit_refs(value: Any) -> None:
            if isinstance(value, dict):
                for nested in value.values():
                    collect_explicit_refs(nested)
                return
            if isinstance(value, list):
                for nested in value:
                    collect_explicit_refs(nested)
                return
            if isinstance(value, str) and value in source_refs:
                referenced_in_draft.add(value)

        if artifact_row and self._owns(execution.principal, artifact_row):
            collect_explicit_refs(artifact_row.get("draft"))
        ordered_display_candidates = [
            source_ref
            for source_ref in source_refs
            if not referenced_in_draft or source_ref in referenced_in_draft
        ]
        citation_by_ref = {
            item.source_ref: item
            for item in execution.citations
            if item.source_ref and item.chunk_id and item.excerpt.strip()
        }
        try:
            source_limit = max(
                1,
                min(
                    int(
                        execution.definition.handler_config.get(
                            "max_presentation_sources"
                        )
                        or 6
                    ),
                    12,
                ),
            )
        except (TypeError, ValueError):
            source_limit = 6
        citations = [
            citation_by_ref[source_ref]
            for source_ref in ordered_display_candidates
            if source_ref in citation_by_ref
        ][:source_limit]
        if not citations:
            return answer, [], [], [], None
        display_source_refs = [item.source_ref for item in citations]
        # ``source_refs`` is the direct evidence contract for this artifact
        # revision; transitive ancestry is a different semantic role. Keep the
        # latter in ``lineage_source_refs`` so every direct source has a response
        # EvidenceRef/citation while the complete private lineage remains
        # inspectable without leaking into used_source_refs.
        lineage_source_refs = source_refs
        artifact.metadata["lineage_source_refs"] = lineage_source_refs
        artifact.metadata["source_refs"] = display_source_refs
        artifact.metadata["display_source_refs"] = display_source_refs
        if artifact_row and self._owns(execution.principal, artifact_row):
            artifact_row["lineage_source_refs"] = lineage_source_refs
            artifact_row["source_refs"] = display_source_refs
            artifact_row["display_source_refs"] = display_source_refs
            artifact_draft = (
                artifact_row.get("draft")
                if isinstance(artifact_row.get("draft"), dict)
                else None
            )
            if artifact_draft is not None:
                artifact_draft["lineage_source_refs"] = lineage_source_refs
                artifact_draft["source_refs"] = display_source_refs
            self.store.put("artifacts", artifact.artifact_id, artifact_row)
        claims: list[GroundedClaim] = []
        source_lines: list[str] = []
        for index, citation in enumerate(citations, start=1):
            record = self._record_for_ref(execution.principal, citation.source_ref)
            source_scope = (
                self.repository.answer_scope(record)
                if record is not None
                else execution.intent.answer_source_scope
            )
            if source_scope not in {"canonical", "operational", "validation"}:
                source_scope = execution.intent.answer_source_scope
            # A provenance claim must itself be source-verifiable. A synthetic
            # sentence such as "this artifact used source X" cannot be bound
            # to the cited chunk, whereas the exact excerpt can.
            claim_text = compact_text(citation.excerpt, 500)
            claims.append(
                GroundedClaim(
                    claim_id=f"artifact-provenance-{index}",
                    text=claim_text,
                    claim_kind=execution.intent.answer_intent,
                    source_scope=source_scope,
                    source_refs=[citation.source_ref],
                    supporting_chunk_ids=[citation.chunk_id],
                    support_status="supported",
                    confidence=1.0,
                    required_for_answer=True,
                )
            )
            source_lines.append(
                f"- **{citation.title}** — {claim_text} "
                f"[근거](/api/v2/citations/{citation.citation_id})"
            )
        return (
            answer.model_copy(
                update={
                    "markdown": answer.markdown
                    + "\n\n### 초안 입력 근거\n"
                    + "\n".join(source_lines)
                }
            ),
            claims,
            display_source_refs,
            citations,
            AnswerabilityReport(
                status="grounded",
                answer_intent=execution.intent.answer_intent,
                supported_claim_count=len(claims),
            ),
        )

    def _handle_routine_plan(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        try:
            answer, artifact, plan_ref = self._work_routine_plan(
                execution.principal,
                execution.definition,
                request=execution.request,
                session=execution.session,
                intent=execution.intent,
                evidence=execution.evidence,
                work_run_id=str(execution.work_run["work_run_id"]),
            )
            return CapabilityHandlerResult(
                answer=answer,
                artifacts=[artifact],
                plan_ref=plan_ref,
            )
        except RuntimeError as exc:
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="자동 확인 계획을 만들려면 정보가 더 필요합니다.",
                    markdown=(
                        f"{compact_text(str(exc), 500)} "
                        "시간이나 상태 조건을 조금 더 구체적으로 알려주세요."
                    ),
                ),
            )

    @staticmethod
    def _ontology_migration_safe_input(value: Any, *, path: str = "input") -> Any:
        """Keep source/query bodies and credentials out of migration review plans."""

        forbidden = {
            "raw_sql",
            "repaired_sql",
            "sql",
            "source_bytes",
            "content_b64",
            "source_body",
            "source_text",
            "raw_rows",
            "rows",
            "result_rows",
            "credential",
            "credentials",
            "password",
            "secret",
            "token",
        }
        if isinstance(value, dict):
            result: dict[str, Any] = {}
            for raw_key, item in value.items():
                key = str(raw_key or "").strip()
                if key.lower() in forbidden:
                    raise ValueError(f"forbidden migration plan input: {path}.{key}")
                result[key] = AgentV2Service._ontology_migration_safe_input(
                    item,
                    path=f"{path}.{key}",
                )
            return result
        if isinstance(value, list):
            return [
                AgentV2Service._ontology_migration_safe_input(
                    item,
                    path=f"{path}[{index}]",
                )
                for index, item in enumerate(value)
            ]
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        raise ValueError(f"unsupported migration plan input: {path}")

    @staticmethod
    def _unavailable_bulk_migration_pi_runner(
        _skill_id: str,
        _payload: dict[str, object],
    ) -> dict[str, object]:
        raise RuntimeError("LOCAL_MODEL_EXECUTION_UNAVAILABLE")

    def _owned_bulk_record(
        self,
        principal: Principal,
        collection: str,
        record_id: str,
        *,
        missing_code: str,
    ) -> dict[str, Any]:
        record = self.store.get(collection, record_id)
        if not record:
            raise BulkMigrationPolicyError(missing_code)
        if (
            str(record.get("employee_id") or "") != principal.employee_id
            and not principal.is_admin
        ):
            raise BulkMigrationPolicyError("SOURCE_ACCESS_DENIED")
        return record

    def _handle_bulk_ontology_migration(
        self,
        execution: CapabilityHandlerContext,
        safe_input: dict[str, Any],
    ) -> CapabilityHandlerResult:
        contract_id=str(safe_input.get('pipeline_contract_id') or P0_B3_PIPELINE_V2.contract_id)
        if contract_id not in {P0_B3_PIPELINE_V2.contract_id, NORTH_STAR_ETCH_PIPELINE_V1.contract_id,
                               SEMANTIC_METADATA_PIPELINE_V1.contract_id}:
            raise BulkMigrationPolicyError('PIPELINE_CONTRACT_UNSUPPORTED')
        metadata=None
        if contract_id==SEMANTIC_METADATA_PIPELINE_V1.contract_id or safe_input.get('metadata_source_profile_id'):
            if self.metadata_runtime_bindings is None or self.source_intake is None:
                raise BulkMigrationPolicyError('SEMANTIC_METADATA_RUNTIME_UNAVAILABLE')
            metadata=self.metadata_runtime_bindings.prepare_metadata(source_intake=self.source_intake,
                principal=execution.principal,value=safe_input)
            safe_input=metadata.input
        pipeline_contract=SEMANTIC_METADATA_PIPELINE_V1 if metadata else P0_B3_PIPELINE_V2
        required = set(execution.definition.input_schema.get("required") or ())
        missing = sorted(
            key for key in required if key not in safe_input or safe_input.get(key) is None
        )
        if missing:
            raise BulkMigrationPolicyError(
                "PIPELINE_INPUT_REQUIRED:" + ",".join(missing)
            )
        source_refs = tuple(
            SourceArtifactRef(
                artifact_ref=str(item.get("artifact_ref") or ""),
                digest=str(item.get("digest") or ""),
                role=str(item.get("role") or ""),
            )
            for item in safe_input.get("source_artifacts") or ()
            if isinstance(item, dict)
        )
        selector_input = dict(safe_input.get("selector") or {})
        selector = SelectorManifest.create(
            systems=selector_input.get("systems") or (),
            schemas=selector_input.get("schemas") or (),
            tables=selector_input.get("tables") or (),
            dependency_closure_refs=(
                selector_input.get("dependency_closure_refs") or ()
            ),
        )
        manifest = BulkMigrationManifest.create(
            project_id=str(safe_input.get("project_id") or ""),
            mode=str(safe_input.get("mode") or ""),
            source_artifacts=source_refs,
            catalog_snapshot_ref=str(safe_input.get("catalog_snapshot_ref") or ""),
            catalog_snapshot_digest=str(
                safe_input.get("catalog_snapshot_digest") or ""
            ),
            schema_snapshot_digest=str(
                safe_input.get("schema_snapshot_digest") or ""
            ),
            selector=selector,
            requested_skill_stages=tuple(
                str(item) for item in safe_input.get("requested_skill_stages") or ()
            ),
            profile_revisions=tuple(
                str(item) for item in safe_input.get("profile_revisions") or ()
            ),
            evaluator_code_digests=tuple(
                str(item) for item in safe_input.get("evaluator_code_digests") or ()
            ),
            model_role_prompt_digests=tuple(
                str(item)
                for item in safe_input.get("model_role_prompt_digests") or ()
            ),
            active_concept_index_digest=str(
                safe_input.get("active_concept_index_digest") or ""
            ),
            acl_policy_digest=str(safe_input.get("acl_policy_digest") or ""),
            purpose=str(safe_input.get("purpose") or execution.request.question),
            idempotency_key=str(safe_input.get("idempotency_key") or ""),
            before_hashes=dict(safe_input.get("before_hashes") or {}),
            atomic_object_count=int(safe_input.get("atomic_object_count") or 1),
            max_objects_per_shard=int(safe_input.get("max_objects_per_shard") or 0),
            dry_run=bool(safe_input.get("dry_run")),
            local_model_policy=str(safe_input.get("local_model_policy") or ""),
            resume_retry_policy=str(safe_input.get("resume_retry_policy") or ""),
            pipeline_contract_id=str(
                safe_input.get("pipeline_contract_id")
                or "boi/p0-b3-pipeline@0.2.0"
            ),
            candidate_preview_question_digests=tuple(
                str(item)
                for item in safe_input.get("candidate_preview_question_digests") or ()
            ),
            metadata_execution=safe_input.get('metadata_execution'),
        )
        catalog = self._owned_bulk_record(
            execution.principal,
            "bulk_migration_catalog_snapshots",
            manifest.catalog_snapshot_ref,
            missing_code="CATALOG_SNAPSHOT_NOT_FOUND",
        )
        if (
            str(catalog.get("digest") or "") != manifest.catalog_snapshot_digest
            or str(catalog.get("schema_digest") or "")
            != manifest.schema_snapshot_digest
        ):
            raise BulkMigrationPolicyError("CATALOG_SNAPSHOT_DIGEST_MISMATCH")
        concept_index_ref = str(safe_input.get("active_concept_index_ref") or "")
        concept_index = self._owned_bulk_record(
            execution.principal,
            "bulk_migration_concept_indexes",
            concept_index_ref,
            missing_code="ACTIVE_CONCEPT_INDEX_NOT_FOUND",
        )
        if (
            str(concept_index.get("digest") or "")
            != manifest.active_concept_index_digest
        ):
            raise BulkMigrationPolicyError("ACTIVE_CONCEPT_INDEX_DIGEST_MISMATCH")
        evidence_spans = tuple(
            self._owned_bulk_record(
                execution.principal,
                "bulk_migration_evidence_spans",
                str(ref),
                missing_code="EVIDENCE_SPAN_NOT_FOUND",
            )
            for ref in safe_input.get("evidence_span_refs") or ()
        )

        def source_resolver(artifact_ref: str) -> bytes:
            if artifact_ref.startswith("SourceArtifact:sha256:"):
                if self.source_intake is None or self.source_intake_authorizer is None:
                    raise BulkMigrationPolicyError("SOURCE_INTAKE_SERVICE_UNAVAILABLE")
                reference = next(item for item in source_refs if item.artifact_ref == artifact_ref)
                return self.source_intake.resolve_bytes(
                    authorization=self.source_intake_authorizer(execution.principal),
                    reference=reference.semantic_payload(),
                )
            record = self._owned_bulk_record(
                execution.principal,
                "bulk_migration_source_artifacts",
                artifact_ref,
                missing_code="SOURCE_ARTIFACT_NOT_FOUND",
            )
            encoded = str(record.get("content_b64") or "")
            if not encoded:
                raise BulkMigrationPolicyError("SOURCE_ARTIFACT_BYTES_UNAVAILABLE")
            return base64.b64decode(encoded, validate=True)

        submit_kwargs=dict(principal=execution.principal.employee_id,
            manifest=manifest,channel=execution.invocation_channel)
        if metadata:
            run=self.bulk_migration_orchestrator.submit_expanded_selector(**submit_kwargs,
                expanded_object_fingerprints=tuple(item.receipt_ref for item in metadata.published_records))
        else:
            run=self.bulk_migration_orchestrator.submit(**submit_kwargs)
        semantic_authority=(self.metadata_runtime_bindings.semantic_authority(
            source_intake=self.source_intake,principal=execution.principal,prepared=metadata)
            if metadata else None)
        metadata_mapping_service=(self.metadata_runtime_bindings.metadata_mapping_service(
            source_intake=self.source_intake,principal=execution.principal,prepared=metadata,
            gateway=getattr(self.general_query_runtime,'gateway',None))
            if metadata else None)
        for shard_index, shard in enumerate(run.shards):
            # Resumption consumes only queued shards. Failed shards require the
            # existing exact retry operation; completed evidence is never rerun.
            if shard.state != 'queued':
                continue
            worker_execution=None
            reviewed_input=None
            if metadata:
                from ..governed_runtime.bulk_migration_review import resolve_reviewed_shard
                reviewed_input=resolve_reviewed_shard(self.bulk_migration_repository,
                    principal=execution.principal.employee_id,run=run,shard=shard,
                    runtime_check=lambda source_manifest,domain:self._semantic_interpretation_runtime_check(
                        execution.principal,source_manifest,domain))
                from ..governed_runtime.bulk_migration_tasks import BulkMigrationTaskService
                worker_execution=BulkMigrationTaskService(self.store).reserve_execution(
                    execution.principal.employee_id,run.run_id,shard.shard_id)
                if worker_execution is None:
                    continue  # Live external task/executor lease: no re-execution.
                if reviewed_input is not None:
                    def validate_reviewed_write(buffer):
                        current_review=resolve_reviewed_shard(AgentV2StoreBulkMigrationRepository(buffer),
                            principal=execution.principal.employee_id,run=run,shard=shard,
                            runtime_check=lambda source_manifest,domain:self._semantic_interpretation_runtime_check(
                                execution.principal,source_manifest,domain))
                        if current_review!=reviewed_input:
                            raise BulkMigrationPolicyError('REVIEWED_DEFINITION_FINAL_CLOSURE_STALE')
                    worker_execution.final_write_validator=validate_reviewed_write
            def record_pi_invocation(record: dict[str, object]) -> None:
                record_digest = str(record.get("record_digest") or "")
                if not record_digest.startswith("sha256:"):
                    raise BulkMigrationPolicyError("PI_INVOCATION_RECORD_DIGEST_REQUIRED")
                self.store.put(
                    "bulk_migration_model_invocations",
                    record_digest,
                    {
                        **record,
                        "run_id": run.run_id,
                        "employee_id": execution.principal.employee_id,
                        "manifest_digest": manifest.manifest_digest,
                        "production_changed": False,
                        "active_transition": False,
                    },
                )

            semantic_services=None
            shard_evidence=evidence_spans
            if metadata:
                from ..governed_runtime.semantic_metadata_stages import SemanticMetadataStageServices
                from ..governed_runtime.record_field_metadata_intake import RecordFieldIntake
                from ..governed_runtime.local_model_routing import LocalModelPolicy
                size=manifest.metadata_execution['records_per_shard']
                selected=metadata.published_records[shard_index*size:(shard_index+1)*size]
                records=tuple(item.intake for item in selected if isinstance(item.intake,RecordFieldIntake))
                intake_attention=tuple({'receipt_ref':item.receipt_ref,**asdict(item.intake)}
                    for item in selected if not isinstance(item.intake,RecordFieldIntake))
                shard_evidence=tuple(self._owned_bulk_record(execution.principal,
                    'bulk_migration_evidence_spans',span.span_ref,missing_code='EVIDENCE_SPAN_NOT_FOUND')
                    for record in records for span in record.evidence)
                semantic_services=SemanticMetadataStageServices(store=self.store,records=records,
                    definitions=metadata.definitions,principal_id=execution.principal.employee_id,
                    policy_digest=manifest.acl_policy_digest,run_ref=run.run_id,shard_ref=shard.shard_id,
                    channel=execution.invocation_channel,identity=None,
                    identity_provider=metadata.model_client.probe_identity,
                    output_model=metadata.model_client.output_model,
                    model_request_builder=metadata.model_client.build_request,
                    source_meaning_client=metadata.source_meaning_client,
                    source_meaning_context_verifier=lambda record:semantic_authority._check(record,metadata.definitions),
                    model_policy=LocalModelPolicy(model_id='ninfer-local/'+metadata.model_client.model_id),invoke=metadata.model_client,
                    resolved_draft_resolver=semantic_authority.resolved_draft,
                    validation_context_resolver=semantic_authority.validation_context,
                    physical_mapping_service=metadata_mapping_service,
                    query_contract_service=metadata_mapping_service.query_contracts,
                    reviewed_input=reviewed_input,
                    canonical_record_verifier=lambda record:self.source_intake.metadata.verify_record(
                        authorization=metadata.authorization,record=record),
                    model_input_authorizer=lambda record:self.source_intake.metadata.authorize_model_input(
                        authorization=metadata.authorization,record=record),
                    intake_attention=intake_attention,max_derived_candidates=manifest.max_objects_per_shard)
            pipeline = BulkMigrationSkillExecutor(
                source_resolver=source_resolver,
                pi_runner=self.bulk_migration_pi_runner,
                pi_invocation_recorder=record_pi_invocation,
                pipeline_contract=pipeline_contract,
                semantic_services=semantic_services,
                worker_execution=worker_execution,
            ).execute_pipeline(
                requested_stages=manifest.requested_skill_stages,
                context=BulkMigrationExecutionContext(
                    migration_id=run.run_id,
                    manifest_digest=manifest.manifest_digest,
                    source_artifacts=tuple(item.semantic_payload() for item in source_refs),
                    catalog_snapshot=dict(catalog),
                    evidence_spans=tuple(dict(item) for item in shard_evidence),
                    active_concept_index=tuple(
                        dict(item) for item in concept_index.get("items") or ()
                    ),
                    mapping_candidates=tuple(
                        dict(item) for item in safe_input.get("mapping_candidates") or ()
                    ),
                    failure_clusters=tuple(
                        dict(item) for item in safe_input.get("failure_clusters") or ()
                    ),
                    before_hashes=dict(manifest.before_hashes),
                    model_role_prompt_digests=manifest.model_role_prompt_digests,
                ),
            )
            stage_results = tuple(asdict(item) for item in pipeline.stage_results)
            attention_refs = tuple(
                str(item)
                for result in pipeline.stage_results
                for item in (result.output or {}).get("attention_items") or ()
            )
            run = self.bulk_migration_orchestrator.record_pipeline_result(
                principal=execution.principal.employee_id,
                run_id=run.run_id,
                shard_id=shard.shard_id,
                pipeline_digest=pipeline.pipeline_digest,
                harness_state=pipeline.harness_state,
                stage_results=stage_results,
                evidence_refs=tuple(
                    str(item.get('canonical_evidence_ref') or item.get("evidence_span_ref") or "")
                    for item in shard_evidence
                    if str(item.get('canonical_evidence_ref') or item.get("evidence_span_ref") or "")
                ),
                attention_refs=attention_refs,
                model_invocation_count=pipeline.pi_invocation_count,
                model_input_bytes=pipeline.pi_input_bytes,
                task_execution=worker_execution,
            )
            if all(item.state in {'completed','failed'} for item in run.shards):
                self.bulk_migration_orchestrator.finalize_receipt(
                    principal=execution.principal.employee_id,
                    run_id=run.run_id,
                    pipeline_contract_id=pipeline.pipeline_contract_id,
                    required_stage_ids=pipeline.required_stage_ids,
                    optional_stage_ids=pipeline.optional_stage_ids,
                    stage_digests={} if len(run.shards)>1 else {
                        result.skill_id: result.output_digest
                        for result in pipeline.stage_results
                        if result.output_digest
                    },
                    component_digests=tuple(
                        result.output_digest for result in pipeline.stage_results
                    ),
                    checks=tuple(
                        {
                            "check_id": f"pipeline-stage:{result.skill_id}",
                            "stage_id": result.skill_id,
                            "status": result.status,
                            "evidence_digest": result.evidence_digest,
                        }
                        for result in pipeline.stage_results
                    ),
                    token_metrics={
                        "pi_invocation_count": run.model_invocation_count,
                        "pi_input_bytes": run.model_input_bytes,
                        "codex_invocation_count": 0,
                        "cache_hit_count": sum(
                            len(
                                (result.output or {}).get(
                                    "candidate_cache_receipt_digests"
                                )
                                or ()
                            )
                            for result in pipeline.stage_results
                        ),
                        "deterministic_replay_count": 0,
                    },
                )
        if metadata and all(item.state in {'completed','failed'} for item in run.shards):
            from ..governed_runtime.bulk_migration_review import persist_semantic_candidate_preview
            persist_semantic_candidate_preview(self.bulk_migration_repository,run)
        if (
            run.control_state == "completed"
            and manifest.pipeline_contract_id == NORTH_STAR_ETCH_PIPELINE_V1.contract_id
        ):
            if self.north_star_etch_preview_service is None:
                raise BulkMigrationPolicyError("NORTH_STAR_PREVIEW_SERVICE_UNAVAILABLE")
            questions = tuple(
                str(item) for item in safe_input.get("candidate_preview_questions") or ()
            )
            if len(questions) != 3:
                raise BulkMigrationPolicyError("NORTH_STAR_THREE_QUESTIONS_REQUIRED")
            self.north_star_etch_preview_service.qualify(
                principal=execution.principal.employee_id,
                run_id=run.run_id,
                questions=questions,  # type: ignore[arg-type]
                catalog_snapshot=dict(catalog),
                policy_digest=manifest.acl_policy_digest,
                active_concept_index_digest=manifest.active_concept_index_digest,
            )
        hierarchy = self.bulk_migration_repository.hierarchy(run.run_id)
        candidates = list(hierarchy.get("candidates") or ())
        receipts = list(hierarchy.get("receipts") or ())
        primary_candidate=(self.store.get('bulk_migration_candidates',run.candidate_refs[0])
            if run.candidate_refs else {}) or {}
        candidate_digest=str(primary_candidate.get('candidate_digest') or '')
        receipt = self._current_bulk_receipt(run.run_id, manifest.semantic_payload(), receipts)
        receipt_digest = str(receipt.get('receipt_digest') or '')
        artifact_id = "artifact:bulk-migration:" + run.run_id.removeprefix("migration_")
        artifact_payload = {
            "artifact_id": artifact_id,
            "employee_id": execution.principal.employee_id,
            "capability_id": execution.definition.capability_id,
            "artifact_type": "bulk_migration_candidate",
            "status": "provisional",
            "lane": "candidate_preview",
            "title": execution.definition.title,
            "run_id": run.run_id,
            "manifest_digest": run.manifest_digest,
            "candidate_digest": candidate_digest,
            "output_digest": run.output_digest,
            "receipt_digest": receipt_digest,
            "control_state": run.control_state,
            "candidate_state": run.candidate_state,
            "ui_url": run.ui_url,
            "mcp_invocation_ref": dict(run.mcp_invocation_ref),
            "production_changed": False,
            "active_transition": False,
            "created_at": now_iso(),
            "updated_at": now_iso(),
        }
        self.store.put("artifacts", artifact_id, artifact_payload)
        return CapabilityHandlerResult(
            status="completed" if run.control_state == "completed" else "needs_input",
            answer=AnswerBlock(
                summary="공통 Ontology migration pipeline 실행을 기록했습니다.",
                markdown=(
                    f"- Run: `{run.run_id}`\n"
                    f"- Manifest: `{run.manifest_digest}`\n"
                    f"- Pipeline result: `{run.output_digest}`\n"
                    f"- Candidate state: `{run.candidate_state}`\n"
                    "- Production Release/active transition: `false`"
                ),
            ),
            artifacts=[
                ArtifactRef(
                    artifact_id=artifact_id,
                    artifact_type="bulk_migration_candidate",
                    title=execution.definition.title,
                    status="provisional",
                    url=run.ui_url,
                    preview=f"{run.run_id} / {run.output_digest}",
                    metadata={
                        "manifest_digest": run.manifest_digest,
                        "candidate_digest": candidate_digest,
                        "receipt_digest": receipt_digest,
                        "lane": "candidate_preview",
                        "candidate_state": run.candidate_state,
                        "mcp_invocation_ref": dict(run.mcp_invocation_ref),
                        "production_changed": False,
                    },
                )
            ],
            job_ref=run.run_id,
        )

    def interpret_reviewed_metadata_question(self, principal, *, run_id, shard_id, preview_digest,
            question, invocation_channel='rest', prepare_native=False, native_submission=None):
        from ..governed_runtime.bulk_migration_transaction import MigrationWriteSet
        from ..governed_runtime.reviewed_metadata_query import read_reviewed_query_scope
        from ..governed_runtime.reviewed_semantic_context import build_reviewed_semantic_context
        from ..governed_runtime.semantic_binding_contract import semantic_digest
        if (not isinstance(question,str) or not question.strip() or len(question)>8192
                or invocation_channel not in {'ui','mcp','rest','cli'}):
            raise BulkMigrationPolicyError('REVIEWED_QUESTION_INPUT_INVALID')
        if prepare_native and native_submission is not None:
            raise BulkMigrationPolicyError('NATIVE_QUESTION_PREPARE_SUBMIT_CONFLICT')
        if not prepare_native and native_submission is None:
            # Literal occurrence cannot establish meaning (negation/examples included).
            # Only a structured native plan can be checked against reviewed authority.
            raise BulkMigrationPolicyError('REVIEWED_QUESTION_NATIVE_SUBMISSION_REQUIRED')
        runtime=self.general_query_runtime
        if not isinstance(runtime,ProfileDrivenQueryRuntime):
            raise BulkMigrationPolicyError('REVIEWED_QUESTION_COMMON_RUNTIME_REQUIRED')
        def read():
            buffer=MigrationWriteSet(self.store)
            repository=AgentV2StoreBulkMigrationRepository(buffer)
            scope=read_reviewed_query_scope(repository,principal=principal.employee_id,run_id=run_id,
                shard_id=shard_id,preview_digest=preview_digest,
                runtime_check=lambda manifest,domain:self._semantic_interpretation_runtime_check(principal,manifest,domain),
                quality_check=lambda inputs,manifest,audit:runtime.gateway.profile_declared_mapping(inputs=inputs,
                    principal=principal.employee_id,purpose=manifest['purpose'],manifest_digest=audit['manifest_digest'],
                    expected_grant_digest=audit['grant_digest']))
            bundle,context=build_reviewed_semantic_context(repository,scope,preview_digest=preview_digest,
                supported_operators=runtime.catalog.supported_operators,
                maximum_rows=min(1000,runtime.planning_policy.max_result_rows),
                retrieval_policy=runtime.reviewed_retriever.policy_version)
            return buffer,scope,bundle,context
        initial,scope,bundle,context=read()
        checked_read=[initial]
        def current(expected):
            current_buffer,_,actual,_=read()
            if actual!=expected:
                raise BulkMigrationPolicyError('REVIEWED_QUESTION_CURRENT_SCOPE_CHANGED')
            checked_read[0]=current_buffer
        if prepare_native:
            retrieval, native_input = runtime.prepare_native_reviewed_question(question,
                bundle=bundle, validate_current_scope=current)
            body = {'contract_version':'boi/native-reviewed-question-input@1',
                'employee_id':principal.employee_id, 'run_id':run_id, 'shard_id':shard_id,
                'question':question, 'semantic_context':context,
                'semantic_bundle':bundle.model_dump(mode='json'),
                'retrieval':retrieval.model_dump(mode='json'),
                'native_input':native_input.model_dump(mode='json'),
                'query_execution_status':'not_run', 'result_status':'PROVISIONAL',
                'production_changed':False, 'active_transition':False}
            return {**body, 'receipt_digest':semantic_digest(body)}
        interpretation = runtime.interpret_submitted_native_question(question,
            submission=native_submission, principal=principal.employee_id,
            bundle=bundle, validate_current_scope=current)
        outcome_presentation = None
        if interpretation.status != 'RESOLVED':
            from ..governed_runtime.reviewed_answer_presentation import (
                compose_reviewed_query_outcome_presentation,
            )
            outcome_presentation = compose_reviewed_query_outcome_presentation(
                question=question, status=interpretation.status,
                reason_codes=interpretation.reason_codes, stage='INTERPRETATION',
                candidate=(interpretation.synthesis.candidate.model_dump(mode='json')
                    if interpretation.synthesis is not None
                    and interpretation.synthesis.candidate is not None else None),
            ).model_dump(mode='json')
        # Fence the last fully revalidated read set: source preparation may
        # refresh a lookup storage timestamp without changing its definition.
        # Semantic equality was checked before replacing the prior read set.
        initial=checked_read[0]
        record={'contract_version':'boi/reviewed-question-result@1','employee_id':principal.employee_id,
            'question':question,'run_id':run_id,'shard_id':shard_id,
            'semantic_context':context,'semantic_bundle':bundle.model_dump(mode='json'),
            'interpretation':interpretation.model_dump(mode='json'),
            'frozen_inference_refs':[],
            **({'outcome_presentation': outcome_presentation}
               if outcome_presentation is not None else {}),
            'query_plan_status':'not_prepared','query_execution_status':'not_run',
            'result_status':'PROVISIONAL','production_changed':False,'active_transition':False}
        record['receipt_digest']=semantic_digest(record)
        key='reviewed-question:'+record['receipt_digest']
        prior=initial.get('bulk_migration_freeze_receipts',key)
        if prior and {k:v for k,v in prior.items() if k!='updated_at'}!=record:
            raise BulkMigrationPolicyError('REVIEWED_QUESTION_RECEIPT_CONFLICT')
        initial.put('bulk_migration_freeze_receipts',key,record)
        fences=tuple(key for key,value in initial.before.items() if value is not None)
        if not self.store.atomic_compare_and_write(initial.writes(fences=fences)):
            raise BulkMigrationPolicyError('REVIEWED_QUESTION_SCOPE_COMMIT_CONFLICT')
        return record

    def prepare_reviewed_metadata_natural_query(self, principal, *, run_id, shard_id,
            preview_digest, question, invocation_channel='rest', native_submission=None):
        """Freeze common interpretation and planning without granting execution."""
        interpreted = self.interpret_reviewed_metadata_question(
            principal, run_id=run_id, shard_id=shard_id,
            preview_digest=preview_digest, question=question,
            invocation_channel=invocation_channel,
            **({'native_submission':native_submission} if native_submission is not None else {}),
        )
        if interpreted['interpretation']['status'] != 'RESOLVED':
            return interpreted
        from ..governed_runtime.bulk_migration_transaction import MigrationWriteSet
        from ..governed_runtime.reviewed_metadata_query import read_reviewed_query_scope
        from ..governed_runtime.reviewed_semantic_context import (
            build_reviewed_planner_catalog,
            build_reviewed_semantic_context,
        )
        from ..governed_runtime.semantic_intent import SemanticQuestionInterpretation
        from ..governed_runtime.semantic_binding_contract import semantic_digest
        from ..governed_runtime.multi_result_query_gateway import (
            ReviewedQueryAuthority,
            create_multi_result_logical_plan,
            validate_multi_result_plan_authority,
        )
        from ..governed_runtime.reviewed_natural_query import apply_reviewed_query_qualifiers
        runtime = self.general_query_runtime
        if not isinstance(runtime, ProfileDrivenQueryRuntime):
            raise BulkMigrationPolicyError('REVIEWED_QUESTION_COMMON_RUNTIME_REQUIRED')

        def read():
            buffer = MigrationWriteSet(self.store)
            repository = AgentV2StoreBulkMigrationRepository(buffer)
            scope = read_reviewed_query_scope(
                repository, principal=principal.employee_id, run_id=run_id,
                shard_id=shard_id, preview_digest=preview_digest,
                runtime_check=lambda manifest, domain:
                    self._semantic_interpretation_runtime_check(principal, manifest, domain),
                quality_check=lambda inputs, manifest, audit:
                    runtime.gateway.profile_declared_mapping(
                        inputs=inputs, principal=principal.employee_id,
                        purpose=manifest['purpose'],
                        manifest_digest=audit['manifest_digest'],
                        expected_grant_digest=audit['grant_digest'],
                    ),
            )
            bundle, context = build_reviewed_semantic_context(
                repository, scope, preview_digest=preview_digest,
                supported_operators=runtime.catalog.supported_operators,
                maximum_rows=min(1000, runtime.planning_policy.max_result_rows),
                retrieval_policy=runtime.reviewed_retriever.policy_version,
            )
            catalog = build_reviewed_planner_catalog(
                repository, scope, capability_digest=bundle.capability_digest,
                supported_operators=runtime.catalog.supported_operators,
            )
            return buffer, scope, bundle, context, catalog

        initial, scope, bundle, context, catalog = read()
        if bundle.model_dump(mode='json') != interpreted['semantic_bundle']:
            raise BulkMigrationPolicyError('REVIEWED_QUESTION_CURRENT_SCOPE_CHANGED')
        checked_read = [initial]

        def current(expected):
            current_buffer, _, actual, _, _ = read()
            if actual != expected:
                raise BulkMigrationPolicyError('REVIEWED_QUESTION_CURRENT_SCOPE_CHANGED')
            checked_read[0] = current_buffer

        interpretation = SemanticQuestionInterpretation.model_validate(
            interpreted['interpretation']
        )
        planned = runtime.plan_reviewed_interpretation(
            interpretation, bundle=bundle, catalog=catalog,
            validate_current_scope=current,
        )
        initial = checked_read[0]
        if planned.status != 'READY':
            from ..governed_runtime.reviewed_answer_presentation import (
                compose_reviewed_query_outcome_presentation,
            )
            outcome_presentation = compose_reviewed_query_outcome_presentation(
                question=question, status=planned.status,
                reason_codes=planned.reason_codes, stage='PLANNING',
                candidate=(interpretation.synthesis.candidate.model_dump(mode='json')
                    if interpretation.synthesis is not None
                    and interpretation.synthesis.candidate is not None else None),
            )
            body = {
                'contract_version': 'boi/reviewed-natural-query-outcome@1',
                'employee_id': principal.employee_id,
                'run_id': run_id,
                'shard_id': shard_id,
                'question': question,
                'question_interpretation_receipt_digest': interpretation.receipt_digest,
                'semantic_plan_outcome': planned.model_dump(mode='json'),
                'outcome_presentation': outcome_presentation.model_dump(mode='json'),
                'query_plan_status': planned.status.casefold(),
                'query_execution_status': 'not_run',
                'result_status': 'PROVISIONAL',
                'production_changed': False,
                'active_transition': False,
            }
            record = {**body, 'receipt_digest': semantic_digest(body)}
            key = 'reviewed-natural-query:' + record['receipt_digest']
            prior = initial.get('bulk_migration_freeze_receipts', key)
            if prior and {k:v for k,v in prior.items() if k != 'updated_at'} != record:
                raise BulkMigrationPolicyError('REVIEWED_NATURAL_QUERY_OUTCOME_CONFLICT')
            initial.put('bulk_migration_freeze_receipts', key, record)
            fences = tuple(key for key, value in initial.before.items() if value is not None)
            if not self.store.atomic_compare_and_write(initial.writes(fences=fences)):
                raise BulkMigrationPolicyError('REVIEWED_NATURAL_QUERY_SCOPE_COMMIT_CONFLICT')
            return record

        selection = planned.shape_selection
        semantic_plan = planned.semantic_plan
        physical = planned.physical_binding
        resolution = interpretation.resolution
        if (selection is None or semantic_plan is None or physical is None
                or resolution is None or resolution.resolved_intent is None):
            raise BulkMigrationPolicyError('REVIEWED_NATURAL_QUERY_PLAN_INCOMPLETE')
        candidate = resolution.resolved_intent.candidate
        qualifier_application = apply_reviewed_query_qualifiers(
            scope=scope, planned=planned
        )
        parameters = json.loads(json.dumps(
            qualifier_application.parameters, ensure_ascii=False
        ))
        freeze_body = {
            'contract_version': 'boi/reviewed-natural-query-input-freeze@1',
            'principal': principal.employee_id,
            'run_id': run_id,
            'shard_id': shard_id,
            'manifest_digest': scope.run.manifest_digest,
            'preview_digest': preview_digest,
            'question': question,
            'question_digest': semantic_digest(question),
            'reviewed_definition_authority': (
                bundle.reviewed_definition_authority.model_dump(mode='json')
            ),
            'semantic_bundle_digest': bundle.bundle_digest,
            'question_interpretation_receipt_digest': interpretation.receipt_digest,
            'semantic_planning_context_digest': planned.planning_context.context_digest,
            'shape_selection_receipt_digest': selection.receipt_digest,
            'semantic_plan_digest': semantic_plan.plan_digest,
            'physical_binding_digest': physical.binding_digest,
            'planning_policy_digest': runtime.planning_policy.policy_digest,
            'qualifier_application_receipt_digest': (
                qualifier_application.receipt['receipt_digest']
            ),
            'intent': candidate.model_dump(mode='json'),
            'intent_digest': resolution.resolved_intent.intent_digest,
            'parameter_digest': semantic_digest(parameters),
        }
        freeze = {**freeze_body, 'receipt_digest': semantic_digest(freeze_body)}
        definition_authority = bundle.reviewed_definition_authority
        authority = ReviewedQueryAuthority(
            contract_version='boi/reviewed-query-authority@2',
            principal=principal.employee_id,
            purpose=scope.manifest['purpose'],
            manifest_digest=scope.run.manifest_digest,
            preview_digest=preview_digest,
            interpretation_receipt_digest=scope.review['receipt_digest'],
            semantic_context_digest=bundle.bundle_digest,
            mapping_input_digest=definition_authority.mapping_input_digest,
            intent_digest=resolution.resolved_intent.intent_digest,
            freeze_receipt_digest=freeze['receipt_digest'],
            question_digest=semantic_digest(question),
            question_interpretation_receipt_digest=interpretation.receipt_digest,
            reviewed_definition_authority_digest=semantic_digest(definition_authority),
            semantic_planning_context_digest=planned.planning_context.context_digest,
            shape_selection_receipt_digest=selection.receipt_digest,
            semantic_plan_digest=semantic_plan.plan_digest,
            physical_binding_digest=physical.binding_digest,
            planning_policy_digest=runtime.planning_policy.policy_digest,
            qualifier_application_receipt_digest=(
                qualifier_application.receipt['receipt_digest']
            ),
        )
        parameter_specs = qualifier_application.parameter_specs
        quality_receipts = selection.solver_outcome.quality_receipts
        logical_plan = create_multi_result_logical_plan(
            shape_solver_outcome_digest=selection.solver_outcome.outcome_digest,
            profile_contract_binding_digest=selection.profile_contracts.binding_digest,
            active_release_digest=None,
            domain_profile_digest=bundle.domain_profile_digest,
            mapping_profile_digest=bundle.mapping_profile_digest,
            query_profile_digest=bundle.query_profile_digest,
            schema_digest=bundle.schema_digest,
            result_sets=qualifier_application.result_sets,
            parameter_specs=parameter_specs,
            quality_receipt_digests=tuple(
                item.receipt_digest for item in quality_receipts
            ),
            candidate_authority=authority,
        )
        selected_relationship_ids = tuple(
            item.contract_id for item in selection.solver_outcome.bound_relationships
        )
        validation = validate_multi_result_plan_authority(
            logical_plan,
            physical_mappings=qualifier_application.physical_mappings,
            selected_relationship_ids=selected_relationship_ids,
        )
        if validation.status != 'PASS':
            raise BulkMigrationPolicyError('REVIEWED_NATURAL_QUERY_PLAN_AUTHORITY_INVALID')
        record_body = {
            'contract_version': 'boi/reviewed-query-preparation@4',
            'input_kind': 'natural_question',
            'employee_id': principal.employee_id,
            'run_id': run_id,
            'shard_id': shard_id,
            'semantic_context': context,
            'semantic_bundle': bundle.model_dump(mode='json'),
            'semantic_interpretation': interpretation.model_dump(mode='json'),
            'semantic_plan_outcome': planned.model_dump(mode='json'),
            'qualifier_resolution': qualifier_application.qualifier_resolution,
            'qualifier_application_receipt': qualifier_application.receipt,
            'input_freeze': freeze,
            'logical_plan': logical_plan.model_dump(mode='json'),
            'validation_receipt': validation.model_dump(mode='json'),
            'physical_mappings': [
                item.model_dump(mode='json')
                for item in qualifier_application.physical_mappings
            ],
            'selected_relationship_ids': list(selected_relationship_ids),
            'quality_receipts': [
                item.model_dump(mode='json') for item in quality_receipts
            ],
            'parameters': parameters,
            'query_plan_status': 'prepared',
            'execution_status': 'not_run',
            'result_status': 'PROVISIONAL',
            'production_changed': False,
            'active_transition': False,
        }
        record = {**record_body, 'receipt_digest': semantic_digest(record_body)}
        key = 'reviewed-query:' + record['receipt_digest']
        existing = initial.get('bulk_migration_freeze_receipts', key)
        if existing and {k:v for k,v in existing.items() if k != 'updated_at'} != record:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_FREEZE_DRIFT')
        initial.put('bulk_migration_freeze_receipts', key, record)
        index_key = 'reviewed-query-input:' + freeze['receipt_digest']
        index = {
            'contract_version': 'boi/reviewed-query-input-index@2',
            'employee_id': principal.employee_id,
            'preparation_ref': key,
            'preparation_digest': record['receipt_digest'],
        }
        prior_index = initial.get('bulk_migration_freeze_receipts', index_key)
        if prior_index and {k:v for k,v in prior_index.items() if k != 'updated_at'} != index:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_INPUT_INDEX_CONFLICT')
        initial.put('bulk_migration_freeze_receipts', index_key, index)
        fences = tuple(key for key, value in initial.before.items() if value is not None)
        if not self.store.atomic_compare_and_write(initial.writes(fences=fences)):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_FREEZE_CONFLICT')
        return record

    def prepare_reviewed_metadata_query(self, principal, *, run_id, shard_id, preview_digest, intent):
        from ..governed_runtime.bulk_migration_transaction import MigrationWriteSet
        from ..governed_runtime.reviewed_metadata_query import prepare_reviewed_query
        buffer=MigrationWriteSet(self.store)
        result=prepare_reviewed_query(AgentV2StoreBulkMigrationRepository(buffer),
            principal=principal.employee_id,run_id=run_id,shard_id=shard_id,preview_digest=preview_digest,intent=intent,
            runtime_check=lambda manifest,domain:self._semantic_interpretation_runtime_check(principal,manifest,domain),
            quality_check=lambda inputs,manifest,audit:self.general_query_runtime.gateway.profile_declared_mapping(
                inputs=inputs,principal=principal.employee_id,purpose=manifest['purpose'],
                manifest_digest=audit['manifest_digest'],expected_grant_digest=audit['grant_digest']))
        key='reviewed-query:'+result['receipt_digest']
        existing=buffer.get('bulk_migration_freeze_receipts',key)
        if existing and {k:v for k,v in existing.items() if k!='updated_at'}!=result:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_FREEZE_DRIFT')
        buffer.put('bulk_migration_freeze_receipts',key,result)
        index_key='reviewed-query-input:'+result['input_freeze']['receipt_digest']
        index={'contract_version':'boi/reviewed-query-input-index@1','employee_id':principal.employee_id,
            'preparation_ref':key,'preparation_digest':result['receipt_digest']}
        prior_index=buffer.get('bulk_migration_freeze_receipts',index_key)
        if prior_index and {k:v for k,v in prior_index.items() if k!='updated_at'}!=index:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_INPUT_INDEX_CONFLICT')
        buffer.put('bulk_migration_freeze_receipts',index_key,index)
        fences=tuple(key for key,value in buffer.before.items() if value is not None)
        if not self.store.atomic_compare_and_write(buffer.writes(fences=fences)):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_FREEZE_CONFLICT')
        return result

    def _load_reviewed_query_preparation(self, principal, receipt_digest):
        from ..governed_runtime.bulk_migration import _digest
        value=self.store.get('bulk_migration_freeze_receipts','reviewed-query:'+receipt_digest) or {}
        body={k:v for k,v in value.items() if k not in {'updated_at','receipt_digest'}}
        if (value.get('employee_id')!=principal.employee_id or value.get('receipt_digest')!=receipt_digest
            or _digest(body)!=receipt_digest or value.get('contract_version') not in {
                'boi/reviewed-query-preparation@1','boi/reviewed-query-preparation@2',
                'boi/reviewed-query-preparation@3','boi/reviewed-query-preparation@4'}):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_PREPARATION_UNAVAILABLE')
        return {**body,'receipt_digest':receipt_digest}

    def _resolve_reviewed_query_access(self, principal, access, grant_revision=None):
        from ..governed_runtime.bulk_migration import _digest
        from ..governed_runtime.multi_result_query_gateway import (
            ReviewedQueryAuthority, ReviewedQueryPagingAccess,
        )
        index=self.store.get('bulk_migration_freeze_receipts',
            'reviewed-query-input:'+access.authority.freeze_receipt_digest) or {}
        if index.get('employee_id')!=principal.employee_id:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_INPUT_INDEX_UNAVAILABLE')
        saved=self._load_reviewed_query_preparation(principal,index.get('preparation_digest',''))
        if index.get('preparation_ref')!='reviewed-query:'+saved['receipt_digest']:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_INPUT_INDEX_CONFLICT')
        from ..governed_runtime.reviewed_query_grants import ReviewedQueryGrantDecision
        decision=(self.reviewed_query_execution_authorizer(principal,saved)
            if self.reviewed_query_execution_authorizer else None)
        if isinstance(decision,ReviewedQueryGrantDecision):
            decision=ReviewedQueryGrantDecision.model_validate(decision.model_dump(mode='json'))
        if (not isinstance(decision,ReviewedQueryGrantDecision)
            or decision.principal!=principal.employee_id
            or decision.preparation_receipt_digest!=saved['receipt_digest']
            or decision.purpose!=access.authority.purpose
            or decision.source_snapshot_digest!=saved['semantic_context']['declared_mapping_inputs']['source_snapshot_digest']):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_EXECUTION_GRANT_REQUIRED')
        if grant_revision is not None:
            if grant_revision and grant_revision[0]!=decision.grant_digest:
                raise BulkMigrationPolicyError('REVIEWED_QUERY_GRANT_CHANGED_DURING_ACCESS')
            if not grant_revision:grant_revision.append(decision.grant_digest)
        from ..governed_runtime.semantic_binding_contract import semantic_digest
        decision_body=decision.model_dump(mode='json')
        decision_ref='reviewed-query-grant:'+semantic_digest(decision)
        from ..governed_runtime.bulk_migration_transaction import MigrationWriteSet
        decision_record={'employee_id':principal.employee_id,**decision_body}
        buffer=MigrationWriteSet(self.store)
        previous=buffer.get('bulk_migration_receipts',decision_ref)
        if previous and {k:v for k,v in previous.items() if k!='updated_at'}!=decision_record:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_GRANT_RECEIPT_CONFLICT')
        buffer.put('bulk_migration_receipts',decision_ref,decision_record)
        if not self.store.atomic_compare_and_write(buffer.writes(fences=(('bulk_migration_receipts',decision_ref),))):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_GRANT_RECEIPT_CONFLICT')
        frozen=saved['input_freeze']
        if saved.get('input_kind') == 'natural_question':
            current=self.prepare_reviewed_metadata_natural_query(
                principal,run_id=saved['run_id'],shard_id=saved['shard_id'],
                preview_digest=frozen['preview_digest'],question=frozen['question'],
                invocation_channel='rest')
        else:
            current=self.prepare_reviewed_metadata_query(principal,run_id=saved['run_id'],shard_id=saved['shard_id'],
                preview_digest=frozen['preview_digest'],intent=frozen['intent'])
        if (current!=saved or saved['logical_plan']['plan_digest']!=access.logical_plan_digest
            or _digest(saved['parameters'])!=access.parameter_digest):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_FROZEN_PLAN_STALE')
        if isinstance(access,ReviewedQueryPagingAccess):
            from ..governed_runtime.reviewed_query_grants import authorize_reviewed_paging
            authorize_reviewed_paging(
                decision.grant,saved,result_set_id=access.result_set_id,
                paging_policy_digest=access.paging_policy_digest,
                page_size=access.page_size,total_row_count=access.total_row_count,
            )
        authority=ReviewedQueryAuthority.model_validate(saved['logical_plan']['candidate_authority'])
        if authority!=access.authority:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_FROZEN_AUTHORITY_STALE')
        return authority

    def execute_reviewed_metadata_query(self, principal, *, preparation_receipt_digest, idempotency_key):
        from ..governed_runtime.multi_result_query_gateway import MultiResultExploratoryExecutionRequest
        if not isinstance(idempotency_key,str) or not idempotency_key.strip() or len(idempotency_key)>256:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_IDEMPOTENCY_KEY_REQUIRED')
        prepared=self._load_reviewed_query_preparation(principal,preparation_receipt_digest)
        authority=prepared['logical_plan']['candidate_authority']
        request=MultiResultExploratoryExecutionRequest(lane='exploratory',logical_plan=prepared['logical_plan'],
            validation_receipt=prepared['validation_receipt'],physical_mappings=prepared['physical_mappings'],
            selected_relationship_ids=prepared.get('selected_relationship_ids',()),
            quality_receipts=prepared.get('quality_receipts',()),parameters=prepared['parameters'],
            principal=principal.employee_id,purpose=authority['purpose'],idempotency_key=idempotency_key,
            inline_row_limit=1000,timeout_seconds=30)
        gateway=self.general_query_runtime.gateway
        backend=getattr(gateway,'_multi_result_gateway',None)
        if backend is None:raise BulkMigrationPolicyError('REVIEWED_QUERY_GATEWAY_UNAVAILABLE')
        if backend.execution_repository is None:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_DURABLE_EXECUTION_REQUIRED')
        grant_revision=[]
        with backend.reviewed_access_scope(lambda access:self._resolve_reviewed_query_access(principal,access,grant_revision)):
            executed=gateway.create(request)
        # Preserve execution evidence without copying raw result rows into the migration store.
        from ..governed_runtime.bulk_migration_transaction import MigrationWriteSet
        record={'contract_version':'boi/reviewed-query-result@1','employee_id':principal.employee_id,
            'preparation_receipt_digest':preparation_receipt_digest,
            'gateway_receipt':executed.receipt.model_dump(mode='json'),'execution_grant_digest':grant_revision[0],
            'production_changed':False,'active_transition':False}
        key='reviewed-query-result:'+executed.receipt.receipt_digest
        buffer=MigrationWriteSet(self.store)
        prior=buffer.get('bulk_migration_receipts',key)
        if prior and {k:v for k,v in prior.items() if k!='updated_at'}!=record:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_RESULT_RECEIPT_CONFLICT')
        buffer.put('bulk_migration_receipts',key,record)
        if not self.store.atomic_compare_and_write(buffer.writes(fences=(('bulk_migration_receipts',key),))):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_RESULT_RECEIPT_CONFLICT')
        return executed

    def read_reviewed_metadata_query_result(self, principal, *, artifact_ref, purpose):
        gateway=self.general_query_runtime.gateway
        backend=getattr(gateway,'_multi_result_gateway',None)
        if backend is None:raise BulkMigrationPolicyError('REVIEWED_QUERY_GATEWAY_UNAVAILABLE')
        with backend.reviewed_access_scope(lambda access:self._resolve_reviewed_query_access(principal,access)):
            return gateway.read_multi_result_artifact(artifact_ref,principal=principal.employee_id,purpose=purpose)

    def read_reviewed_metadata_query_answer(self, principal, *, preparation_receipt_digest, artifact_ref):
        from ..governed_runtime.reviewed_metadata_answer import build_reviewed_metadata_answer
        from ..governed_runtime.multi_result_query_gateway import ReviewedQueryAccess, ReviewedQueryAuthority
        from ..governed_runtime.semantic_binding_contract import semantic_digest
        prepared=self._load_reviewed_query_preparation(principal,preparation_receipt_digest)
        authority=ReviewedQueryAuthority.model_validate(prepared['logical_plan']['candidate_authority'])
        gateway=self.general_query_runtime.gateway
        backend=getattr(gateway,'_multi_result_gateway',None)
        if backend is None:raise BulkMigrationPolicyError('REVIEWED_QUERY_GATEWAY_UNAVAILABLE')
        revisions=[]
        resolver=lambda access:self._resolve_reviewed_query_access(principal,access,revisions)
        with backend.reviewed_access_scope(resolver):
            artifact=gateway.read_multi_result_artifact(artifact_ref,principal=principal.employee_id,purpose=authority.purpose)
        if (artifact.get('logical_plan_digest')!=prepared['logical_plan']['plan_digest']
            or artifact.get('candidate_authority')!=authority.model_dump(mode='json')):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_RESULT_PLAN_MISMATCH')
        execution=backend.get(artifact['run_id'])
        if (execution is None or execution.receipt.result_artifact_ref!=artifact_ref
            or execution.receipt.result_artifact_digest!=artifact['artifact_digest']
            or execution.receipt.result_digest!=artifact['result_digest']):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_EXECUTION_RECEIPT_UNAVAILABLE')
        access={'contract_version':'boi/reviewed-answer-access@1','principal':principal.employee_id,
            'preparation_receipt_digest':preparation_receipt_digest,'artifact_digest':artifact['artifact_digest'],
            'execution_receipt_digest':execution.receipt.receipt_digest,'grant_digest':revisions[0]}
        answer=build_reviewed_metadata_answer(prepared=prepared,execution=execution,
            access_receipt_digest=semantic_digest(access))
        resolver(ReviewedQueryAccess(authority=authority,logical_plan_digest=prepared['logical_plan']['plan_digest'],
            parameter_digest=semantic_digest(prepared['parameters'])))
        # The original protected result remains immutable. Persist only answer
        # evidence; values are read from the same protected Gateway artifact.
        from ..governed_runtime.bulk_migration_transaction import MigrationWriteSet
        record={'contract_version':'boi/reviewed-answer-receipt@2','employee_id':principal.employee_id,
            'artifact_semantic_digest':answer.artifact_semantic_digest,'access_receipt':access,
            'meaning_context_digest':answer.meaning_context.context_digest,
            'presentation_digest':answer.presentation.presentation_digest,
            'production_changed':False,'active_transition':False}
        key='reviewed-answer:'+answer.artifact_semantic_digest
        buffer=MigrationWriteSet(self.store)
        prior=buffer.get('bulk_migration_receipts',key)
        if prior and {k:v for k,v in prior.items() if k!='updated_at'}!=record:
            raise BulkMigrationPolicyError('REVIEWED_ANSWER_RECEIPT_CONFLICT')
        buffer.put('bulk_migration_receipts',key,record)
        if not self.store.atomic_compare_and_write(buffer.writes(fences=(('bulk_migration_receipts',key),))):
            raise BulkMigrationPolicyError('REVIEWED_ANSWER_RECEIPT_CONFLICT')
        return answer.model_dump(mode='json')

    def read_reviewed_metadata_query_page(self, principal, *,
            preparation_receipt_digest, artifact_ref,
            answer_artifact_semantic_digest, result_set_id, cursor):
        """Read one protected page after revalidating review, source and grant."""
        from ..governed_runtime.reviewed_metadata_answer import (
            ReviewedGovernedAnswerArtifact, build_reviewed_metadata_answer,
        )
        from ..governed_runtime.reviewed_query_paging import (
            build_reviewed_query_answer_page,
        )
        from ..governed_runtime.multi_result_query_gateway import ReviewedQueryAuthority
        from ..governed_runtime.semantic_binding_contract import semantic_digest
        prepared=self._load_reviewed_query_preparation(
            principal,preparation_receipt_digest)
        authority=ReviewedQueryAuthority.model_validate(
            prepared['logical_plan']['candidate_authority'])
        gateway=self.general_query_runtime.gateway
        backend=getattr(gateway,'_multi_result_gateway',None)
        if backend is None:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_GATEWAY_UNAVAILABLE')
        revisions=[]
        resolver=lambda access:self._resolve_reviewed_query_access(
            principal,access,revisions)
        with backend.reviewed_access_scope(resolver):
            artifact=gateway.read_multi_result_artifact(
                artifact_ref,principal=principal.employee_id,purpose=authority.purpose)
            if (artifact.get('logical_plan_digest')!=prepared['logical_plan']['plan_digest']
                or artifact.get('candidate_authority')!=authority.model_dump(mode='json')):
                raise BulkMigrationPolicyError('REVIEWED_QUERY_RESULT_PLAN_MISMATCH')
            protected_set=next((item for item in artifact.get('result_sets',())
                if item.get('result_set_id')==result_set_id),None)
            if protected_set is None:
                raise BulkMigrationPolicyError('REVIEWED_QUERY_PAGE_RESULT_SET_NOT_FOUND')
            paging=protected_set.get('paging')
            if not isinstance(paging,dict) or not paging.get('paging_ref'):
                raise BulkMigrationPolicyError('REVIEWED_QUERY_PAGE_NOT_DECLARED')
            execution=backend.get(artifact['run_id'])
            if (execution is None or execution.receipt.result_artifact_ref!=artifact_ref
                or execution.receipt.result_artifact_digest!=artifact['artifact_digest']
                or execution.receipt.result_digest!=artifact['result_digest']):
                raise BulkMigrationPolicyError('REVIEWED_QUERY_EXECUTION_RECEIPT_UNAVAILABLE')
            answer_access={'contract_version':'boi/reviewed-answer-access@1',
                'principal':principal.employee_id,
                'preparation_receipt_digest':preparation_receipt_digest,
                'artifact_digest':artifact['artifact_digest'],
                'execution_receipt_digest':execution.receipt.receipt_digest,
                'grant_digest':revisions[0]}
            answer=ReviewedGovernedAnswerArtifact.model_validate(
                build_reviewed_metadata_answer(
                    prepared=prepared,execution=execution,
                    access_receipt_digest=semantic_digest(answer_access)))
            if answer.artifact_semantic_digest!=answer_artifact_semantic_digest:
                raise BulkMigrationPolicyError('REVIEWED_QUERY_PAGE_ANSWER_STALE')
            page=gateway.read_snapshot_result_page(
                paging['paging_ref'],principal=principal.employee_id,
                purpose=authority.purpose,cursor=cursor)
        if (page.get('run_id')!=execution.execution_id
            or page.get('result_set_id')!=result_set_id
            or page.get('logical_plan_digest')!=prepared['logical_plan']['plan_digest']
            or page.get('paging_ref')!=paging['paging_ref']
            or page.get('source_snapshot_digest')!=execution.receipt.source_snapshot_digest
            or page.get('total_row_count')!=paging.get('total_row_count')):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_PAGE_EXECUTION_MISMATCH')
        access={'contract_version':'boi/reviewed-page-access@1',
            'principal':principal.employee_id,
            'preparation_receipt_digest':preparation_receipt_digest,
            'artifact_digest':artifact['artifact_digest'],
            'answer_artifact_semantic_digest':answer_artifact_semantic_digest,
            'execution_receipt_digest':execution.receipt.receipt_digest,
            'page_receipt_digest':page['receipt_digest'],
            'grant_digest':revisions[0]}
        page_access_receipt_digest=semantic_digest(access)
        answer_set=next((item for item in answer.result_sets
            if item.result_set_id==result_set_id),None)
        if (answer_set is None or answer_set.paging is None
            or answer_set.paging.paging_ref!=page['paging_ref']):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_PAGE_ANSWER_MISMATCH')
        response=build_reviewed_query_answer_page(
            prepared=prepared,answer_digest=answer.artifact_semantic_digest,
            protected_artifact_digest=artifact['artifact_digest'],
            execution_receipt_digest=execution.receipt.receipt_digest,
            grant_digest=revisions[0],
            page_access_receipt_digest=page_access_receipt_digest,
            result_set=answer_set,page=page)
        record={'contract_version':'boi/reviewed-page-receipt@1',
            'employee_id':principal.employee_id,
            'preparation_receipt_digest':preparation_receipt_digest,
            'protected_artifact_digest':artifact['artifact_digest'],
            'result_set_id':result_set_id,
            'page_receipt_digest':page['receipt_digest'],
            'page_result_digest':page['page_result_digest'],
            'page_access_receipt_digest':page_access_receipt_digest,
            'response_digest':response.response_digest,
            'grant_digest':revisions[0],
            'production_changed':False,'active_transition':False}
        key='reviewed-query-page:'+page['receipt_digest']
        from ..governed_runtime.bulk_migration_transaction import MigrationWriteSet
        buffer=MigrationWriteSet(self.store)
        prior=buffer.get('bulk_migration_receipts',key)
        if prior and {k:v for k,v in prior.items() if k!='updated_at'}!=record:
            raise BulkMigrationPolicyError('REVIEWED_QUERY_PAGE_RECEIPT_CONFLICT')
        buffer.put('bulk_migration_receipts',key,record)
        if not self.store.atomic_compare_and_write(
                buffer.writes(fences=(('bulk_migration_receipts',key),))):
            raise BulkMigrationPolicyError('REVIEWED_QUERY_PAGE_RECEIPT_CONFLICT')
        return response.model_dump(mode='json')

    def preview_run_relation_quality(self, principal, *, run_id, expected_preview_digest,
                                     relation_dependency_digest, relationship_contract):
        """Read the protected source and preserve one candidate diagnostic."""
        from ..governed_runtime.bulk_migration_qualification import (
            semantic_candidate_closure,pinned_relation_definition_index)
        from ..governed_runtime.run_relation_mapping import (
            RunRelationQualityPreviewRequest,assemble_run_relation_quality_inputs,
            persist_run_relation_quality_receipt)
        from ..governed_runtime.semantic_profile_loader import ProfilePrincipal
        from ..governed_runtime.metadata_mapping_profile import verify_declared_metadata_mapping_catalog
        from ..governed_runtime.bulk_migration import _digest

        request=RunRelationQualityPreviewRequest.model_validate({
            'expected_preview_digest':expected_preview_digest,
            'relation_dependency_digest':relation_dependency_digest,
            'relationship_contract':relationship_contract})
        if ('boi.editor' not in principal.roles and not principal.is_admin) or (
            principal.token_id and 'boi.draft' not in principal.token_scopes):
            raise BulkMigrationPolicyError('RUN_RELATION_PREVIEW_ACCESS_DENIED')
        run=self.bulk_migration_repository.get(run_id)
        if (not run or run.principal!=principal.employee_id
            or run.control_state=='cancelled'):
            raise BulkMigrationPolicyError('RUN_RELATION_PREVIEW_ACCESS_DENIED')
        view=self.ontology_migration_workbench_view(principal,run_id)
        if view['staging']['preview_digest']!=request.expected_preview_digest:
            raise BulkMigrationPolicyError('RUN_RELATION_PREVIEW_STALE')
        matches=[item for item in view['relation_mapping_dependencies']
            if item['dependency_digest']==request.relation_dependency_digest]
        if len(matches)!=1 or matches[0]['status']!='candidate_mapping_closed':
            raise BulkMigrationPolicyError('RUN_RELATION_DEPENDENCY_NOT_CLOSED')
        dependency=matches[0]
        manifest=self.bulk_migration_repository.manifest_payload(run)
        if _digest(manifest)!=run.manifest_digest or not manifest.get('metadata_execution'):
            raise BulkMigrationPolicyError('RUN_RELATION_MANIFEST_STALE')
        children=semantic_candidate_closure(run,manifest,self.bulk_migration_repository)
        domain=[item for item in children['records'] if 'candidate_profile' not in item]
        runtime=self._semantic_interpretation_runtime_check(principal,manifest,domain)
        if any(runtime.get(key)!=manifest.get(key) for key in (
            'metadata_execution','catalog_snapshot_digest','schema_snapshot_digest',
            'active_concept_index_digest','acl_policy_digest','selector')):
            raise BulkMigrationPolicyError('RUN_RELATION_SOURCE_OR_POLICY_STALE')
        bindings=self.metadata_runtime_bindings
        authorization=bindings.authorize(principal)
        if authorization.policy_digest!=manifest['acl_policy_digest']:
            raise BulkMigrationPolicyError('RUN_RELATION_POLICY_STALE')
        configuration=bindings.current_metadata_configuration()
        selection=configuration.source_selections.get(
            manifest['metadata_execution']['source_selection_id'])
        policy=selection.physical_metadata_policy if selection else None
        if (policy is None or not policy.quality_grant_digest
            or policy.source_id!=dependency['left_key_mappings'][0]['source_id']):
            raise BulkMigrationPolicyError('RUN_RELATION_QUALITY_GRANT_UNAVAILABLE')
        index_ref='definition-index:'+manifest['metadata_execution']['definition_closure_digest']
        index=self.store.get('bulk_migration_concept_indexes',index_ref) or {}
        _,lookup,_=pinned_relation_definition_index(index,manifest,principal.employee_id)
        snapshot=bindings.definition_loader().load_definition_scope(
            principal=ProfilePrincipal(principal_id=principal.employee_id,
                team_ids=tuple(principal.teams)),purpose=manifest['purpose'],
            namespace=lookup.namespace,policy_digest=authorization.policy_digest,
            at=bindings.clock())
        definitions=pinned_relation_definition_index(index,manifest,principal.employee_id,
            active_snapshot=snapshot)
        inputs=assemble_run_relation_quality_inputs(children=children,dependency=dependency,
            definition_index=definitions,relationship=request.relationship_contract,
            manifest=manifest,source_snapshot_digest=policy.source_snapshot_digest)
        catalog=self.store.get('bulk_migration_catalog_snapshots',manifest['catalog_snapshot_ref']) or {}
        if (catalog.get('employee_id')!=principal.employee_id
            or catalog.get('digest')!=manifest['catalog_snapshot_digest']
            or catalog.get('schema_digest')!=manifest['schema_snapshot_digest']):
            raise BulkMigrationPolicyError('RUN_RELATION_CATALOG_STALE')
        catalog_check=verify_declared_metadata_mapping_catalog(inputs,
            catalog_snapshot=catalog,catalog_snapshot_digest=manifest['catalog_snapshot_digest'])
        if catalog_check['catalog_checks_status']!='pass':
            raise BulkMigrationPolicyError('RUN_RELATION_CATALOG_MAPPING_INVALID')
        gateway=getattr(self.general_query_runtime,'gateway',None)
        if gateway is None:
            raise BulkMigrationPolicyError('RUN_RELATION_QUALITY_GATEWAY_UNAVAILABLE')
        audit=gateway.profile_declared_mapping(inputs=inputs,principal=principal.employee_id,
            purpose=manifest['purpose'],manifest_digest=run.manifest_digest,
            expected_grant_digest=policy.quality_grant_digest)
        response={'contract_version':'boi/run-relation-quality-preview@1',
            'run_id':run_id,'manifest_digest':run.manifest_digest,
            'run_semantic_digest':run.semantic_digest,
            'preview_digest':request.expected_preview_digest,
            'run_candidate_closure_digest':children['closure_digest'],
            'relation_dependency_digest':dependency['dependency_digest'],
            'relationship_contract_digest':request.relationship_contract.contract_digest,
            'relationship_contract':request.relationship_contract.model_dump(mode='json'),
            'mapping_input_digest':_digest(inputs.model_dump(mode='json')),
            'catalog_check_digest':_digest(catalog_check),
            'quality_audit_receipt':audit,
            'status':'candidate_quality_measured' if (audit['status']=='partial'
                and audit['relationship_quality_status']=='measured_candidate_only')
                else 'candidate_quality_incomplete',
            'semantic_authority_approved':False,'query_execution_status':'not_run',
            'authority':'candidate_only','production_changed':False,'active_transition':False}
        return persist_run_relation_quality_receipt(self.bulk_migration_repository,
            run=run,manifest=manifest,children=children,dependency=dependency,
            preview_digest=request.expected_preview_digest,catalog=catalog,index=index,
            response=response)

    def _semantic_interpretation_runtime_check(self, principal, manifest, domain):
        if ('boi.editor' not in principal.roles and not principal.is_admin) or (
            principal.token_id and 'boi.draft' not in principal.token_scopes
        ):
            raise BulkMigrationPolicyError('INTERPRETATION_REVIEW_ACCESS_DENIED')
        if self.metadata_runtime_bindings is None or self.source_intake is None:
            raise BulkMigrationPolicyError('SEMANTIC_METADATA_RUNTIME_UNAVAILABLE')
        # Manifest construction canonicalizes these lists as sets. Re-resolve
        # them in runtime order, then compare with the persisted set contract.
        set_fields = {'profile_revisions', 'evaluator_code_digests', 'model_role_prompt_digests'}
        prepared = self.metadata_runtime_bindings.prepare_metadata(
            source_intake=self.source_intake, principal=principal,
            value={**{key:value for key,value in manifest.items() if key not in set_fields | {'selector'}},
                'metadata_source_profile_id':manifest['metadata_execution']['source_selection_id']})
        if any(sorted(set(prepared.input[key])) != manifest.get(key) for key in set_fields):
            raise BulkMigrationPolicyError('INTERPRETATION_RUNTIME_REVISION_STALE')
        if SelectorManifest.create(**prepared.input['selector']).semantic_payload() != manifest.get('selector'):
            raise BulkMigrationPolicyError('INTERPRETATION_SELECTOR_STALE')
        from ..governed_runtime.record_field_metadata_intake import RecordFieldIntake
        records = {item.intake.record.identity_digest:item.intake for item in prepared.published_records
            if isinstance(item.intake, RecordFieldIntake)}
        for candidate in domain:
            record = records.get(candidate.get('record_identity_digest'))
            # Identity is never inferred from a display name or array position.
            if record is None:
                record = next((item for item in records.values()
                    if item.record.model_dump(mode='json') == candidate.get('source_record')), None)
            if record is None or record.record.model_dump(mode='json') != candidate.get('source_record'):
                raise BulkMigrationPolicyError('INTERPRETATION_SOURCE_RECORD_STALE')
            actual = {span.span_ref:span.model_dump(mode='json') for span in record.evidence}
            for span in candidate.get('field_evidence', []):
                if actual.get(span.get('span_ref')) != span:
                    raise BulkMigrationPolicyError('INTERPRETATION_SOURCE_EVIDENCE_STALE')
        return {key:prepared.input[key] for key in (
            'metadata_execution','catalog_snapshot_digest','schema_snapshot_digest',
            'active_concept_index_digest','acl_policy_digest','evaluator_code_digests',
            'model_role_prompt_digests','profile_revisions','selector')}

    def _handle_semantic_interpretation_review(self, execution, safe_input):
        from ..governed_runtime.bulk_migration_review import prepare_interpretation_review, SemanticInterpretationRequest
        review_input = {key:safe_input[key] for key in SemanticInterpretationRequest.model_fields
            if key in safe_input}
        plan = prepare_interpretation_review(self.bulk_migration_repository,
            principal=execution.principal.employee_id, request=review_input,
            runtime_check=lambda manifest,domain:self._semantic_interpretation_runtime_check(
                execution.principal,manifest,domain))
        plan_id = 'interpretation_' + plan['plan_digest'].removeprefix('sha256:')
        if not self.store.get('plans', plan_id):
            self.store.put('plans', plan_id, {
                'plan_id':plan_id, 'employee_id':execution.principal.employee_id,
                'capability_id':execution.definition.capability_id, 'operation':'draft',
                'status':'draft', 'risk':'medium', 'revision':1,
                'production_changed':False, 'ui_url':plan['ui_url'],
                'domain_operation':'ontology.migration.interpretation-review',
                'domain_payload':{'interpretation_plan_digest':plan['plan_digest']},
                'domain_validation':{'valid':True,'errors':[],'warnings':[]},
                'idempotency_key':plan_id,
            })
        self._ensure_plan_binding(plan_id)
        return CapabilityHandlerResult(status='needs_input', plan_ref=plan_id,
            job_ref=plan['closure']['run_id'], answer=AnswerBlock(
                summary='같은 run의 의미 해석 검토 계획을 만들었습니다.',
                markdown=(f"[{plan['closure']['run_id']}]({plan['ui_url']}) · "
                    f"검토 계획 `{plan['plan_digest']}`. "
                    '의미 해석 확인만 기록하며 Mapping/Query 검증, 최종 이관 승인, Release/활성화 권한은 부여하지 않습니다.')))

    def _confirm_semantic_interpretation_plan(self, principal, plan, reason):
        from ..governed_runtime.bulk_migration_review import confirm_interpretation_review
        try:
            result = confirm_interpretation_review(self.bulk_migration_repository,
                principal=principal.employee_id,
                plan_digest=plan['domain_payload']['interpretation_plan_digest'], reason=reason,
                confirmation_plan=plan,
                runtime_check=lambda manifest,domain:self._semantic_interpretation_runtime_check(principal,manifest,domain))
        except (BulkMigrationPolicyError, ValueError) as error:
            code = str(error)
            if not re.fullmatch(r'[A-Z][A-Z0-9_]{1,100}', code):
                code = 'INTERPRETATION_REVIEW_REJECTED'
            raise HTTPException(status_code=409, detail={'code':code}) from None
        return result

    def _handle_ontology_migration(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        """Create a review-bound migration candidate without DB or Release authority."""

        try:
            safe_input = self._ontology_migration_safe_input(
                execution.request.input_delta
            )
        except ValueError as exc:
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="원문 본문이나 실행 데이터를 계획에 직접 넣을 수 없습니다.",
                    markdown=(
                        f"{compact_text(str(exc), 300)}. "
                        "Data Lake SourceArtifact, SQL source, catalog snapshot의 ref와 digest만 전달해주세요."
                    ),
                ),
            )
        if (execution.definition.capability_id == 'ontology.migration.migration-batch-review'
            and safe_input.get('review_mode') == 'semantic_interpretation'):
            try:
                return self._handle_semantic_interpretation_review(execution, safe_input)
            except (BulkMigrationPolicyError, ValueError) as error:
                code = str(error)
                if not re.fullmatch(r'[A-Z][A-Z0-9_]{1,100}', code):
                    code = 'INTERPRETATION_REVIEW_REJECTED'
                return CapabilityHandlerResult(status='needs_input', answer=AnswerBlock(
                    summary='의미 해석 검토를 진행할 수 없습니다.', markdown=code))
        if str(execution.definition.handler_config.get("orchestration") or "") == "bulk_pipeline":
            try:
                return self._handle_bulk_ontology_migration(
                    execution,
                    dict(safe_input),
                )
            except (BulkMigrationPolicyError, ValueError, TypeError) as exc:
                return CapabilityHandlerResult(
                    status="needs_input",
                    answer=AnswerBlock(
                        summary="Bulk ontology migration 입력 또는 검증이 차단되었습니다.",
                        markdown=f"`{compact_text(str(exc), 500)}`",
                    ),
                )

        skill_id = str(execution.definition.handler_config.get("skill_id") or "")
        skill = ontology_migration_skill_registry().get(skill_id)
        if skill is None:
            raise RuntimeError(f"unknown ontology migration skill: {skill_id}")

        candidate = {
            "contract_version": "ontology-migration-capability/v1",
            "skill_id": skill.skill_id,
            "goal": execution.request.question.strip(),
            "input": safe_input,
            "required_inputs": list(skill.required_inputs),
            "outputs": list(skill.outputs),
            "output_authority": skill.output_authority,
            "allowed_actions": list(skill.allowed_actions),
            "forbidden_actions": sorted(skill.forbidden_actions),
            "deterministic_first": skill.deterministic_first,
            "local_model_allowed": skill.local_model_allowed,
            "local_model_fallback": skill.local_model_fallback,
            "release_authority": "forbidden",
            "production_changed": False,
        }
        candidate_digest = "sha256:" + self._contract_checksum(candidate)
        source_manifest_digest = "sha256:" + self._contract_checksum(safe_input)
        artifact_id = new_id("artifact")
        plan_id = new_id("plan")
        job_id = new_id("migration")
        created_at = now_iso()
        stored_artifact = {
            "artifact_id": artifact_id,
            "employee_id": execution.principal.employee_id,
            "capability_id": execution.definition.capability_id,
            "artifact_type": "ontology_migration_candidate",
            "status": "draft",
            "title": execution.definition.title,
            "draft": candidate,
            "candidate_digest": candidate_digest,
            "work_session_id": str(execution.session["session_id"]),
            "work_run_id": str(execution.work_run["work_run_id"]),
            "revision": 1,
            "production_changed": False,
            "created_at": created_at,
            "updated_at": created_at,
        }
        self.store.put("artifacts", artifact_id, stored_artifact)
        self.store.put(
            "ontology_migration_jobs",
            job_id,
            {
                "job_id": job_id,
                "employee_id": execution.principal.employee_id,
                "capability_id": execution.definition.capability_id,
                "skill_id": skill.skill_id,
                "state": "captured",
                "candidate_digest": candidate_digest,
                "source_manifest_digest": source_manifest_digest,
                "artifact_id": artifact_id,
                "plan_id": plan_id,
                "approved": False,
                "released": False,
                "active_transition": False,
                "production_changed": False,
                "revision": 1,
                "created_at": created_at,
                "updated_at": created_at,
            },
        )
        self.store.put(
            "plans",
            plan_id,
            {
                "plan_id": plan_id,
                "employee_id": execution.principal.employee_id,
                "capability_id": execution.definition.capability_id,
                "operation": "draft",
                "artifact_id": artifact_id,
                "status": "draft",
                "risk": execution.definition.risk.value,
                "production_changed": False,
                "work_run_id": str(execution.work_run["work_run_id"]),
                "domain_operation": "",
                "domain_payload": {
                    "candidate_digest": candidate_digest,
                    "skill_id": skill.skill_id,
                    "output_authority": skill.output_authority,
                    "release_authority": "forbidden",
                },
                "domain_validation": {"valid": True, "errors": [], "warnings": []},
                "revision": 1,
                "created_at": created_at,
                "updated_at": created_at,
            },
        )
        artifact = ArtifactRef(
            artifact_id=artifact_id,
            artifact_type="ontology_migration_candidate",
            title=execution.definition.title,
            status="draft",
            url=(
                f"/agent?session={execution.session['session_id']}"
                f"&artifact={artifact_id}"
            ),
            preview=(
                f"{skill.skill_id} 후보 {candidate_digest}. "
                "DB 실행·attestation·Verdict·approval·Release 권한은 포함하지 않습니다."
            ),
            metadata={
                "capability_id": execution.definition.capability_id,
                "skill_id": skill.skill_id,
                "candidate_digest": candidate_digest,
                "output_authority": skill.output_authority,
                "release_authority": "forbidden",
                "production_changed": False,
                "revision": 1,
            },
        )
        return CapabilityHandlerResult(
            answer=AnswerBlock(
                summary=f"{execution.definition.title} 검토 후보를 준비했습니다.",
                markdown=(
                    "### Ontology migration 후보\n\n"
                    f"- Skill: `{skill.skill_id}`\n"
                    f"- Candidate digest: `{candidate_digest}`\n"
                    f"- Output authority: `{skill.output_authority}`\n"
                    "- DB 실행, attestation, Verdict, approval, Release, active pointer 변경: 금지\n\n"
                    "확인은 exact candidate digest에 대한 검토 기록만 남기며 Release하지 않습니다."
                ),
            ),
            artifacts=[artifact],
            plan_ref=plan_id,
            job_ref=job_id,
        )

    def _load_answer_protected_result(
        self, artifact_ref: str, principal: str, purpose: str
    ) -> dict[str, Any]:
        runtime = self.general_query_runtime
        gateway = getattr(runtime, "gateway", None)
        reader = getattr(gateway, "read_multi_result_artifact", None)
        if not callable(reader):
            raise AnswerDeliveryError("ANSWER_FULL_RESULT_LOADER_UNAVAILABLE")
        gateway_principal = (
            principal if principal.startswith("employee:") else f"employee:{principal}"
        )
        try:
            return reader(
                artifact_ref, principal=gateway_principal, purpose=purpose
            )
        except ValueError as error:
            raise AnswerDeliveryError(str(error)) from error

    @staticmethod
    def _artifact_structural_summary(record: GovernedAnswerArtifactRecord) -> str:
        artifact = record.artifact
        rows = sum(item.total_row_count for item in artifact.result_sets)
        return (
            f"{record.execution_classification} · {artifact.result_shape} · "
            f"{len(artifact.result_sets)} result set(s) · {rows} row(s)"
        )

    def _render_governed_answer_markdown(
        self, record: GovernedAnswerRecord | GovernedAnswerArtifactRecord
    ) -> str:
        """Render only the frozen answer envelope, never a Gateway ResultSet."""

        if isinstance(record, GovernedAnswerArtifactRecord):
            artifact = record.artifact
            sections = [self._artifact_structural_summary(record)]
            for result_set in artifact.result_sets:
                field_labels = ", ".join(
                    f"{item.label} (`{item.output_name}`: {item.value_type})"
                    for item in result_set.fields
                )
                sections.append(
                    f"### {result_set.result_set_id}\n\n"
                    f"- Shape: `{result_set.shape}`\n"
                    f"- Object: `{result_set.object_ref}`\n"
                    f"- Exact grain: `{', '.join(result_set.exact_grain)}`\n"
                    f"- Rows: `{result_set.total_row_count}`"
                    + (f" (preview `{result_set.preview_row_count}`)" if result_set.truncated else "")
                    + f"\n- Fields: {field_labels}\n"
                    f"- Result digest: `{result_set.result_digest}`"
                )
            if artifact.data_quality:
                sections.append(
                    "### Data quality\n\n"
                    + "\n".join(
                        (
                            f"- `{item.receipt_id}`: scanned={item.scanned_rows}, "
                            f"matched={item.matched_rows}, unmatched={item.unmatched_rows}, "
                            f"null_fk={item.null_fk_rows}, orphan={item.orphan_rows}, "
                            f"excluded={item.excluded_rows}, policy=`{item.applied_policy}`"
                        )
                        for item in artifact.data_quality
                    )
                )
            sections.append(
                "<details><summary>Evidence / Grounding / Execution</summary>\n\n"
                f"- Classification: `{record.execution_classification}`\n"
                f"- Execution: `{record.execution_id}`\n"
                f"- Execution receipt: `{artifact.execution.execution_receipt_digest}`\n"
                f"- Artifact: {record.api_url}\n\n</details>"
            )
            return "\n\n".join(sections)

        presentation = self.answer_delivery.presentation(record)
        sections = [str(presentation["direct_answer"])]
        for view in presentation["views"]:
            labels = [item["label"] for item in view["columns"]]
            preview_rows = min(int(view["preview_row_count"]), 20)

            def cell(value: object) -> str:
                return str(value if value is not None else "").replace(
                    "|", "\\|"
                ).replace("\n", " ")

            table_rows = [item["cells"] for item in view["rows"][:preview_rows]]
            table = "\n".join(
                [
                    "| " + " | ".join(labels) + " |",
                    "| " + " | ".join("---" for _ in labels) + " |",
                    *[
                        "| " + " | ".join(cell(value) for value in row) + " |"
                        for row in table_rows
                    ],
                ]
            )
            range_notice = (
                f"전체 {view['total_row_count']:,}건 중 1-{preview_rows:,}건 표시"
                if view["total_row_count"]
                else "결과 0건"
            )
            if view["total_row_count"] > preview_rows:
                range_notice += f" · 전체 결과: {view['rows_url'] or record.ui_url}"
            sections.append(
                f"### {view['display_name']}\n\n{range_notice}\n\n{table}"
            )
            for row in view["rows"][:preview_rows]:
                for collection_name, collection in row["collections"].items():
                    sections.append(
                        f"#### {collection_name}\n\n"
                        f"상위 객체별 {collection['count']:,}건"
                    )
        if presentation["quality_notices"]:
            sections.append(
                "### 데이터 품질 및 완전성\n\n"
                + "\n".join(
                    f"- {item['message']}" for item in presentation["quality_notices"]
                )
            )
        sections.append(
            "<details><summary>Evidence / Grounding / Execution</summary>\n\n"
            f"- Classification: `{record.execution_classification}`\n"
            f"- Execution: `{record.execution_id}`\n"
            f"- Delivery receipt: `{record.delivery_receipt.receipt_digest}`\n"
            f"- Answer: {record.ui_url}\n\n</details>"
        )
        return "\n\n".join(sections)

    def _publish_governed_query_answer(
        self,
        *,
        principal: Principal,
        purpose: str,
        idempotency_key: str,
        channel: str,
        outcome: object,
        question: str,
        request_digest: str = "",
    ) -> GovernedAnswerRecord | GovernedAnswerArtifactRecord:
        artifact = getattr(outcome, "governed_answer_artifact", None)
        if artifact is not None:
            question_digest = "sha256:" + self._contract_checksum(question)
            if artifact.question_digest != question_digest:
                raise AnswerDeliveryError("ANSWER_QUESTION_DIGEST_MISMATCH")
            if channel not in {"agent", "mcp", "rest", "cli"}:
                raise AnswerDeliveryError("ANSWER_INVOCATION_CHANNEL_INVALID")
            return self.answer_delivery.publish_artifact(
                principal=principal.employee_id,
                purpose=purpose,
                idempotency_key=idempotency_key,
                channel=channel,
                artifact=artifact,
                request_digest=request_digest,
            )
        context = getattr(outcome, "answer_delivery_context", None)
        query_execution = getattr(outcome, "execution", None)
        if query_execution is None:
            raise AnswerDeliveryError("ANSWER_EXECUTION_NOT_SUCCESSFUL")
        if not isinstance(context, GovernedQueryAnswerDeliveryContext):
            raise AnswerDeliveryError("ANSWER_DELIVERY_CONTEXT_REQUIRED")
        question_digest = "sha256:" + self._contract_checksum(question)
        if context.requirement.question_digest != question_digest:
            raise AnswerDeliveryError("ANSWER_QUESTION_DIGEST_MISMATCH")
        if channel not in {"agent", "ui", "mcp", "rest"}:
            raise AnswerDeliveryError("ANSWER_INVOCATION_CHANNEL_INVALID")
        return self.answer_delivery.publish_from_execution(
            principal=principal.employee_id,
            purpose=purpose,
            idempotency_key=idempotency_key,
            channel=channel,
            requirement=context.requirement,
            execution=query_execution,
            result_bindings=context.result_bindings,
            quality_measurements=context.quality_measurements,
            quality_evidence_digests=context.quality_evidence_digests,
            renderer_code_digest=context.renderer_code_digest,
            evaluator_code_digest=context.evaluator_code_digest,
            request_digest=request_digest,
        )

    def _handle_governed_query(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        """Run only registered or validated typed plans through the Gateway."""

        if self.general_query_runtime is None:
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="검증된 Query Gateway가 현재 연결되어 있지 않습니다.",
                    markdown="SQLite reference 또는 사내 Gateway capability가 VERIFIED가 된 뒤 다시 실행해주세요.",
                ),
            )
        parameters = execution.request.input_delta.get("parameters") or {}
        if not isinstance(parameters, dict):
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="질의 파라미터 형식을 확인할 수 없습니다.",
                    markdown="파라미터는 이름과 typed 값의 객체로 전달해주세요. SQL 본문은 받지 않습니다.",
                ),
            )
        outcome = self.general_query_runtime.handle(
            execution.request.question,
            principal=f"employee:{execution.principal.employee_id}",
            purpose=str(execution.request.input_delta.get("purpose") or "agent-data-query"),
            parameters=parameters,
            request_id=execution.run_id,
            team_ids=tuple(execution.principal.teams),
        )
        query_answerability = getattr(outcome, "answerability", None)
        if query_answerability is None:
            query_answerability = classify_query_answerability(
                executable=getattr(outcome, "execution", None) is not None,
                reason_codes=tuple(getattr(outcome, "reason_codes", ())),
                missing_dependency_ids=(),
                active_release_digest=str(
                    getattr(outcome, "active_release_digest", "")
                ),
                query_digest="sha256:"
                + self._contract_checksum(
                    {
                        "question": execution.request.question,
                        "parameters": parameters,
                        "principal": execution.principal.employee_id,
                        "purpose": str(
                            execution.request.input_delta.get("purpose")
                            or "agent-data-query"
                        ),
                    }
                ),
            )
        if outcome.route == "clarification_required":
            receipt = query_answerability
            receipt_details = (
                f"\n\n- Answerability: `{receipt.state}`"
                f"\n- Receipt: `{receipt.receipt_digest}`"
                if receipt is not None
                else ""
            )
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="결과가 달라지는 기준을 한 번만 확인해야 합니다.",
                    markdown=outcome.clarification + receipt_details,
                ),
            )
        if outcome.execution is None:
            reason_codes = tuple(getattr(outcome, "reason_codes", ()))
            reason_text = (
                " 차단 사유: " + ", ".join(f"`{code}`" for code in reason_codes)
                if reason_codes else ""
            )
            receipt = query_answerability
            artifacts: list[ArtifactRef] = []
            plan_ref = ""
            job_ref = ""
            receipt_text = ""
            if receipt is not None:
                receipt_text = (
                    f"\n\n- Answerability: `{receipt.state}`"
                    f"\n- Receipt: `{receipt.receipt_digest}`"
                )
                repair = receipt.repair_candidate
                if repair is not None:
                    artifact_id = new_id("artifact")
                    plan_ref = new_id("plan")
                    job_ref = new_id("migration")
                    created_at = now_iso()
                    repair_payload = repair.model_dump(mode="json")
                    stored_artifact = {
                        "artifact_id": artifact_id,
                        "employee_id": execution.principal.employee_id,
                        "capability_id": execution.definition.capability_id,
                        "artifact_type": "ontology_migration_candidate",
                        "status": "draft",
                        "title": "Query contract gap repair",
                        "draft": repair_payload,
                        "candidate_digest": repair.candidate_digest,
                        "answerability_receipt_digest": receipt.receipt_digest,
                        "approved": False,
                        "released": False,
                        "active": False,
                        "production_changed": False,
                        "revision": 1,
                        "created_at": created_at,
                        "updated_at": created_at,
                    }
                    self.store.put("artifacts", artifact_id, stored_artifact)
                    self.store.put(
                        "ontology_migration_jobs",
                        job_ref,
                        {
                            "job_id": job_ref,
                            "employee_id": execution.principal.employee_id,
                            "capability_id": execution.definition.capability_id,
                            "skill_id": "query-contract-author",
                            "state": "captured",
                            "candidate_digest": repair.candidate_digest,
                            "source_manifest_digest": receipt.receipt_digest,
                            "artifact_id": artifact_id,
                            "plan_id": plan_ref,
                            "answerability_receipt_digest": receipt.receipt_digest,
                            "approved": False,
                            "released": False,
                            "active_transition": False,
                            "production_changed": False,
                            "revision": 1,
                            "created_at": created_at,
                            "updated_at": created_at,
                        },
                    )
                    self.store.put(
                        "plans",
                        plan_ref,
                        {
                            "plan_id": plan_ref,
                            "employee_id": execution.principal.employee_id,
                            "capability_id": execution.definition.capability_id,
                            "operation": "draft",
                            "artifact_id": artifact_id,
                            "status": "draft",
                            "risk": execution.definition.risk.value,
                            "production_changed": False,
                            "work_run_id": str(execution.work_run["work_run_id"]),
                            "domain_operation": "",
                            "domain_payload": {
                                "candidate_digest": repair.candidate_digest,
                                "answerability_receipt_digest": receipt.receipt_digest,
                                "missing_dependency_ids": list(
                                    repair.missing_dependency_ids
                                ),
                                "workbench_route": repair.workbench_route,
                                "release_authority": "forbidden",
                            },
                            "domain_validation": {
                                "valid": True,
                                "errors": [],
                                "warnings": [],
                            },
                            "revision": 1,
                            "created_at": created_at,
                            "updated_at": created_at,
                        },
                    )
                    artifacts.append(
                        ArtifactRef(
                            artifact_id=artifact_id,
                            artifact_type="ontology_migration_candidate",
                            title="Query contract gap repair",
                            status="draft",
                            url=repair.workbench_route,
                            preview=(
                                "Candidate-only contract repair; approval, Release, "
                                "and active transition are forbidden."
                            ),
                            metadata={
                                "candidate_digest": repair.candidate_digest,
                                "answerability_receipt_digest": receipt.receipt_digest,
                                "missing_dependency_ids": list(
                                    repair.missing_dependency_ids
                                ),
                                "workbench_route": repair.workbench_route,
                                "approved": False,
                                "released": False,
                                "active": False,
                                "production_changed": False,
                            },
                        )
                    )
                    receipt_text += (
                        "\n- Missing dependencies: `"
                        + "`, `".join(repair.missing_dependency_ids)
                        + "`"
                        f"\n- Workbench: `{repair.workbench_route}`"
                        f"\n- Repair candidate: `{repair.candidate_digest}`"
                        "\n- Authority: candidate-only; approval, Release, active 전환 금지"
                    )
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="안전하게 실행할 수 있는 데이터 질의 계획을 만들지 못했습니다.",
                    markdown=(
                        f"상태: `{outcome.route}`. raw SQL로 우회하지 않습니다. "
                        "조회 대상, grain, 기간 또는 기준을 구체적으로 지정해주세요."
                        f"{reason_text}"
                        f"{receipt_text}"
                    ),
                ),
                artifacts=artifacts,
                plan_ref=plan_ref,
                job_ref=job_ref,
            )

        purpose = str(
            execution.request.input_delta.get("purpose") or "agent-data-query"
        )
        try:
            answer_record = self._publish_governed_query_answer(
                principal=execution.principal,
                purpose=purpose,
                idempotency_key=f"agent:{execution.run_id}",
                channel="agent",
                outcome=outcome,
                question=execution.request.question,
                request_digest="sha256:"
                + self._contract_checksum(
                    {
                        "question": execution.request.question,
                        "parameters": parameters,
                        "purpose": purpose,
                    }
                ),
            )
        except AnswerDeliveryError as error:
            return CapabilityHandlerResult(
                status="needs_input",
                answer=AnswerBlock(
                    summary="실행 결과를 검증 가능한 답변으로 안전하게 구성하지 못했습니다.",
                    markdown=(
                        f"차단 사유: `{error}`. Gateway ResultSet을 직접 표시하거나 "
                        "prepared answer 참조로 우회하지 않습니다."
                    ),
                ),
            )

        artifact_id = new_id("artifact")
        plan_id = new_id("plan")
        created_at = now_iso()
        if isinstance(answer_record, GovernedAnswerArtifactRecord):
            direct_summary = self._artifact_structural_summary(answer_record)
            delivery_receipt_digest = (
                answer_record.artifact.execution.execution_receipt_digest
            )
            answer_url = answer_record.api_url
        else:
            direct_summary = answer_record.envelope.direct_answer
            delivery_receipt_digest = answer_record.delivery_receipt.receipt_digest
            answer_url = answer_record.ui_url
        artifact_payload = {
            "artifact_id": artifact_id,
            "employee_id": execution.principal.employee_id,
            "capability_id": execution.definition.capability_id,
            "artifact_type": "governed_query_result",
            "status": (
                "reviewed"
                if answer_record.execution_classification == "ATTESTED"
                else "provisional"
            ),
            "title": execution.definition.title,
            "answer_id": answer_record.answer_id,
            "answer_semantic_digest": answer_record.answer_semantic_digest,
            "answer_record_digest": answer_record.record_digest,
            "delivery_receipt_digest": delivery_receipt_digest,
            "execution_id": answer_record.execution_id,
            "result_status": answer_record.execution_classification,
            "route": outcome.route,
            "plan_digest": outcome.plan_digest,
            "query_answerability": query_answerability.model_dump(mode="json"),
            "answer_url": answer_url,
            "production_changed": False,
            "created_at": created_at,
            "updated_at": created_at,
        }
        self.store.put("artifacts", artifact_id, artifact_payload)
        self.store.put(
            "plans",
            plan_id,
            {
                "plan_id": plan_id,
                "employee_id": execution.principal.employee_id,
                "capability_id": execution.definition.capability_id,
                "operation": "read",
                "artifact_id": artifact_id,
                "status": "completed",
                "risk": execution.definition.risk.value,
                "production_changed": False,
                "work_run_id": str(execution.work_run["work_run_id"]),
                "domain_operation": "",
                "domain_payload": {
                    "answer_id": answer_record.answer_id,
                    "answer_semantic_digest": answer_record.answer_semantic_digest,
                    "execution_id": answer_record.execution_id,
                    "logical_plan_digest": outcome.plan_digest,
                    "answerability_receipt_digest": query_answerability.receipt_digest,
                    "release_authority": "forbidden",
                },
                "domain_validation": {"valid": True, "errors": [], "warnings": []},
                "revision": 1,
                "created_at": created_at,
                "updated_at": created_at,
            },
        )
        artifact = ArtifactRef(
            artifact_id=artifact_id,
            artifact_type="governed_query_result",
            title=execution.definition.title,
            status=artifact_payload["status"],
            url=answer_url,
            preview=(
                f"{direct_summary} "
                f"({answer_record.execution_classification})"
            ),
            metadata={
                "answer_id": answer_record.answer_id,
                "answer_semantic_digest": answer_record.answer_semantic_digest,
                "answer_record_digest": answer_record.record_digest,
                "delivery_receipt_digest": delivery_receipt_digest,
                "execution_id": answer_record.execution_id,
                "result_status": answer_record.execution_classification,
                "route": outcome.route,
                "plan_digest": outcome.plan_digest,
                "answerability_state": query_answerability.state,
                "answerability_receipt_digest": query_answerability.receipt_digest,
                "production_changed": False,
            },
        )
        return CapabilityHandlerResult(
            answer=AnswerBlock(
                summary=direct_summary,
                markdown=self._render_governed_answer_markdown(answer_record),
            ),
            artifacts=[artifact],
            answerability=AnswerabilityReport(
                status=(
                    "partial"
                    if answer_record.execution_classification == "PROVISIONAL"
                    else "grounded"
                ),
                answer_intent="fact",
                supported_claim_count=1,
            ),
            plan_ref=plan_id,
        )

    def _handle_task_runtime(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        context = execution.work_context
        completion_checks = [
            item.label
            for item in (context.completion_design.checks if context.completion_design else [])
        ] or list(context.exit_criteria)
        completion_evidence = [
            item.label
            for item in (context.completion_design.evidence if context.completion_design else [])
            if item.required
        ] or list(context.required_evidence)
        task_title = (
            context.goal_anchor.title
            if context.goal_anchor and context.goal_anchor.title not in {"", "진행 중 Task"}
            else execution.request.task_ref or "현재 Task"
        )
        if execution.intent.operation == WorkOperation.complete:
            supplied_evidence = list(
                dict.fromkeys(
                    str(item).strip()
                    for item in execution.request.input_delta.get("completion_evidence") or []
                    if str(item).strip()
                )
            )
            required_evidence_items = [
                item
                for item in (
                    execution.work_context.completion_design.evidence
                    if execution.work_context.completion_design
                    else []
                )
                if item.required
            ]
            requirement_keys: dict[str, list[str]] = {}
            for item in required_evidence_items:
                for key in (item.evidence_id, item.label, item.ref):
                    clean_key = str(key or "").strip()
                    if clean_key:
                        requirement_keys.setdefault(clean_key, []).append(item.evidence_id)
            raw_links = execution.request.input_delta.get("completion_evidence_links")
            evidence_links: dict[str, list[str]] = {}
            link_errors: list[str] = []
            if isinstance(raw_links, dict):
                for raw_requirement, raw_refs in raw_links.items():
                    requirement = str(raw_requirement or "").strip()
                    matches = list(dict.fromkeys(requirement_keys.get(requirement) or []))
                    if len(matches) != 1:
                        link_errors.append(
                            f"'{requirement}' 확인 자료 항목을 하나로 확정하지 못했습니다."
                        )
                        continue
                    values = raw_refs if isinstance(raw_refs, list) else [raw_refs]
                    refs = list(
                        dict.fromkeys(
                            str(item).strip()
                            for item in values
                            if str(item).strip()
                        )
                    )
                    inaccessible = [
                        ref for ref in refs if self._record_for_ref(execution.principal, ref) is None
                    ]
                    if inaccessible:
                        link_errors.append(
                            f"'{requirement}'에 연결한 근거를 읽거나 검증할 수 없습니다: "
                            + ", ".join(inaccessible)
                        )
                        continue
                    evidence_links[matches[0]] = refs
                    supplied_evidence.extend(ref for ref in refs if ref not in supplied_evidence)
            if link_errors:
                return CapabilityHandlerResult(
                    status="needs_input",
                    answer=AnswerBlock(
                        summary="Task 완료 근거 연결을 확인해야 합니다.",
                        markdown="### 완료 근거 연결 확인\n\n"
                        + "\n".join(f"- {item}" for item in link_errors),
                    ),
                )
            satisfied_evidence_ids = list(evidence_links)
            if not evidence_links:
                supplied_set = set(supplied_evidence)
                satisfied_evidence_ids = [
                    item.evidence_id
                    for item in required_evidence_items
                    if item.evidence_id in supplied_set
                    or (item.ref and item.ref in supplied_set)
                ]
            lines = [
                f"'{task_title}'의 완료 여부는 담당자 또는 연결된 시스템의 확인이 있어야 확정됩니다.",
                "",
                "### 완료된 모습",
                *([f"- {item}" for item in completion_checks] or ["- 이 Task의 완료된 모습을 먼저 정해주세요."]),
                "",
                "### 확인할 자료",
                *([f"- {item}" for item in completion_evidence] or ["- 확인할 자료를 먼저 정해주세요."]),
                "",
                (
                    "직접 확인한 내용과 판단 기록을 남기면 같은 업무에서 완료 여부를 다시 평가합니다."
                    if context.task_mode in {TaskMode.manual, TaskMode.copilot}
                    else "연결된 Event·Action·데이터 결과가 확인될 때만 자동 완료됩니다."
                ),
            ]
            plan_id = new_id("plan")
            idempotency_key = str(
                execution.request.input_delta.get("idempotency_key")
                or f"task-complete:{execution.work_run['work_run_id']}"
            )
            evidence_ready = bool(supplied_evidence)
            self.store.put(
                "plans",
                plan_id,
                {
                    "plan_id": plan_id,
                    "employee_id": execution.principal.employee_id,
                    "capability_id": execution.definition.capability_id,
                    "operation": WorkOperation.complete.value,
                    "target_ref": execution.request.task_ref,
                    "status": "draft",
                    "risk": execution.intent.risk.value,
                    "production_changed": False,
                    "work_run_id": execution.work_run["work_run_id"],
                    "domain_operation": "task.complete",
                    "domain_payload": {
                        "task_ref": execution.request.task_ref,
                        "evidence_refs": supplied_evidence,
                        "evidence_links": evidence_links,
                        "satisfied_evidence_ids": satisfied_evidence_ids,
                        "idempotency_key": idempotency_key,
                    },
                    "domain_validation": {
                        "valid": evidence_ready,
                        "errors": [] if evidence_ready else ["Task completion requires verified evidence refs"],
                        "warnings": [],
                    },
                    "created_at": now_iso(),
                    "updated_at": now_iso(),
                },
            )
            return CapabilityHandlerResult(
                answer=AnswerBlock(
                    summary=(
                        f"'{task_title}' 완료 확인 계획을 준비했습니다."
                        if evidence_ready
                        else f"'{task_title}' 완료 계획에서 필수 근거가 비어 있음을 확인했습니다."
                    ),
                    markdown=(
                        "### 완료 확인 미리보기\n\n"
                        + "\n".join(lines)
                        + (
                            "\n\n아직 Task를 완료 처리하지 않았습니다. 연결할 근거와 완료된 모습을 확인한 뒤 별도로 승인해주세요."
                            if evidence_ready
                            else "\n\n필수 근거가 없어 이 계획은 실행할 수 없습니다. 누락 상태를 검토할 수 있도록 미리보기만 보존했습니다."
                        )
                    ),
                ),
                plan_ref=plan_id,
            )
        return CapabilityHandlerResult(
            **self._task_runtime_read_result(
                execution,
                task_title=task_title,
                completion_checks=completion_checks,
                completion_evidence=completion_evidence,
            )
        )

    def _task_runtime_read_result(
        self,
        execution: CapabilityHandlerContext,
        *,
        task_title: str,
        completion_checks: list[str],
        completion_evidence: list[str],
    ) -> dict[str, Any]:
        """Ground Task design separately from an unverified live checkpoint."""

        context = execution.work_context
        source_refs = list(
            dict.fromkeys(
                ref
                for ref in [
                    context.workflow_ref,
                    context.surface_context.get("document_ref", ""),
                    context.page_anchor.ref if context.page_anchor else "",
                ]
                if str(ref).strip()
            )
        )
        source_evidence: list[EvidenceRef] = []
        for source_ref in source_refs:
            record = self._record_for_ref(execution.principal, source_ref)
            if record is None:
                continue
            source_evidence.append(self._evidence_from_record(record, score=1.0))
        citations = self._citations_for_evidence(
            execution.principal,
            str(execution.session.get("session_id") or ""),
            execution.request.question,
            source_evidence,
        )
        source_markers = [
            f"- [{citation.title}](/api/v2/citations/{citation.citation_id})"
            for citation in citations
        ]
        supported_claims = [
            GroundedClaim(
                claim_id=f"task-contract-source-{index}",
                text=compact_text(citation.excerpt, 1_200),
                claim_kind="work",
                source_scope=(
                    self.repository.answer_scope(record)
                    if (record := self._record_for_ref(execution.principal, citation.source_ref))
                    is not None
                    else "canonical"
                ),
                source_refs=[citation.source_ref],
                supporting_chunk_ids=[citation.chunk_id],
                support_status="supported",
                confidence=1.0,
                required_for_answer=False,
            )
            for index, citation in enumerate(citations, start=1)
            if citation.chunk_id and citation.excerpt.strip()
        ]
        unsupported_checkpoint = GroundedClaim(
            claim_id="task-live-checkpoint-unverified",
            text="연결된 운영 기록에서 이 Task의 실제 진행 checkpoint는 확인되지 않았습니다.",
            claim_kind="work",
            source_scope="operational",
            source_refs=[],
            supporting_chunk_ids=[],
            support_status="unsupported",
            confidence=1.0,
            required_for_answer=True,
        )
        markdown_lines = [
            f"### {task_title}",
            "- 실제 진행 checkpoint: 연결된 운영 기록에서 확인되지 않았습니다.",
            f"- 수행 방식: {context.task_mode.value}",
            *[f"- 완료된 모습: {item}" for item in completion_checks],
            *[f"- 확인할 자료: {item}" for item in completion_evidence],
        ]
        if source_markers:
            markdown_lines.extend(["", "### Task 정의 근거", *source_markers])
        markdown_lines.extend(
            [
                "",
                "### 확인하지 못한 내용",
                f"- {unsupported_checkpoint.text} — 실제 WorkRun 근거가 연결되기 전에는 현재 진행 상태로 확정하지 않습니다.",
            ]
        )
        return {
            "answer": AnswerBlock(
                summary=(
                    f"'{task_title}'의 완료 설계는 확인했지만 실제 진행 checkpoint는 확인되지 않았습니다."
                ),
                markdown="\n".join(markdown_lines),
            ),
            "grounded_claims": [*supported_claims, unsupported_checkpoint],
            "used_source_refs": [item.source_ref for item in citations],
            "citations": citations,
            "evidence": source_evidence,
            "answerability": AnswerabilityReport(
                status="partial" if supported_claims else "insufficient",
                answer_intent="work",
                supported_claim_count=len(supported_claims),
                unsupported_claim_count=1,
                missing_evidence=[unsupported_checkpoint.text],
            ),
            "claim_grounded_response": bool(supported_claims),
        }

    def _handle_current_work(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        source_refs = {item.evidence_id for item in execution.current_work_evidence}
        citations = [
            item
            for item in execution.citations
            if item.source_ref in source_refs and item.chunk_id
        ]
        evidence_by_ref = {
            item.evidence_id: item for item in execution.current_work_evidence
        }
        displayed_evidence = [
            evidence_by_ref[item.source_ref]
            for item in citations
            if item.source_ref in evidence_by_ref
        ]
        claims = [
            GroundedClaim(
                claim_id=f"current-work-{index}",
                # Grounding metadata carries the exact displayed citation
                # statement.  The compact Inbox title remains presentation,
                # while the claim itself is directly bound to its chunk.
                text=compact_text(item.excerpt, 1200),
                claim_kind="work",
                source_scope="operational",
                source_refs=[item.source_ref],
                supporting_chunk_ids=[item.chunk_id],
                support_status="supported",
                confidence=1.0,
                required_for_answer=True,
            )
            for index, item in enumerate(citations, start=1)
            if item.chunk_id and item.source_ref in evidence_by_ref
        ]
        return CapabilityHandlerResult(
            answer=self._inbox_answer(displayed_evidence),
            grounded_claims=claims,
            used_source_refs=[item.source_ref for item in citations],
            citations=citations,
            evidence=displayed_evidence,
            answerability=AnswerabilityReport(
                status="grounded" if claims else "insufficient",
                answer_intent="work",
                supported_claim_count=len(claims),
                missing_evidence=[] if claims else ["현재 업무 projection을 뒷받침하는 기록이 없습니다."],
            ),
            claim_grounded_response=bool(claims),
        )

    def _attach_private_learning_lineage(
        self,
        principal: Principal,
        *,
        answer: AnswerBlock,
        claims: list[GroundedClaim],
        used_source_refs: set[str],
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
        answer_intent: str,
        session_id: str = "",
        query: str = "",
        subject_refs: set[str] | None = None,
    ) -> tuple[AnswerBlock, list[GroundedClaim], set[str]]:
        """Expose a visible private candidate when it derives from a used source.

        Search may correctly select the original CompletionRecord as the most
        authoritative statement while also finding an ACL-visible private
        KnowledgeCandidate derived from it.  The candidate is reusable Second
        Brain evidence only when it is actually shown and cited, so project one
        exact candidate statement through its stored lineage instead of merely
        returning it as an unused search result.
        """

        resolved_subject_refs = {
            str(item).strip()
            for item in subject_refs or set()
            if str(item).strip()
        }
        if not used_source_refs and not resolved_subject_refs:
            return answer, claims, used_source_refs
        preferred_candidate_ids = self._ensure_private_learning_lineage_sources(
            principal,
            used_source_refs=used_source_refs,
            evidence=evidence,
            citations=citations,
            session_id=session_id,
            query=query,
            subject_refs=resolved_subject_refs,
        )
        preferred_order = {
            candidate_id: index
            for index, candidate_id in enumerate(preferred_candidate_ids)
        }
        citation_by_ref = {
            item.source_ref: item
            for item in citations
            if item.source_ref and item.chunk_id
        }
        # Retrieval may already have selected the newest verified private
        # candidate.  In that case its exact citation is sufficient lineage;
        # projecting a second, older candidate for the same subject would bind
        # the current answer to stale reusable knowledge.
        if any(
            candidate_id in used_source_refs and candidate_id in citation_by_ref
            for candidate_id in preferred_candidate_ids
        ):
            return answer, claims, used_source_refs
        ordered_evidence = sorted(
            evidence,
            key=lambda item: (
                preferred_order.get(item.evidence_id, len(preferred_order)),
                item.evidence_id,
            ),
        )
        for item in ordered_evidence:
            if item.kind != "knowledge_candidate" or item.evidence_id in used_source_refs:
                continue
            citation = citation_by_ref.get(item.evidence_id)
            if citation is None:
                continue
            record = self._record_for_ref(principal, item.evidence_id)
            if record is None or record.source != "knowledge_candidate":
                continue
            lineage_refs = {
                str(ref)
                for ref in record.metadata.get("source_refs") or []
                if str(ref).strip()
            }
            candidate_row = self.store.get("knowledge_candidates", item.evidence_id) or {}
            candidate_subject_refs = {
                str(candidate_row.get("source_task_ref") or "").strip(),
                str(candidate_row.get("target_asset_ref") or "").strip(),
            } - {""}
            subject_match = bool(
                candidate_subject_refs.intersection(resolved_subject_refs)
                and item.evidence_id in preferred_order
            )
            source_validation = (
                candidate_row.get("source_validation")
                if isinstance(candidate_row.get("source_validation"), dict)
                else {}
            )
            verified_lineage_refs = {
                str(ref)
                for ref in source_validation.get("verified_refs") or []
                if str(ref).strip()
            }
            verified_anchor_match = bool(
                verified_lineage_refs.intersection(
                    {*used_source_refs, *resolved_subject_refs}
                )
                and item.evidence_id in preferred_order
            )
            if (
                not lineage_refs.intersection(used_source_refs)
                and not subject_match
                and not verified_anchor_match
            ):
                continue
            statements = self._atomic_source_statements(
                citation.excerpt or record.text or item.summary
            )
            statement = (
                statements[0]
                if statements
                else compact_text(citation.excerpt or record.text or item.summary, 1200)
            )
            if not statement:
                continue
            projected_claim = GroundedClaim(
                claim_id=f"private-learning-reuse-{item.evidence_id}",
                text=statement,
                claim_kind=answer_intent,  # type: ignore[arg-type]
                source_scope="operational",
                source_refs=[item.evidence_id],
                supporting_chunk_ids=[citation.chunk_id],
                support_status="supported",
                confidence=1.0,
                required_for_answer=False,
            )
            marker = f"/api/v2/citations/{citation.citation_id}"
            projected_answer = answer.model_copy(
                update={
                    "markdown": (
                        "### 저장된 private provisional 지식\n\n"
                        f"- {statement} [저장된 지식 근거]({marker})\n\n"
                        f"{answer.markdown}"
                    )
                }
            )
            return (
                projected_answer,
                [*claims, projected_claim],
                {*used_source_refs, item.evidence_id},
            )
        return answer, claims, used_source_refs

    def _ensure_private_learning_lineage_sources(
        self,
        principal: Principal,
        *,
        used_source_refs: set[str],
        evidence: list[EvidenceRef],
        citations: list[CitationRef],
        session_id: str,
        query: str,
        subject_refs: set[str] | None = None,
    ) -> list[str]:
        """Materialize verified, ACL-visible Second Brain lineage evidence.

        The authoritative source remains the displayed CompletionRecord (or
        other verified source). This bounded expansion only adds an owner's
        active private candidate when its validation ledger names an actually
        used source. It neither broadens retrieval nor promotes an arbitrary
        provisional note to authoritative evidence.
        """

        resolved_subject_refs = {
            str(item).strip()
            for item in subject_refs or set()
            if str(item).strip()
        }
        if not used_source_refs and not resolved_subject_refs:
            return []
        known_evidence = {item.evidence_id for item in evidence}
        known_citations = {item.source_ref for item in citations}
        query_tokens = meaningful_query_tokens(query)
        ranked_candidates: list[
            tuple[bool, int, str, bool, str, dict[str, Any]]
        ] = []
        for candidate in self.store.list(
            "knowledge_candidates",
            employee_id=principal.employee_id,
            limit=500,
        ):
            candidate_id = str(candidate.get("candidate_id") or "")
            if (
                not candidate_id
                or candidate.get("visibility") != "private"
                or candidate.get("status")
                not in {"provisional", "reviewed", "promotion_requested"}
            ):
                continue
            source_validation = (
                candidate.get("source_validation")
                if isinstance(candidate.get("source_validation"), dict)
                else {}
            )
            verified_refs = {
                str(ref)
                for ref in source_validation.get("verified_refs") or []
                if str(ref).strip()
            }
            if not verified_refs:
                continue
            candidate_subject_refs = {
                str(candidate.get("source_task_ref") or "").strip(),
                str(candidate.get("target_asset_ref") or "").strip(),
            } - {""}
            subject_match = bool(
                candidate_subject_refs.intersection(resolved_subject_refs)
            )
            lineage_match = bool(
                verified_refs.intersection(
                    {*used_source_refs, *resolved_subject_refs}
                )
            )
            if not subject_match and not lineage_match:
                continue
            candidate_tokens = meaningful_query_tokens(
                " ".join(
                    str(candidate.get(field) or "")
                    for field in ("title", "summary", "reusable_lesson")
                )
            )
            ranked_candidates.append(
                (
                    subject_match,
                    len(query_tokens.intersection(candidate_tokens)),
                    str(candidate.get("updated_at") or candidate.get("created_at") or ""),
                    lineage_match,
                    candidate_id,
                    candidate,
                )
            )
        preferred_candidate_ids: list[str] = []
        for (
            _subject_match,
            _query_overlap,
            _updated_at,
            _lineage_match,
            candidate_id,
            _candidate,
        ) in sorted(
            ranked_candidates,
            key=lambda item: item[:5],
            reverse=True,
        )[:3]:
            preferred_candidate_ids.append(candidate_id)
            record = self._record_for_ref(principal, candidate_id)
            if record is None or record.source != "knowledge_candidate":
                continue
            if candidate_id not in known_evidence:
                candidate_evidence = self._evidence_from_record(record, score=1.0)
                evidence.append(candidate_evidence)
                known_evidence.add(candidate_id)
            if candidate_id not in known_citations:
                candidate_evidence = next(
                    item for item in evidence if item.evidence_id == candidate_id
                )
                projected_citations = self._citations_for_evidence(
                    principal,
                    session_id,
                    query or record.title,
                    [candidate_evidence],
                )
                citations.extend(projected_citations)
                known_citations.update(
                    item.source_ref for item in projected_citations
                )
            if candidate_id in used_source_refs:
                break
        return preferred_candidate_ids

    @staticmethod
    def _private_learning_subject_refs(intent: WorkIntent) -> set[str]:
        return {
            str(item).strip()
            for item in [
                intent.primary_topic_entity,
                intent.topic_subject,
                intent.target_ref,
                *intent.topic_entities,
                *intent.context_refs,
            ]
            if str(item).strip()
        }

    @staticmethod
    def _final_answer_fallback_scope(
        answer_context_manifest: Any,
        citations: list[CitationRef],
    ) -> set[str]:
        """Reuse a preliminary answer scope only when it still names final evidence.

        The planner-side answer context is selected before the catalog-compiled
        evidence policy is applied. A valid plan may therefore switch from a
        broad preliminary source set to a narrower operational or validation
        set. Treating the now-stale preliminary refs as a hard fallback filter
        would hide the final ACL-checked evidence and incorrectly return
        ``no_evidence``. An empty result deliberately means "use the final
        citation set", never "reuse the preliminary source set".
        """

        if not isinstance(answer_context_manifest, dict):
            return set()
        declared = {
            str(item)
            for item in answer_context_manifest.get("selected_hint_refs") or []
            if str(item).strip()
        }
        available = {
            str(item.source_ref)
            for item in citations
            if str(item.source_ref).strip()
        }
        return declared & available

    def _apply_grounded_output_contract(
        self,
        execution: CapabilityHandlerContext,
        result: CapabilityHandlerResult,
    ) -> CapabilityHandlerResult:
        """Compile catalog-declared domain output semantics after grounding.

        The SemanticPlan decides the operation. The Catalog then selects a
        typed output contract for that operation; neither the request wording
        nor a capability/scenario branch is interpreted here. Compilers may
        only consume the already ACL- and evidence-policy-checked handler
        context and therefore cannot broaden retrieval or add a model call.
        """

        raw_contracts = execution.definition.handler_config.get(
            "grounded_output_contracts"
        )
        contracts = raw_contracts if isinstance(raw_contracts, dict) else {}
        operation = (
            execution.intent.operation.value
            if isinstance(execution.intent.operation, WorkOperation)
            else str(execution.intent.operation or "")
        )
        contract_id = str(contracts.get(operation) or "").strip()
        if not contract_id:
            return result
        compiler = self._grounded_output_contracts.get(contract_id)
        if compiler is None:
            raise RuntimeError(f"unknown grounded output contract: {contract_id}")
        return compiler(execution, result)

    def _compile_case_comparison_output(
        self,
        execution: CapabilityHandlerContext,
        result: CapabilityHandlerResult,
    ) -> CapabilityHandlerResult:
        """Project verified case evidence into difference/applicability bounds.

        This is a deterministic domain adapter. It does not infer that an old
        case applies to the current work. Instead it exposes (1) the recorded
        difference, (2) the reusable comparison point, and (3) the explicit
        application boundary, each bound to exact source/chunk citations.
        """

        if result.status != "completed":
            return result

        allowed_kinds = {
            str(item)
            for item in execution.definition.handler_config.get("kinds") or []
            if str(item).strip()
        }
        allowed_statuses = {
            str(item)
            for item in execution.intent.evidence_statuses
            if str(item).strip()
        }
        evidence_by_ref = {
            item.evidence_id: item
            for item in execution.evidence
            if item.evidence_id
        }
        selected: list[tuple[CitationRef, EvidenceRef, Any]] = []
        seen_refs: set[str] = set()
        try:
            source_limit = max(
                1,
                min(
                    int(
                        execution.definition.handler_config.get(
                            "max_presentation_sources"
                        )
                        or 2
                    ),
                    4,
                ),
            )
        except (TypeError, ValueError):
            source_limit = 2
        # Two cases are enough to expose a concrete contrast; retaining more
        # would make the visible claim/citation contract noisy while the full
        # retrieval remains available in the ContextManifest.
        source_limit = min(source_limit, 2)
        for citation in execution.citations:
            source_ref = str(citation.source_ref or "").strip()
            if (
                not source_ref
                or source_ref in seen_refs
                or not citation.chunk_id
                or not citation.excerpt.strip()
            ):
                continue
            evidence_item = evidence_by_ref.get(source_ref)
            if evidence_item is None or (
                allowed_kinds and evidence_item.kind not in allowed_kinds
            ):
                continue
            record = self._record_for_ref(execution.principal, source_ref)
            if record is None:
                continue
            if allowed_statuses and str(record.status or "") not in allowed_statuses:
                continue
            selected.append((citation, evidence_item, record))
            seen_refs.add(source_ref)
            if len(selected) >= source_limit:
                break

        # A typed claim must never be manufactured when no eligible case
        # citation survived the common evidence policy. Preserve the original
        # partial/no-evidence response so the Golden contract correctly fails.
        if not selected:
            return result

        def source_scope(record: Any) -> str:
            scope = str(self.repository.answer_scope(record) or "")
            return (
                scope
                if scope in {"canonical", "operational", "validation"}
                else "operational"
            )

        def source_statement(citation: CitationRef) -> str:
            statements = self._atomic_source_statements(citation.excerpt)
            return compact_text(
                statements[0] if statements else citation.excerpt,
                260,
            )

        first_citation, first_evidence, first_record = selected[0]
        first_statement = source_statement(first_citation)
        comparison_target = compact_text(
            execution.intent.topic_subject
            or execution.intent.resolved_goal
            or execution.request.question,
            140,
        )
        if len(selected) > 1:
            second_citation, second_evidence, _ = selected[1]
            second_statement = source_statement(second_citation)
            difference_text = (
                "확인된 사례의 기록 범위가 다릅니다. "
                f"'{first_evidence.title}'에는 '{first_statement}'가, "
                f"'{second_evidence.title}'에는 '{second_statement}'가 기록되어 있습니다."
            )
            difference_refs = [first_citation.source_ref, second_citation.source_ref]
            difference_chunks = [first_citation.chunk_id, second_citation.chunk_id]
        else:
            difference_text = (
                f"현재 비교 기준은 '{comparison_target}'이고, 확인된 완료 사례의 기록 범위는 "
                f"'{first_evidence.title}: {first_statement}'입니다."
            )
            difference_refs = [first_citation.source_ref]
            difference_chunks = [first_citation.chunk_id]

        applicability_text = (
            f"적용 후보는 '{first_statement}'에 기록된 확인·조치 결과이며, "
            "현재 업무의 입력과 완료 조건을 대조하는 근거로 재사용할 수 있습니다."
        )
        limit_text = (
            f"이 근거가 직접 증명하는 범위는 '{first_evidence.title}' 사례의 기록입니다. "
            "현재 업무에 그대로 적용하려면 입력, 완료 조건, 필수 근거의 일치를 별도로 검증해야 합니다."
        )
        claims = [
            GroundedClaim(
                claim_id="case-comparison-difference",
                text=difference_text,
                claim_kind="case_difference",
                source_scope=source_scope(first_record),
                source_refs=difference_refs,
                supporting_chunk_ids=difference_chunks,
                support_status="supported",
                confidence=1.0,
                required_for_answer=True,
            ),
            GroundedClaim(
                claim_id="case-comparison-applicability",
                text=applicability_text,
                claim_kind="case_applicability",
                source_scope=source_scope(first_record),
                source_refs=[first_citation.source_ref],
                supporting_chunk_ids=[first_citation.chunk_id],
                support_status="supported",
                confidence=1.0,
                required_for_answer=True,
            ),
            GroundedClaim(
                claim_id="case-comparison-limit",
                text=limit_text,
                claim_kind="application_limit",
                source_scope=source_scope(first_record),
                source_refs=[first_citation.source_ref],
                supporting_chunk_ids=[first_citation.chunk_id],
                support_status="supported",
                confidence=1.0,
                required_for_answer=True,
            ),
        ]
        selected_citations = [item[0] for item in selected]
        number_by_ref = {
            citation.source_ref: index
            for index, citation in enumerate(selected_citations, start=1)
        }

        def markers(refs: list[str]) -> str:
            return " ".join(
                f"[{number_by_ref[ref]}](/api/v2/citations/{citation.citation_id})"
                for ref in refs
                for citation in selected_citations
                if citation.source_ref == ref
            )

        answer = AnswerBlock(
            summary=(
                f"확인된 완료 사례 {len(selected)}개는 현재 요청에 참고할 수 있지만, "
                "동일 적용 전 입력·완료 조건 검증이 필요합니다."
            ),
            markdown="\n\n".join(
                [
                    "### 사례 차이\n"
                    f"- {difference_text} {markers(difference_refs)}",
                    "### 적용 가능성\n"
                    f"- {applicability_text} {markers([first_citation.source_ref])}",
                    "### 적용 한계\n"
                    f"- {limit_text} {markers([first_citation.source_ref])}",
                ]
            ),
        )
        selected_refs = [citation.source_ref for citation in selected_citations]
        return replace(
            result,
            answer=answer,
            related_questions=[],
            grounded_claims=claims,
            used_source_refs=selected_refs,
            answerability=AnswerabilityReport(
                status="grounded",
                answer_intent="comparison",
                supported_claim_count=len(claims),
            ),
            citations=selected_citations,
            evidence=[evidence_by_ref[ref] for ref in selected_refs],
            claim_grounded_response=True,
        )

    def _handle_grounded_read(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        empty_summary = str(
            execution.definition.handler_config.get("empty_summary")
            or "확인된 근거가 없습니다."
        )
        helper_guidance = "\n".join(
            [
                str(execution.request.input_delta.get("_helper_instructions") or ""),
                *[
                    f"{item.get('title')}: {item.get('description')}"
                    for item in execution.request.input_delta.get("_helper_skills") or []
                    if isinstance(item, dict)
                ],
            ]
        ).strip()
        specific_result_ref = self._specific_followup_result_ref(
            execution.session,
            execution.intent,
        )
        allow_private_learning_projection = not bool(specific_result_ref)
        if (
            allow_private_learning_projection
            and "private_learning"
            in set(execution.intent.evidence_requirements.modes)
        ):
            # A verified plan target is already an ACL-checked lineage anchor.
            # Materialize its private provisional lesson before deterministic
            # claim binding so an unsupported model claim cannot hide a valid
            # Second Brain source from the fallback assembler.
            self._ensure_private_learning_lineage_sources(
                execution.principal,
                used_source_refs=set(),
                evidence=execution.evidence,
                citations=execution.citations,
                session_id=str(execution.session.get("session_id") or ""),
                query=(
                    execution.intent.retrieval_query
                    or execution.intent.resolved_goal
                ),
                subject_refs=self._private_learning_subject_refs(execution.intent),
            )
        planned_block, planned_questions, planned_claims, report = self._grounded_answer_from_plan(
            execution.principal,
            execution.session,
            execution.route.get("grounded_answer"),
            execution.evidence,
            execution.citations,
            primary_source_ref="",
            include_report=True,
            intent=execution.intent,
            work_run_id=str(execution.work_run["work_run_id"]),
        )
        if planned_block is not None and not helper_guidance:
            supported_claims = [
                claim for claim in planned_claims if claim.support_status == "supported"
            ]
            used_refs = {
                source_ref
                for claim in supported_claims
                for source_ref in claim.source_refs
            }
            projected_refs = set(used_refs)
            if allow_private_learning_projection:
                planned_block, planned_claims, projected_refs = (
                    self._attach_private_learning_lineage(
                        execution.principal,
                        answer=planned_block,
                        claims=planned_claims,
                        used_source_refs=used_refs,
                        evidence=execution.evidence,
                        citations=execution.citations,
                        answer_intent=execution.intent.answer_intent,
                        session_id=str(execution.session.get("session_id") or ""),
                        query=(
                            execution.intent.retrieval_query
                            or execution.intent.resolved_goal
                        ),
                        subject_refs=self._private_learning_subject_refs(
                            execution.intent
                        ),
                    )
                )
            projected_count = len(projected_refs - used_refs)
            used_refs = projected_refs
            if projected_count:
                report = report.model_copy(
                    update={
                        "supported_claim_count": (
                            report.supported_claim_count + projected_count
                        )
                    }
                )
            return CapabilityHandlerResult(
                answer=planned_block,
                related_questions=planned_questions,
                grounded_claims=planned_claims,
                used_source_refs=list(used_refs),
                answerability=report,
                citations=[
                    item for item in execution.citations if item.source_ref in used_refs
                ],
                claim_grounded_response=bool(supported_claims),
            )

        citation_pairs = {
            (item.source_ref, item.chunk_id)
            for item in execution.citations
            if item.source_ref and item.chunk_id
        }
        bound_unsupported_pairs = {
            (str(source_ref), str(chunk_id))
            for claim in planned_claims
            if claim.support_status != "supported"
            for source_ref in claim.source_refs
            for chunk_id in claim.supporting_chunk_ids
            if str(source_ref).strip() and str(chunk_id).strip()
            and (str(source_ref), str(chunk_id)) in citation_pairs
        }
        allowed_fallback_scopes = set(execution.intent.evidence_requirements.scopes)
        cross_scope_bound_pairs: set[tuple[str, str]] = set()
        for source_ref, chunk_id in bound_unsupported_pairs:
            record = self._record_for_ref(execution.principal, source_ref)
            if record is None:
                continue
            source_scope = self.repository.answer_scope(record)
            if (
                source_scope in allowed_fallback_scopes
                and source_scope != execution.intent.answer_source_scope
            ):
                cross_scope_bound_pairs.add((source_ref, chunk_id))
        if (
            execution.definition.handler_config.get("unbound_fallback")
            == "evidence_table"
            and execution.citations
            and not helper_guidance
            and (
                not bound_unsupported_pairs
                or bool(cross_scope_bound_pairs)
            )
        ):
            allowed_kinds = {
                str(item)
                for item in execution.definition.handler_config.get("kinds") or []
                if str(item).strip()
            }
            try:
                source_limit = max(
                    1,
                    min(
                        int(
                            execution.definition.handler_config.get(
                                "max_presentation_sources"
                            )
                            or 4
                        ),
                        12,
                    ),
                )
            except (TypeError, ValueError):
                source_limit = 4
            evidence_by_ref = {
                item.evidence_id: item for item in execution.evidence
            }
            answer_context_manifest = execution.request.input_delta.get(
                "_answer_context_manifest"
            )
            scoped_fallback_refs = self._final_answer_fallback_scope(
                answer_context_manifest,
                execution.citations,
            )
            fallback_citations = [
                citation
                for citation in execution.citations
                if (
                    (item := evidence_by_ref.get(citation.source_ref)) is not None
                    and (
                        not scoped_fallback_refs
                        or citation.source_ref in scoped_fallback_refs
                    )
                    and (
                        not bound_unsupported_pairs
                        or (citation.source_ref, citation.chunk_id)
                        in cross_scope_bound_pairs
                    )
                    and (not allowed_kinds or item.kind in allowed_kinds)
                    and citation.chunk_id
                    and citation.excerpt.strip()
                )
            ][:source_limit]
            fallback_refs = {item.source_ref for item in fallback_citations}
            fallback_evidence = [
                item
                for item in execution.evidence
                if item.evidence_id in fallback_refs
            ]
            table_result = self._grounded_evidence_table(
                fallback_evidence,
                fallback_citations,
            )
            fallback_claims: list[GroundedClaim] = []
            for index, citation in enumerate(fallback_citations, start=1):
                record = self._record_for_ref(
                    execution.principal,
                    citation.source_ref,
                )
                if record is None:
                    continue
                statements = self._atomic_source_statements(citation.excerpt)
                statement = (
                    statements[0]
                    if statements
                    else compact_text(citation.excerpt, 1200)
                )
                if not statement:
                    continue
                fallback_claims.append(
                    GroundedClaim(
                        claim_id=f"catalog-source-fallback-{index}",
                        text=statement,
                        claim_kind=execution.intent.answer_intent,
                        source_scope=self.repository.answer_scope(record),
                        source_refs=[citation.source_ref],
                        supporting_chunk_ids=[citation.chunk_id],
                        support_status="supported",
                        confidence=1.0,
                        required_for_answer=True,
                    )
                )
            if table_result is not None and fallback_claims:
                answer, related_questions = table_result
                supported_texts = {
                    " ".join(item.text.split()).casefold()
                    for item in fallback_claims
                    if item.text.strip()
                }
                remaining_planned_claims = [
                    item
                    for item in planned_claims
                    if (
                        item.support_status != "supported"
                        and " ".join(item.text.split()).casefold()
                        not in supported_texts
                    )
                ]
                unresolved_required = [
                    item
                    for item in remaining_planned_claims
                    if item.support_status in {"partial", "unsupported"}
                    and item.required_for_answer
                ]
                conflicting_claims = [
                    item
                    for item in remaining_planned_claims
                    if item.support_status == "conflicting"
                ]
                if unresolved_required:
                    answer = answer.model_copy(
                        update={
                            "markdown": (
                                f"{answer.markdown}\n\n### 확인하지 못한 내용\n"
                                + "\n".join(
                                    f"- {item.text}"
                                    for item in unresolved_required
                                )
                            )
                        }
                    )
                if conflicting_claims:
                    answer = answer.model_copy(
                        update={
                            "markdown": (
                                f"{answer.markdown}\n\n### 상충하는 내용\n"
                                + "\n".join(
                                    f"- {item.text}"
                                    for item in conflicting_claims
                                )
                            )
                        }
                    )
                combined_claims = [
                    *fallback_claims,
                    *unresolved_required,
                    *conflicting_claims,
                ]
                fallback_used_refs = {
                    item.source_ref for item in fallback_citations
                }
                projected_refs = set(fallback_used_refs)
                if allow_private_learning_projection:
                    answer, combined_claims, projected_refs = (
                        self._attach_private_learning_lineage(
                            execution.principal,
                            answer=answer,
                            claims=combined_claims,
                            used_source_refs=fallback_used_refs,
                            evidence=execution.evidence,
                            citations=execution.citations,
                            answer_intent=execution.intent.answer_intent,
                            session_id=str(
                                execution.session.get("session_id") or ""
                            ),
                            query=(
                                execution.intent.retrieval_query
                                or execution.intent.resolved_goal
                            ),
                            subject_refs=self._private_learning_subject_refs(
                                execution.intent
                            ),
                        )
                    )
                projected_count = len(projected_refs - fallback_used_refs)
                return CapabilityHandlerResult(
                    answer=answer,
                    related_questions=related_questions,
                    grounded_claims=combined_claims,
                    used_source_refs=[
                        item.source_ref
                        for item in execution.citations
                        if item.source_ref in projected_refs
                    ],
                    answerability=AnswerabilityReport(
                        status=(
                            "conflicting"
                            if conflicting_claims
                            else "partial"
                            if unresolved_required
                            else "grounded"
                        ),
                        answer_intent=execution.intent.answer_intent,
                        supported_claim_count=(
                            len(fallback_claims) + projected_count
                        ),
                        unsupported_claim_count=sum(
                            item.support_status in {"partial", "unsupported"}
                            for item in unresolved_required
                        ),
                        conflicting_claim_count=len(conflicting_claims),
                        missing_evidence=[
                            item.text
                            for item in unresolved_required
                        ],
                        conflicts=[item.text for item in conflicting_claims],
                    ),
                    citations=[
                        item
                        for item in execution.citations
                        if item.source_ref in projected_refs
                    ],
                    claim_grounded_response=True,
                )

        if execution.intent.presentation_mode == "table" and not helper_guidance:
            prior_topic = (
                execution.session.get("topic_state")
                if isinstance(execution.session.get("topic_state"), dict)
                else {}
            )
            prior_verified_chunks: dict[str, set[str]] = {}
            for prior_claim in prior_topic.get("claims") or []:
                if (
                    not isinstance(prior_claim, dict)
                    or prior_claim.get("support_status") != "supported"
                ):
                    continue
                chunk_ids = {
                    str(item)
                    for item in prior_claim.get("supporting_chunk_ids") or []
                    if str(item)
                }
                for source_ref in prior_claim.get("source_refs") or []:
                    source_key = str(source_ref)
                    if source_key and chunk_ids:
                        prior_verified_chunks.setdefault(source_key, set()).update(chunk_ids)
            prior_citations = [
                item
                for item in execution.citations
                if item.source_ref in prior_verified_chunks
                and item.chunk_id in prior_verified_chunks[item.source_ref]
            ]
            prior_refs = {item.source_ref for item in prior_citations}
            prior_evidence = [
                item for item in execution.evidence if item.evidence_id in prior_refs
            ]
            table_answer = (
                self._grounded_evidence_table(prior_evidence, prior_citations)
                if execution.intent.followup_semantic_change == "evidence_scope"
                and prior_verified_chunks
                else None
            )
            if table_answer is not None:
                answer, related_questions = table_answer
                return CapabilityHandlerResult(
                    answer=answer,
                    related_questions=related_questions,
                    grounded_claims=planned_claims,
                    used_source_refs=list(prior_refs),
                    answerability=AnswerabilityReport(
                        status="grounded",
                        answer_intent=execution.intent.answer_intent,
                        supported_claim_count=len(prior_citations),
                    ),
                    citations=prior_citations,
                    claim_grounded_response=True,
                )

        if execution.citations and not helper_guidance:
            eligible_bound_pairs = {
                (str(ref), str(chunk_id))
                for claim in planned_claims
                if claim.support_status != "supported"
                and claim.source_scope == execution.intent.answer_source_scope
                for ref in claim.source_refs
                for chunk_id in claim.supporting_chunk_ids
                if str(ref).strip() and str(chunk_id).strip()
            }
            ordered_citations = [
                item
                for item in execution.citations
                if (item.source_ref, item.chunk_id) in eligible_bound_pairs
            ]
            fallback_claims: list[GroundedClaim] = []
            fallback_citations: list[CitationRef] = []
            for citation in ordered_citations:
                if citation.source_ref in {
                    item.source_ref for item in fallback_citations
                }:
                    continue
                statements = self._atomic_source_statements(citation.excerpt)
                statement = (
                    statements[0]
                    if statements
                    else str(citation.excerpt or "").strip()[:1200]
                )
                if not statement:
                    continue
                fallback_citations.append(citation)
                fallback_claims.append(
                    GroundedClaim(
                        claim_id=f"source-fallback-{len(fallback_claims) + 1}",
                        text=statement,
                        claim_kind=execution.intent.answer_intent,
                        source_scope=execution.intent.answer_source_scope,
                        source_refs=[citation.source_ref],
                        supporting_chunk_ids=[citation.chunk_id],
                        support_status="supported",
                        confidence=1.0,
                        required_for_answer=False,
                    )
                )
                if len(fallback_claims) >= 3:
                    break
            if fallback_claims:
                unresolved_required = [
                    item
                    for item in planned_claims
                    if item.support_status != "supported"
                    and item.required_for_answer
                ]
                lines = ["### 확인 가능한 원문 근거"]
                for claim, citation in zip(
                    fallback_claims,
                    fallback_citations,
                ):
                    lines.extend(
                        [
                            f"- {claim.text} [근거](/api/v2/citations/{citation.citation_id})",
                        ]
                    )
                if unresolved_required:
                    lines.extend(["", "### 확인하지 못한 내용"])
                    lines.extend(f"- {item.text}" for item in unresolved_required)
                return CapabilityHandlerResult(
                    answer=AnswerBlock(
                        summary=fallback_claims[0].text,
                        markdown="\n".join(lines),
                    ),
                    grounded_claims=[*fallback_claims, *unresolved_required],
                    used_source_refs=[item.source_ref for item in fallback_citations],
                    answerability=AnswerabilityReport(
                        status="partial" if unresolved_required else "grounded",
                        answer_intent=execution.intent.answer_intent,
                        supported_claim_count=len(fallback_claims),
                        unsupported_claim_count=len(unresolved_required),
                        missing_evidence=[item.text for item in unresolved_required],
                    ),
                    citations=fallback_citations,
                    claim_grounded_response=True,
                )

        return CapabilityHandlerResult(
            answer=AnswerBlock(
                summary=empty_summary,
                markdown=(
                    "확인된 근거가 없습니다. 이 질문을 직접 뒷받침하는 ACL-visible "
                    "BoI Wiki 정본을 찾지 못했습니다. 관련 정본이 추가되거나 질문 대상을 "
                    "지정하면 다시 확인하겠습니다."
                ),
            ),
            grounded_claims=planned_claims,
            answerability=report,
            citations=[],
            claim_grounded_response=True,
        )

    def _handle_deep_job(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        job_ref = self._queue_deep_job(
            execution.principal,
            execution.definition,
            execution.request,
            execution.work_context,
            work_session_id=str(execution.session["session_id"]),
            work_run_id=str(execution.work_run["work_run_id"]),
        )
        return CapabilityHandlerResult(
            status="queued",
            job_ref=job_ref,
            answer=AnswerBlock(
                summary="심층 작업을 시작했습니다. 결과는 검토 가능한 draft로만 생성됩니다.",
                markdown=(
                    f"심층 작업 `{job_ref}`을 시작했습니다. "
                    "작업공간에서 진행 상태와 근거를 확인할 수 있습니다."
                ),
            ),
        )

    def _handle_draft_artifact(
        self,
        execution: CapabilityHandlerContext,
    ) -> CapabilityHandlerResult:
        if (
            execution.intent.operation == WorkOperation.capture
            and bool(execution.definition.handler_config.get("direct_verified_capture"))
        ):
            explicit_task_ref = str(
                execution.request.task_ref or execution.work_context.task_ref or ""
            ).strip()
            completion: dict[str, Any] | None = None
            if explicit_task_ref:
                normalised_task_ref = explicit_task_ref.removeprefix(
                    "task:"
                ).removeprefix("runtime-task:")
                completions = [
                    item
                    for item in self.store.list(
                        "completion_records",
                        employee_id=execution.principal.employee_id,
                        limit=1000,
                    )
                    if str(item.get("task_ref") or "")
                    .removeprefix("task:")
                    .removeprefix("runtime-task:")
                    == normalised_task_ref
                    and self._owns(execution.principal, item)
                ]
                completion = max(
                    completions,
                    key=lambda item: str(item.get("created_at") or ""),
                    default=None,
                )
            else:
                # A completed Action, Event, Workflow, or Task may be the
                # current subject even when there is no Task reference. The
                # durable WorkSession binding is the authority for "this
                # result"; the planner never invents a CompletionRecord ID.
                active_run_id = str(
                    execution.session.get("active_work_run_id") or ""
                )
                active_run = (
                    self.store.get("work_runs", active_run_id)
                    if active_run_id
                    else None
                )
                if (
                    active_run
                    and self._owns(execution.principal, active_run)
                    and str(active_run.get("status") or "") == "completed"
                ):
                    completion_id = str(
                        active_run.get("completion_record_id") or ""
                    )
                    candidate = (
                        self.store.get("completion_records", completion_id)
                        if completion_id
                        else None
                    )
                    if candidate and self._owns(execution.principal, candidate):
                        completion = candidate
            if completion is None:
                return CapabilityHandlerResult(
                    status="needs_input",
                    answer=AnswerBlock(
                        summary="저장할 검증 완료 기록을 찾지 못했습니다.",
                        markdown=(
                            "현재 업무 결과의 Completion Record가 아직 없습니다. 먼저 완료 근거와 "
                            "담당자 확인을 기록한 뒤 private 지식 저장을 다시 요청해주세요."
                        ),
                    ),
                    answerability=AnswerabilityReport(
                        status="insufficient",
                        answer_intent="work",
                        missing_evidence=["검증된 Completion Record가 없습니다."],
                    ),
                    citations=[],
                    evidence=[],
                    claim_grounded_response=True,
                )

            completion_id = str(completion.get("completion_id") or "")
            completion_record = self._record_for_ref(execution.principal, completion_id)
            if completion_record is None:
                return CapabilityHandlerResult(
                    status="needs_input",
                    answer=AnswerBlock(
                        summary="완료 기록의 접근 권한이나 출처를 검증하지 못했습니다.",
                        markdown="ACL-visible Completion Record를 확인한 뒤 다시 시도해주세요.",
                    ),
                    answerability=AnswerabilityReport(
                        status="insufficient",
                        answer_intent="work",
                        missing_evidence=["접근 가능한 Completion Record가 없습니다."],
                    ),
                    citations=[],
                    evidence=[],
                    claim_grounded_response=True,
                )

            captured_evidence = [self._evidence_from_record(completion_record)]
            self._merge_context_evidence(execution.work_context, captured_evidence, limit=8)
            captured_citations = self._citations_for_evidence(
                execution.principal,
                str(execution.session["session_id"]),
                execution.request.question,
                captured_evidence,
            )
            if not captured_citations:
                return CapabilityHandlerResult(
                    status="needs_input",
                    answer=AnswerBlock(
                        summary="완료 기록의 원문 위치를 확인하지 못했습니다.",
                        markdown="Completion Record의 WorkRun 연결을 복구한 뒤 다시 시도해주세요.",
                    ),
                    answerability=AnswerabilityReport(
                        status="insufficient",
                        answer_intent="work",
                        missing_evidence=["Completion Record 원문 위치가 없습니다."],
                    ),
                    citations=[],
                    evidence=[],
                    claim_grounded_response=True,
                )

            summary = str(completion.get("summary") or "Task 완료 판단을 검증했습니다.")
            subject_label = str(
                explicit_task_ref
                or execution.intent.topic_subject
                or execution.intent.target_ref
                or "업무"
            ).strip()
            claim_text = f"{subject_label}의 검증된 완료 판단: {summary}"
            citation = captured_citations[0]
            claim = GroundedClaim(
                claim_id=f"completion-capture-{completion_id}",
                text=claim_text,
                claim_kind="work",
                source_scope="operational",
                source_refs=[completion_id],
                supporting_chunk_ids=[citation.chunk_id],
                support_status="supported",
                confidence=1.0,
                required_for_answer=True,
            )
            return CapabilityHandlerResult(
                answer=AnswerBlock(
                    summary=claim_text,
                    markdown=(
                        "### Private provisional 지식 후보\n\n"
                        f"- {claim_text}\n"
                        "- 원문 대화는 저장하지 않았습니다.\n"
                        "- Team/Public 승격은 별도 리뷰가 필요합니다.\n\n"
                        f"[완료 근거](/api/v2/citations/{citation.citation_id})"
                    ),
                ),
                grounded_claims=[claim],
                used_source_refs=[completion_id],
                answerability=AnswerabilityReport(
                    status="grounded",
                    answer_intent="work",
                    supported_claim_count=1,
                ),
                citations=captured_citations,
                evidence=captured_evidence,
                claim_grounded_response=True,
            )
        if (
            execution.intent.operation == WorkOperation.refine
            and execution.active_artifact
            and self._artifact_contract_type(execution.active_artifact) == "sop_draft"
        ):
            proposal = self.refine_sop_artifact_preview(
                execution.principal,
                str(execution.active_artifact["artifact_id"]),
                execution.request.question,
            )
            proposed = proposal.get("after") if isinstance(proposal.get("after"), dict) else {}
            artifact_id = str(execution.active_artifact["artifact_id"])
            artifact = ArtifactRef(
                artifact_id=artifact_id,
                artifact_type="sop_draft",
                title=str(proposed.get("title") or execution.active_artifact.get("title") or "SOP 초안"),
                status="draft",
                url=f"/agent?session={execution.session['session_id']}&artifact={artifact_id}",
                preview=json.dumps(proposed, ensure_ascii=False, indent=2)[:1800],
                metadata={
                    "capability_id": execution.definition.capability_id,
                    "proposal_id": proposal["proposal_id"],
                    "base_revision": proposal["base_revision"],
                    "revision": proposal["base_revision"],
                    "task_count": len(proposed.get("tasks") or []),
                    "preview_only": True,
                },
            )
            return CapabilityHandlerResult(
                answer=AnswerBlock(
                    summary="기존 SOP 초안의 변경 미리보기를 준비했습니다.",
                    markdown=(
                        "기존 초안은 아직 바꾸지 않았습니다. 추가·변경된 내용을 비교한 뒤 "
                        "이 변경안을 적용할 수 있습니다."
                    ),
                ),
                artifacts=[artifact],
            )
        prefill_key = str(execution.definition.handler_config.get("planner_prefill_key") or "")
        prefilled = execution.route.get(prefill_key) if prefill_key else None
        try:
            answer, artifact, plan_ref = self._draft(
                execution.principal,
                execution.definition,
                execution.request,
                execution.evidence,
                work_run_id=str(execution.work_run["work_run_id"]),
                prefilled_draft=prefilled if isinstance(prefilled, dict) else None,
            )
            (
                answer,
                provenance_claims,
                provenance_refs,
                provenance_citations,
                provenance_report,
            ) = self._artifact_provenance(execution, artifact, answer)
            return CapabilityHandlerResult(
                answer=answer,
                artifacts=[artifact],
                plan_ref=plan_ref,
                grounded_claims=provenance_claims,
                used_source_refs=provenance_refs,
                citations=provenance_citations,
                answerability=provenance_report,
                claim_grounded_response=bool(provenance_claims),
            )
        except Exception as exc:
            capability_id = execution.definition.capability_id
            self.learning.fail_run(
                execution.principal,
                str(execution.work_run["work_run_id"]),
                f"{execution.definition.title} 작업 실패: {type(exc).__name__}",
            )
            failure = {
                "status": "draft_generation_failed",
                "capability_id": capability_id,
                "message": f"{type(exc).__name__}: {exc}",
                "run_id": execution.run_id,
            }
            self.store.put(
                "runs",
                execution.run_id,
                {
                    "run_id": execution.run_id,
                    "employee_id": execution.principal.employee_id,
                    "conversation_id": str(execution.session["conversation_id"]),
                    "work_session_id": str(execution.session["session_id"]),
                    "capability_id": capability_id,
                    "status": "failed",
                    "context_id": execution.work_context.context_id,
                    "routing": execution.route,
                    "events": [
                        {"event": "accepted", "run_id": execution.run_id},
                        {"event": "capability.selected", "capability_id": capability_id},
                        {"event": "error", **failure},
                    ],
                    "error": failure,
                    "created_at": now_iso(),
                },
            )
            self.store.put(
                "turns",
                execution.turn_id,
                {
                    "turn_id": execution.turn_id,
                    "run_id": execution.run_id,
                    "employee_id": execution.principal.employee_id,
                    "question_hash": hashlib.sha256(
                        execution.request.question.encode("utf-8")
                    ).hexdigest(),
                    "capability_id": capability_id,
                    "status": "failed",
                    "created_at": now_iso(),
                },
            )
            execution.goal_plan.update({"status": "failed", "updated_at": now_iso()})
            self.store.put(
                "goal_plans",
                str(execution.goal_plan["goal_plan_id"]),
                execution.goal_plan,
            )
            failure_response = AgentTurnResponse(
                run_id=execution.run_id,
                turn_id=execution.turn_id,
                conversation_id=str(execution.session["conversation_id"]),
                work_session_id=str(execution.session["session_id"]),
                status="failed",
                capability_id=capability_id,
                answer=AnswerBlock(
                    summary="초안을 만들지 못했습니다.",
                    markdown="초안을 만들지 못했습니다. 입력과 모델 준비 상태를 확인해주세요.",
                ),
                context_ref=execution.work_context.context_id,
                error_code="draft_generation_failed",
                goal_plan_ref=str(execution.goal_plan["goal_plan_id"]),
                source_set_ref=str(execution.source_set["source_set_id"]),
                citations=execution.citations,
                grounding_status="partial" if execution.citations else "no_evidence",
            )
            self._finish_work_session(
                execution.principal,
                execution.session,
                failure_response,
                execution.request.question,
            )
            raise HTTPException(status_code=502, detail=failure) from exc

    def _cancelled_turn_response(
        self,
        *,
        principal: Principal,
        session: dict[str, Any],
        request: AgentTurnRequest,
        run_id: str,
        turn_id: str,
        work_run: dict[str, Any] | None = None,
        capability_id: str = "semantic.planner",
    ) -> AgentTurnResponse:
        work_run_id = str((work_run or {}).get("work_run_id") or "")
        if work_run_id:
            work_run = {
                **(work_run or {}),
                "status": "cancelled",
                "decision": "stopped",
                "stop_reason": "user_cancelled",
                "revision": int((work_run or {}).get("revision") or 1) + 1,
                "updated_at": now_iso(),
            }
            self.store.put("work_runs", work_run_id, work_run)
        response = AgentTurnResponse(
            run_id=run_id,
            turn_id=turn_id,
            conversation_id=str(session.get("conversation_id") or ""),
            work_session_id=str(session.get("session_id") or ""),
            status="cancelled",
            capability_id=capability_id,
            answer=AnswerBlock(
                summary="요청을 중지했습니다.",
                markdown="현재 요청을 중지했습니다. 이전 대화와 이미 확인된 결과는 작업공간에 그대로 유지됩니다.",
            ),
            error_code="turn_cancelled",
            source_set_ref=str(session.get("source_set_id") or ""),
            grounding_status="no_evidence",
            answerability=AnswerabilityReport(status="insufficient"),
            work_run_id=work_run_id,
            loop_state={"status": "cancelled", "decision": "stopped"},
            stop_reason="user_cancelled",
            context_usage={"request_id": request.request_id},
        )
        self.store.put(
            "runs",
            run_id,
            {
                "run_id": run_id,
                "employee_id": principal.employee_id,
                "conversation_id": response.conversation_id,
                "work_session_id": response.work_session_id,
                "capability_id": capability_id,
                "status": "cancelled",
                "work_run_id": work_run_id,
                "request_id": request.request_id,
                "response": response.model_dump(mode="json"),
                "created_at": now_iso(),
            },
        )
        self._finish_work_session(principal, session, response, request.question)
        return response

    def run_turn(
        self,
        principal: Principal,
        request: AgentTurnRequest,
        *,
        progress_sink: Callable[[str, dict[str, Any]], None] | None = None,
        invocation_channel: str = "rest",
    ) -> AgentTurnResponse:
        # Intake before request registration, work-session persistence, plan
        # routing, audit, or any model budget/invocation. UI/REST/MCP share this.
        if "source_envelopes" in request.input_delta or str(request.capability_id or '').startswith('ontology.migration.'):
            request = request.model_copy(update={"input_delta": self._normalize_source_input(
                principal, request.capability_id, request.input_delta,
            )})
        self.register_turn_request(principal, request)
        if request.semantic_cache_mode == "refresh" and not principal.is_admin:
            raise HTTPException(
                status_code=403,
                detail="semantic cache refresh requires boi.admin",
            )
        usage_id = new_id("usage")
        # Start every request inside the ordinary-read ceiling. A validated
        # catalog ExecutionPlan may deliberately expand it later for a
        # non-turn goal/deep workflow, but no unvalidated planner call can do
        # so on its own.
        usage_token = begin_model_usage(
            usage_id,
            self.settings.run_token_budget,
            max_model_calls=2,
            max_elapsed_seconds=15,
            input_token_budget=16_384,
        )
        try:
            response = self._run_turn(
                principal,
                request,
                progress_sink=progress_sink,
                invocation_channel=invocation_channel,
            )
            response = self._attach_plan_binding(response)
            response.semantic_result_checksum = self._semantic_result_checksum(response)
        except Exception:
            usage = finish_model_usage(usage_token)
            self.store.put(
                "usage_ledgers",
                usage_id,
                {
                    "usage_id": usage_id,
                    "employee_id": principal.employee_id,
                    "status": "failed",
                    **usage,
                    "created_at": now_iso(),
                },
            )
            raise
        finally:
            self._release_turn_request(request)
        usage = finish_model_usage(usage_token)
        total_budget_exceeded = bool(
            usage.get("token_budget")
            and int(usage.get("total_tokens") or usage.get("total_tokens_estimate") or 0)
            > int(usage["token_budget"])
        )
        input_budget_exceeded = bool(
            usage.get("input_token_budget")
            and int(usage.get("input_tokens") or usage.get("input_tokens_estimate") or 0)
            > int(usage["input_token_budget"])
        )
        if total_budget_exceeded or input_budget_exceeded:
            self.store.put(
                "usage_ledgers",
                usage_id,
                {
                    "usage_id": usage_id,
                    "employee_id": principal.employee_id,
                    "run_id": response.run_id,
                    "work_run_id": response.work_run_id,
                    "capability_id": response.capability_id,
                    "status": "budget_exceeded",
                    **usage,
                    "created_at": now_iso(),
                },
            )
            raise RuntimeError(
                "model input token budget exceeded after provider usage accounting"
                if input_budget_exceeded
                else "model token budget exceeded after provider usage accounting"
            )
        usage_row = self.store.put(
            "usage_ledgers",
            usage_id,
            {
                "usage_id": usage_id,
                "employee_id": principal.employee_id,
                "run_id": response.run_id,
                "work_run_id": response.work_run_id,
                "capability_id": response.capability_id,
                "status": response.status,
                **usage,
                "created_at": now_iso(),
            },
        )
        model_usage = {
            "usage_ref": usage_id,
            "accounting": usage_row.get("accounting") or "estimated",
            "input_tokens": usage_row.get("input_tokens") or usage_row.get("input_tokens_estimate") or 0,
            "output_tokens": usage_row.get("output_tokens") or usage_row.get("output_tokens_estimate") or 0,
            "total_tokens": usage_row.get("total_tokens") or usage_row.get("total_tokens_estimate") or 0,
            "input_tokens_estimate": usage_row.get("input_tokens_estimate") or 0,
            "output_tokens_estimate": usage_row.get("output_tokens_estimate") or 0,
            "total_tokens_estimate": usage_row.get("total_tokens_estimate") or 0,
            "token_budget": usage_row.get("token_budget") or self.settings.run_token_budget,
            "input_token_budget": usage_row.get("input_token_budget") or 0,
            "remaining_tokens_estimate": usage_row.get("remaining_tokens_estimate") or 0,
            "model_calls": usage_row.get("model_calls") or 0,
            "model_call_types": usage_row.get("model_call_types") or {},
            "embedding_calls": usage_row.get("embedding_calls") or 0,
            "total_provider_calls": usage_row.get("total_provider_calls") or 0,
            "max_model_calls": usage_row.get("max_model_calls") or 0,
            "max_elapsed_seconds": usage_row.get("max_elapsed_seconds") or 0,
            "elapsed_ms": usage_row.get("elapsed_ms") or 0,
        }
        response.usage = model_usage
        response.context_usage["model_usage"] = model_usage
        response = self._enforce_response_budget(response)
        stored_run = self.store.get("runs", response.run_id)
        if stored_run:
            stored_run["usage_ref"] = usage_id
            stored_run["usage"] = model_usage
            stored_run["response"] = response.model_dump(mode="json")
            self.store.put("runs", response.run_id, stored_run)
        if response.work_run_id:
            work_run = self.store.get("work_runs", response.work_run_id)
            if work_run:
                work_run["usage_refs"] = list(dict.fromkeys([*work_run.get("usage_refs", []), usage_id]))[-20:]
                work_run["usage"] = model_usage
                self.store.put("work_runs", response.work_run_id, work_run)
        return response

    def _run_turn(
        self,
        principal: Principal,
        request: AgentTurnRequest,
        *,
        progress_sink: Callable[[str, dict[str, Any]], None] | None = None,
        invocation_channel: str = "rest",
    ) -> AgentTurnResponse:
        if invocation_channel not in {"ui", "rest", "mcp", "cli"}:
            raise ValueError(f"unsupported invocation channel: {invocation_channel}")
        turn_started = time.perf_counter()
        last_stage = turn_started
        stage_timings_ms: dict[str, float] = {}

        def mark_stage(name: str) -> None:
            nonlocal last_stage
            current = time.perf_counter()
            stage_timings_ms[name] = round((current - last_stage) * 1000, 2)
            last_stage = current

        run_id = new_id("run")
        turn_id = new_id("turn")
        self._apply_starter_suggestion(principal, request)
        session = self._resolve_turn_session(principal, request)
        source_set = self._ensure_source_set(
            principal,
            str(session["session_id"]),
        )
        excluded_source_refs = {
            str(ref)
            for ref in source_set.get("excluded") or []
            if str(ref).strip()
        }
        if self._turn_cancelled(request):
            return self._cancelled_turn_response(
                principal=principal,
                session=session,
                request=request,
                run_id=run_id,
                turn_id=turn_id,
            )
        planning_harness_bindings = self.learning.effective_harness_bindings(["context.work"])
        retrieval_policy = self.learning.retrieval_policy(planning_harness_bindings)
        retrieval_candidate_limit = max(
            12,
            min(
                self.settings.retrieval_candidate_limit,
                int(
                    retrieval_policy.get("candidate_limit")
                    or self.settings.retrieval_candidate_limit
                ),
            ),
        )
        self._emit_turn_progress(
            progress_sink,
            "context",
            "현재 화면과 이어진 업무 맥락을 확인하고 있습니다.",
            work_session_id=str(session["session_id"]),
        )
        offer_capability = ""
        if request.offer_id:
            offer = self._load_offer(principal, request.offer_id)
            offer_capability = str(offer.get("capability_id") or "")
            if request.capability_id and request.capability_id != offer_capability:
                raise HTTPException(status_code=409, detail="offer capability does not match request")
        active_session_artifact = self.store.get("artifacts", str(session.get("active_artifact_id") or "")) or {}
        active_capability = (
            str(active_session_artifact.get("capability_id") or "")
            if active_session_artifact and self._owns(principal, active_session_artifact)
            else ""
        )
        active_work_run = self._active_session_work_run(principal, session)
        page_anchor_for_route = self.learning.contexts.page_anchor(principal, request.page_ref)
        surface_context = normalise_agent_surface_context(
            request.surface_context,
            page_ref=request.page_ref,
            task_ref=request.task_ref,
            selected_text=request.selected_text,
        )
        selection_binding = self._verified_page_selection(
            principal,
            page_anchor=page_anchor_for_route,
            selected_text=request.selected_text,
            selection_ref=str(surface_context.get("selection_ref") or ""),
        )
        selection_binding = self._selection_after_source_policy(
            selection_binding,
            excluded_source_refs,
        )
        request.input_delta["_selection_binding"] = copy.deepcopy(
            selection_binding
        )
        verified_surface_targets = self._verified_surface_targets(
            principal,
            surface_context,
        )
        request.input_delta["_verified_surface_targets"] = copy.deepcopy(
            verified_surface_targets
        )
        starter_refs = [str(item) for item in request.input_delta.get("_starter_source_refs") or [] if str(item)]
        route_conversation_context = (
            request.input_delta.get("_work_session_context")
            if isinstance(request.input_delta.get("_work_session_context"), dict)
            else {}
        )
        route_conversation_context = self._planner_conversation_after_source_policy(
            route_conversation_context,
            excluded_source_refs,
        )
        request.input_delta["_work_session_context"] = copy.deepcopy(
            route_conversation_context
        )
        # Retrieve the current request as written. The verified prior topic and
        # citations are supplied as separate planner context below. Prefixing
        # every turn with the old subject polluted explicit topic changes,
        # while short follow-ups can still resolve through prior hints.
        planner_retrieval_query = request.question
        planner_search = None
        self._emit_turn_progress(
            progress_sink,
            "retrieval",
            "Wiki 전체에서 관련 지식과 업무 이력을 찾고 있습니다.",
        )
        if (
            self.settings.lmstudio_require_preloaded_models
            and not int(self.model_residency.get("generation_context_window") or 0)
        ):
            self.inspect_model_residency()
        requested_planner_tokens = (
            request.loop_policy.max_context_tokens
            if request.loop_policy is not None
            else self.settings.planner_context_tokens
        )
        planner_context_budget = resolve_context_budget(
            self.settings,
            requested_tokens=min(PLANNER_CONTEXT_TOKEN_LIMIT, requested_planner_tokens)
            if requested_planner_tokens > 0
            else PLANNER_CONTEXT_TOKEN_LIMIT,
            residency_state=self.model_residency,
        )
        try:
            planner_search = self.search.search(
                planner_retrieval_query,
                principal,
                limit=retrieval_candidate_limit,
                include_history=False,
                page_ref=request.page_ref,
                task_ref=request.task_ref,
                answer_scopes={"canonical", "operational", "validation"},
                ranking_policy=retrieval_policy,
                allow_semantic=False,
            )
            selected_planner_items = list(planner_search.items)
            planner_hints = [
                {
                    "ref": item.evidence_id,
                    "title": item.title,
                    "kind": item.kind,
                    "summary": item.summary,
                    "authority": item.authority,
                    "source": item.source,
                    "answer_scope": str(item.metadata.get("answer_scope") or "canonical"),
                    "authority_scope": str(item.metadata.get("authority_scope") or ""),
                    "chunk_id": str((item.metadata.get("best_chunk") or {}).get("chunk_id") or ""),
                    "chunk_text": str(
                        (item.metadata.get("best_chunk") or {}).get("content")
                        or (item.metadata.get("best_chunk") or {}).get("text")
                        or item.summary
                    ),
                    "is_primary": bool(
                        page_anchor_for_route
                        and page_anchor_for_route.resolved
                        and item.evidence_id == page_anchor_for_route.ref
                    ),
                }
                for item in selected_planner_items
                if item.evidence_id not in excluded_source_refs
            ]
        except Exception:
            planner_hints = []
        planner_hint_refs = {str(item.get("ref") or "") for item in planner_hints}
        if (
            page_anchor_for_route
            and page_anchor_for_route.resolved
            and page_anchor_for_route.ref not in excluded_source_refs
            and page_anchor_for_route.ref not in planner_hint_refs
        ):
            page_item = next(
                (
                    item
                    for item in (planner_search.items if planner_search else [])
                    if item.evidence_id == page_anchor_for_route.ref
                ),
                None,
            )
            if page_item is not None:
                page_chunk = page_item.metadata.get("best_chunk") or {}
                planner_hints = [
                    {
                        "ref": page_item.evidence_id,
                        "title": page_item.title,
                        "kind": page_item.kind,
                        "summary": page_item.summary,
                        "authority": page_item.authority,
                        "source": page_item.source,
                        "answer_scope": str(page_item.metadata.get("answer_scope") or "canonical"),
                        "authority_scope": str(page_item.metadata.get("authority_scope") or ""),
                        "chunk_id": str(page_chunk.get("chunk_id") or ""),
                        "chunk_text": str(
                            page_chunk.get("content")
                            or page_chunk.get("text")
                            or page_item.summary
                        ),
                        "is_primary": True,
                        "from_page_anchor": True,
                    },
                    *planner_hints,
                ]
        source_set_hints = self._source_set_planner_hints(
            principal,
            source_set,
        )
        if source_set_hints:
            pinned_refs = {
                str(item.get("ref") or "") for item in source_set_hints
            }
            planner_hints = [
                *source_set_hints,
                *(
                    item
                    for item in planner_hints
                    if str(item.get("ref") or "") not in pinned_refs
                ),
            ]
        planner_hints = self._query_specific_primary_hints(
            principal,
            planner_hints,
            request.question,
            selection_binding=selection_binding,
        )
        planner_hints.sort(key=lambda item: not bool(item.get("is_primary")))
        prior_hints: list[dict[str, Any]] = []
        prior_claim_chunks: dict[str, list[str]] = {}
        prior_topic_state = (
            route_conversation_context.get("topic_state")
            if isinstance(route_conversation_context.get("topic_state"), dict)
            else {}
        )
        for prior_claim in prior_topic_state.get("claims") or []:
            if not isinstance(prior_claim, dict) or prior_claim.get("support_status") != "supported":
                continue
            claim_chunks = [
                str(item)
                for item in prior_claim.get("supporting_chunk_ids") or []
                if str(item).strip()
            ]
            for source_ref in prior_claim.get("source_refs") or []:
                source_key = str(source_ref).strip()
                if source_key and claim_chunks:
                    prior_claim_chunks.setdefault(source_key, []).extend(claim_chunks)
        prior_citation_refs = [
            str(item)
            for item in prior_topic_state.get("used_source_refs") or []
            if (
                str(item).strip()
                and str(item) in prior_claim_chunks
                and str(item) not in excluded_source_refs
            )
        ]
        for source_ref in prior_citation_refs:
            record = self._record_for_ref(principal, source_ref)
            if not record or self.repository.answer_scope(record) not in {
                "canonical",
                "operational",
                "validation",
            }:
                continue
            evidence_item = self._evidence_from_record(record, score=1.0)
            trusted_chunk_ids = set(prior_claim_chunks.get(source_ref) or [])
            prior_chunk = next(
                (
                    item
                    for item in chunks_for_record(record)
                    if str(item.get("chunk_id") or "") in trusted_chunk_ids
                ),
                None,
            )
            if prior_chunk is None:
                continue
            prior_hints.append(
                {
                    "ref": evidence_item.evidence_id,
                    "title": evidence_item.title,
                    "kind": evidence_item.kind,
                    "summary": evidence_item.summary,
                    "authority": evidence_item.authority,
                    "source": evidence_item.source,
                    "answer_scope": self.repository.answer_scope(record),
                    "authority_scope": self.repository.authority_scope(record),
                    "chunk_id": str(prior_chunk.get("chunk_id") or ""),
                    "chunk_text": str(prior_chunk.get("content") or evidence_item.summary),
                    "is_primary": False,
                    "from_previous_answer": True,
                }
            )
        if prior_hints:
            prior_hint_refs = {str(item.get("ref") or "") for item in prior_hints}
            planner_hints = [
                *prior_hints,
                *(
                    item
                    for item in planner_hints
                    if str(item.get("ref") or "") not in prior_hint_refs
                ),
            ]

        mark_stage("retrieval")
        if self._turn_cancelled(request):
            return self._cancelled_turn_response(
                principal=principal,
                session=session,
                request=request,
                run_id=run_id,
                turn_id=turn_id,
            )
        trusted_targets = {
            "current_principal": f"person:{principal.employee_id}",
            "page_anchor": (
                str(page_anchor_for_route.ref)
                if page_anchor_for_route and page_anchor_for_route.resolved
                else ""
            ),
            "action_key": (
                f"action:{str(request.input_delta.get('action_key') or '').strip()}"
                if str(request.input_delta.get("action_key") or "").strip()
                else ""
            ),
            "starter_subject": str(request.input_delta.get("_starter_subject_ref") or ""),
            **{
                f"starter_source_{index}": ref
                for index, ref in enumerate(starter_refs, start=1)
            },
            **{
                f"pinned_source_{index}": str(item.get("ref") or "")
                for index, item in enumerate(source_set_hints, start=1)
                if str(item.get("ref") or "")
            },
            **{
                f"surface_{field}": str(value.get("ref") or "")
                for field, value in verified_surface_targets.items()
                if str(value.get("ref") or "")
            },
            **(
                {
                    "selection_source": str(
                        selection_binding.get("source_ref") or ""
                    )
                }
                if selection_binding.get("status") == "verified"
                else {}
            ),
        }
        trusted_kind_refs = list(
            dict.fromkeys(
                str(ref)
                for ref in [
                    *trusted_targets.values(),
                    *(
                        prior_topic_state.get("entities") or []
                        if isinstance(prior_topic_state, dict)
                        else []
                    ),
                ]
                if str(ref).strip()
            )
        )
        trusted_entity_kinds = {
            ref: entity_kind
            for ref in trusted_kind_refs
            if (entity_kind := self._semantic_entity_kind_for_ref(principal, ref))
        }
        selected_subject_refs = list(
            dict.fromkeys(
                ref
                for ref in [
                    str(request.task_ref or ""),
                    *[
                        str(item.get("ref") or "")
                        for item in source_set_hints
                    ],
                    *[
                        str(value.get("ref") or "")
                        for value in verified_surface_targets.values()
                    ],
                    (
                        str(selection_binding.get("source_ref") or "")
                        if selection_binding.get("status") == "verified"
                        else ""
                    ),
                    (
                        f"action:{str(request.input_delta.get('action_key') or '').strip()}"
                        if str(request.input_delta.get("action_key") or "").strip()
                        else ""
                    ),
                    str(request.input_delta.get("_starter_subject_ref") or ""),
                    *starter_refs,
                ]
                if ref
            )
        )
        requested_user_effect = (
            str(request.input_delta.get("user_effect") or "")
            or (
                "draft"
                if bool(request.input_delta.get("save_verified_learning"))
                else "execute"
                if (
                    bool(str(request.input_delta.get("action_key") or "").strip())
                    and isinstance(request.input_delta.get("payload"), dict)
                )
                or (
                    bool(str(request.task_ref or "").strip())
                    and "completion_evidence" in request.input_delta
                )
                else ""
            )
        )
        typed_capability_id = str(request.capability_id or offer_capability or "")
        typed_capability = (
            self.registry.get(typed_capability_id) if typed_capability_id else None
        )
        dry_run_is_manifest_only = bool(
            typed_capability
            and str(
                typed_capability.handler_config.get("dry_run_semantics") or ""
            )
            == "manifest_only"
        )
        requested_operation = (
            str(request.input_delta.get("operation") or "")
            or (
                "capture"
                if bool(request.input_delta.get("save_verified_learning"))
                else "complete"
                if (
                    bool(str(request.task_ref or "").strip())
                    and "completion_evidence" in request.input_delta
                )
                else "test"
                if (
                    bool(str(request.input_delta.get("action_key") or "").strip())
                    and isinstance(request.input_delta.get("payload"), dict)
                )
                else (
                    "test"
                    if bool(request.input_delta.get("dry_run"))
                    and not dry_run_is_manifest_only
                    and bool(request.capability_id or offer_capability)
                    else ""
                )
            )
        )
        verified_typed_command_source = ""
        surface_target_refs = {
            str(value.get("ref") or "")
            for value in verified_surface_targets.values()
            if str(value.get("ref") or "").strip()
        }
        if (
            requested_user_effect
            and requested_operation
            and len(selected_subject_refs) == 1
            and selected_subject_refs[0] in surface_target_refs
        ):
            target_ref = selected_subject_refs[0]
            target_record = self._record_for_ref(principal, target_ref)
            if (
                target_record is not None
                and target_record.record_id == target_ref
                and str(target_record.kind or "")
                == str(trusted_entity_kinds.get(target_ref) or "")
            ):
                verified_typed_command_source = "verified_surface_target"
        try:
            auto_governed_query = bool(
                self.general_query_runtime is not None
                and not request.capability_id
                and not offer_capability
                and self.general_query_runtime.is_applicable(request.question)
            )
            route_input = {
                "question": request.question,
                "page_kind": self.page_kind(request.page_ref),
                "page_ref": request.page_ref,
                "page_title": (
                    page_anchor_for_route.title
                    if page_anchor_for_route and page_anchor_for_route.resolved
                    else ""
                ),
                "explicit_capability": (
                    request.capability_id
                    or ("data.query.governed" if auto_governed_query else "")
                ),
                "offered_capability": offer_capability,
                "active_capability": active_capability,
                "active_artifact_title": str(active_session_artifact.get("title") or ""),
                "active_artifact_input": (
                    {
                        "ref": str(active_session_artifact.get("artifact_id") or ""),
                        "kind": str(active_session_artifact.get("artifact_type") or ""),
                        "title": str(active_session_artifact.get("title") or ""),
                    }
                    if active_session_artifact
                    else {}
                ),
                "active_work_run": self._active_work_run_for_planner(active_work_run),
                "task_ref": request.task_ref,
                "conversation_summary": str(session.get("conversation_summary") or ""),
                "conversation_context": route_conversation_context,
                "source_policy_context": self._source_policy_context(
                    principal,
                    source_set,
                ),
                "current_selection": (
                    {
                        "selection_ref": str(
                            selection_binding.get("selection_ref") or ""
                        ),
                        "source_ref": str(
                            selection_binding.get("source_ref") or ""
                        ),
                        "source_kind": str(
                            selection_binding.get("source_kind") or ""
                        ),
                        "source_title": str(
                            selection_binding.get("source_title") or ""
                        ),
                        "chunk_id": str(
                            (selection_binding.get("chunk") or {}).get(
                                "chunk_id"
                            )
                            or ""
                        ),
                        "text": str(
                            selection_binding.get("selected_text") or ""
                        ),
                    }
                    if selection_binding.get("status") == "verified"
                    else {}
                ),
                "knowledge_hints": planner_hints,
                "trusted_targets": trusted_targets,
                "trusted_entity_kinds": trusted_entity_kinds,
                "selected_subject_refs": selected_subject_refs,
                "verified_typed_command_source": verified_typed_command_source,
                "requested_user_effect": requested_user_effect,
                "requested_operation": requested_operation,
                "requested_result_kind": str(request.input_delta.get("_starter_result_kind") or ""),
                "requested_graph_query_kind": str(request.input_delta.get("_starter_graph_query_kind") or ""),
                "requested_graph_node_kinds": [
                    str(item)
                    for item in request.input_delta.get("graph_node_kinds") or []
                    if str(item)
                ],
                "requested_graph_relation_kinds": [
                    str(item)
                    for item in request.input_delta.get("graph_relation_kinds") or []
                    if str(item)
                ],
                "requested_work_view": (
                    str(request.input_delta.get("work_view") or "")
                    or (
                        "current"
                        if bool(str(request.task_ref or "").strip())
                        and (
                            "completion_evidence" in request.input_delta
                            or bool(request.input_delta.get("save_verified_learning"))
                        )
                        else ""
                    )
                ),
                # Semantic planning receives identities and metadata. The one
                # answer call must wait until the Catalog-compiled retrieval,
                # ACL, authority, freshness, and citation checks are complete.
                "defer_grounded_answer": True,
            }
            route = self._semantic_route(
                principal,
                {**route_input, "context_token_budget": planner_context_budget.effective_tokens},
                read_cache=request.semantic_cache_mode != "refresh",
            )
            request.input_delta["_planner_context_manifest"] = copy.deepcopy(
                route.get("planner_context_manifest") or {}
            )
            request.input_delta["_answer_context_manifest"] = copy.deepcopy(
                (route.get("grounded_answer_diagnostics") or {}).get("context_manifest")
                or {}
            )
            if self._turn_cancelled(request):
                return self._cancelled_turn_response(
                    principal=principal,
                    session=session,
                    request=request,
                    run_id=run_id,
                    turn_id=turn_id,
                )
            capability_id = str(route["capability_id"])
            definition = self.registry.get(capability_id)
            semantic_plan = SemanticPlan.model_validate(route.get("semantic_plan") or {})
            if semantic_plan.topic_action == "clarify" and not semantic_plan.clarification_question.strip():
                raise SemanticPlanningError(
                    "planner_invalid",
                    "A clarification plan reached execution without a model-authored question.",
                )
            if bool(route.get("safe_stop_after_repair")):
                return self._semantic_repair_stop_response(
                    principal=principal,
                    session=session,
                    request=request,
                    run_id=run_id,
                    turn_id=turn_id,
                    route=route,
                )
        except SemanticPlanningError as exc:
            return self._planning_failure_response(
                principal=principal,
                session=session,
                request=request,
                run_id=run_id,
                turn_id=turn_id,
                error=exc,
            )
        except KeyError as exc:
            raise HTTPException(status_code=404, detail=str(exc)) from exc
        mark_stage("planning")
        if request.helper_id:
            helper = self.get_helper(principal, request.helper_id)
            allowed = list(helper.get("capability_ids") or [])
            if capability_id not in allowed:
                raise HTTPException(
                    status_code=403,
                    detail={
                        "status": "capability_not_allowed",
                        "capability_id": capability_id,
                        "helper_id": request.helper_id,
                    },
                )
            request.input_delta.setdefault("_helper_instructions", str(helper.get("instructions") or ""))
            request.input_delta.setdefault("_helper_source_scopes", helper.get("source_scopes") or [])
            request.input_delta.setdefault("_helper_skill_ids", helper.get("skill_ids") or [])
            helper_skills, missing_skills = self._skill_contracts(
                principal,
                list(helper.get("skill_ids") or []),
                require_active=helper.get("status") == "active",
            )
            if missing_skills:
                raise HTTPException(status_code=422, detail={"status": "skill_unavailable", "skill_ids": missing_skills})
            request.input_delta.setdefault("_helper_skills", helper_skills)
        preliminary_intent = WorkIntent.model_validate(route.get("work_intent") or {})
        routine_id = str(request.input_delta.get("_routine_id") or "").strip()
        registered_routine = self.store.get("work_routines", routine_id) if routine_id else None
        registered_routine_policy = (
            LoopPolicy.model_validate(registered_routine.get("loop_policy") or {})
            if registered_routine
            else None
        )
        registered_routine_child = bool(
            registered_routine
            and registered_routine_policy
            and registered_routine.get("status") == "active"
            and str(registered_routine.get("employee_id") or "") == principal.employee_id
            and str(registered_routine.get("capability_id") or "") == definition.capability_id
            and request.loop_policy is not None
            and request.loop_policy.kind == registered_routine_policy.kind
            and request.loop_policy.trigger == registered_routine_policy.trigger
        )
        if request.loop_policy is not None:
            requested_loop = request.loop_policy
            if (
                requested_loop.kind not in definition.allowed_loop_kinds
                or requested_loop.trigger not in definition.allowed_loop_triggers
            ):
                raise HTTPException(
                    status_code=422,
                    detail={
                        "code": "loop_contract_not_allowed",
                        "capability_id": definition.capability_id,
                        "kind": requested_loop.kind.value,
                        "trigger": requested_loop.trigger.value,
                    },
                )
            catalog_loop = preliminary_intent.loop_contract
            if (
                not registered_routine_child
                and (
                    requested_loop.kind != catalog_loop.kind
                    or requested_loop.trigger != catalog_loop.trigger
                )
            ):
                raise HTTPException(
                    status_code=422,
                    detail={
                        "code": "loop_contract_semantics_mismatch",
                        "capability_id": definition.capability_id,
                        "requested_kind": requested_loop.kind.value,
                        "compiled_kind": catalog_loop.kind.value,
                        "message": "클라이언트는 Catalog가 결정한 loop 의미를 승격할 수 없습니다.",
                    },
                )
            requested_context = int(requested_loop.max_context_tokens or 0)
            catalog_context = int(catalog_loop.max_context_tokens or 0)
            bounded_context = (
                min(catalog_context, requested_context)
                if catalog_context and requested_context
                else catalog_context
            )
            bounded_loop = catalog_loop.model_copy(
                update={
                    "kind": requested_loop.kind if registered_routine_child else catalog_loop.kind,
                    "trigger": requested_loop.trigger if registered_routine_child else catalog_loop.trigger,
                    "task_stop": requested_loop.task_stop if registered_routine_child else catalog_loop.task_stop,
                    "routine_stop": requested_loop.routine_stop if registered_routine_child else catalog_loop.routine_stop,
                    "max_iterations": min(catalog_loop.max_iterations, requested_loop.max_iterations),
                    "max_tool_loops": min(catalog_loop.max_tool_loops, requested_loop.max_tool_loops),
                    "max_model_calls": min(catalog_loop.max_model_calls, requested_loop.max_model_calls),
                    "max_elapsed_seconds": min(
                        catalog_loop.max_elapsed_seconds,
                        requested_loop.max_elapsed_seconds,
                    ),
                    "max_context_tokens": bounded_context,
                    "max_runs": min(catalog_loop.max_runs, requested_loop.max_runs),
                    "interval_seconds": (
                        requested_loop.interval_seconds if registered_routine_child else catalog_loop.interval_seconds
                    ),
                    "source_fingerprint": (
                        requested_loop.source_fingerprint if registered_routine_child else ""
                    ),
                    "routine_id": routine_id if registered_routine_child else "",
                }
            )
            preliminary_intent = preliminary_intent.model_copy(
                update={"loop_contract": bounded_loop}
            )
        if (
            self.settings.lmstudio_require_preloaded_models
            and not int(self.model_residency.get("generation_context_window") or 0)
        ):
            self.inspect_model_residency()
        context_budget = resolve_context_budget(
            self.settings,
            requested_tokens=preliminary_intent.loop_contract.max_context_tokens,
            residency_state=self.model_residency,
        )
        standard_read = bool(
            preliminary_intent.user_effect == "read"
            and (
                preliminary_intent.loop_contract.kind == LoopKind.turn
                or registered_routine_child
            )
            and preliminary_intent.analysis_depth == "standard"
            and not definition.deep
            and preliminary_intent.operation not in {
                WorkOperation.validate,
                WorkOperation.test,
                WorkOperation.run,
                WorkOperation.complete,
                WorkOperation.promote,
            }
        )
        # Registered time/proactive routines keep the same bounded two-call
        # read budget, but they are independent child executions and therefore
        # must leave a durable GoalPlan/WorkRun/checkpoint trail.  An arbitrary
        # client loop_policy cannot cross this boundary because
        # registered_routine_child is established only after matching the
        # stored active routine, owner, capability, kind, and trigger above.
        persist_execution_record = bool(
            not standard_read or registered_routine_child
        )
        if standard_read:
            preliminary_intent = preliminary_intent.model_copy(
                update={
                    "loop_contract": preliminary_intent.loop_contract.model_copy(
                        update={
                            "max_model_calls": min(
                                2,
                                preliminary_intent.loop_contract.max_model_calls,
                            ),
                            "max_elapsed_seconds": min(
                                15,
                                preliminary_intent.loop_contract.max_elapsed_seconds,
                            ),
                            "max_context_tokens": min(
                                16_384,
                                preliminary_intent.loop_contract.max_context_tokens or 16_384,
                            ),
                        }
                    )
                }
            )
            context_budget = resolve_context_budget(
                self.settings,
                requested_tokens=preliminary_intent.loop_contract.max_context_tokens,
                residency_state=self.model_residency,
            )
        update_model_usage_limits(
            max_model_calls=preliminary_intent.loop_contract.max_model_calls,
            max_elapsed_seconds=preliminary_intent.loop_contract.max_elapsed_seconds,
        )
        update_model_input_token_budget(16_384 if standard_read else 0)
        planned_input_budget = (
            16_384
            if standard_read
            else context_budget.effective_tokens
            * max(1, preliminary_intent.loop_contract.max_model_calls)
        )
        planned_run_token_budget = planned_input_budget + (
            context_budget.max_output_tokens
            * max(1, preliminary_intent.loop_contract.max_model_calls)
        )
        update_model_token_budget(
            min(self.settings.run_token_budget, max(4_000, planned_run_token_budget))
        )
        self._emit_turn_progress(
            progress_sink,
            "judgment",
            "요청 의도와 확인할 근거를 함께 판단하고 있습니다.",
            capability_id=capability_id,
        )
        if (
            active_work_run
            and self._semantic_continuation_applies(route, preliminary_intent)
        ):
            return self._continue_active_work_from_turn(
                principal=principal,
                request=request,
                session=session,
                active_work_run=active_work_run,
                route=route,
                run_id=run_id,
                turn_id=turn_id,
            )
        resolved_goal = compact_text(preliminary_intent.resolved_goal or request.question, 12000)
        retrieval_goal = compact_text(preliminary_intent.retrieval_query or resolved_goal, 12000)
        request.input_delta["_resolved_goal"] = resolved_goal
        request.input_delta["_retrieval_query"] = retrieval_goal
        goal_plan = self._create_goal_plan(
            principal,
            session,
            resolved_goal,
            definition,
            route,
            preliminary_intent,
            persist=persist_execution_record,
        )
        active_session_task = self._active_session_task(principal, session)
        active_mode = str(active_session_task.get("execution_mode") or active_session_task.get("mode") or "").lower()
        task_mode = (
            TaskMode(active_mode)
            if active_mode in {item.value for item in TaskMode}
            else self.policy.resolve_mode(principal, request.task_ref)
        )
        dependencies = self.readiness(principal)["dependencies"]
        supplied = {"query": resolved_goal, "goal": resolved_goal, **request.input_delta}
        state, missing, reason = self.registry.state_for(
            definition,
            principal=principal,
            readiness=dependencies,
            task_mode=task_mode,
            supplied_input=supplied,
        )
        if not self.registry.handler_supported(definition):
            raise HTTPException(
                status_code=503,
                detail={
                    "status": "capability_unavailable",
                    "capability_id": capability_id,
                    "message": "이 기능의 안전한 실행 경로가 아직 준비되지 않았습니다.",
                    "retryable": False,
                },
            )
        if state == CapabilityState.unavailable:
            raise HTTPException(
                status_code=503 if any(not dependencies.get(name, False) for name in definition.readiness) else 403,
                detail={"status": "capability_unavailable", "capability_id": capability_id, "message": reason},
            )
        if state == CapabilityState.needs_input:
            response = self._needs_input_response(
                capability_id,
                missing,
                reason,
                work_session_id=str(session["session_id"]),
            )
            response.goal_plan_ref = str(goal_plan["goal_plan_id"])
            response.source_set_ref = str(source_set["source_set_id"])
            self._finish_work_session(principal, session, response, request.question)
            return response
        decision = self.policy.evaluate(
            definition,
            principal=principal,
            task_ref=request.task_ref,
            semantic_operation=preliminary_intent.operation.value,
        )
        self.policy.enforce(decision)

        retrieval_query = retrieval_goal
        handler_config = definition.handler_config or {}
        capability_retrieval_policy = handler_config.get("retrieval_policy")
        if isinstance(capability_retrieval_policy, dict):
            retrieval_policy = {
                **retrieval_policy,
                **{
                    str(key): float(value)
                    for key, value in capability_retrieval_policy.items()
                    if isinstance(value, (int, float))
                    and not isinstance(value, bool)
                },
            }
        retrieval_provider = str(handler_config.get("retrieval_provider") or "hybrid")
        include_history = bool(handler_config.get("include_history"))
        history_by_operation = handler_config.get("include_history_by_operation")
        if isinstance(history_by_operation, dict):
            operation_history = history_by_operation.get(
                preliminary_intent.operation.value
            )
            if isinstance(operation_history, bool):
                include_history = operation_history
        include_history = include_history or bool(
            request.input_delta.get("include_history", False)
        )
        retrieval_kinds = {
            str(item) for item in handler_config.get("kinds") or [] if str(item).strip()
        } or None
        planner_evidence_ids = {
            item.evidence_id
            for item in (planner_search.items if planner_search is not None else [])
            if item.evidence_id
        }
        required_planner_refs = {
            item
            for item in [
                *preliminary_intent.context_refs,
                preliminary_intent.target_ref,
            ]
            if item and self._record_for_ref(principal, item)
        }
        excluded_specific_refs = self._specific_followup_excluded_prior_refs(
            session,
            preliminary_intent,
        )
        specific_followup_result_ref = self._specific_followup_result_ref(
            session,
            preliminary_intent,
        )
        planned_grounded_answer = self._without_excluded_grounded_sources(
            route.get("grounded_answer"),
            excluded_specific_refs,
        )
        if excluded_specific_refs:
            route["grounded_answer"] = planned_grounded_answer
            request.input_delta["_excluded_prior_result_refs"] = sorted(excluded_specific_refs)
        planned_grounded_refs: set[str] = set()
        if isinstance(planned_grounded_answer, dict):
            planned_grounded_refs.update(
                str(item)
                for item in planned_grounded_answer.get("summary_source_refs") or []
                if str(item)
            )
            for claim in planned_grounded_answer.get("claims") or []:
                if isinstance(claim, dict):
                    claim_refs = [str(ref) for ref in claim.get("source_refs") or [] if str(ref)]
                    planned_grounded_refs.update(
                        claim_refs
                    )
            for outcome in planned_grounded_answer.get("outcomes") or []:
                if not isinstance(outcome, dict):
                    continue
                for item in outcome.get("items") or []:
                    if isinstance(item, dict):
                        planned_grounded_refs.update(
                            str(ref) for ref in item.get("source_refs") or [] if str(ref)
                        )
            for item in planned_grounded_answer.get("related_questions") or []:
                if isinstance(item, dict):
                    planned_grounded_refs.update(
                        str(ref) for ref in item.get("source_refs") or [] if str(ref)
                    )
        planner_answer_is_bounded = bool(
            planned_grounded_refs
            and planned_grounded_refs.issubset(planner_evidence_ids)
        )
        planner_search_covers_intent = bool(
            planner_search is not None
            and not include_history
            and (
                planner_answer_is_bounded
                or
                retrieval_query == request.question
                # A validated exact subject/reference is already resolved by
                # the discourse state and ACL-aware record lookup. It does
                # not need to reappear in a semantic search for an ordinal or
                # artifact follow-up; the exact record is injected below and
                # checked against the same evidence policy.
                or bool(required_planner_refs)
            )
        )
        context_started = time.perf_counter()
        context_substage_started = context_started

        def mark_context_substage(name: str) -> None:
            nonlocal context_substage_started
            current = time.perf_counter()
            stage_timings_ms[f"context.{name}"] = round(
                (current - context_substage_started) * 1000,
                2,
            )
            context_substage_started = current

        evidence_requirements = preliminary_intent.evidence_requirements
        allowed_answer_scopes = {
            scope
            for scope in evidence_requirements.scopes
            if scope in set(definition.evidence_scopes)
        } or {preliminary_intent.answer_source_scope}
        require_outcome_by_operation = (
            definition.handler_config.get("require_outcome_by_operation")
            if isinstance(
                definition.handler_config.get("require_outcome_by_operation"),
                dict,
            )
            else {}
        )
        require_outcome = bool(
            require_outcome_by_operation.get(
                preliminary_intent.operation.value,
                "outcome_present" in definition.evidence_policy,
            )
        )
        evidence_policy_args = {
            "allowed_authorities": set(preliminary_intent.evidence_authorities),
            "allowed_statuses": set(preliminary_intent.evidence_statuses),
            "require_freshness": bool(evidence_requirements.require_freshness),
            "require_outcome": require_outcome,
            "required_authority_scope": str(evidence_requirements.authority_scope or "any"),
            "as_of": str(evidence_requirements.as_of or ""),
        }
        search_result = None
        continued_topic_source_refs: list[str] = []
        current_work_employee_id = principal.employee_id
        for subject in semantic_plan.subjects:
            if (
                subject.entity_kind == "person"
                and subject.resolution == "resolved"
                and str(subject.entity_ref or "").startswith("person:")
            ):
                current_work_employee_id = str(subject.entity_ref).removeprefix("person:")
                break
        try:
            current_work_limit = max(
                1,
                min(int(definition.handler_config.get("max_display_items") or 8), 50),
            )
        except (TypeError, ValueError):
            current_work_limit = 8
        if retrieval_provider == "current_work":
            work = self._current_work_records(
                principal,
                employee_id=current_work_employee_id,
                limit=current_work_limit,
            )
            evidence = [
                EvidenceRef(
                    evidence_id=item.record_id,
                    kind="task",
                    title=item.title,
                    summary=item.description,
                    url=item.url,
                    source="runtime",
                    authority="runtime",
                    metadata={"status": item.status},
                )
                for item in work
            ]
            current_work_evidence = list(evidence)
        else:
            if planner_search is not None and include_history:
                filtered_planner_search = self.search.filter_response(
                    planner_search,
                    principal,
                    include_history=False,
                    reuse_acl_snapshot=True,
                    **evidence_policy_args,
                )
                history_search = self.search.search_history_partition(
                    resolved_goal,
                    principal,
                    limit=retrieval_candidate_limit,
                    page_ref=request.page_ref,
                    task_ref=request.task_ref,
                    kinds=retrieval_kinds,
                    answer_scopes=allowed_answer_scopes,
                    ontology_terms=planner_search.ontology_terms,
                    ranking_policy=retrieval_policy,
                    **evidence_policy_args,
                )
                result_limit = max(
                    1,
                    min(retrieval_candidate_limit, 20),
                )
                preferred_base_refs = {
                    *required_planner_refs,
                    *planned_grounded_refs,
                }
                base_items = self._prioritize_evidence(
                    list(filtered_planner_search.items),
                    preferred_base_refs,
                )
                history_items = [
                    item
                    for item in history_search.items
                    if item.evidence_id
                    not in {base.evidence_id for base in base_items}
                ]
                history_budget = min(
                    len(history_items),
                    max(2, result_limit // 2),
                )
                base_budget = max(1, result_limit - history_budget)
                merged_items: list[EvidenceRef] = []
                for item in [
                    *base_items[:base_budget],
                    *history_items[:history_budget],
                    *base_items[base_budget:],
                    *history_items[history_budget:],
                ]:
                    if item.evidence_id in {
                        existing.evidence_id for existing in merged_items
                    }:
                        continue
                    merged_items.append(item)
                    if len(merged_items) >= result_limit:
                        break
                if merged_items:
                    merged_manifest = {
                        **filtered_planner_search.policy_manifest,
                        "history_partition": history_search.policy_manifest,
                        "history_source_revision": history_search.policy_manifest.get(
                            "history_source_revision"
                        ),
                        "history_partition_compiled": True,
                        "returned_refs": [
                            item.evidence_id for item in merged_items
                        ],
                        "returned_count": len(merged_items),
                    }
                    search_result = filtered_planner_search.model_copy(
                        update={
                            "query": resolved_goal,
                            "mode": (
                                f"{filtered_planner_search.mode}+"
                                f"{history_search.mode}"
                            ),
                            "items": merged_items,
                            "degraded": list(
                                dict.fromkeys(
                                    [
                                        *filtered_planner_search.degraded,
                                        *history_search.degraded,
                                    ]
                                )
                            ),
                            "index_manifest": {
                                **filtered_planner_search.index_manifest,
                                **history_search.index_manifest,
                            },
                            "policy_manifest": merged_manifest,
                        }
                    )
                else:
                    search_result = self.search.search(
                        retrieval_query,
                        principal,
                        limit=retrieval_candidate_limit,
                        include_history=True,
                        page_ref=request.page_ref,
                        task_ref=request.task_ref,
                        kinds=retrieval_kinds,
                        answer_scopes=allowed_answer_scopes,
                        ranking_policy=retrieval_policy,
                        **evidence_policy_args,
                    )
            elif planner_search_covers_intent:
                filtered_planner_search = self.search.filter_response(
                    planner_search,
                    principal,
                    include_history=include_history,
                    reuse_acl_snapshot=True,
                    **evidence_policy_args,
                )
                # Filtering a planner search can remove a lower-authority or
                # stale candidate without making the remaining evidence
                # insufficient. Re-running the same hybrid search merely to
                # refill the candidate count duplicates an embedding call and
                # can reintroduce irrelevant sources. The grounded-read
                # completion contract needs one or more eligible sources; only
                # an empty filtered set requires a fresh retrieval query.
                if not filtered_planner_search.items and not required_planner_refs:
                    search_result = self.search.search(
                        retrieval_query,
                        principal,
                        limit=retrieval_candidate_limit,
                        include_history=include_history,
                        page_ref=request.page_ref,
                        task_ref=request.task_ref,
                        kinds=retrieval_kinds,
                        answer_scopes=allowed_answer_scopes,
                        ranking_policy=retrieval_policy,
                        **evidence_policy_args,
                    )
                else:
                    search_result = filtered_planner_search
            else:
                search_result = self.search.search(
                    retrieval_query,
                    principal,
                    limit=retrieval_candidate_limit,
                    include_history=include_history,
                    page_ref=request.page_ref,
                    task_ref=request.task_ref,
                    kinds=retrieval_kinds,
                    answer_scopes=allowed_answer_scopes,
                    ranking_policy=retrieval_policy,
                    **evidence_policy_args,
                )
            evidence = search_result.items
            current_work_evidence = []
            evidence_refs = {item.evidence_id for item in evidence}
            required_evidence_refs = {
                *planned_grounded_refs,
                *required_planner_refs,
            }
            for source_ref in sorted(required_evidence_refs - evidence_refs):
                record = self._record_for_ref(principal, source_ref)
                if record is None or self.repository.answer_scope(record) not in allowed_answer_scopes:
                    continue
                if self.search._policy_exclusion_reason(
                    record,
                    allowed_authorities=set(evidence_policy_args["allowed_authorities"]),
                    allowed_statuses=set(evidence_policy_args["allowed_statuses"]),
                    require_freshness=bool(evidence_policy_args["require_freshness"]),
                    require_outcome=bool(evidence_policy_args["require_outcome"]),
                    required_authority_scope=str(evidence_policy_args["required_authority_scope"]),
                    as_of=str(evidence_policy_args["as_of"]),
                ):
                    continue
                evidence.append(self._evidence_from_record(record, score=1.0))
            if required_evidence_refs:
                evidence = self._prioritize_evidence(
                    evidence,
                    required_evidence_refs,
                )
            if (
                preliminary_intent.user_effect == "read"
                and preliminary_intent.topic_mode == "continue"
                and preliminary_intent.followup_semantic_change
                == "same_subject_question"
            ):
                continued_topic_source_refs = list(
                    dict.fromkeys(
                        str(source_ref)
                        for source_ref in prior_topic_state.get("used_source_refs") or []
                        if str(source_ref).strip()
                        and str(source_ref) not in excluded_specific_refs
                        and str(source_ref) in prior_claim_chunks
                    )
                )
                evidence_by_ref = {
                    item.evidence_id: item for item in evidence
                }
                for source_ref in continued_topic_source_refs:
                    record = self._record_for_ref(principal, source_ref)
                    if (
                        record is None
                        or self.repository.answer_scope(record)
                        not in allowed_answer_scopes
                        or self.search._policy_exclusion_reason(
                            record,
                            allowed_authorities=set(
                                evidence_policy_args["allowed_authorities"]
                            ),
                            allowed_statuses=set(
                                evidence_policy_args["allowed_statuses"]
                            ),
                            require_freshness=bool(
                                evidence_policy_args["require_freshness"]
                            ),
                            require_outcome=bool(
                                evidence_policy_args["require_outcome"]
                            ),
                            required_authority_scope=str(
                                evidence_policy_args["required_authority_scope"]
                            ),
                            as_of=str(evidence_policy_args["as_of"]),
                        )
                    ):
                        continue
                    evidence_item = evidence_by_ref.get(source_ref) or self._evidence_from_record(
                        record,
                        score=1.0,
                    )
                    trusted_chunk_ids = set(
                        prior_claim_chunks.get(source_ref) or []
                    )
                    trusted_chunk = next(
                        (
                            item
                            for item in chunks_for_record(record)
                            if str(item.get("chunk_id") or "")
                            in trusted_chunk_ids
                        ),
                        None,
                    )
                    if trusted_chunk is not None:
                        evidence_item = evidence_item.model_copy(
                            update={
                                "score": max(1.0, float(evidence_item.score or 0.0)),
                                "metadata": {
                                    **dict(evidence_item.metadata or {}),
                                    "best_chunk": trusted_chunk,
                                    "from_previous_answer": True,
                                },
                            }
                        )
                    evidence_by_ref[source_ref] = evidence_item
                evidence = [
                    *[
                        evidence_by_ref[source_ref]
                        for source_ref in continued_topic_source_refs
                        if source_ref in evidence_by_ref
                    ],
                    *[
                        item
                        for item in evidence
                        if item.evidence_id
                        not in set(continued_topic_source_refs)
                    ],
                ]
        mark_context_substage("retrieval")
        if preliminary_intent.work_view == "combined" and not current_work_evidence:
            current_work_evidence = [
                EvidenceRef(
                    evidence_id=item.record_id,
                    kind="task",
                    title=item.title,
                    summary=item.description,
                    url=item.url,
                    source="runtime",
                    authority="runtime",
                    metadata={"status": item.status},
                )
                for item in self._current_work_records(
                    principal,
                    employee_id=current_work_employee_id,
                    limit=current_work_limit,
                )
            ]
        if retrieval_provider != "current_work":
            evidence = self._apply_source_set(
                principal,
                str(session["session_id"]),
                evidence,
                page_ref=request.page_ref,
                context_refs=preliminary_intent.context_refs,
            )
            evidence = [
                item
                for item in evidence
                if (
                    (record := self._record_for_ref(principal, item.evidence_id)) is None
                    or self.repository.answer_scope(record) in allowed_answer_scopes
                )
            ]
            # Claim-selected sources are the only candidates that can become
            # final citations. Keep them ahead of broader retrieval and pinned
            # context so the bounded citation window cannot discard the
            # planner's exact provenance.
            if planned_grounded_refs:
                evidence = self._prioritize_evidence(evidence, planned_grounded_refs)
            if continued_topic_source_refs:
                evidence = self._prioritize_evidence(
                    evidence,
                    set(continued_topic_source_refs),
                )
        continued_artifact_source_refs = self._continued_artifact_source_refs(
            principal,
            session=session,
            intent=preliminary_intent,
            source_set=source_set,
            active_artifact=(
                active_session_artifact
                if active_session_artifact and self._owns(principal, active_session_artifact)
                else None
            ),
        )
        if continued_artifact_source_refs and retrieval_provider != "current_work":
            evidence_by_ref = {item.evidence_id: item for item in evidence}
            for source_ref in continued_artifact_source_refs:
                if source_ref in evidence_by_ref:
                    continue
                record = self._record_for_ref(principal, source_ref)
                if record is None or self.repository.answer_scope(record) not in allowed_answer_scopes:
                    continue
                if self.search._policy_exclusion_reason(
                    record,
                    allowed_authorities=set(evidence_policy_args["allowed_authorities"]),
                    allowed_statuses=set(evidence_policy_args["allowed_statuses"]),
                    require_freshness=bool(evidence_policy_args["require_freshness"]),
                    require_outcome=bool(evidence_policy_args["require_outcome"]),
                    required_authority_scope=str(evidence_policy_args["required_authority_scope"]),
                    as_of=str(evidence_policy_args["as_of"]),
                ):
                    continue
                evidence_by_ref[source_ref] = self._evidence_from_record(
                    record,
                    score=1.0,
                )
            evidence = [
                evidence_by_ref[source_ref]
                for source_ref in continued_artifact_source_refs
                if source_ref in evidence_by_ref
            ]
        if excluded_specific_refs:
            evidence = [
                item
                for item in evidence
                if item.evidence_id not in excluded_specific_refs
            ]
            current_work_evidence = [
                item
                for item in current_work_evidence
                if item.evidence_id not in excluded_specific_refs
            ]
        if specific_followup_result_ref and retrieval_provider != "current_work":
            # The planner already resolved this selection against the verified
            # ordered result set.  Keep only that ACL/policy/source-set eligible
            # record; an absent target must become no-evidence instead of a
            # semantically different broad-search answer.
            evidence = [
                item
                for item in evidence
                if item.evidence_id == specific_followup_result_ref
            ]
            continued_topic_source_refs = (
                [specific_followup_result_ref] if evidence else []
            )
        if retrieval_provider != "current_work":
            evidence = self._bind_verified_selection_evidence(
                evidence,
                selection_binding,
            )
        if current_work_evidence:
            try:
                max_display_items = int(
                    definition.handler_config.get("max_display_items") or 20
                )
            except (TypeError, ValueError):
                max_display_items = 20
            max_display_items = max(1, min(max_display_items, 50))
            current_work_evidence = current_work_evidence[:max_display_items]
        if preliminary_intent.work_view == "combined":
            evidence = list(
                {
                    item.evidence_id: item
                    for item in [*evidence, *current_work_evidence]
                }.values()
            )
        if (
            preliminary_intent.operation in {WorkOperation.run, WorkOperation.test}
            and preliminary_intent.target_ref
        ):
            target_record = self._record_for_ref(
                principal,
                preliminary_intent.target_ref,
            )
            if (
                target_record is not None
                and target_record.kind == "action"
                and not self.search._policy_exclusion_reason(
                    target_record,
                    allowed_authorities=set(
                        evidence_policy_args["allowed_authorities"]
                    ),
                    allowed_statuses=set(evidence_policy_args["allowed_statuses"]),
                    require_freshness=bool(
                        evidence_policy_args["require_freshness"]
                    ),
                    require_outcome=bool(evidence_policy_args["require_outcome"]),
                    required_authority_scope=str(
                        evidence_policy_args["required_authority_scope"]
                    ),
                    as_of=str(evidence_policy_args["as_of"]),
                )
            ):
                target_evidence = self._evidence_from_record(target_record, score=1.0)
                evidence = [
                    target_evidence,
                    *[
                        item
                        for item in evidence
                        if item.evidence_id != target_evidence.evidence_id
                    ],
                ]
        retrieved_candidate_refs = [
            item.evidence_id for item in evidence if item.evidence_id
        ]
        protected_context_refs = {
            *planned_grounded_refs,
            *required_planner_refs,
            *continued_topic_source_refs,
            *continued_artifact_source_refs,
            *[
                str(item)
                for item in source_set.get("pinned") or []
                if str(item).strip()
            ],
            str(selection_binding.get("source_ref") or ""),
            str(specific_followup_result_ref or ""),
        }
        evidence, context_excluded_refs, context_source_limit = (
            self._bound_context_evidence(
                evidence,
                definition.handler_config,
                protected_refs=protected_context_refs,
            )
        )
        retrieval_policy_manifest = (
            copy.deepcopy(search_result.policy_manifest)
            if search_result is not None
            else {
                "schema_revision": "evidence-policy-manifest/v1",
                "acl_applied_before_policy": True,
                "source": "current_work",
                "allowed_authorities": ["runtime"],
                "allowed_statuses": [],
                "require_freshness": True,
                "as_of": str(evidence_requirements.as_of or ""),
            }
        )
        retrieval_policy_manifest.update(
            {
                "retrieved_candidate_refs": retrieved_candidate_refs,
                "retrieved_candidate_count": len(retrieved_candidate_refs),
                "returned_refs": [item.evidence_id for item in evidence],
                "returned_count": len(evidence),
                "context_source_limit": context_source_limit,
                "context_excluded_refs": context_excluded_refs,
                "context_exclusion_reason": (
                    "catalog_context_source_limit"
                    if context_excluded_refs
                    else ""
                ),
                "whole_item_selection": True,
                "raw_source_content": False,
                "continued_artifact_source_refs": continued_artifact_source_refs,
                "continued_topic_source_refs": continued_topic_source_refs,
                "specific_followup_result_ref": specific_followup_result_ref,
                "context_freeze": bool(
                    continued_artifact_source_refs
                    or specific_followup_result_ref
                ),
            }
        )
        request.input_delta["_retrieval_policy_manifest"] = retrieval_policy_manifest
        mark_context_substage("selection")
        citations = self._citations_for_evidence(
            principal,
            str(session["session_id"]),
            retrieval_query,
            evidence,
        )
        mark_context_substage("citations")
        if self.capability_handlers.supports_phase(
            definition.handler,
            "post_retrieval_grounding",
        ):
            # Never reuse a planner-time answer after the ExecutionPlan has
            # selected a different evidence set. A repaired planner has
            # already consumed the two-call ceiling, so it falls through to
            # deterministic claim assembly instead of making a third call.
            route["grounded_answer"] = None
            planner_was_repaired = bool(
                (route.get("planner_repair") or {}).get("attempted")
            )
            graph_answer_is_authoritative = bool(
                semantic_plan.graph_query and semantic_plan.graph_query.enabled
            )
            if (
                preliminary_intent.user_effect == "read"
                and preliminary_intent.topic_mode != "clarify"
                and not preliminary_intent.needs_clarification
                and not graph_answer_is_authoritative
                and not planner_was_repaired
            ):
                final_answer_hints = self._grounded_answer_hints(
                    principal,
                    evidence,
                    citations,
                )
                try:
                    grounded_answer, grounded_diagnostics = (
                        self.quick_agent.ground_answer(
                            question=request.question,
                            semantic_plan=semantic_plan,
                            evidence_requirements=(
                                preliminary_intent.evidence_requirements
                            ),
                            hints=final_answer_hints,
                            current_selection={
                                "selection_ref": str(
                                    selection_binding.get("selection_ref") or ""
                                ),
                                "source_ref": str(
                                    selection_binding.get("source_ref") or ""
                                ),
                                "chunk_id": str(
                                    (selection_binding.get("chunk") or {}).get(
                                        "chunk_id"
                                    )
                                    if isinstance(
                                        selection_binding.get("chunk"), dict
                                    )
                                    else ""
                                ),
                            }
                            if selection_binding.get("status") == "verified"
                            else {},
                            model=self.model,
                            answer_input_token_limit=int(
                                definition.handler_config.get(
                                    "answer_input_tokens"
                                )
                                or 12_000
                            ),
                            max_answer_sources=int(
                                definition.handler_config.get(
                                    "max_answer_sources"
                                )
                                or 100
                            ),
                        )
                    )
                except Exception as exc:
                    grounded_answer = None
                    grounded_diagnostics = {
                        "repair": "failed_after_catalog_evidence",
                        "failure": type(exc).__name__,
                    }
                route["grounded_answer"] = grounded_answer
                route["grounded_answer_diagnostics"] = grounded_diagnostics
            else:
                route["grounded_answer_diagnostics"] = {
                    "repair": (
                        "deterministic_after_planner_repair"
                        if planner_was_repaired
                        else "deferred_to_graph_result"
                        if graph_answer_is_authoritative
                        else "not_applicable"
                    )
                }
            request.input_delta["_answer_context_manifest"] = copy.deepcopy(
                (route.get("grounded_answer_diagnostics") or {}).get(
                    "context_manifest"
                )
                or {}
            )
            mark_context_substage("answer")
        context = self._context(
            principal,
            definition,
            request,
            evidence,
            task_mode,
            session=session,
            source_set=source_set,
            resolved_goal=resolved_goal,
            task_override=active_session_task,
            subject_ref=preliminary_intent.target_ref,
            subject_title=preliminary_intent.topic_subject,
            context_token_budget=context_budget.effective_tokens,
            context_budget_resolution=context_budget.as_dict(),
        )
        mark_context_substage("compile")
        context.business_context["user_work_profile"] = self.user_work_profile(
            principal
        )
        # A validated source-intake command is not a Wiki search result. Its
        # exact, authorized input contract opens candidate validation without
        # manufacturing a canonical citation or requiring an unrelated page.
        context.business_context.pop('source_intake_execution_contract',None)
        context.business_context.pop('semantic_interpretation_execution_contract',None)
        context.business_context.pop('semantic_interpretation_rejection',None)
        if (definition.capability_id=='ontology.migration.pipeline-run'
            and request.input_delta.get('metadata_execution')
            and self.metadata_runtime_bindings is not None):
            prepared=self.metadata_runtime_bindings.prepare_metadata(source_intake=self.source_intake,
                principal=principal,value=request.input_delta)
            contract={
                'contract_version':'boi/source-intake-execution-context@1',
                'principal_id':principal.employee_id,'capability_id':definition.capability_id,
                'source_artifact_refs':[item['artifact_ref'] for item in prepared.input['source_artifacts']],
                'metadata_execution_digest':'sha256:'+self._contract_checksum(prepared.input['metadata_execution']),
                'policy_digest':prepared.authorization.policy_digest,'output_authority':'candidate'}
            context.business_context['source_intake_execution_contract']={**contract,
                'contract_digest':'sha256:'+self._contract_checksum(contract)}
        if (definition.capability_id == 'ontology.migration.migration-batch-review'
            and request.input_delta.get('review_mode') == 'semantic_interpretation'):
            from ..governed_runtime.bulk_migration_review import (
                SemanticInterpretationRequest, _interpretation_context)
            try:
                review = SemanticInterpretationRequest.model_validate({
                    key:request.input_delta[key] for key in SemanticInterpretationRequest.model_fields
                    if key in request.input_delta})
                _, closure = _interpretation_context(self.bulk_migration_repository,
                    principal.employee_id, review,
                    lambda manifest,domain:self._semantic_interpretation_runtime_check(principal,manifest,domain))
                contract = {
                    'contract_version':'boi/semantic-interpretation-execution-context@1',
                    'principal_id':principal.employee_id, 'capability_id':definition.capability_id,
                    'run_id':review.run_id, 'shard_id':review.shard_id,
                    'closure_digest':'sha256:'+self._contract_checksum(closure),
                    'output_authority':'meaning_interpretation_plan'}
                context.business_context['semantic_interpretation_execution_contract'] = {
                    **contract, 'contract_digest':'sha256:'+self._contract_checksum(contract)}
            except (BulkMigrationPolicyError, ValueError) as error:
                # An unresolved or stale review target cannot open the work loop.
                # Keep only a static diagnostic category, never exception text,
                # source excerpts or stored references whose ACL may have changed.
                code=str(error) if isinstance(error,BulkMigrationPolicyError) else ''
                category=('access' if code=='INTERPRETATION_REVIEW_ACCESS_DENIED' else
                    'state' if code in {'INTERPRETATION_REVIEW_SHARD_NOT_AVAILABLE',
                        'INTERPRETATION_REVIEW_CANDIDATE_BOUND','INTERPRETATION_REVIEW_LOGICAL_CONTRACT_REQUIRED'} else
                    'stale' if code.startswith('INTERPRETATION_') and code.endswith('_STALE') else 'input')
                context.business_context['semantic_interpretation_rejection']={'category':category}
        harness_binding_manifest = [
            {
                "harness_id": str(binding.get("harness_id") or ""),
                "version": str(binding.get("version") or ""),
                "model_profile": str(binding.get("model_profile") or ""),
                "release_state": str(binding.get("release_state") or ""),
                "active_changes": copy.deepcopy(binding.get("active_changes") or {}),
            }
            for binding in planning_harness_bindings
            if isinstance(binding, dict) and str(binding.get("harness_id") or "")
        ]
        if context.context_manifest is not None:
            context.context_manifest.stage_manifests["harness"] = {
                "bindings": copy.deepcopy(harness_binding_manifest)
            }
        context.manifest["harness_bindings"] = copy.deepcopy(
            harness_binding_manifest
        )
        mark_context_substage("profile")
        self.store.put("contexts", context.context_id, context.model_dump(mode="json"))
        mark_context_substage("persist")
        stage_timings_ms["context"] = round((time.perf_counter() - context_started) * 1000, 2)
        if self._turn_cancelled(request):
            return self._cancelled_turn_response(
                principal=principal,
                session=session,
                request=request,
                run_id=run_id,
                turn_id=turn_id,
                capability_id=capability_id,
            )
        intent = preliminary_intent
        requested_action_key = str(request.input_delta.get("action_key") or "").strip()
        if requested_action_key:
            context.business_context["action_key"] = requested_action_key
            self.store.put("contexts", context.context_id, context.model_dump(mode="json"))
        presentation_started = time.perf_counter()
        work_run = self.learning.create_run(
            principal=principal,
            agent_run_id=run_id,
            session=session,
            context=context,
            intent=intent,
            goal_plan_id=str(goal_plan["goal_plan_id"]),
            loop_policy=intent.loop_contract,
            catalog_revision=self.registry.version,
            planner_schema_revision=PLANNER_SCHEMA_REVISION,
            semantic_plan_ref=str(route.get("semantic_plan_ref") or ""),
            pinned_harness_bindings=planning_harness_bindings,
            persist=persist_execution_record,
        )
        artifacts: list[ArtifactRef] = []
        generated_related_questions: list[RelatedQuestion] = []
        grounded_claims: list[GroundedClaim] = []
        verified_used_source_refs: list[str] = []
        answerability = AnswerabilityReport(
            status="insufficient",
            answer_intent=intent.answer_intent,
        )
        claim_grounded_response = False
        plan_ref = ""
        job_ref = ""
        status: str = "completed"
        active_artifact_row = None
        active_artifact_id = str(session.get("active_artifact_id") or "")
        if active_artifact_id:
            candidate_artifact = self.store.get("artifacts", active_artifact_id)
            if candidate_artifact and self._owns(principal, candidate_artifact):
                active_artifact_row = candidate_artifact
        graph_clarification = ""
        graph_planning_error: SemanticPlanningError | None = None
        response_error_code = ""
        graph_result_bundle = None
        planned_grounded_answer = route.get("grounded_answer")
        has_planned_grounded_content = bool(
            isinstance(planned_grounded_answer, dict)
            and (
                str(planned_grounded_answer.get("summary") or "").strip()
                or any(
                    isinstance(item, dict) and str(item.get("text") or "").strip()
                    for item in planned_grounded_answer.get("claims") or []
                )
            )
        )
        graph_started = time.perf_counter()
        if intent.topic_mode == "clarify" or intent.needs_clarification:
            graph_clarification = semantic_plan.clarification_question.strip()
            if intent.followup_reference_resolution == "ambiguous":
                response_error_code = "needs_input:reference_resolution"
                if not graph_clarification:
                    graph_clarification = "어느 대상을 말씀하시는지 선택해주세요."
                if not re.search(r"(?m)^\s*[-*]\s+\S", graph_clarification):
                    choices = self._verified_clarification_choices(principal, session)
                    if len(choices) >= 2:
                        graph_clarification = (
                            f"{graph_clarification}\n\n선택 가능한 대상:\n"
                            + "\n".join(f"- {item}" for item in choices)
                        )
            work_run["status"] = "waiting_input"
            self.store.put("work_runs", str(work_run["work_run_id"]), work_run)
        try:
            graph_result_bundle = (
                self._graph_result_artifact(
                    principal,
                    session=session,
                    intent=intent,
                    current_work=current_work_evidence,
                    citations=citations,
                    work_run_id=str(work_run["work_run_id"]),
                    capability_id=capability_id,
                    excluded_source_refs=excluded_source_refs,
                )
                if (
                    not graph_clarification
                    and intent.user_effect == "read"
                    and intent.graph_query_draft
                    and intent.graph_query_draft.enabled
                    and intent.graph_query_draft.query_kind in set(definition.graph_query_kinds)
                )
                else None
            )
        except AmbiguousEntityError as exc:
            if intent.presentation_mode == "prose" and has_planned_grounded_content:
                # A relationship traversal is an enrichment for prose. When
                # entity resolution is ambiguous but the Planner supplied
                # directly grounded claims, keep the answer and omit the
                # optional graph instead of blocking the user's read request.
                graph_result_bundle = None
            else:
                try:
                    question = semantic_plan.clarification_question.strip() or (
                        f"'{exc.mention}'에 해당하는 대상을 아래 항목 중에서 하나 선택해주세요."
                    )
                    choices = "\n".join(
                        f"- {item.label}"
                        for item in exc.candidates[:10]
                    )
                    graph_clarification = f"{question}\n\n{choices}" if choices else question
                    intent = intent.model_copy(update={"needs_clarification": True})
                    work_run["intent"] = intent.model_dump(mode="json")
                    work_run["status"] = "waiting_input"
                except SemanticPlanningError as planning_error:
                    graph_planning_error = planning_error
                    response_error_code = planning_error.code
                    work_run["status"] = "failed"
                    work_run["stop_reason"] = "semantic_repair"
                self.store.put("work_runs", str(work_run["work_run_id"]), work_run)
        finally:
            stage_timings_ms["graph"] = round((time.perf_counter() - graph_started) * 1000, 2)

        if graph_planning_error:
            status = "failed"
            citations = []
            answer = AnswerBlock(
                summary="확인할 대상을 안전하게 확정하지 못했습니다.",
                markdown="요청의 대상을 안전하게 확정하지 못했습니다. 다른 기능으로 바꾸어 실행하지 않았습니다.",
            )
        elif graph_clarification:
            status = "needs_input"
            citations = []
            answer = AnswerBlock(
                summary="확인할 대상이 여러 개입니다.",
                markdown=graph_clarification,
            )
        elif (
            work_run.get("status") == "blocked"
            and intent.asset_kind == WorkAssetKind.action
            and intent.operation in {WorkOperation.run, WorkOperation.test}
            and not str(request.input_delta.get("action_key") or "").strip()
            and not str(intent.target_ref or "").startswith("action:")
        ):
            status = "needs_input"
            citations = []
            response_error_code = "needs_input:action_target"
            choices = self._verified_action_target_choices(
                principal,
                evidence,
                limit=3,
            )
            choice_markdown = (
                "\n\n선택 가능한 등록 Action:\n"
                + "\n".join(f"- {item}" for item in choices)
                if choices
                else ""
            )
            answer = AnswerBlock(
                summary="실행할 Action을 선택해주세요.",
                markdown=(
                    "등록된 실행 대상을 자동으로 고르지 않았습니다. 아래 ACL·readiness 검사를 통과한 "
                    "Action 중 하나를 선택하면 입력, 예상 결과, 위험과 dry-run 계획을 보여드립니다."
                    f"{choice_markdown}"
                ),
            )
        elif work_run.get("status") == "blocked":
            status = "needs_input"
            citations = []
            review_rejection=context.business_context.get('semantic_interpretation_rejection')
            if review_rejection:
                messages={
                    'access':('이 의미 검토 대상에 접근할 수 없습니다.', '접근 가능한 작업과 검토 권한을 확인해 주세요.'),
                    'state':('현재 작업 상태에서는 의미 검토를 시작할 수 없습니다.',
                        '작업의 의미 계약 생성 상태와 Attention을 확인해 주세요. 누락된 계약이나 참조가 있는 결과는 완료된 것으로 처리하지 않습니다.'),
                    'stale':('검토 기준이 바뀌어 기존 미리보기를 사용할 수 없습니다.',
                        '현재 원문·정의·권한 기준으로 미리보기를 갱신한 뒤 다시 검토해 주세요.'),
                    'input':('의미 검토 입력을 확인해야 합니다.', '선택한 작업의 현재 미리보기를 확인해 주세요.')}
                summary,detail=messages.get(review_rejection.get('category'),messages['input'])
                response_error_code='needs_input:semantic_interpretation'
                answer=AnswerBlock(summary=summary,markdown=summary+'\n\n'+detail)
            else:
                answer = AnswerBlock(
                    summary="현재 업무 맥락을 먼저 확인해야 합니다.",
                    markdown=(
                        "현재 화면이나 대상 업무를 안전하게 확인하지 못했습니다. "
                        "대상 문서나 Task를 지정하면 Wiki 전체의 관련 지식과 함께 다시 확인하겠습니다."
                    ),
                )
        elif active_artifact_row and intent.operation in {WorkOperation.validate, WorkOperation.test}:
            domain_test: dict[str, Any] = {}
            artifact_domain = (
                active_artifact_row.get("domain")
                if isinstance(active_artifact_row.get("domain"), dict)
                else {}
            )
            if (
                intent.operation == WorkOperation.test
                and artifact_domain.get("domain_kind") == "business_event_definition"
                and artifact_domain.get("domain_ref")
                and self.domain_services.supports("business_event.draft.test")
            ):
                domain_test = self.domain_services.execute(
                    "business_event.draft.test",
                    principal,
                    {
                        "domain_ref": str(artifact_domain.get("domain_ref") or ""),
                        "sample_signal": (
                            request.input_delta.get("sample_signal")
                            if isinstance(request.input_delta.get("sample_signal"), dict)
                            else (active_artifact_row.get("draft") or {}).get("sample_signal") or {}
                        ),
                        "artifact_id": str(active_artifact_row.get("artifact_id") or ""),
                        "work_session_id": str(session.get("session_id") or ""),
                    },
                )
                active_artifact_row["domain_test"] = domain_test
                active_artifact_row["updated_at"] = now_iso()
                self.store.put("artifacts", str(active_artifact_row["artifact_id"]), active_artifact_row)
            artifact_type = self._artifact_contract_type(active_artifact_row) or "draft"
            preview_results = [
                self.harnesses.evaluate(
                    harness_id,
                    phase="test" if intent.operation == WorkOperation.test else "validate",
                    intent=intent,
                    context=context,
                    artifact=active_artifact_row,
                    task_mode=context.task_mode,
                )
                for harness_id in self.harnesses.harnesses_for(
                    intent,
                    artifact_type,
                    phase="test" if intent.operation == WorkOperation.test else "validate",
                )
            ]
            blockers = [message for item in preview_results for message in item.blockers]
            artifacts.append(
                ArtifactRef(
                    artifact_id=str(active_artifact_row["artifact_id"]),
                    artifact_type=artifact_type,
                    title=str(active_artifact_row.get("title") or "작업 초안"),
                    status=str(active_artifact_row.get("status") or "draft"),  # type: ignore[arg-type]
                    url=f"/agent?session={session['session_id']}&artifact={active_artifact_row['artifact_id']}",
                    metadata={
                        "capability_id": active_artifact_row.get("capability_id") or "",
                        "revision": active_artifact_row.get("revision") or 1,
                        "domain_test": domain_test,
                    },
                )
            )
            if blockers:
                status = "needs_input"
                answer = AnswerBlock(
                    summary=f"보완할 항목이 {len(blockers)}개 있습니다.",
                    markdown="### 보완 필요\n\n" + "\n".join(f"- {item}" for item in blockers),
                )
            else:
                if domain_test:
                    decision = domain_test.get("decision") if isinstance(domain_test.get("decision"), dict) else {}
                    answer = AnswerBlock(
                        summary=str(domain_test.get("message") or "샘플 판단을 완료했습니다."),
                        markdown=(
                            "### 샘플 판단 결과\n\n"
                            f"- 결과: {decision.get('decision') or '확인 필요'}\n"
                            f"- 이유: {decision.get('reason') or domain_test.get('message') or '-'}\n\n"
                            "실제 업무 이벤트를 발행하지 않았고 판단 상태도 변경하지 않았습니다."
                        ),
                    )
                else:
                    answer = AnswerBlock(
                        summary="현재 초안이 업무 품질 기준을 통과했습니다.",
                        markdown="현재 초안의 업무 맥락, 완료 항목, 근거와 실행 안전 기준을 확인했습니다.",
                    )
        elif (
            active_artifact_row
            and self._artifact_contract_type(active_artifact_row) == "sop_draft"
            and intent.operation == WorkOperation.refine
            and bool(session.get("selected_task_id"))
        ):
            draft = active_artifact_row.get("draft") if isinstance(active_artifact_row.get("draft"), dict) else {}
            tasks = [item for item in draft.get("tasks") or [] if isinstance(item, dict)]
            selected_task_id = str(session.get("selected_task_id") or "")
            task = next((item for item in tasks if item.get("task_id") == selected_task_id), None) or (tasks[0] if tasks else None)
            if not task:
                status = "needs_input"
                answer = AnswerBlock(
                    summary="다듬을 Task가 필요합니다.",
                    markdown="SOP에 Task를 추가하거나 다듬을 Task를 선택해주세요.",
                )
            else:
                if context.task_mode == TaskMode.manual:
                    status = "needs_input"
                    answer = AnswerBlock(
                        summary="이 Task는 사람이 직접 다듬는 방식입니다.",
                        markdown="현재 내용을 직접 편집하거나, AI 변경 제안이 필요하면 수행 방식을 Copilot으로 바꿔주세요.",
                    )
                else:
                    proposal = self.refine_task_preview(
                        principal,
                        str(active_artifact_row["artifact_id"]),
                        str(task["task_id"]),
                        TaskRefinePreviewRequest(
                            expected_revision=int(active_artifact_row.get("revision") or 1),
                            instruction=request.question,
                        ),
                    )
                    artifacts.append(
                        ArtifactRef(
                            artifact_id=str(active_artifact_row["artifact_id"]),
                            artifact_type="sop_draft",
                            title=str(active_artifact_row.get("title") or "SOP 초안"),
                            status="draft",
                            url=f"/agent?session={session['session_id']}&artifact={active_artifact_row['artifact_id']}",
                            metadata={
                                "capability_id": str(active_artifact_row.get("capability_id") or ""),
                                "revision": active_artifact_row.get("revision") or 1,
                                "proposal_id": proposal["proposal_id"],
                                "task_id": task["task_id"],
                            },
                        )
                    )
                    answer = AnswerBlock(
                        summary=f"'{task.get('name') or 'Task'}'의 변경 제안을 준비했습니다.",
                        markdown="기존 업무 목적은 유지했습니다. 변경 전·후를 확인하고 적용할 내용만 선택하세요.",
                    )
        elif intent.operation in {WorkOperation.run, WorkOperation.test, WorkOperation.promote}:
            target_ref = intent.target_ref or active_artifact_id or (context.page_anchor.ref if context.page_anchor else "")
            typed_action_key = (
                target_ref.removeprefix("action:")
                if intent.asset_kind == WorkAssetKind.action
                and target_ref.startswith("action:")
                else ""
            )
            action_key = str(
                typed_action_key
                or request.input_delta.get("action_key")
                or context.business_context.get("action_key")
            ).strip()
            domain_operation = ""
            domain_payload: dict[str, Any] = {}
            if intent.operation in {WorkOperation.run, WorkOperation.test} and action_key:
                domain_operation = "action.invoke"
                domain_payload = {
                    "action_key": action_key,
                    "payload": request.input_delta.get("payload")
                    if isinstance(request.input_delta.get("payload"), dict)
                    else {},
                    "event": request.input_delta.get("event")
                    if isinstance(request.input_delta.get("event"), dict)
                    else {},
                    "boi_id": str(request.input_delta.get("boi_id") or ""),
                    "dry_run": True if intent.operation == WorkOperation.test else bool(request.input_delta.get("dry_run", True)),
                    "idempotency_key": str(request.input_delta.get("idempotency_key") or new_id("agent-plan")),
                }
            if intent.operation in {WorkOperation.run, WorkOperation.test} and not domain_operation:
                status = "needs_input"
                answer = AnswerBlock(
                    summary="실행할 Action을 먼저 확인해야 합니다.",
                    markdown="Action 이름이나 연결된 Task를 지정하면 입력값과 예상 결과를 확인하는 실행 계획을 만들겠습니다.",
                )
            else:
                plan_ref = new_id("plan")
                self.store.put(
                    "plans",
                    plan_ref,
                    {
                        "plan_id": plan_ref,
                        "employee_id": principal.employee_id,
                        "capability_id": capability_id,
                        "operation": intent.operation.value,
                        "target_ref": target_ref,
                        "status": "draft",
                        "risk": intent.risk.value,
                        "production_changed": False,
                        "work_run_id": work_run["work_run_id"],
                        "domain_operation": domain_operation,
                        "domain_payload": domain_payload,
                        "created_at": now_iso(),
                    },
                )
                answer = AnswerBlock(
                    summary="실행 전에 확인할 계획을 준비했습니다.",
                    markdown="대상, 입력값, 예상 결과와 위험도를 확인한 뒤 승인해야 기존 업무 API의 실행 단계로 이어집니다. 아직 실행하거나 게시하지 않았습니다.",
                )
                if domain_operation == "action.invoke":
                    action_ref = f"action:{action_key}"
                    action_evidence = next(
                        (
                            item
                            for item in evidence
                            if item.evidence_id in {target_ref, action_ref}
                            and item.kind == "action"
                        ),
                        None,
                    )
                    action_citation = next(
                        (
                            item
                            for item in citations
                            if action_evidence is not None
                            and item.source_ref == action_evidence.evidence_id
                            and item.chunk_id
                        ),
                        None,
                    )
                    if action_evidence is not None and action_citation is not None:
                        claim_text = compact_text(
                            action_evidence.summary
                            or action_citation.excerpt
                            or action_evidence.title,
                            1000,
                        )
                        grounded_claims.append(
                            GroundedClaim(
                                claim_id="action-preview-contract",
                                text=claim_text,
                                claim_kind="procedure",
                                source_scope="operational",
                                source_refs=[action_evidence.evidence_id],
                                supporting_chunk_ids=[action_citation.chunk_id],
                                support_status="supported",
                                confidence=1.0,
                                required_for_answer=True,
                            )
                        )
                        verified_used_source_refs.append(action_evidence.evidence_id)
                        claim_grounded_response = True
                        answerability = AnswerabilityReport(
                            status="grounded",
                            answer_intent="procedure",
                            supported_claim_count=1,
                        )
                        answer.markdown = (
                            f"{answer.markdown}\n\n### Action 계약 근거\n"
                            f"- {claim_text} "
                            f"[근거](/api/v2/citations/{action_citation.citation_id})"
                        )
        elif graph_result_bundle is not None:
            (
                answer,
                graph_artifact,
                graph_evidence,
                graph_claim_specs,
                graph_missing_evidence,
            ) = graph_result_bundle
            artifacts.append(graph_artifact)
            evidence = graph_evidence or evidence
            if graph_evidence:
                self._merge_context_evidence(context, graph_evidence)
            citation_evidence = [
                item
                for item in graph_evidence
                if not item.evidence_id.startswith("graph-evidence:")
            ]
            if intent.work_view == "combined":
                citation_evidence.extend(current_work_evidence)
            citations = self._citations_for_evidence(
                principal,
                str(session["session_id"]),
                resolved_goal,
                citation_evidence,
            )
            citation_by_ref = {item.source_ref: item for item in citations if item.chunk_id}
            seen_graph_claim_bindings: set[
                tuple[str, str, str, str, str, str]
            ] = set()
            for index, claim_spec in enumerate(graph_claim_specs, start=1):
                claim_refs = [
                    str(source_ref)
                    for source_ref in claim_spec.get("source_refs") or []
                    if str(source_ref) in citation_by_ref
                ]
                # ``_graph_result_artifact`` has already enforced evidence
                # scope, authority, freshness, work-view boundaries, and the
                # Catalog projection allowlist before it emits a displayed
                # relation claim.  Filtering the same claim again by the
                # primary work view drops legitimate supplemental execution
                # evidence (for example Agent/System usage requested alongside
                # official responsibility), leaving displayed relation lines
                # without typed claim bindings.  Bind every relation that
                # survived that common policy boundary to its exact citation.
                if not claim_refs:
                    continue
                subject_ref = str(claim_spec.get("subject_ref") or "")
                predicate = str(claim_spec.get("predicate") or "")
                object_ref = str(claim_spec.get("object_ref") or "")
                provenance = str(claim_spec.get("provenance") or "")
                claim_text = compact_text(str(claim_spec.get("text") or ""), 1200)
                if not all(
                    (subject_ref, predicate, object_ref, provenance, claim_text)
                ):
                    continue
                for source_ref in claim_refs:
                    citation = citation_by_ref[source_ref]
                    binding = (
                        subject_ref,
                        predicate,
                        object_ref,
                        source_ref,
                        citation.chunk_id,
                        provenance,
                    )
                    if not citation.chunk_id or binding in seen_graph_claim_bindings:
                        continue
                    seen_graph_claim_bindings.add(binding)
                    source_record = self._record_for_ref(principal, source_ref)
                    source_scope = (
                        self.repository.answer_scope(source_record)
                        if source_record is not None
                        else "validation"
                    )
                    if source_scope not in {"canonical", "operational", "validation"}:
                        source_scope = "validation"
                    grounded_claims.append(
                        GroundedClaim(
                            claim_id=f"graph-relation-{index}-{len(grounded_claims) + 1}",
                            text=claim_text,
                            claim_kind="relationship",
                            source_scope=source_scope,
                            source_refs=[source_ref],
                            supporting_chunk_ids=[citation.chunk_id],
                            evidence_bindings=[
                                ClaimEvidenceBinding(
                                    subject_ref=subject_ref,
                                    predicate=predicate,
                                    object_ref=object_ref,
                                    source_ref=source_ref,
                                    chunk_id=citation.chunk_id,
                                    provenance=provenance,
                                )
                            ],
                            support_status="supported",
                            confidence=1.0,
                            required_for_answer=True,
                        )
                    )
            if intent.work_view == "combined":
                current_work_by_ref = {
                    item.evidence_id: item for item in current_work_evidence
                }
                for citation in citations:
                    work_item = current_work_by_ref.get(citation.source_ref)
                    if work_item is None or not citation.chunk_id:
                        continue
                    grounded_claims.append(
                        GroundedClaim(
                            claim_id=f"current-work-{len(grounded_claims) + 1}",
                            text=compact_text(citation.excerpt, 1200),
                            claim_kind="work",
                            source_scope="operational",
                            source_refs=[citation.source_ref],
                            supporting_chunk_ids=[citation.chunk_id],
                            support_status="supported",
                            confidence=1.0,
                            required_for_answer=True,
                        )
                    )
            official_responsibility_supported = any(
                claim.support_status == "supported"
                and claim.claim_kind == "relationship"
                and claim.source_scope == "canonical"
                and any(
                    binding.predicate in {"has_role", "responsible_for"}
                    and binding.provenance
                    in {"canonical_declared", "human_verified"}
                    for binding in claim.evidence_bindings
                )
                for claim in grounded_claims
            )
            if (
                intent.work_view in {"responsibility", "combined"}
                and not official_responsibility_supported
            ):
                grounded_claims.append(
                    GroundedClaim(
                        claim_id="official-responsibility-not-grounded",
                        text=(
                            "공식 역할·책임 관계를 확인할 수 없습니다. "
                            "공식 소속을 책임으로 해석하지 않았습니다."
                        ),
                        claim_kind="relationship",
                        source_scope="canonical",
                        source_refs=[],
                        supporting_chunk_ids=[],
                        evidence_bindings=[],
                        support_status="unsupported",
                        confidence=1.0,
                        required_for_answer=True,
                    )
                )
            claim_grounded_response = bool(grounded_claims)
            verified_used_source_refs.extend(
                source_ref
                for claim in grounded_claims
                for source_ref in claim.source_refs
                if source_ref
            )
            answerability = AnswerabilityReport(
                status=(
                    "partial"
                    if grounded_claims and graph_missing_evidence
                    else "grounded"
                    if grounded_claims
                    else "insufficient"
                ),
                answer_intent="relationship",
                supported_claim_count=sum(
                    item.support_status == "supported" for item in grounded_claims
                ),
                unsupported_claim_count=len(graph_missing_evidence),
                missing_evidence=(
                    graph_missing_evidence
                    if graph_missing_evidence
                    else []
                    if grounded_claims
                    else ["관계 결과를 직접 뒷받침하는 내부 기록이 없습니다."]
                ),
            )
            unsupported_required_claims = [
                item
                for item in grounded_claims
                if item.required_for_answer
                and item.support_status in {"partial", "unsupported"}
            ]
            if unsupported_required_claims:
                unsupported_texts = list(
                    dict.fromkeys(
                        item.text.strip()
                        for item in unsupported_required_claims
                        if item.text.strip()
                    )
                )
                answerability.status = "partial"
                answerability.unsupported_claim_count = len(
                    unsupported_required_claims
                )
                answerability.missing_evidence = unsupported_texts
                if "### 확인하지 못한 내용" not in answer.markdown:
                    answer.markdown += (
                        "\n\n### 확인하지 못한 내용\n"
                        + "\n".join(f"- {item}" for item in unsupported_texts)
                    )
            if citations:
                markers = " ".join(
                    f"[{index}](/api/v2/citations/{item.citation_id})"
                    for index, item in enumerate(citations, start=1)
                )
                answer.markdown = f"{answer.markdown}\n\n관계 근거 {markers}"
        elif intent.presentation_mode == "mermaid" and bool(definition.graph_query_kinds):
            mermaid_evidence, mermaid_citations = (
                self._continued_topic_presentation_sources(
                    request,
                    intent,
                    evidence,
                    citations,
                )
            )
            # The graph generator and its safe table fallback must expose the
            # same bounded source set. Otherwise a failed graph could expand
            # into every retrieved document and violate citation/display
            # parity even though the successful path was catalog-bounded.
            mermaid_evidence, mermaid_citations = (
                self._select_mermaid_presentation_sources(
                    capability_id=capability_id,
                    intent=intent,
                    evidence=mermaid_evidence,
                    citations=mermaid_citations,
                )
            )
            try:
                answer, diagram_artifact, generated_related_questions = self._mermaid_artifact(
                    principal,
                    request=request,
                    session=session,
                    intent=intent,
                    evidence=mermaid_evidence,
                    citations=mermaid_citations,
                    work_run_id=str(work_run["work_run_id"]),
                    capability_id=capability_id,
                )
                artifacts.append(diagram_artifact)
                diagram_row = self.store.get("artifacts", diagram_artifact.artifact_id) or {}
                diagram_graph = (
                    diagram_row.get("draft")
                    if isinstance(diagram_row.get("draft"), dict)
                    else {}
                )
                grounded_claims = self._grounded_claims_for_mermaid_graph(
                    diagram_graph,
                    mermaid_citations,
                    source_scope=intent.answer_source_scope,
                )
                supported_mermaid_claims = [
                    claim
                    for claim in grounded_claims
                    if claim.support_status == "supported"
                ]
                unsupported_mermaid_claims = [
                    claim
                    for claim in grounded_claims
                    if claim.support_status in {"partial", "unsupported"}
                ]
                claim_grounded_response = bool(supported_mermaid_claims)
                verified_used_source_refs.extend(
                    source_ref
                    for claim in supported_mermaid_claims
                    for source_ref in claim.source_refs
                    if source_ref
                )
                answerability = AnswerabilityReport(
                    status=(
                        "partial"
                        if supported_mermaid_claims and unsupported_mermaid_claims
                        else "grounded"
                        if supported_mermaid_claims
                        else "insufficient"
                    ),
                    answer_intent="relationship",
                    supported_claim_count=len(supported_mermaid_claims),
                    unsupported_claim_count=len(unsupported_mermaid_claims),
                    missing_evidence=(
                        [claim.text for claim in unsupported_mermaid_claims]
                        if supported_mermaid_claims and unsupported_mermaid_claims
                        else []
                        if supported_mermaid_claims
                        else ["그림의 관계를 직접 뒷받침하는 내부 근거가 없습니다."]
                    ),
                )
            except RuntimeError as exc:
                work_run["diagnostics"] = [
                    *[item for item in work_run.get("diagnostics") or [] if isinstance(item, dict)],
                    {
                        "kind": "mermaid_validation",
                        "detail": compact_text(str(exc), 1000),
                        "created_at": now_iso(),
                    },
                ][-10:]
                self.store.put("work_runs", str(work_run["work_run_id"]), work_run)
                evidence_by_ref = {
                    item.evidence_id: item for item in mermaid_evidence
                }
                fallback_claims = [
                    GroundedClaim(
                        claim_id=f"presentation-fallback-{index}",
                        text=compact_text(
                            citation.excerpt
                            or evidence_by_ref[citation.source_ref].summary,
                            500,
                        ),
                        claim_kind="relationship",
                        source_scope=intent.answer_source_scope,
                        source_refs=[citation.source_ref],
                        supporting_chunk_ids=[citation.chunk_id],
                        support_status="supported",
                        confidence=1.0,
                        required_for_answer=False,
                    )
                    for index, citation in enumerate(mermaid_citations, start=1)
                    if citation.source_ref in evidence_by_ref
                    and citation.chunk_id
                    and (citation.excerpt or evidence_by_ref[citation.source_ref].summary)
                ]
                fallback_table = self._grounded_evidence_table(
                    mermaid_evidence,
                    mermaid_citations,
                )
                if fallback_claims and fallback_table is not None:
                    table_answer, fallback_questions = fallback_table
                    answer = AnswerBlock(
                        summary="흐름 그림 대신 검증된 근거 표를 준비했습니다.",
                        markdown=(
                            "### 흐름 그림 대체 결과\n\n"
                            "검증 가능한 Mermaid를 만들지 못해 같은 내부 근거를 표로 정리했습니다.\n\n"
                            f"{table_answer.markdown}"
                        ),
                    )
                    fallback_artifact = self._grounded_claims_table_artifact(
                        principal,
                        session=session,
                        claims=fallback_claims,
                        work_run_id=str(work_run["work_run_id"]),
                        capability_id=capability_id,
                    )
                    if fallback_artifact is not None:
                        fallback_artifact.metadata["fallback_from"] = "mermaid"
                        artifacts.append(fallback_artifact)
                    generated_related_questions.extend(fallback_questions)
                    grounded_claims = fallback_claims
                    claim_grounded_response = True
                    verified_used_source_refs.extend(
                        source_ref
                        for claim in fallback_claims
                        for source_ref in claim.source_refs
                    )
                    answerability = AnswerabilityReport(
                        status="grounded",
                        answer_intent="relationship",
                        supported_claim_count=len(fallback_claims),
                    )
                    response_error_code = "presentation_fallback"
                    status = "completed"
                else:
                    status = "needs_input"
                    answer = AnswerBlock(
                        summary="흐름 그림을 만들지 못했습니다.",
                        markdown=(
                            "### 흐름 그림 생성 실패\n\n"
                            "질문의 대상과 직접 연결된 근거만으로는 검증 가능한 흐름 그림이나 대체 표를 "
                            "구성하지 못했습니다. 확인할 대상이나 관계를 조금 더 구체적으로 지정해주세요."
                        ),
                    )
        else:
            handler_context = CapabilityHandlerContext(
                principal=principal,
                definition=definition,
                request=request,
                session=session,
                intent=intent,
                work_context=context,
                evidence=evidence,
                citations=citations,
                current_work_evidence=current_work_evidence,
                work_run=work_run,
                route=route,
                active_artifact=active_artifact_row,
                run_id=run_id,
                turn_id=turn_id,
                goal_plan=goal_plan,
                source_set=source_set,
                invocation_channel=invocation_channel,
            )
            handler_result = self.capability_handlers.execute(
                definition.handler,
                handler_context,
            )
            handler_result = self._apply_grounded_output_contract(
                handler_context,
                handler_result,
            )
            answer = handler_result.answer
            status = handler_result.status
            artifacts.extend(handler_result.artifacts)
            generated_related_questions.extend(handler_result.related_questions)
            grounded_claims = handler_result.grounded_claims
            verified_used_source_refs.extend(handler_result.used_source_refs)
            if handler_result.answerability is not None:
                answerability = handler_result.answerability
            if handler_result.citations is not None:
                citations = handler_result.citations
            if handler_result.evidence is not None:
                evidence = handler_result.evidence
                self._merge_context_evidence(context, evidence)
            plan_ref = handler_result.plan_ref
            job_ref = handler_result.job_ref
            claim_grounded_response = handler_result.claim_grounded_response

        if self._turn_cancelled(request):
            return self._cancelled_turn_response(
                principal=principal,
                session=session,
                request=request,
                run_id=run_id,
                turn_id=turn_id,
                work_run=work_run,
                capability_id=capability_id,
            )

        for artifact in artifacts:
            artifact_source_refs = (
                artifact.metadata.get("display_source_refs")
                if "display_source_refs" in artifact.metadata
                else artifact.metadata.get("source_refs")
            )
            verified_used_source_refs.extend(
                str(item)
                for item in artifact_source_refs or []
                if str(item)
            )
        verified_used_set = set(verified_used_source_refs)
        citations = [item for item in citations if item.source_ref in verified_used_set]
        verified_used_source_refs = list(
            dict.fromkeys(item.source_ref for item in citations if item.source_ref)
        )

        if (
            intent.presentation_mode == "table"
            and claim_grounded_response
            and not artifacts
        ):
            table_artifact = self._grounded_claims_table_artifact(
                principal,
                session=session,
                claims=grounded_claims,
                work_run_id=str(work_run["work_run_id"]),
                capability_id=capability_id,
            )
            if table_artifact is not None:
                artifacts.append(table_artifact)

        stage_timings_ms["presentation"] = round(
            (time.perf_counter() - presentation_started) * 1000,
            2,
        )

        if citations and not claim_grounded_response:
            markers = " ".join(
                f"[{index}](/api/v2/citations/{item.citation_id})"
                for index, item in enumerate(citations, start=1)
            )
            answer.markdown = f"{answer.markdown}\n\n사용한 지식 {markers}"

        self._emit_turn_progress(
            progress_sink,
            "composing",
            "근거와 검증 결과를 바탕으로 답변을 정리하고 있습니다.",
            citation_count=len(citations),
            artifact_count=len(artifacts),
        )

        finalize_started = time.perf_counter()
        context.artifact_refs = artifacts
        context.loop_delta = {
            "kind": "job_queued" if job_ref else "artifact_created" if artifacts else "evidence_selected",
            "evidence_ids": [item.evidence_id for item in evidence],
            "artifact_ids": [item.artifact_id for item in artifacts],
            "job_id": job_ref,
        }
        context.manifest.update({"plan_id": plan_ref, "job_id": job_ref})
        self.store.put("contexts", context.context_id, context.model_dump(mode="json"))

        source_set = self._ensure_source_set(principal, str(session["session_id"]))
        related_questions = generated_related_questions
        artifact_payloads = [
            value
            for item in artifacts
            if (value := self.store.get("artifacts", item.artifact_id)) is not None
        ]
        citation_chunks_by_ref = {
            item.source_ref: item.chunk_id
            for item in citations
            if item.source_ref and item.chunk_id
        }
        evidence_bindings = {
            source_ref: {
                "chunk_ids": [chunk_id],
                "claim_bindings": [
                    {
                        "claim_id": claim.claim_id,
                        "text": claim.text,
                        "support_status": claim.support_status,
                        "chunk_ids": [
                            item
                            for item in claim.supporting_chunk_ids
                            if item == chunk_id
                        ],
                    }
                    for claim in grounded_claims
                    if claim.support_status == "supported"
                    and source_ref in claim.source_refs
                    and chunk_id in claim.supporting_chunk_ids
                ],
            }
            for source_ref, chunk_id in citation_chunks_by_ref.items()
        }
        work_run, knowledge_candidates = self.learning.finish_run(
            principal=principal,
            work_run=work_run,
            context=context,
            intent=intent,
            response_status=status,
            answer_summary=answer.summary,
            artifacts=artifact_payloads,
            evidence_refs=[item.source_ref for item in citations],
            evidence_bindings=evidence_bindings,
            job_id=job_ref,
        )
        harness_results = [HarnessResult.model_validate(raw) for raw in work_run.get("harness_results") or []]
        goal_plan = self._finish_goal_plan(
            goal_plan,
            evidence=evidence,
            artifacts=artifacts,
            queued=bool(job_ref),
            response_status=status,
            plan_ref=plan_ref,
            intent=intent,
            work_run=work_run,
        )
        progress = [
            {
                "step_id": item.get("step_id"),
                "label": item.get("label"),
                "status": item.get("status"),
            }
            for item in goal_plan.get("steps") or []
        ]

        topic_state_ref = f"topic:{session['session_id']}:{turn_id}"

        response = AgentTurnResponse(
            run_id=run_id,
            turn_id=turn_id,
            conversation_id=str(session["conversation_id"]),
            work_session_id=str(session["session_id"]),
            status=status,  # type: ignore[arg-type]
            capability_id=capability_id,
            answer=answer,
            error_code=response_error_code,
            evidence_refs=evidence,
            artifact_refs=artifacts,
            offers=[],
            next_actions=self._next_actions(
                work_session_id=str(session["session_id"]),
                artifacts=artifacts,
                evidence=evidence,
                plan_ref=plan_ref,
            ),
            context_ref=context.context_id,
            plan_ref=plan_ref,
            job_ref=job_ref,
            goal_plan_ref=str(goal_plan["goal_plan_id"]),
            source_set_ref=str(source_set["source_set_id"]),
            citations=citations,
            used_source_refs=verified_used_source_refs,
            related_questions=related_questions,
            grounding_status=public_grounding_status(answerability.status),  # type: ignore[arg-type]
            answerability=answerability,
            grounded_claims=grounded_claims,
            topic_state_ref=topic_state_ref,
            progress=progress,
            work_run_id=str(work_run["work_run_id"]),
            work_intent=intent,
            graph_result_ref=next(
                (
                    item.artifact_id
                    for item in artifacts
                    if item.artifact_type in {"ontology_graph", "mermaid_diagram"}
                ),
                "",
            ),
            loop_state={
                "flow": (work_run.get("loop") or {}).get("flow") or [],
                "policy": (work_run.get("loop") or {}).get("policy") or {},
                "iteration_count": (work_run.get("loop") or {}).get("iteration_count") or 0,
                "decision": work_run.get("decision") or "",
                "status": work_run.get("status") or "",
                "revision": work_run.get("revision") or 1,
            },
            harness_results=harness_results,
            knowledge_candidates=knowledge_candidates,
            semantic_plan_ref=str(route.get("semantic_plan_ref") or ""),
            stop_reason=str(work_run.get("stop_reason") or ""),
            loop_contract=LoopPolicy.model_validate(
                (work_run.get("loop") or {}).get("policy") or intent.loop_contract
            ),
            context_usage={
                "page_anchor": context.page_anchor.model_dump(mode="json") if context.page_anchor else None,
                "goal_anchor": context.goal_anchor.model_dump(mode="json") if context.goal_anchor else None,
                "resolved_goal": intent.resolved_goal,
                "presentation_mode": intent.presentation_mode,
                "context_refs": list(intent.context_refs),
                "surface_context": dict(context.surface_context),
                "selection_binding": copy.deepcopy(
                    context.manifest.get("selection_binding") or {}
                ),
                "selected_source_count": len(context.evidence_refs),
                "missing_evidence": (context.evidence_summary or {}).get("missing") or [],
                "raw_content_in_prompt": bool(
                    context.context_manifest
                    and context.context_manifest.raw_content_in_prompt
                ),
                "bounded_selection_in_prompt": bool(
                    context.context_manifest
                    and context.context_manifest.bounded_selection_in_prompt
                ),
                "resource_budget": context_budget.as_dict(),
            },
        )
        response = self._enforce_response_budget(response)
        work_run = self.learning.reconcile_response_evidence(
            context=context,
            work_run=work_run,
            displayed_source_refs=response.used_source_refs,
            citations=[item.model_dump(mode="json") for item in response.citations],
            claims=[item.model_dump(mode="json") for item in response.grounded_claims],
        )
        source_set = self._update_auto_sources(
            principal,
            str(session["session_id"]),
            evidence,
            request.external_artifact_refs,
            used_refs=response.used_source_refs,
        )
        response.source_set_ref = str(source_set["source_set_id"])
        response.presentation_plan = presentation_plan(response)
        a2ui_started = time.perf_counter()
        try:
            a2ui_surface = compile_surface(response)
        except (TypeError, ValueError):
            a2ui_surface = {}
        if a2ui_surface:
            response.a2ui_surface_ref = str(a2ui_surface["surface_id"])
            a2ui_surface["employee_id"] = principal.employee_id
            self.store.put("a2ui_surfaces", response.a2ui_surface_ref, a2ui_surface)
            for artifact in artifacts:
                stored_artifact = self.store.get("artifacts", artifact.artifact_id)
                if not stored_artifact or not self._owns(principal, stored_artifact):
                    continue
                stored_artifact["a2ui_surface_ref"] = response.a2ui_surface_ref
                self.store.put("artifacts", artifact.artifact_id, stored_artifact)
                artifact.metadata["a2ui_surface_ref"] = response.a2ui_surface_ref
        stage_timings_ms["a2ui"] = round((time.perf_counter() - a2ui_started) * 1000, 2)
        stage_timings_ms["finalize"] = round((time.perf_counter() - finalize_started) * 1000, 2)
        stage_timings_ms["total"] = round((time.perf_counter() - turn_started) * 1000, 2)
        response.context_usage["timings_ms"] = stage_timings_ms
        run_payload = {
            "run_id": run_id,
            "employee_id": principal.employee_id,
            "conversation_id": str(session["conversation_id"]),
            "work_session_id": str(session["session_id"]),
            "capability_id": capability_id,
            "status": status,
            "context_id": context.context_id,
            "plan_id": plan_ref,
            "job_id": job_ref,
            "goal_plan_id": goal_plan["goal_plan_id"],
            "source_set_id": source_set["source_set_id"],
            "work_run_id": work_run["work_run_id"],
            "semantic_plan_ref": str(route.get("semantic_plan_ref") or ""),
            "events": [
                {"event": "accepted", "run_id": run_id},
                {
                    "event": "sources.selected",
                    "source_set_ref": source_set["source_set_id"],
                    "source_count": len(evidence),
                },
                {
                    "event": "goal.interpreted",
                    "goal_plan_ref": goal_plan["goal_plan_id"],
                    "route_class": goal_plan["route_class"],
                },
                {
                    "event": "capability.selected",
                    "capability_id": capability_id,
                    "route_source": route["source"],
                },
                {"event": "evidence.found", "evidence_count": len(evidence)},
                *(
                    [{"event": "citation.ready", "citation_count": len(citations)}]
                    if citations
                    else []
                ),
                *(
                    [{"event": "artifact.created", "artifact_ids": [item.artifact_id for item in artifacts]}]
                    if artifacts
                    else []
                ),
                *(
                    [{"event": "a2ui.surface", "surface_ref": response.a2ui_surface_ref}]
                    if response.a2ui_surface_ref
                    else []
                ),
                {"event": "final", "status": status},
            ],
            "response": response.model_dump(mode="json"),
            "routing": route,
            "resolved_goal": intent.resolved_goal,
            "presentation_mode": intent.presentation_mode,
            "context_refs": list(intent.context_refs),
            "planner_grounding_diagnostics": route.get("grounded_answer_diagnostics") or {},
            "timings_ms": stage_timings_ms,
            "created_at": now_iso(),
        }
        self.store.put("runs", run_id, run_payload)
        self.store.put(
            "turns",
            turn_id,
            {
                "turn_id": turn_id,
                "run_id": run_id,
                "employee_id": principal.employee_id,
                "question_hash": hashlib.sha256(request.question.encode("utf-8")).hexdigest(),
                "capability_id": capability_id,
                "route_source": route["source"],
                "resolved_goal": intent.resolved_goal,
                "presentation_mode": intent.presentation_mode,
                "context_refs": list(intent.context_refs),
                "evidence_ids": [item.evidence_id for item in evidence],
                "status": status,
                "created_at": now_iso(),
            },
        )
        self._finish_work_session(principal, session, response, request.question)
        return response

    def _enforce_response_budget(self, response: AgentTurnResponse) -> AgentTurnResponse:
        response.grounding_status = public_grounding_status(  # type: ignore[assignment]
            response.answerability.status
        )
        citation_link_pattern = re.compile(
            r"\s*\[\d+\]\(/api/v2/citations/(cite_[A-Za-z0-9]+)\)"
        )
        verified_source_refs = {
            str(item)
            for item in response.used_source_refs
            if str(item).strip()
        }
        verified_source_refs.update(
            str(ref)
            for claim in response.grounded_claims
            if claim.support_status == "supported"
            for ref in claim.source_refs
            if str(ref).strip()
        )

        def refresh_used_source_refs() -> None:
            response.used_source_refs = list(
                dict.fromkeys(
                    item.source_ref
                    for item in response.citations
                    if item.source_ref in verified_source_refs
                )
            )

        response.answer.markdown = re.sub(
            r"\n+###\s*사용한 지식\s*(?:\n[\s\S]*)?$",
            "",
            response.answer.markdown,
        ).rstrip()
        response.answer.markdown = re.sub(
            r"\n+사용한 지식(?:\s+\[\d+\]\(/api/v2/citations/[^)]+\))+\s*$",
            "",
            response.answer.markdown,
        ).rstrip()

        def keep_rendered_citations() -> None:
            rendered_ids = list(
                dict.fromkeys(
                    re.findall(
                        r"/api/v2/citations/(cite_[A-Za-z0-9]+)",
                        response.answer.markdown,
                    )
                )
            )
            if not rendered_ids:
                if not response.citations:
                    return
                primary = response.citations[0]
                response.answer.markdown = (
                    response.answer.markdown.rstrip()
                    + f"\n\n[근거](/api/v2/citations/{primary.citation_id})"
                )
                rendered_ids = [primary.citation_id]
            by_id = {item.citation_id: item for item in response.citations}
            response.citations = [by_id[item_id] for item_id in rendered_ids if item_id in by_id]

        def enforce_visible_provenance() -> None:
            """Keep public supported claims bound to the citations actually returned."""

            citation_by_ref = {
                item.source_ref: item
                for item in response.citations
                if item.source_ref and item.chunk_id
            }
            visible_refs = set(citation_by_ref)
            response.grounded_claims = [
                claim
                for claim in response.grounded_claims
                if claim.support_status != "supported"
                or (
                    bool(claim.source_refs)
                    and set(claim.source_refs).issubset(visible_refs)
                    and all(
                        citation_by_ref[ref].chunk_id in set(claim.supporting_chunk_ids)
                        for ref in claim.source_refs
                    )
                )
            ]
            response.related_questions = [
                item
                for item in response.related_questions
                if item.source_refs and set(item.source_refs).issubset(visible_refs)
            ]
            refresh_used_source_refs()

        include_display_html = True

        def refresh_display_html() -> None:
            response.answer.display_html = render_agent_markdown(response.answer.markdown) if include_display_html else ""

        def ensure_primary_citation() -> None:
            if not response.citations or "/api/v2/citations/" in response.answer.markdown:
                return
            citation = response.citations[0]
            response.answer.markdown = (
                response.answer.markdown.rstrip()
                + f"\n\n[근거](/api/v2/citations/{citation.citation_id})"
            )

        def response_size() -> int:
            return len(
                json.dumps(
                    response.model_dump(mode="json"),
                    ensure_ascii=False,
                ).encode("utf-8")
            )

        def compact_artifact_metadata(artifact: ArtifactRef) -> dict[str, Any]:
            # Presentation is part of the typed artifact contract, not optional
            # preview decoration. The deterministic A2UI compiler needs it even
            # after the response has been reduced to the transport budget.
            return {
                key: artifact.metadata[key]
                for key in (
                    "revision",
                    "task_count",
                    "presentation",
                    "compiler",
                    "generation_mode",
                )
                if key in artifact.metadata
            }

        def representative_claims(limit: int) -> list[GroundedClaim]:
            eligible = [
                item
                for item in response.grounded_claims
                if item.support_status in {"supported", "partial", "conflicting"}
            ]
            selected: list[GroundedClaim] = []
            selected_ids: set[str] = set()
            seen_kinds: set[str] = set()
            for item in eligible:
                kind = str(item.claim_kind or "")
                if kind in seen_kinds:
                    continue
                selected.append(item)
                selected_ids.add(item.claim_id)
                seen_kinds.add(kind)
                if len(selected) >= limit:
                    return selected
            for item in eligible:
                if item.claim_id in selected_ids:
                    continue
                selected.append(item)
                if len(selected) >= limit:
                    break
            return selected

        refresh_display_html()
        keep_rendered_citations()
        latest_harnesses: dict[str, HarnessResult] = {}
        for item in response.harness_results:
            latest_harnesses[item.harness_id] = item
        response.harness_results = [
            item.model_copy(
                update={
                    "checks": [check for check in item.checks if check.status != "passed"][:4],
                    "blockers": item.blockers[:4],
                }
            )
            for item in latest_harnesses.values()
        ]
        response.loop_state = {
            key: response.loop_state.get(key)
            for key in ("iteration_count", "decision", "status", "revision")
            if key in response.loop_state
        }
        enforce_visible_provenance()
        payload = response.model_dump(mode="json")
        if len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) <= self.settings.response_budget_bytes:
            return response
        include_display_html = False
        refresh_display_html()
        response.evidence_refs = [
            item.model_copy(update={"summary": compact_text(item.summary, 120), "metadata": {}})
            for item in response.evidence_refs[:4]
        ]
        response.citations = [
            item.model_copy(update={"excerpt": compact_text(item.excerpt, 160)})
            for item in response.citations[:4]
        ]
        response.related_questions = [
            item.model_copy(update={"source_refs": item.source_refs[:1]})
            for item in response.related_questions[:3]
        ]
        response.answer.markdown = truncate_markdown(response.answer.markdown, 2200)
        for artifact in response.artifact_refs:
            artifact.preview = artifact.preview[:600]
        payload = response.model_dump(mode="json")
        if len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > self.settings.response_budget_bytes:
            response.evidence_refs = [
                item.model_copy(update={"summary": compact_text(item.summary, 80)})
                for item in response.evidence_refs[:2]
            ]
            response.citations = [
                item.model_copy(update={"excerpt": compact_text(item.excerpt, 90)})
                for item in response.citations
            ]
            response.related_questions = [
                item.model_copy(update={"source_refs": item.source_refs[:1]})
                for item in response.related_questions[:2]
                if item.source_refs
            ]
            response.answer.markdown = truncate_markdown(response.answer.markdown, 1800)
        payload = response.model_dump(mode="json")
        if len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > self.settings.response_budget_bytes:
            response.evidence_refs = [
                item.model_copy(update={"summary": compact_text(item.summary, 60), "metadata": {}})
                for item in response.evidence_refs[:1]
            ]
            response.citations = [item.model_copy(update={"excerpt": ""}) for item in response.citations[:4]]
            response.related_questions = [
                item.model_copy(update={"source_refs": item.source_refs[:1]})
                for item in response.related_questions[:1]
                if item.source_refs
            ]
            response.progress = []
            response.answer.markdown = truncate_markdown(response.answer.markdown, 1500)
        payload = response.model_dump(mode="json")
        if len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > self.settings.response_budget_bytes:
            response.answer.summary = compact_text(response.answer.summary, 420)
            response.answer.markdown = truncate_markdown(response.answer.markdown, 1200)
            response.next_actions = response.next_actions[:2]
            response.related_questions = [
                item.model_copy(update={"source_refs": item.source_refs[:1]})
                for item in response.related_questions[:1]
                if item.source_refs
            ]
            anchor = response.context_usage.get("page_anchor") if isinstance(response.context_usage, dict) else None
            response.context_usage = {
                "page_anchor": {
                    key: anchor.get(key)
                    for key in ("ref", "kind", "title", "resolved")
                    if isinstance(anchor, dict) and key in anchor
                }
                if isinstance(anchor, dict)
                else None,
                "selected_source_count": response.context_usage.get("selected_source_count", 0)
                if isinstance(response.context_usage, dict)
                else 0,
            }
            for artifact in response.artifact_refs:
                artifact.preview = ""
        payload = response.model_dump(mode="json")
        if len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > self.settings.response_budget_bytes:
            primary_citation_id = response.citations[0].citation_id if response.citations else ""
            response.answer.markdown = citation_link_pattern.sub(
                lambda match: match.group(0) if match.group(1) == primary_citation_id else "",
                truncate_markdown(response.answer.markdown, 900),
            )
            response.citations = [item.model_copy(update={"excerpt": ""}) for item in response.citations[:1]]
            response.evidence_refs = [
                item.model_copy(update={"summary": "", "metadata": {}})
                for item in response.evidence_refs[:1]
            ]
            response.related_questions = []
            response.progress = []
            response.next_actions = response.next_actions[:1]
            response.harness_results = [item for item in response.harness_results if item.status != "passed"][:1]
            if response.work_intent:
                response.work_intent = response.work_intent.model_copy(
                    update={
                        "goal": compact_text(response.work_intent.goal, 120),
                        "operation_plan": [response.work_intent.operation],
                        "target_ref": compact_text(response.work_intent.target_ref, 120),
                        "desired_outcome": compact_text(response.work_intent.desired_outcome, 120),
                    }
                )
            for artifact in response.artifact_refs:
                artifact.preview = ""
                artifact.metadata = compact_artifact_metadata(artifact)
        payload = response.model_dump(mode="json")
        if len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > self.settings.response_budget_bytes:
            response.answer.markdown = truncate_markdown(response.answer.markdown, 700)
            response.citations = [item.model_copy(update={"excerpt": ""}) for item in response.citations[:1]]
            response.evidence_refs = [
                item.model_copy(update={"summary": "", "metadata": {}})
                for item in response.evidence_refs[:1]
            ]
            response.harness_results = []
            response.presentation_plan = {}
            response.progress = []
            response.context_usage = {
                "page_anchor": response.context_usage.get("page_anchor")
                if isinstance(response.context_usage, dict)
                else None,
                "selected_source_count": response.context_usage.get("selected_source_count", 0)
                if isinstance(response.context_usage, dict)
                else 0,
            }
            for artifact in response.artifact_refs:
                artifact.metadata = compact_artifact_metadata(artifact)
            ensure_primary_citation()
        keep_rendered_citations()
        refresh_display_html()
        budget = self.settings.response_budget_bytes
        if response_size() > budget:
            response.progress = []
            response.offers = []
            response.next_actions = response.next_actions[:1]
            response.knowledge_candidates = response.knowledge_candidates[:1]
            response.answer.summary = compact_text(response.answer.summary, 240)
            refresh_display_html()
        # Citation restoration can make a truncated answer as long as it was
        # before truncation. Keep compaction bounded and require every pass to
        # make measurable progress before trying the same strategy again.
        for _ in range(8):
            if response_size() <= budget or len(response.answer.markdown) <= 240:
                break
            previous_length = len(response.answer.markdown)
            excess = response_size() - budget
            target = max(240, len(response.answer.markdown) - max(80, excess // 2 + 32))
            response.answer.markdown = truncate_markdown(response.answer.markdown, target)
            ensure_primary_citation()
            keep_rendered_citations()
            refresh_display_html()
            if len(response.answer.markdown) >= previous_length:
                break
        if response_size() > budget:
            response.related_questions = response.related_questions[:1]
            response.next_actions = []
            response.knowledge_candidates = []
            response.plan_ref = ""
            response.job_ref = ""
            refresh_display_html()
        response.grounding_status = public_grounding_status(  # type: ignore[assignment]
            response.answerability.status
        )
        if response_size() > budget:
            response.related_questions = []
            response.artifact_refs = [
                item.model_copy(update={"preview": "", "metadata": compact_artifact_metadata(item)})
                for item in response.artifact_refs[:1]
            ]
            response.answer.summary = compact_text(response.answer.summary, 120)
            response.answer.markdown = truncate_markdown(response.answer.markdown, 240)
            ensure_primary_citation()
            keep_rendered_citations()
            refresh_display_html()
        if response_size() > budget:
            response.answer.display_html = ""
        if response_size() > budget:
            response.grounded_claims = [
                item.model_copy(
                    update={
                        "text": compact_text(item.text, 180),
                        "source_refs": item.source_refs[:2],
                        "supporting_chunk_ids": item.supporting_chunk_ids[:2],
                    }
                )
                for item in representative_claims(4)
            ]
            response.answerability = response.answerability.model_copy(
                update={
                    "missing_evidence": [compact_text(item, 100) for item in response.answerability.missing_evidence[:2]],
                    "conflicts": [compact_text(item, 100) for item in response.answerability.conflicts[:2]],
                }
            )
            if response.work_intent:
                response.work_intent = response.work_intent.model_copy(
                    update={
                        "goal": compact_text(response.work_intent.goal, 100),
                        "resolved_goal": compact_text(response.work_intent.resolved_goal, 140),
                        "retrieval_query": compact_text(response.work_intent.retrieval_query, 100),
                        "topic_subject": compact_text(response.work_intent.topic_subject, 100),
                        "primary_topic_entity": compact_text(response.work_intent.primary_topic_entity, 100),
                        "topic_entities": response.work_intent.topic_entities[:4],
                        "referenceable_topic_entities": response.work_intent.referenceable_topic_entities[:4],
                        "selected_prior_topic_entities": response.work_intent.selected_prior_topic_entities[:4],
                        "context_refs": response.work_intent.context_refs[:2],
                        "operation_plan": [response.work_intent.operation],
                    }
                )
        for _ in range(8):
            if response_size() <= budget or len(response.answer.markdown) <= 120:
                break
            previous_length = len(response.answer.markdown)
            excess = response_size() - budget
            target = max(120, len(response.answer.markdown) - max(40, excess + 24))
            response.answer.markdown = truncate_markdown(response.answer.markdown, target)
            ensure_primary_citation()
            keep_rendered_citations()
            if len(response.answer.markdown) >= previous_length:
                break
        if response_size() > budget:
            response.answer.summary = compact_text(response.answer.summary, 80)
            response.grounded_claims = response.grounded_claims[:1]
            response.answerability = response.answerability.model_copy(
                update={"missing_evidence": [], "conflicts": []}
            )
        if response_size() > budget and response.work_intent:
            response.work_intent = response.work_intent.model_copy(
                update={
                    "topic_entities": response.work_intent.topic_entities[:1],
                    "referenceable_topic_entities": response.work_intent.referenceable_topic_entities[:1],
                    "selected_prior_topic_entities": response.work_intent.selected_prior_topic_entities[:1],
                    "comparison_focal_entities": response.work_intent.comparison_focal_entities[:1],
                    "relationship_focal_entities": response.work_intent.relationship_focal_entities[:1],
                    "context_refs": response.work_intent.context_refs[:1],
                    "harness_ids": response.work_intent.harness_ids[:1],
                    "requested_asset_kinds": response.work_intent.requested_asset_kinds[:1],
                }
            )
        if response_size() > budget:
            response.context_usage = {}
        if response_size() > budget:
            # The citation and AnswerabilityReport retain the transport-level
            # grounding contract. Detailed claim/chunk bindings remain durable
            # on the run and topic state when an unusually small response
            # budget cannot carry them safely.
            response.grounded_claims = []
        if response_size() > budget:
            # A constrained transport can resolve the full semantic plan and
            # loop state through the durable refs retained above. Prefer the
            # user answer, citations, artifact and those refs over duplicating
            # the complete planning diagnostics in the same tiny response.
            response.work_intent = None
            response.loop_state = {}
            response.presentation_plan = {}
        if response_size() > budget:
            # Detailed provider accounting is durable on both the AgentRun and
            # WorkRun.  A constrained wire response only needs the stable
            # ledger reference and the totals a client can display.  Compact
            # this diagnostic envelope before sacrificing navigable citations
            # or the typed artifact the user explicitly requested.
            response.usage = {
                key: response.usage[key]
                for key in (
                    "usage_ref",
                    "model_calls",
                    "total_provider_calls",
                    "input_tokens",
                    "output_tokens",
                    "total_tokens",
                    "elapsed_ms",
                )
                if key in response.usage
            }
        enforce_visible_provenance()
        response.grounding_status = public_grounding_status(  # type: ignore[assignment]
            response.answerability.status
        )
        return response

    def get_run(self, principal: Principal, run_id: str) -> dict[str, Any]:
        run = self.store.get("runs", run_id)
        if not run:
            raise HTTPException(status_code=404, detail="run not found")
        if run.get("employee_id") != principal.employee_id and not principal.is_admin:
            raise HTTPException(status_code=403, detail="run belongs to another employee")
        return run

    def create_note_from_turn(self, principal: Principal, request: NoteFromTurnRequest) -> dict[str, Any]:
        run = self.get_run(principal, request.run_id)
        session = self.get_work_session(principal, request.work_session_id)
        if str(run.get("work_session_id") or "") != request.work_session_id:
            raise HTTPException(status_code=409, detail="run does not belong to this work session")
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        answer = response.get("answer") if isinstance(response.get("answer"), dict) else {}
        body = str(answer.get("markdown") or answer.get("summary") or "").strip()
        if not body:
            raise HTTPException(status_code=409, detail="the selected turn has no answer to save")
        artifact_id = new_id("artifact")
        title = compact_text(request.title or str(answer.get("summary") or "업무 지식 노트"), 160)
        citation_refs = [str(item.get("citation_id") or "") for item in response.get("citations") or [] if item.get("citation_id")]
        source_refs = [str(item.get("evidence_id") or "") for item in response.get("evidence_refs") or [] if item.get("evidence_id")]
        artifact = {
            "artifact_id": artifact_id,
            "employee_id": principal.employee_id,
            "capability_id": str(run.get("capability_id") or ""),
            "artifact_type": "knowledge_note",
            "status": "provisional",
            "title": title or "업무 지식 노트",
            "draft": {
                "title": title or "업무 지식 노트",
                "body": body,
                "source_refs": source_refs,
                "citation_refs": citation_refs,
            },
            "work_session_id": request.work_session_id,
            "revision": 1,
            "evidence_ledger": response.get("evidence_refs") or [],
            "created_at": now_iso(),
            "updated_at": now_iso(),
        }
        self.store.put("artifacts", artifact_id, artifact)
        source_set = self._ensure_source_set(principal, request.work_session_id)
        pinned = list(source_set.get("pinned") or [])
        if artifact_id not in pinned:
            pinned.append(artifact_id)
        source_set.update(
            {
                "pinned": pinned[:100],
                "revision": int(source_set.get("revision") or 1) + 1,
                "updated_at": now_iso(),
            }
        )
        self.store.put("source_sets", str(source_set["source_set_id"]), source_set)
        session.update(
            {
                "active_artifact_id": artifact_id,
                "revision": int(session.get("revision") or 1) + 1,
                "updated_at": now_iso(),
            }
        )
        self.store.put("work_sessions", request.work_session_id, session)
        return {"artifact": self.get_artifact(principal, artifact_id), "source_set": self.get_source_set(principal, request.work_session_id)}

    def use_note_as_source(self, principal: Principal, artifact_id: str) -> dict[str, Any]:
        artifact = self.get_artifact(principal, artifact_id)
        if self._artifact_contract_type(artifact) != "knowledge_note":
            raise HTTPException(status_code=409, detail="only a private knowledge note can be used as a source")
        session_id = str(artifact.get("work_session_id") or "")
        source_set = self._ensure_source_set(principal, session_id)
        pinned = list(source_set.get("pinned") or [])
        if artifact_id not in pinned:
            pinned.append(artifact_id)
            source_set.update(
                {
                    "pinned": pinned[:100],
                    "revision": int(source_set.get("revision") or 1) + 1,
                    "updated_at": now_iso(),
                }
            )
            self.store.put("source_sets", str(source_set["source_set_id"]), source_set)
        return {"artifact_id": artifact_id, "status": "source_ready", "source_set": self.get_source_set(principal, session_id)}

    def get_context(self, principal: Principal, context_id: str) -> dict[str, Any]:
        context = self.store.get("contexts", context_id)
        if not context:
            raise HTTPException(status_code=404, detail="context not found")
        if context.get("employee_id") != principal.employee_id and not principal.is_admin:
            raise HTTPException(status_code=403, detail="context belongs to another employee")
        return context

